rtl:
module nor4b_4_input (
    Y,
    A,
    B,
    C,
    D_N
);

    output Y;
    input A, B, C, D_N;

    assign Y = ~( A | B | C| D_N);

endmodule

sva:
module nor4b_4_input_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D_N
);

// Y must always equal the NOR of A, B, C, and D_N.
    check_nor_equation: assert property (
        @(posedge clk) Y == ~(A | B | C | D_N)
    );

// If all inputs are low, Y must be high.
    check_all_low_drives_high: assert property (
        @(posedge clk) (!A && !B && !C && !D_N) |-> (Y == 1'b1)
    );

// A high forces Y low.
    check_a_high_drives_low: assert property (
        @(posedge clk) A |-> (Y == 1'b0)
    );

// B high forces Y low.
    check_b_high_drives_low: assert property (
        @(posedge clk) B |-> (Y == 1'b0)
    );

// C high forces Y low.
    check_c_high_drives_low: assert property (
        @(posedge clk) C |-> (Y == 1'b0)
    );

// D_N high forces Y low.
    check_d_n_high_drives_low: assert property (
        @(posedge clk) D_N |-> (Y == 1'b0)
    );

// A high Y means all inputs are low.
    check_high_output_requires_all_low: assert property (
        @(posedge clk) (Y == 1'b1) |-> (!A && !B && !C && !D_N)
    );

// A low Y means at least one input is high.
    check_low_output_requires_some_high: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A || B || C || D_N)
    );

endmodule

rtl:
module calculator(
    input [7:0] A,
    input [7:0] B,
    input [1:0] op,
    output reg [7:0] Y
);

    always @* begin
        case(op)
            2'b00: Y = A + B;
            2'b01: Y = A - B;
            2'b10: Y = A * B;
            2'b11: Y = A / B;
        endcase
    end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] op,
    input logic [7:0] Y
);

// Addition opcode drives Y with the 8-bit sum.
    check_addition_result: assert property (
        @(posedge clk)
        (op === 2'b00) |-> (Y === 8'(A + B))
    );

// Subtraction opcode drives Y with the 8-bit difference.
    check_subtraction_result: assert property (
        @(posedge clk)
        (op === 2'b01) |-> (Y === 8'(A - B))
    );

endmodule

rtl:
module calculator(a, b, op, result, valid);
   input [7:0] a, b;
   input [1:0] op;
   output reg [7:0] result;
   output reg valid;

   always @(*) begin
      case (op)
         2'b00: result = a + b;
         2'b01: result = a - b;
         2'b10: result = a * b;
         2'b11: begin
            if (b == 0) begin
               result = 8'b0;
               valid = 1'b0;
            end else begin
               result = a / b;
               valid = 1'b1;
            end
         end
      endcase

      if (op == 2'b11 && b == 0) begin
         valid = 1'b0;
      end else begin
         valid = 1'b1;
      end
   end
endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result,
    input logic valid
);

// Addition returns the 8-bit sum and sets valid.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((result == (a + b)) && (valid == 1'b1))
    );

// Subtraction returns the 8-bit difference and sets valid.
    check_sub_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((result == (a - b)) && (valid == 1'b1))
    );

// Division by zero forces a zero result and clears valid.
    check_div_zero_result: assert property (
        @(posedge clk)
        ((op == 2'b11) && (b == 8'h00)) |-> ((result == 8'h00) && (valid == 1'b0))
    );

// valid can be low only for division by zero.
    check_valid_low_only_on_div_zero: assert property (
        @(posedge clk)
        (valid == 1'b0) |-> ((op == 2'b11) && (b == 8'h00))
    );

// Any case other than division by zero must set valid.
    check_valid_high_otherwise: assert property (
        @(posedge clk)
        (!((op == 2'b11) && (b == 8'h00))) |-> (valid == 1'b1)
    );

endmodule

rtl:
module and3(
    X,
    A,
    B,
    C
);

    output X;
    input A;
    input B;
    input C;

    wire AB;
    wire ABC;

    assign AB = A & B;
    assign ABC = AB & C;
    assign X = ABC;

endmodule

sva:
module and3_sva(
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

// X must equal the AND of A, B, and C.
    check_x_matches_and3: assert property (
        @(posedge clk) X == (A & B & C)
    );

// X high requires all three inputs to be high.
    check_x_high_implies_all_inputs_high: assert property (
        @(posedge clk) X |-> (A && B && C)
    );

// All three inputs high must drive X high.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge clk) (A && B && C) |-> X
    );

// Any low input must force X low.
    check_any_low_input_forces_x_low: assert property (
        @(posedge clk) ((!A) || (!B) || (!C)) |-> !X
    );

endmodule

rtl:
module MUX_2_TO_1
(
  input A,
  input B,
  input S,
  output Z
);

  assign Z = (S == 0) ? A : B;

endmodule

sva:
module MUX_2_TO_1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic Z
);

// Output must implement the mux equation.
    check_mux_function: assert property (
        @(posedge clk) Z === ((S == 1'b0) ? A : B)
    );

// Low select routes A to the output.
    check_select_a: assert property (
        @(posedge clk) (S === 1'b0) |-> (Z === A)
    );

// High select routes B to the output.
    check_select_b: assert property (
        @(posedge clk) (S === 1'b1) |-> (Z === B)
    );

// If both inputs match, the output must match them as well.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (A === B) |-> (Z === A)
    );

endmodule

module mux_4to1_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);

// When sel is 2'b00, out must reflect in[0].
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// When sel is 2'b01, out must reflect in[1].
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// When sel is 2'b10, out must reflect in[2].
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// When sel is 2'b11, out must reflect in[3].
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

endmodule

rtl:
module priority_mux (
    input [3:0] A, B, C, D,
    input [1:0] S,
    output reg Y, Z
);

always @(*) begin
    case(S)
        2'b00: begin
            if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(C) begin
                Y = 0;
                Z = 0;
            end
            else if(D) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
        2'b01: begin
            if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(C) begin
                Y = 0;
                Z = 0;
            end
            else if(D) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
        2'b10: begin
            if(C) begin
                Y = 0;
                Z = 0;
            end
            else if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(D) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
        2'b11: begin
            if(D) begin
                Y = 0;
                Z = 0;
            end
            else if(A) begin
                Y = 1;
                Z = 0;
            end
            else if(B) begin
                Y = 0;
                Z = 1;
            end
            else if(C) begin
                Y = 0;
                Z = 0;
            end
            else begin
                Y = 0;
                Z = 0;
            end
        end
    endcase
end

endmodule

sva:
module priority_mux_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [3:0]  C,
    input logic [3:0]  D,
    input logic [1:0]  S,
    input logic        Y,
    input logic        Z
);

// Y and Z are never driven high together.
    check_outputs_not_both_high: assert property (
        @(posedge clk) !(Y && Z)
    );

// For S=00, any nonzero A selects Y=1 and Z=0.
    check_sel00_a_priority: assert property (
        @(posedge clk)
        (S == 2'b00 && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=00, B selects Y=0 and Z=1 when A is zero.
    check_sel00_b_priority: assert property (
        @(posedge clk)
        (S == 2'b00 && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=00, outputs are 0 when both A and B are zero.
    check_sel00_default_zero: assert property (
        @(posedge clk)
        (S == 2'b00 && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=01, any nonzero B selects Y=0 and Z=1.
    check_sel01_b_priority: assert property (
        @(posedge clk)
        (S == 2'b01 && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=01, A selects Y=1 and Z=0 when B is zero.
    check_sel01_a_priority: assert property (
        @(posedge clk)
        (S == 2'b01 && (B == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=01, outputs are 0 when both B and A are zero.
    check_sel01_default_zero: assert property (
        @(posedge clk)
        (S == 2'b01 && (B == 4'b0000) && (A == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=10, any nonzero C forces both outputs low.
    check_sel10_c_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=10, A selects Y=1 and Z=0 when C is zero.
    check_sel10_a_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=10, B selects Y=0 and Z=1 when C and A are zero.
    check_sel10_b_priority: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=10, outputs are 0 when C, A, and B are all zero.
    check_sel10_default_zero: assert property (
        @(posedge clk)
        (S == 2'b10 && (C == 4'b0000) && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=11, any nonzero D forces both outputs low.
    check_sel11_d_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

// For S=11, A selects Y=1 and Z=0 when D is zero.
    check_sel11_a_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A != 4'b0000)) |-> (Y == 1'b1 && Z == 1'b0)
    );

// For S=11, B selects Y=0 and Z=1 when D and A are zero.
    check_sel11_b_priority: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A == 4'b0000) && (B != 4'b0000)) |-> (Y == 1'b0 && Z == 1'b1)
    );

// For S=11, outputs are 0 when D, A, and B are all zero.
    check_sel11_default_zero: assert property (
        @(posedge clk)
        (S == 2'b11 && (D == 4'b0000) && (A == 4'b0000) && (B == 4'b0000)) |-> (Y == 1'b0 && Z == 1'b0)
    );

endmodule

rtl:
module BCD_Converter (
  input [3:0] bin,
  output [3:0] bcd
);

  wire [3:0] temp;

  assign temp[3] = bin[3] & bin[2] & bin[1] & bin[0];
  assign temp[2] = (~bin[3] & bin[2] & bin[1] & bin[0]) | (bin[3] & ~bin[2] & bin[1] & bin[0]) | (bin[3] & bin[2] & ~bin[1] & bin[0]) | (bin[3] & bin[2] & bin[1] & ~bin[0]);
  assign temp[1] = (~bin[3] & ~bin[2] & bin[1] & bin[0]) | (bin[3] & ~bin[2] & ~bin[1] & bin[0]) | (bin[3] & bin[2] & ~bin[1] & ~bin[0]) | (~bin[3] & bin[2] & bin[1] & ~bin[0]);
  assign temp[0] = (~bin[3] & ~bin[2] & ~bin[1] & bin[0]) | (bin[3] & ~bin[2] & ~bin[1] & ~bin[0]) | (bin[3] & bin[2] & ~bin[1] & ~bin[0]) | (bin[3] & ~bin[2] & bin[1] & ~bin[0]);

  assign bcd = temp;

endmodule

sva:
module BCD_Converter_sva (
    input logic clk,
    input logic [3:0] bin,
    input logic [3:0] bcd
);

// bcd[3] is high only for an all-ones input.
    check_bcd_bit3_all_ones: assert property (
        @(posedge clk)
        (bcd[3] == (bin == 4'b1111))
    );

// bcd[2] is high for the four three-ones input patterns.
    check_bcd_bit2_three_high_patterns: assert property (
        @(posedge clk)
        (bcd[2] == (
            (bin == 4'b0111) ||
            (bin == 4'b1011) ||
            (bin == 4'b1101) ||
            (bin == 4'b1110)
        ))
    );

// bcd[1] is high for the four patterns encoded by the RTL.
    check_bcd_bit1_selected_patterns: assert property (
        @(posedge clk)
        (bcd[1] == (
            (bin == 4'b0011) ||
            (bin == 4'b0110) ||
            (bin == 4'b1001) ||
            (bin == 4'b1100)
        ))
    );

// bcd[0] is high for the four patterns encoded by the RTL.
    check_bcd_bit0_selected_patterns: assert property (
        @(posedge clk)
        (bcd[0] == (
            (bin == 4'b0001) ||
            (bin == 4'b1000) ||
            (bin == 4'b1010) ||
            (bin == 4'b1100)
        ))
    );

// Inputs 0, 2, 4, and 5 produce a zero output.
    check_zero_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0000) ||
            (bin == 4'b0010) ||
            (bin == 4'b0100) ||
            (bin == 4'b0101)
        ) |-> (bcd == 4'b0000)
    );

// Inputs 1, 8, and 10 produce 0001.
    check_one_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0001) ||
            (bin == 4'b1000) ||
            (bin == 4'b1010)
        ) |-> (bcd == 4'b0001)
    );

// Inputs 3, 6, and 9 produce 0010.
    check_two_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0011) ||
            (bin == 4'b0110) ||
            (bin == 4'b1001)
        ) |-> (bcd == 4'b0010)
    );

// Inputs 7, 11, 13, and 14 produce 0100.
    check_four_output_cases: assert property (
        @(posedge clk)
        (
            (bin == 4'b0111) ||
            (bin == 4'b1011) ||
            (bin == 4'b1101) ||
            (bin == 4'b1110)
        ) |-> (bcd == 4'b0100)
    );

// Input 12 is the only case that produces 0011.
    check_three_output_case: assert property (
        @(posedge clk)
        (bin == 4'b1100) |-> (bcd == 4'b0011)
    );

// Input 15 produces 1000.
    check_eight_output_case: assert property (
        @(posedge clk)
        (bin == 4'b1111) |-> (bcd == 4'b1000)
    );

endmodule

rtl:
module four_bit_adder (
    A,
    B,
    CI,
    SUM,
    COUT
);

    input [3:0] A;
    input [3:0] B;
    input CI;
    output [3:0] SUM;
    output COUT;

    wire [3:0] a_xor_b;
    wire [3:0] a_xor_b_xor_ci;
    wire [3:0] a_and_b;
    wire [3:0] a_and_b_and_ci;
    wire [3:0] a_or_b;
    wire [3:0] a_or_b_or_ci;
    wire a_xor_b_xor_ci_xor_cout;

    // Implement the adder logic using only the allowed gates and the named wires
    xor xor0 (a_xor_b[0], A[0], B[0]);
    xor xor1 (a_xor_b[1], A[1], B[1]);
    xor xor2 (a_xor_b[2], A[2], B[2]);
    xor xor3 (a_xor_b[3], A[3], B[3]);

    xor xor4 (a_xor_b_xor_ci[0], a_xor_b[0], CI);
    xor xor5 (a_xor_b_xor_ci[1], a_xor_b[1], CI);
    xor xor6 (a_xor_b_xor_ci[2], a_xor_b[2], CI);
    xor xor7 (a_xor_b_xor_ci[3], a_xor_b[3], CI);

    and and0 (a_and_b[0], A[0], B[0]);
    and and1 (a_and_b[1], A[1], B[1]);
    and and2 (a_and_b[2], A[2], B[2]);
    and and3 (a_and_b[3], A[3], B[3]);

    and and4 (a_and_b_and_ci[0], a_and_b[0], CI);
    and and5 (a_and_b_and_ci[1], a_and_b[1], CI);
    and and6 (a_and_b_and_ci[2], a_and_b[2], CI);
    and and7 (a_and_b_and_ci[3], a_and_b[3], CI);

    or or0 (a_or_b[0], A[0], B[0]);
    or or1 (a_or_b[1], A[1], B[1]);
    or or2 (a_or_b[2], A[2], B[2]);
    or or3 (a_or_b[3], A[3], B[3]);

    or or4 (a_or_b_or_ci[0], a_or_b[0], CI);
    or or5 (a_or_b_or_ci[1], a_or_b[1], CI);
    or or6 (a_or_b_or_ci[2], a_or_b[2], CI);
    or or7 (a_or_b_or_ci[3], a_or_b[3], CI);

    xor xor8 (a_xor_b_xor_ci_xor_cout, a_xor_b_xor_ci[3], a_and_b_and_ci[3]);

    // Assign the output ports
    assign SUM = a_xor_b_xor_ci;
    assign COUT = a_xor_b_xor_ci_xor_cout;

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CI,
    input logic [3:0] SUM,
    input logic COUT
);

// External sampling clock; RTL has no clock or reset.

    // SUM must match the implemented bitwise XOR with replicated CI.
    check_sum_vector: assert property (
        @(posedge clk) SUM == (A ^ B ^ {4{CI}})
    );

// SUM[0] is A[0] xor B[0] xor CI.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0] ^ CI)
    );

// SUM[1] is A[1] xor B[1] xor CI.
    check_sum_bit1: assert property (
        @(posedge clk) SUM[1] == (A[1] ^ B[1] ^ CI)
    );

// SUM[2] is A[2] xor B[2] xor CI.
    check_sum_bit2: assert property (
        @(posedge clk) SUM[2] == (A[2] ^ B[2] ^ CI)
    );

// SUM[3] is A[3] xor B[3] xor CI.
    check_sum_bit3: assert property (
        @(posedge clk) SUM[3] == (A[3] ^ B[3] ^ CI)
    );

// COUT must match the implemented relation to SUM[3].
    check_cout_from_sum_msb: assert property (
        @(posedge clk) COUT == (SUM[3] ^ (A[3] & B[3] & CI))
    );

// COUT must match the exact implemented MSB equation.
    check_cout_function: assert property (
        @(posedge clk) COUT == (A[3] ^ B[3] ^ CI ^ (A[3] & B[3] & CI))
    );

// With CI low, SUM reduces to A xor B.
    check_sum_ci_low: assert property (
        @(posedge clk) (!CI) |-> (SUM == (A ^ B))
    );

// With CI high, SUM reduces to bitwise complement of A xor B.
    check_sum_ci_high: assert property (
        @(posedge clk) CI |-> (SUM == ~(A ^ B))
    );

// With CI low, COUT reduces to the MSB xor.
    check_cout_ci_low: assert property (
        @(posedge clk) (!CI) |-> (COUT == (A[3] ^ B[3]))
    );

// With CI high, COUT is high only when both MSB inputs are low.
    check_cout_ci_high: assert property (
        @(posedge clk) CI |-> (COUT == ~(A[3] | B[3]))
    );

endmodule

rtl:
module math_op(
    input [7:0] a,
    input [7:0] b,
    input [1:0] op,
    output reg [7:0] result
);

always @(*) begin
    case (op)
        2'b00: result = a + b;
        2'b01: result = a - b;
        2'b10: result = a * b;
        2'b11: begin
            if (b == 0) begin
                result = 8'd0;
            end else begin
                result = a / b;
            end
        end
    endcase
end

endmodule

sva:
module math_op_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    input logic [7:0] result
);

// Addition mode returns the 8-bit sum of a and b.
    check_add_result: assert property (
        @(posedge clk) (op == 2'b00) |-> (result == byte_t'(a + b))
    );

// Subtraction mode returns the 8-bit difference of a and b.
    check_sub_result: assert property (
        @(posedge clk) (op == 2'b01) |-> (result == byte_t'(a - b))
    );

// Division by zero forces the result to zero.
    check_div_by_zero_result: assert property (
        @(posedge clk) ((op == 2'b11) && (b == 8'd0)) |-> (result == 8'd0)
    );

endmodule

