    check_out_sel_00: assert property (
        @(posedge shift) (sel === 2'b00) |-> (out === in_0)
    );

// out selects in_1 when sel is 2'b01.
    check_out_sel_01: assert property (
        @(posedge shift) (sel === 2'b01) |-> (out === in_1)
    );

// out selects in_2 when sel is 2'b10.
    check_out_sel_10: assert property (
        @(posedge shift) (sel === 2'b10) |-> (out === in_2)
    );

// out selects in_3 when sel is 2'b11.
    check_out_sel_11: assert property (
        @(posedge shift) (sel === 2'b11) |-> (out === in_3)
    );

// out stays stable when sel and all mux inputs stay stable.
    check_out_stable_when_mux_inputs_stable: assert property (
        @(posedge shift)
        1'b1 |=> (
            !((sel  === $past(sel))  &&
              (in_0 === $past(in_0)) &&
              (in_1 === $past(in_1)) &&
              (in_2 === $past(in_2)) &&
              (in_3 === $past(in_3))) ||
            (out === $past(out))
        )
    );

endmodule

rtl:
module binary_counter(
   input clk,
   input rst,
   input [15:0] max_count,
   output reg [15:0] count,
   output reg done
   );

   always @(posedge clk or posedge rst) begin
      if (rst) begin
         count <= 0;
         done <= 0;
      end
      else begin
         if (count == max_count) begin
            count <= 0;
            done <= 1;
         end
         else begin
            count <= count + 1;
            done <= 0;
         end
      end
   end

endmodule

sva:
module binary_counter_sva (
    input logic        clk,
    input logic        rst,
    input logic [15:0] max_count,
    input logic [15:0] count,
    input logic        done
);

// Reset keeps count and done cleared.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |-> (count == 16'd0 && done == 1'b0)
    );

// Reaching max_count wraps count and raises done on the next cycle.
    check_wrap_on_max_count: assert property (
        @(posedge clk) disable iff (rst)
        (count == max_count) |=> (count == 16'd0 && done == 1'b1)
    );

// Any non-max count increments and keeps done low on the next cycle.
    check_increment_when_not_max: assert property (
        @(posedge clk) disable iff (rst)
        (count != max_count) |=> (count == ($past(count) + 16'd1) && done == 1'b0)
    );

// The first clock after reset release still observes the reset state.
    check_hold_reset_state_after_release: assert property (
        @(posedge clk) disable iff (rst)
        $past(rst) |-> (count == 16'd0 && done == 1'b0)
    );

endmodule

