rtl:
module bidirectional_data_port (
  input clk,
  input reset,
  input [3:0] in,
  input dir,
  output reg [3:0] out,
  output reg [3:0] dout
);

  always @(posedge clk, negedge reset) begin
    if (!reset) begin
      out <= 4'b0;
      dout <= 4'b0;
    end else begin
      if (dir == 1) begin
        out <= {in[3], in[2], in[1], in[0]};
        dout <= {in[0], in[1], in[2], in[3]};
      end else begin
        out <= in;
      end
    end
  end

endmodule

sva:
module bidirectional_data_port_sva (
    input logic clk,
    input logic reset,
    input logic [3:0] in,
    input logic dir,
    input logic [3:0] out,
    input logic [3:0] dout
);

// Sampled low reset clears both outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) (reset == 1'b0) |-> (out == 4'b0000) && (dout == 4'b0000)
    );

// With dir high, out loads the input value.
    check_out_loads_input_when_dir_high: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b1) |=> (out == $past(in))
    );

// With dir high, dout loads the reversed input value.
    check_dout_loads_reversed_input_when_dir_high: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b1) |=> (dout == {$past(in[0]), $past(in[1]), $past(in[2]), $past(in[3])})
    );

// With dir low, out still loads the input value.
    check_out_loads_input_when_dir_low: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b0) |=> (out == $past(in))
    );

// With dir low, dout holds its previous value.
    check_dout_holds_when_dir_low: assert property (
        @(posedge clk) disable iff (!reset) (dir == 1'b0) |=> (dout == $past(dout))
    );

endmodule

rtl:
module pio_latency (
                     // inputs:
                      address,
                      clk,
                      in_port,
                      reset_n,

                     // outputs:
                      readdata
                   )
;

  output  [ 15: 0] readdata;
  input   [  1: 0] address;
  input            clk;
  input   [ 15: 0] in_port;
  input            reset_n;

  wire             clk_en;
  wire    [ 15: 0] data_in;
  wire    [ 15: 0] read_mux_out;
  reg     [ 15: 0] readdata;
  assign clk_en = 1;
  //s1, which is an e_avalon_slave
  assign read_mux_out = {16 {(address == 0)}} & data_in;
  always @(posedge clk or negedge reset_n)
    begin
      if (reset_n == 0)
          readdata <= 0;
      else if (clk_en)
          readdata <= read_mux_out;
    end


  assign data_in = in_port;

endmodule

sva:
module pio_latency_assertions (
    input  logic [1:0]  address,
    input  logic        clk,
    input  logic [15:0] in_port,
    input  logic        reset_n,
    input  logic [15:0] readdata
);

// After reset was sampled low, readdata is zero on the next active clock.
    check_post_reset_readdata_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        ($past(reset_n) === 1'b0) |-> (readdata == 16'h0000)
    );

// A prior read of address 0 returns the prior input, unless reset forced zero.
    check_addr0_read_matches_input_or_reset_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b00)) |->
        ((readdata == $past(in_port)) || (readdata == 16'h0000))
    );

// A prior read of address 1 returns zero.
    check_addr1_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b01)) |-> (readdata == 16'h0000)
    );

// A prior read of address 2 returns zero.
    check_addr2_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b10)) |-> (readdata == 16'h0000)
    );

// A prior read of address 3 returns zero.
    check_addr3_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b11)) |-> (readdata == 16'h0000)
    );

// Address 0 with zero input returns zero on the following clock.
    check_addr0_zero_input_reads_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && ($past(address) === 2'b00) && ($past(in_port) === 16'h0000)) |->
        (readdata == 16'h0000)
    );

// Any nonzero readdata must come from a prior read of address 0.
    check_nonzero_readdata_from_addr0: assert property (
        @(posedge clk) disable iff (!reset_n)
        (($past(reset_n) === 1'b1) && (readdata != 16'h0000)) |->
        (($past(address) === 2'b00) && (readdata == $past(in_port)))
    );

endmodule

