    check_default_zero: assert property (
        @(posedge clk)
        ((B != 4'b0001) && (B != 4'b0010) && (B != 4'b0100) && (B != 4'b1000))
        |-> (O == 8'b00000000)
    );

// The upper four output bits are always zero.
    check_upper_bits_zero: assert property (
        @(posedge clk) (O[7:4] == 4'b0000)
    );

