rtl:
module five_to_one(
    input input1,
    input input2,
    input input3,
    input input4,
    input input5,
    output output1
);

    wire and1, and2, and3, and4, or1;

    assign and1 = input1 & input2;
    assign and2 = input3 & input4;
    assign and3 = and2 & input5;
    assign or1 = and1 | and3;
    assign output1 = or1;

endmodule

sva:
module five_to_one_sva (
    input logic clk,
    input logic input1,
    input logic input2,
    input logic input3,
    input logic input4,
    input logic input5,
    input logic output1
);

// Output matches the RTL sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        output1 == ((input1 & input2) | (input3 & input4 & input5))
    );

// The input1/input2 AND path forces the output high.
    check_first_path_drives_high: assert property (
        @(posedge clk)
        (input1 & input2) |-> output1
    );

// The input3/input4/input5 AND path forces the output high.
    check_second_path_drives_high: assert property (
        @(posedge clk)
        (input3 & input4 & input5) |-> output1
    );

// A high output must come from at least one implemented path.
    check_output_high_has_valid_cause: assert property (
        @(posedge clk)
        output1 |-> ((input1 & input2) | (input3 & input4 & input5))
    );

// If the first path is inactive, output equals the second path.
    check_no_first_path_means_second_path_only: assert property (
        @(posedge clk)
        !(input1 & input2) |-> (output1 == (input3 & input4 & input5))
    );

// If the second path is inactive, output equals the first path.
    check_no_second_path_means_first_path_only: assert property (
        @(posedge clk)
        !(input3 & input4 & input5) |-> (output1 == (input1 & input2))
    );

endmodule

rtl:
module top_module(
    input a,
    input b,
    input sel_b1,
    input sel_b2,
    output reg out_always,
    output out_and,
    output out_or,
    output out_xor
);

    wire mux_out;
    wire [3:0] logic_gate_out;

    // 2-to-1 Multiplexer
    assign mux_out = (sel_b1 & sel_b2) ? b : a;

    // 4-input Logic Gate
    and_gate logic_and(.and_out(logic_gate_out[0]), .a(a), .b(b), .c(sel_b1), .d(sel_b2));
    or_gate logic_or(.or_out(logic_gate_out[1]), .a(a), .b(b), .c(sel_b1), .d(sel_b2));
    xor_gate logic_xor(.xor_out(logic_gate_out[2]), .a(a), .b(b), .c(sel_b1), .d(sel_b2));
    assign logic_gate_out[3] = 1'b0;

    // Output assignments
    assign out_and = logic_gate_out[0];
    assign out_or = logic_gate_out[1];
    assign out_xor = logic_gate_out[2];
    always @* begin
        out_always = mux_out;
    end

endmodule

module and_gate(
    output and_out,
    input a,
    input b,
    input c,
    input d
);
    assign and_out = a & b & c & d;
endmodule

module or_gate(
    output or_out,
    input a,
    input b,
    input c,
    input d
);
    assign or_out = a | b | c | d;
endmodule

module xor_gate(
    output xor_out,
    input a,
    input b,
    input c,
    input d
);
    assign xor_out = a ^ b ^ c ^ d;
endmodule

