sva:
module constant_voltage_driver_sva (
    input logic clk,
    input logic control,
    input logic [7:0] vref,
    input logic vout
);

// When control is low, the output must be low.
    check_output_zero_when_control_low: assert property (
        @(posedge clk) (control === 1'b0) |-> (vout === 1'b0)
