module power_ground_module (
    input clk,
    input rst_n,
    input enable,
    output reg VPWR,
    output reg VGND
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        VPWR <= 0;
        VGND <= 0;
    end else if (enable) begin
        VPWR <= 1;
        VGND <= 0;
    end else begin
        VPWR <= 0;
        VGND <= 0;
    end
end

endmodule

sva:
module power_ground_module_sva (
    input logic clk,
    input logic rst_n,
    input logic enable,
    input logic VPWR,
    input logic VGND
);

// Clock: clk; reset: rst_n active-low; logic is sequential.
    // VPWR follows enable on the next clocked state update, and VGND is always low.

    // If reset is low, both outputs are low by the next sampled clock.
    check_reset_clears_outputs: assert property (
        @(posedge clk) !rst_n |=> (VPWR == 1'b0 && VGND == 1'b0)
    );

// Outside reset, the next sampled outputs match the current enable value.
    check_outputs_follow_enable: assert property (
        @(posedge clk) disable iff (!rst_n)
        1'b1 |=> ((VPWR == $past(enable)) && (VGND == 1'b0))
    );

// When enable is high, the next registered outputs are VPWR=1 and VGND=0.
    check_enable_sets_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        enable |=> (VPWR == 1'b1 && VGND == 1'b0)
    );

// When enable is low, the next registered outputs are VPWR=0 and VGND=0.
    check_disable_clears_outputs: assert property (
        @(posedge clk) disable iff (!rst_n)
        !enable |=> (VPWR == 1'b0 && VGND == 1'b0)
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic up_down,
    input logic [3:0] count
);

// Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'b0000)
    );

// When not enabled, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// In up mode, the counter increments when below 15.
    check_increment_in_up_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && up_down && (count != 4'b1111)) |=> (count == ($past(count) + 4'b0001))
    );

// In up mode, the counter wraps from 15 to 0.
    check_wrap_in_up_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && up_down && (count == 4'b1111)) |=> (count == 4'b0000)
    );

// In down mode, the counter decrements when above 0.
    check_decrement_in_down_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !up_down && (count != 4'b0000)) |=> (count == ($past(count) - 4'b0001))
    );

// In down mode, the counter wraps from 0 to 15.
    check_wrap_in_down_mode: assert property (
        @(posedge clk) disable iff (reset)
        (enable && !up_down && (count == 4'b0000)) |=> (count == 4'b1111)
    );

endmodule

rtl:
module AdderSubtractor (
    input [3:0] A,
    input [3:0] B,
    input Sub,
    output [3:0] S,
    output Cout
);

wire [3:0] A_comp;
wire [3:0] B_comp;

assign A_comp = ~A + 1;
assign B_comp = ~B + 1;

wire [4:0] temp_sum;
assign temp_sum = (Sub == 1) ? A + B_comp : A + B;

assign Cout = (Sub == 1) ? (A >= B) : (temp_sum[4] == 1);
assign S = (Sub == 1) ? temp_sum : temp_sum[3:0];

endmodule

sva:
module AdderSubtractor_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Sub,
    input logic [3:0] S,
    input logic Cout
);

// Addition mode returns the 4-bit sum.
    check_add_sum: assert property (
        @(posedge clk) (Sub == 1'b0) |-> (S == (A + B))
    );

// Subtraction mode returns the 4-bit difference.
    check_sub_diff: assert property (
        @(posedge clk) (Sub == 1'b1) |-> (S == (A - B))
    );

// Subtraction mode uses A>=B as the Cout flag.
    check_sub_cout_no_borrow: assert property (
        @(posedge clk) (Sub == 1'b1) |-> (Cout == (A >= B))
    );

// Equal operands subtract to zero with Cout asserted.
    check_sub_equal_zero: assert property (
        @(posedge clk) (Sub == 1'b1 && A == B) |-> (S == 4'b0000 && Cout == 1'b1)
    );

// Adding zero passes A through and keeps Cout low.
    check_add_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b0 && B == 4'b0000) |-> (S == A && Cout == 1'b0)
    );

// Subtracting zero passes A through and asserts Cout.
    check_sub_zero_passthrough: assert property (
        @(posedge clk) (Sub == 1'b1 && B == 4'b0000) |-> (S == A && Cout == 1'b1)
    );

// 0x0 - 0x1 wraps to 0xF with Cout deasserted.
    check_sub_underflow_wrap: assert property (
        @(posedge clk) (Sub == 1'b1 && A == 4'h0 && B == 4'h1) |-> (S == 4'hF && Cout == 1'b0)
    );

endmodule

