sva:
module sky130_fd_sc_lp__a22o_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2
);

// X must implement the OR of the two AND terms.
    check_output_equation: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2))
