    output reg [7:0] out
);

always @(*) begin
    case (in)
        3'b000: out = 8'b11111110;
        3'b001: out = 8'b11111101;
        3'b010: out = 8'b11111011;
        3'b011: out = 8'b11110111;
        3'b100: out = 8'b11101111;
        3'b101: out = 8'b11011111;
        3'b110: out = 8'b10111111;
        3'b111: out = 8'b01111111;
        default: out = 8'b11111111;
    endcase
end

endmodule

sva:
module decoder_3to8_sva (
    input logic clk,
    input logic [2:0] in,
    input logic [7:0] out
);

// Input 000 drives only bit 0 low.
    check_decode_000: assert property (
        @(posedge clk) (in == 3'b000) |-> (out == 8'b11111110)
    );

// Input 001 drives only bit 1 low.
    check_decode_001: assert property (
        @(posedge clk) (in == 3'b001) |-> (out == 8'b11111101)
    );

// Input 010 drives only bit 2 low.
    check_decode_010: assert property (
        @(posedge clk) (in == 3'b010) |-> (out == 8'b11111011)
    );

// Input 011 drives only bit 3 low.
    check_decode_011: assert property (
        @(posedge clk) (in == 3'b011) |-> (out == 8'b11110111)
    );

// Input 100 drives only bit 4 low.
    check_decode_100: assert property (
        @(posedge clk) (in == 3'b100) |-> (out == 8'b11101111)
    );

// Input 101 drives only bit 5 low.
    check_decode_101: assert property (
        @(posedge clk) (in == 3'b101) |-> (out == 8'b11011111)
    );

// Input 110 drives only bit 6 low.
    check_decode_110: assert property (
        @(posedge clk) (in == 3'b110) |-> (out == 8'b10111111)
    );

// Input 111 drives only bit 7 low.
    check_decode_111: assert property (
        @(posedge clk) (in == 3'b111) |-> (out == 8'b01111111)
    );

// Known inputs produce an active-low one-hot output.
    check_active_low_onehot: assert property (
        @(posedge clk) !$isunknown(in) |-> $onehot(~out)
    );

// Unknown input bits select the default all-high output.
    check_default_unknown_input: assert property (
        @(posedge clk) $isunknown(in) |-> (out == 8'b11111111)
    );

endmodule

rtl:
module data_parser(
  input [3:0] data_in,
  output reg [1:0] data_out_1,
  output reg [1:0] data_out_2,
  output reg parity
);

  always @(*) begin
    data_out_1 = data_in[1:0];
    data_out_2 = data_in[3:2];
    parity = ^data_in;
  end

endmodule

sva:
module data_parser_sva(
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] data_out_1,
    input logic [1:0] data_out_2,
    input logic parity
);

// data_out_1 mirrors the low two bits of data_in.
    check_data_out_1_slice: assert property (
        @(posedge clk) data_out_1 == data_in[1:0]
    );

// data_out_2 mirrors the high two bits of data_in.
    check_data_out_2_slice: assert property (
        @(posedge clk) data_out_2 == data_in[3:2]
    );

// parity is the reduction XOR of data_in.
    check_parity_from_input: assert property (
        @(posedge clk) parity == (^data_in)
    );

// The two output fields reconstruct the full input bus.
    check_outputs_reconstruct_input: assert property (
        @(posedge clk) {data_out_2, data_out_1} == data_in
    );

// parity matches the XOR of the split output fields.
    check_parity_from_outputs: assert property (
        @(posedge clk) parity == (^({data_out_2, data_out_1}))
    );

endmodule

rtl:
module absolute_value_calculator (
  input signed [7:0] input_num,
  output reg [7:0] abs_value
);

  always @(*) begin
    if (input_num < 0) begin
      abs_value = ~input_num + 1;
    end else begin
      abs_value = input_num;
    end
  end

endmodule

sva:
module absolute_value_calculator_sva (
    input logic clk,
    input logic signed [7:0] input_num,
    input logic [7:0] abs_value
);

// Output always matches the RTL's conditional function.
    check_absolute_value_function: assert property (
        @(posedge clk)
        abs_value == ((input_num < 0) ? (~input_num + 8'd1) : input_num)
    );

// Non-negative inputs pass through unchanged.
    check_non_negative_passthrough: assert property (
        @(posedge clk)
        (input_num >= 0) |-> (abs_value == input_num)
    );

// Negative inputs produce the two's-complement magnitude.
    check_negative_twos_complement: assert property (
        @(posedge clk)
        (input_num < 0) |-> (abs_value == (~input_num + 8'd1))
    );

// Zero maps to zero.
    check_zero_case: assert property (
        @(posedge clk)
        (input_num == 8'sd0) |-> (abs_value == 8'd0)
    );

// Negative one maps to one.
    check_negative_one_case: assert property (
        @(posedge clk)
        (input_num == -8'sd1) |-> (abs_value == 8'd1)
    );

// The most-negative input wraps to 8'h80 in 8-bit two's complement.
    check_min_negative_case: assert property (
        @(posedge clk)
        (input_num == 8'sh80) |-> (abs_value == 8'h80)
    );

endmodule

rtl:
module register_4bit (
    input CLK,
    input [3:0] D,
    input LD,
    input RST,
    output reg [3:0] Q
);

    // Local signals
    reg [3:0] reg_Q;
    reg [3:0] reg_Q_N;
    reg [3:0] mux_out;
    reg [3:0] rst_d;

    // Instantiate the flip-flop modules
    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            reg_Q <= 4'b0;
        end else begin
            reg_Q <= mux_out;
        end
    end

    // 4-to-1 multiplexer to select between D input and buffered output
    always @* begin
        mux_out[0] = (LD) ? D[0] : reg_Q[0];
        mux_out[1] = (LD) ? D[1] : reg_Q[1];
        mux_out[2] = (LD) ? D[2] : reg_Q[2];
        mux_out[3] = (LD) ? D[3] : reg_Q[3];
    end

    // Asynchronous reset
    always @* begin
        rst_d = (RST) ? 4'b0 : 4'b1;
    end

    // Output
    always @* begin
        Q = reg_Q;
    end

endmodule

sva:
module register_4bit_sva (
    input logic CLK,
    input logic [3:0] D,
    input logic LD,
    input logic RST,
    input logic [3:0] Q
);

// Reset forces the register output to zero.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |-> (Q == 4'b0000)
    );

// A load captures D into Q on the next clock.
    check_load_captures_d: assert property (
        @(posedge CLK) disable iff (RST) LD |=> (Q == $past(D))
    );

// With load deasserted, Q holds its previous value.
    check_hold_when_ld_low: assert property (
        @(posedge CLK) disable iff (RST) !LD |=> $stable(Q)
    );

// Loading a new value causes Q to change to that value.
    check_load_new_value_changes_q: assert property (
        @(posedge CLK) disable iff (RST) (LD && (D != Q)) |=> ((Q == $past(D)) && !$stable(Q))
    );

// Loading the current value leaves Q unchanged.
    check_load_same_value_keeps_q_stable: assert property (
        @(posedge CLK) disable iff (RST) (LD && (D == Q)) |=> $stable(Q)
    );

// After reset release, Q stays zero if no load is requested.
    check_reset_release_keeps_zero_without_load: assert property (
        @(posedge CLK) RST ##1 (!RST && !LD) |-> (Q == 4'b0000)
    );

endmodule

rtl:
module ripple_carry_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [3:0] carry;
    assign carry[0] = cin;

    full_adder fa0(a[0], b[0], carry[0], sum[0], carry[1]);
    full_adder fa1(a[1], b[1], carry[1], sum[1], carry[2]);
    full_adder fa2(a[2], b[2], carry[2], sum[2], carry[3]);
    full_adder fa3(a[3], b[3], carry[3], sum[3], cout);

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign {cout, sum} = a + b + cin;

endmodule

sva:
module ripple_carry_adder_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

// Combined output must equal the 4-bit addition with carry in.
    check_total_addition: assert property (
        @(posedge clk) disable iff (1'b0)
        {cout, sum} == add5_fn(a, b, cin)
    );

// Bit 0 sum matches the first full-adder stage.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry rippled from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[1] == (a[1] ^ b[1] ^ c1_fn(a, b, cin))
    );

// Bit 2 sum uses the carry rippled from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[2] == (a[2] ^ b[2] ^ c2_fn(a, b, cin))
    );

// Bit 3 sum uses the carry rippled from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) disable iff (1'b0)
        sum[3] == (a[3] ^ b[3] ^ c3_fn(a, b, cin))
    );

// Carry out matches the final ripple carry.
    check_carry_out: assert property (
        @(posedge clk) disable iff (1'b0)
        cout == c4_fn(a, b, cin)
    );

// Carry out must be low when the total is below 16.
    check_no_overflow_range: assert property (
        @(posedge clk) disable iff (1'b0)
        (add5_fn(a, b, cin) < 5'd16) |-> !cout
    );

// Carry out must be high when the total is 16 or more.
    check_overflow_range: assert property (
        @(posedge clk) disable iff (1'b0)
        (add5_fn(a, b, cin) >= 5'd16) |-> cout
    );

// Adding zero with no carry-in passes a through unchanged.
    check_b_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (b == 4'b0000 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero with no carry-in passes b through unchanged.
    check_a_zero_passthrough: assert property (
        @(posedge clk) disable iff (1'b0)
        (a == 4'b0000 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

endmodule

rtl:
module BLOCK1 ( PIN1, PIN2, GIN1, GIN2, PHI, POUT, GOUT );
input  PIN1;
input  PIN2;
input  GIN1;
input  GIN2;
input  PHI;
output POUT;
output GOUT;
   assign POUT =  ~ (PIN1 | PIN2);
   assign GOUT =  ~ (GIN2 & (PIN2 | GIN1));
endmodule

sva:
module BLOCK1_sva (
    input logic PIN1,
    input logic PIN2,
    input logic GIN1,
    input logic GIN2,
    input logic PHI,
    input logic POUT,
    input logic GOUT
);

// POUT must implement the NOR of PIN1 and PIN2.
    check_pout_equation: assert property (
        @(posedge PHI) POUT == ~(PIN1 | PIN2)
    );

// GOUT must implement the inverted AND of GIN2 with (PIN2 | GIN1).
    check_gout_equation: assert property (
        @(posedge PHI) GOUT == ~(GIN2 & (PIN2 | GIN1))
    );

// If either PIN input is high, POUT must be low.
    check_pout_low_when_any_pin_high: assert property (
        @(posedge PHI) ((PIN1 == 1'b1) || (PIN2 == 1'b1)) |-> (POUT == 1'b0)
    );

// If both PIN inputs are low, POUT must be high.
    check_pout_high_when_both_pins_low: assert property (
        @(posedge PHI) ((PIN1 == 1'b0) && (PIN2 == 1'b0)) |-> (POUT == 1'b1)
    );

// If GIN2 is low, GOUT must be high.
    check_gout_high_when_gin2_low: assert property (
        @(posedge PHI) (GIN2 == 1'b0) |-> (GOUT == 1'b1)
    );

// If both PIN2 and GIN1 are low, GOUT must be high.
    check_gout_high_when_or_term_low: assert property (
        @(posedge PHI) ((PIN2 == 1'b0) && (GIN1 == 1'b0)) |-> (GOUT == 1'b1)
    );

// If GIN2 and PIN2 are high, GOUT must be low.
    check_gout_low_when_gin2_and_pin2_high: assert property (
        @(posedge PHI) ((GIN2 == 1'b1) && (PIN2 == 1'b1)) |-> (GOUT == 1'b0)
    );

// If GIN2 and GIN1 are high, GOUT must be low.
    check_gout_low_when_gin2_and_gin1_high: assert property (
        @(posedge PHI) ((GIN2 == 1'b1) && (GIN1 == 1'b1)) |-> (GOUT == 1'b0)
    );

endmodule

rtl:
module and_gate(
    input a,
    input b,
    output y
);

    assign y = a & b;

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic y
);

// Output must match the AND of both inputs.
    check_and_function: assert property (
        @(posedge clk) y == (a & b)
    );

// If input a is low, the output must be low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) !a |-> !y
    );

// If input b is low, the output must be low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) !b |-> !y
    );

