        @(posedge clk) y |-> (a && b)
    );

endmodule

rtl:
module top_module (
    input [3:0] DIN,
    input [1:0] SHIFT,
    input [3:0] a,
    input [3:0] b,
    input cin,
    output cout,
    output [3:0] sum,
    output [3:0] DOUT
);

    wire [3:0] shifted_input;
    wire [3:0] adder_input;
    wire [3:0] adder_output;

    barrel_shifter barrel_shifter_inst(
        .DIN(DIN),
        .SHIFT(SHIFT),
        .DOUT(shifted_input)
    );

    four_bit_adder adder_inst(
        .a(a),
        .b(shifted_input),
        .cin(cin),
        .cout(cout),
        .sum(adder_output)
    );

    assign adder_input = b;

    assign sum = adder_output + adder_input + cin;
    assign DOUT = adder_output;

endmodule
module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output cout,
    output [3:0] sum
);

    assign {cout, sum} = a + b + cin;

endmodule
module barrel_shifter (
    input [3:0] DIN,
    input [1:0] SHIFT,
    output [3:0] DOUT
);

    assign DOUT = {DIN[SHIFT[1]], DIN[SHIFT[0]], DIN[3], DIN[2]};

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [3:0]  DIN,
    input logic [1:0]  SHIFT,
    input logic [3:0]  a,
    input logic [3:0]  b,
    input logic        cin,
    input logic        cout,
    input logic [3:0]  sum,
    input logic [3:0]  DOUT
);

// SHIFT=00 selects DIN[0], DIN[0], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_00: assert property (
        @(posedge clk)
        (SHIFT == 2'b00) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[0], DIN[0], DIN[3], DIN[2]}} + cin))
    );

// SHIFT=01 selects DIN[0], DIN[1], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_01: assert property (
        @(posedge clk)
        (SHIFT == 2'b01) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[0], DIN[1], DIN[3], DIN[2]}} + cin))
    );

// SHIFT=10 selects DIN[1], DIN[0], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_10: assert property (
        @(posedge clk)
        (SHIFT == 2'b10) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[1], DIN[0], DIN[3], DIN[2]}} + cin))
    );

// SHIFT=11 selects DIN[1], DIN[1], DIN[3], DIN[2] into the first adder.
    check_first_stage_shift_11: assert property (
        @(posedge clk)
        (SHIFT == 2'b11) |-> ({cout, DOUT} == ({1'b0, a} + {1'b0, {DIN[1], DIN[1], DIN[3], DIN[2]}} + cin))
    );

// sum is DOUT plus b plus cin, truncated to 4 bits.
    check_sum_from_dout_b_cin: assert property (
        @(posedge clk)
        ({1'b0, sum} == (({1'b0, DOUT} + {1'b0, b} + cin) & 5'h0f))
    );

// With b and cin both zero, sum matches DOUT.
    check_sum_equals_dout_when_b_and_cin_zero: assert property (
        @(posedge clk)
        ((b == 4'h0) && (cin == 1'b0)) |-> (sum == DOUT)
    );

endmodule

rtl:
module mux4(
    input A0, A1, A2, A3, S0, S1, VPWR, VGND, VPB, VNB,
    output X
);

wire w1, w2, w3;

assign w1 = (~S1 & ~S0) ? A0 : (~S1 & S0) ? A1 : (S1 & ~S0) ? A2 : A3;
assign w2 = (VGND == 0) ? 0 : VPWR;
assign w3 = (VPB == 0) ? 0 : VNB;

assign X = (w1 & w2 & w3);

endmodule

sva:
module mux4_sva (
    input logic clk,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic S0,
    input logic S1,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic X
);

// X must match the RTL mux and gating function.
    check_output_matches_rtl_function: assert property (
        @(posedge clk)
        X == (
            (
                ((S1 == 1'b0) && (S0 == 1'b0)) ? A0 :
                ((S1 == 1'b0) && (S0 == 1'b1)) ? A1 :
                ((S1 == 1'b1) && (S0 == 1'b0)) ? A2 :
                A3
            ) &
            ((VGND == 1'b0) ? 1'b0 : VPWR) &
            ((VPB  == 1'b0) ? 1'b0 : VNB)
        )
    );

// Select 00 routes A0 through the power gating.
    check_select_00_uses_a0: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b0)) |->
        (X == (A0 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// Select 01 routes A1 through the power gating.
    check_select_01_uses_a1: assert property (
        @(posedge clk)
        ((S1 == 1'b0) && (S0 == 1'b1)) |->
        (X == (A1 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// Select 10 routes A2 through the power gating.
    check_select_10_uses_a2: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b0)) |->
        (X == (A2 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// Select 11 routes A3 through the power gating.
    check_select_11_uses_a3: assert property (
        @(posedge clk)
        ((S1 == 1'b1) && (S0 == 1'b1)) |->
        (X == (A3 & ((VGND == 1'b0) ? 1'b0 : VPWR) & ((VPB == 1'b0) ? 1'b0 : VNB)))
    );

// VGND low forces the output low.
    check_vgnd_low_forces_x_low: assert property (
        @(posedge clk)
        (VGND == 1'b0) |-> (X == 1'b0)
    );

// VPB low forces the output low.
    check_vpb_low_forces_x_low: assert property (
        @(posedge clk)
        (VPB == 1'b0) |-> (X == 1'b0)
    );

// With VGND high, low VPWR blocks the output.
    check_vpwr_low_blocks_x: assert property (
        @(posedge clk)
        ((VGND == 1'b1) && (VPWR == 1'b0)) |-> (X == 1'b0)
    );

// With VPB high, low VNB blocks the output.
    check_vnb_low_blocks_x: assert property (
        @(posedge clk)
        ((VPB == 1'b1) && (VNB == 1'b0)) |-> (X == 1'b0)
    );

// With all power controls high, X reduces to a plain 4:1 mux.
    check_fully_enabled_path_behaves_as_mux: assert property (
        @(posedge clk)
        ((VGND == 1'b1) && (VPB == 1'b1) && (VPWR == 1'b1) && (VNB == 1'b1)) |->
        (
            X == (
                ((S1 == 1'b0) && (S0 == 1'b0)) ? A0 :
                ((S1 == 1'b0) && (S0 == 1'b1)) ? A1 :
                ((S1 == 1'b1) && (S0 == 1'b0)) ? A2 :
                A3
            )
        )
    );

endmodule

rtl:
module incrementer(input clk, input wire signed [31:0] in, output reg signed [31:0] out);
   always @(posedge clk) begin
      out <= in + 1;
   end
endmodule

sva:
module incrementer_assertions (
    input logic clk,
    input logic signed [31:0] in,
    input logic signed [31:0] out
);

// Out is the previous cycle's input incremented by one.
    check_registered_increment: assert property (
        @(posedge clk) 1'b1 |=> (out == ($past(in) + 32'sd1))
    );

// Zero increments to one on the next clock.
    check_zero_to_one: assert property (
        @(posedge clk) (in == 32'sd0) |=> (out == 32'sd1)
    );

// Minus one increments to zero on the next clock.
    check_minus_one_to_zero: assert property (
        @(posedge clk) (in == -32'sd1) |=> (out == 32'sd0)
    );

// Maximum positive value wraps to minimum negative on the next clock.
    check_positive_overflow_wrap: assert property (
        @(posedge clk) (in == 32'sh7fffffff) |=> (out == 32'sh80000000)
    );

// Minimum negative value increments to the next signed value.
    check_negative_min_to_next: assert property (
        @(posedge clk) (in == 32'sh80000000) |=> (out == 32'sh80000001)
    );

endmodule

rtl:
module signal_combiner (
    input [3:0] input_signals,
    output output_signal
);

wire[1:0] input_sum;

assign input_sum[0] = input_signals[0] ^ input_signals[1];
assign input_sum[1] = input_signals[2] ^ input_signals[3];

assign output_signal = input_sum[0] ^ input_sum[1];

endmodule

sva:
module signal_combiner_sva (
    input logic       clk,
    input logic [3:0] input_signals,
    input logic       output_signal
);

// Output matches the XOR tree implemented in the RTL.
    check_output_matches_xor_tree: assert property (
        @(posedge clk)
        output_signal == ((input_signals[0] ^ input_signals[1]) ^ (input_signals[2] ^ input_signals[3]))
    );

// Output is the parity of all four input bits.
    check_output_matches_reduction_xor: assert property (
        @(posedge clk)
        output_signal == ^input_signals
    );

// If the lower pair XOR is 0, the output equals the upper pair XOR.
    check_lower_pair_equal_passes_upper_pair: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == 1'b0) |-> (output_signal == (input_signals[2] ^ input_signals[3]))
    );

// If the lower pair XOR is 1, the output is the inverse of the upper pair XOR.
    check_lower_pair_diff_flips_upper_pair: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == 1'b1) |-> (output_signal == ~(input_signals[2] ^ input_signals[3]))
    );

// If the upper pair XOR is 0, the output equals the lower pair XOR.
    check_upper_pair_equal_passes_lower_pair: assert property (
        @(posedge clk)
        ((input_signals[2] ^ input_signals[3]) == 1'b0) |-> (output_signal == (input_signals[0] ^ input_signals[1]))
    );

// If the upper pair XOR is 1, the output is the inverse of the lower pair XOR.
    check_upper_pair_diff_flips_lower_pair: assert property (
        @(posedge clk)
        ((input_signals[2] ^ input_signals[3]) == 1'b1) |-> (output_signal == ~(input_signals[0] ^ input_signals[1]))
    );

// Equal pair parities force the output low.
    check_matching_pair_parities_drive_zero: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) == (input_signals[2] ^ input_signals[3])) |-> (output_signal == 1'b0)
    );

// Different pair parities force the output high.
    check_different_pair_parities_drive_one: assert property (
        @(posedge clk)
        ((input_signals[0] ^ input_signals[1]) != (input_signals[2] ^ input_signals[3])) |-> (output_signal == 1'b1)
    );

endmodule

module shift_register_4bit_sva(
    input logic clk,
    input logic rst,
    input logic load,
    input logic [3:0] data_in,
    input logic shift,
    input logic [3:0] data_out
);

// Reset forces the register output low.
    check_reset_clears_data_out: assert property (
        @(posedge clk) !rst |-> (data_out == 4'b0000)
    );

// Load alone captures data_in on the next clock.
    check_load_captures_data_in: assert property (
        @(posedge clk) disable iff (!rst)
        (load && !shift) |=> (data_out == $past(data_in))
    );

// Load has priority when load and shift are both asserted.
    check_load_priority_over_shift: assert property (
        @(posedge clk) disable iff (!rst)
        (load && shift) |=> (data_out == $past(data_in))
    );

// Shift alone moves the register left and inserts zero.
    check_shift_left_with_zero_fill: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && shift) |=> (data_out == {$past(data_out[2:0]), 1'b0})
    );

// With no load or shift, the register holds its value.
    check_idle_holds_value: assert property (
        @(posedge clk) disable iff (!rst)
        (!load && !shift) |=> (data_out == $past(data_out))
    );

endmodule

