module d_ff_sync_reset (
    input CLK,
    input D,
    input RESET,
    output Q,
    output Q_N
);

    reg Q_buf;

    always @(posedge CLK) begin
        if (RESET) begin
            Q_buf <= 1'b0;
        end
        else begin
            Q_buf <= D;
        end
    end

    assign Q = Q_buf;
    assign Q_N = ~Q_buf;

endmodule

sva:
module d_ff_sync_reset_sva (
    input logic CLK,
    input logic D,
    input logic RESET,
    input logic Q,
    input logic Q_N
);

// A sampled reset drives the outputs to the reset state by the next clock.
    check_reset_state: assert property (
        @(posedge CLK) RESET |=> (Q == 1'b0 && Q_N == 1'b1)
    );

// Without reset, Q captures D on the next clock.
    check_q_captures_d: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q == $past(D))
    );

// Without reset, Q_N captures the inverse of D on the next clock.
    check_qn_captures_inverse_d: assert property (
        @(posedge CLK) disable iff (RESET) 1'b1 |=> (Q_N == ~$past(D))
    );

// Outside reset, the two outputs remain logical complements.
    check_outputs_are_complements: assert property (
        @(posedge CLK) disable iff (RESET) (Q_N == ~Q)
    );

endmodule

module karnaugh_map_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic F
);

// F matches the implemented truth table for all sampled inputs.
    check_function_matches_truth_table: assert property (
        @(posedge clk) F == (B ^ C ^ D)
    );

// When BCD is 000, F must be low.
    check_bcd_000_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b000) |-> (F == 1'b0)
    );

// When BCD is 001, F must be high.
    check_bcd_001_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b001) |-> (F == 1'b1)
    );

// When BCD is 010, F must be high.
    check_bcd_010_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b010) |-> (F == 1'b1)
    );

// When BCD is 011, F must be low.
    check_bcd_011_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b011) |-> (F == 1'b0)
    );

// When BCD is 100, F must be high.
    check_bcd_100_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b100) |-> (F == 1'b1)
    );

// When BCD is 101, F must be low.
    check_bcd_101_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b101) |-> (F == 1'b0)
    );

// When BCD is 110, F must be low.
    check_bcd_110_output_low: assert property (
        @(posedge clk) ({B, C, D} == 3'b110) |-> (F == 1'b0)
    );

// When BCD is 111, F must be high.
    check_bcd_111_output_high: assert property (
        @(posedge clk) ({B, C, D} == 3'b111) |-> (F == 1'b1)
    );

endmodule

rtl:
module FullAdder(
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module Adder4(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire c1, c2, c3;
  FullAdder fa1(.a(A[0]), .b(B[0]), .cin(Cin), .sum(S[0]), .cout(c1));
  FullAdder fa2(.a(A[1]), .b(B[1]), .cin(c1), .sum(S[1]), .cout(c2));
  FullAdder fa3(.a(A[2]), .b(B[2]), .cin(c2), .sum(S[2]), .cout(c3));
  FullAdder fa4(.a(A[3]), .b(B[3]), .cin(c3), .sum(S[3]), .cout(Cout));

endmodule

sva:
module Adder4_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

// Bit 2 sum uses the carry propagated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ carry3(A[1], B[1], carry3(A[0], B[0], Cin)))
    );

// Bit 3 sum uses the carry propagated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ carry3(A[2], B[2], carry3(A[1], B[1], carry3(A[0], B[0], Cin))))
    );

// The maximum input case produces all ones across Cout and S.
    check_full_overflow_case: assert property (
        @(posedge clk) ((A == 4'hF) && (B == 4'hF) && (Cin == 1'b1)) |-> ({Cout, S} == 5'h1F)
    );

endmodule

rtl:
module counter_4bit(
  input clk, rst, en,
  output reg [3:0] out
);

  always @(posedge clk or negedge rst)
  begin
    if (!rst) // synchronous reset
      out <= 4'b0;
    else if (en) // asynchronous enable
      out <= out + 1;
  end

endmodule

sva:
module counter_4bit_sva (
    input logic       clk,
    input logic       rst,
    input logic       en,
    input logic [3:0] out
);

// A sampled low reset clears the counter by the next clock.
    check_reset_clears_counter: assert property (
        @(posedge clk) (!rst) |=> (out == 4'b0000)
    );

// With enable low, the counter holds its previous value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (!rst) (!en) |=> (out == $past(out))
    );

// With enable high below 4'hF, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) (en && (out != 4'hF)) |=> (out == ($past(out) + 4'd1))
    );

// With enable high at 4'hF, the counter wraps to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (!rst) (en && (out == 4'hF)) |=> (out == 4'h0)
    );

// An enabled cycle always changes the counter value.
    check_change_when_enabled: assert property (
        @(posedge clk) disable iff (!rst) en |=> (out != $past(out))
    );

endmodule

module up_down_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       control,
    input logic [3:0] count
);

// Each active cycle updates count by one in the selected direction.
    check_next_state_update: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (count == ($past(control) ? ($past(count) + 4'd1) : ($past(count) - 4'd1)))
    );

// control high causes an increment on the next clock.
    check_increment: assert property (
        @(posedge clk) disable iff (reset)
        control |=> (count == ($past(count) + 4'd1))
    );

// control low causes a decrement on the next clock.
    check_decrement: assert property (
        @(posedge clk) disable iff (reset)
        !control |=> (count == ($past(count) - 4'd1))
    );

// Incrementing from 4'hF wraps back to zero.
    check_increment_wrap: assert property (
        @(posedge clk) disable iff (reset)
        control && (count == 4'hF) |=> (count == 4'h0)
    );

// Decrementing from zero wraps to 4'hF.
    check_decrement_wrap: assert property (
        @(posedge clk) disable iff (reset)
        !control && (count == 4'h0) |=> (count == 4'hF)
    );

endmodule

rtl:
module sky130_fd_sc_hd__fahcon (
    COUT_N,
    SUM   ,
    A     ,
    B     ,
    CI
);

    output COUT_N;
    output SUM   ;
    input  A     ;
    input  B     ;
    input  CI    ;

    wire xor0_out_SUM ;
    wire a_b          ;
    wire a_ci         ;
    wire b_ci         ;
    wire or0_out_coutn;

    xor xor0 (xor0_out_SUM , A, B, CI       );
    buf buf0 (SUM          , xor0_out_SUM   );
    nor nor0 (a_b          , A, B           );
    nor nor1 (a_ci         , A, CI          );
    nor nor2 (b_ci         , B, CI          );
    or  or0  (or0_out_coutn, a_b, a_ci, b_ci);
    buf buf1 (COUT_N       , or0_out_coutn  );

endmodule

sva:
module sky130_fd_sc_hd__fahcon_sva (
    input logic clk,
    input logic COUT_N,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CI
);

// SUM is the three-input XOR of A, B, and CI.
    check_sum_parity: assert property (
        @(posedge clk) SUM == (A ^ B ^ CI)
    );

// COUT_N is the inverted carry-out from the three inputs.
    check_coutn_function: assert property (
        @(posedge clk) COUT_N == ~((A & B) | (A & CI) | (B & CI))
    );

// The outputs encode a full-adder result with active-low carry.
    check_full_adder_encoding: assert property (
        @(posedge clk) ({1'b0, A} + {1'b0, B} + {1'b0, CI}) == {~COUT_N, SUM}
    );

// All-zero inputs produce zero sum and deasserted carry.
    check_all_zero_case: assert property (
        @(posedge clk) (!A && !B && !CI) |-> (!SUM && COUT_N)
    );

// Any single high input produces sum one and deasserted carry.
    check_one_high_case: assert property (
        @(posedge clk)
        ((A && !B && !CI) || (!A && B && !CI) || (!A && !B && CI)) |-> (SUM && COUT_N)
    );

// Any two high inputs produce sum zero and asserted carry.
    check_two_high_case: assert property (
        @(posedge clk)
        ((A && B && !CI) || (A && !B && CI) || (!A && B && CI)) |-> (!SUM && !COUT_N)
    );

// All-one inputs produce sum one and asserted carry.
    check_all_one_case: assert property (
        @(posedge clk) (A && B && CI) |-> (SUM && !COUT_N)
    );

endmodule

rtl:
module complement_module (
    input [3:0] in_vec,
    input sel_comp,
    output [3:0] outv,
    output [3:0] complement
);

    assign outv = in_vec;

    assign complement = (sel_comp == 1) ? ~in_vec + 1 : ~in_vec;

endmodule

sva:
module complement_module_sva (
    input logic clk,
    input logic [3:0] in_vec,
    input logic sel_comp,
    input logic [3:0] outv,
    input logic [3:0] complement
);

// outv is a direct pass-through of in_vec.
    check_outv_passthrough: assert property (
        @(posedge clk) outv == in_vec
    );

// complement matches the RTL's selected complement function.
    check_complement_exact_function: assert property (
        @(posedge clk) complement == ((sel_comp == 1'b1) ? (~in_vec + 4'b0001) : ~in_vec)
    );

// sel_comp low selects ones' complement.
    check_ones_complement_when_not_selected: assert property (
        @(posedge clk) (sel_comp == 1'b0) |-> (complement == ~in_vec)
    );

// sel_comp high selects twos' complement.
    check_twos_complement_when_selected: assert property (
        @(posedge clk) (sel_comp == 1'b1) |-> (complement == (~in_vec + 4'b0001))
    );

// Ones' complement output is the bitwise inverse of the input.
    check_ones_complement_inverse_relation: assert property (
        @(posedge clk) (sel_comp == 1'b0) |-> ((complement ^ in_vec) == 4'hF)
    );

// Twos' complement output adds with the input to zero modulo 16.
    check_twos_complement_additive_inverse: assert property (
        @(posedge clk) (sel_comp == 1'b1) |-> ((complement + in_vec) == 4'b0000)
    );

endmodule

rtl:
module state_machine (
    input clk,
    input rst_,
    output reg [2:0] state_r
);

    // Define the states as enumerated types
    parameter [2:0] IDLE = 3'b000;
    parameter [2:0] SEND = 3'b001;
    parameter [2:0] WAIT1 = 3'b010;
    parameter [2:0] UPDATE1 = 3'b011;
    parameter [2:0] WAIT2 = 3'b100;
    parameter [2:0] UPDATE2 = 3'b101;

    // Define the next state variable
    reg [2:0] next_state;

    // Define the state transition logic
    always @(*) begin
        case (state_r)
            IDLE: next_state = SEND;
            SEND: next_state = WAIT1;
            WAIT1: next_state = UPDATE1;
            UPDATE1: next_state = WAIT2;
            WAIT2: next_state = UPDATE2;
            UPDATE2: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Define the state update logic
    always @(posedge clk or negedge rst_) begin
        if (~rst_) begin
            state_r <= IDLE;
        end else begin
            state_r <= next_state;
        end
    end

endmodule

sva:
module state_machine_sva (
    input logic clk,
    input logic rst_,
    input logic [2:0] state_r
);

// Reset drives the machine to IDLE.
    check_reset_idle: assert property (
        @(posedge clk)
        !rst_ |-> (state_r == IDLE)
    );

// IDLE advances to SEND on the next clock.
    check_idle_to_send: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == IDLE) |=> (state_r == SEND)
    );

// SEND advances to WAIT1 on the next clock.
    check_send_to_wait1: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == SEND) |=> (state_r == WAIT1)
    );

// WAIT1 advances to UPDATE1 on the next clock.
    check_wait1_to_update1: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == WAIT1) |=> (state_r == UPDATE1)
    );

// UPDATE1 advances to WAIT2 on the next clock.
    check_update1_to_wait2: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == UPDATE1) |=> (state_r == WAIT2)
    );

// WAIT2 advances to UPDATE2 on the next clock.
    check_wait2_to_update2: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == WAIT2) |=> (state_r == UPDATE2)
    );

// UPDATE2 wraps back to IDLE on the next clock.
    check_update2_to_idle: assert property (
        @(posedge clk) disable iff (!rst_)
        (state_r == UPDATE2) |=> (state_r == IDLE)
    );

// Any invalid state encoding returns to IDLE on the next clock.
    check_invalid_state_to_idle: assert property (
        @(posedge clk) disable iff (!rst_)
        !((state_r == IDLE) || (state_r == SEND) || (state_r == WAIT1) ||
          (state_r == UPDATE1) || (state_r == WAIT2) || (state_r == UPDATE2))
        |=> (state_r == IDLE)
    );

// After any non-reset cycle, the next state is always a legal encoding.
    check_next_state_is_legal: assert property (
        @(posedge clk) disable iff (!rst_)
        1'b1 |=> ((state_r == IDLE) || (state_r == SEND) || (state_r == WAIT1) ||
                  (state_r == UPDATE1) || (state_r == WAIT2) || (state_r == UPDATE2))
    );

endmodule

rtl:
module shift_register (
    input CLK,
    input LOAD,
    input [3:0] DATA,
    output reg [3:0] Q
);

reg [3:0] reg_out;

always @(posedge CLK) begin
    if (LOAD) begin
        reg_out <= DATA;
    end else begin
        reg_out <= {reg_out[2:0], 1'b0};
    end
end

always @(*) begin
    Q = reg_out;
end

endmodule

sva:
module shift_register_sva (
    input logic       CLK,
    input logic       LOAD,
    input logic [3:0] DATA,
    input logic [3:0] Q
);

// A load cycle captures DATA into Q by the next sampled clock.
    check_load_captures_data: assert property (
        @(posedge CLK) LOAD |=> (Q == $past(DATA))
    );

// A non-load cycle shifts Q left and inserts 0 into bit 0.
    check_shift_behavior: assert property (
        @(posedge CLK) !LOAD |=> (Q == {$past(Q[2:0]), 1'b0})
    );

// A non-load cycle always drives the next LSB low.
    check_shift_inserts_zero: assert property (
        @(posedge CLK) !LOAD |=> (Q[0] == 1'b0)
    );

// A non-load cycle moves the prior lower bits into the upper bits.
    check_shift_moves_bits: assert property (
        @(posedge CLK) !LOAD |=> (Q[3:1] == $past(Q[2:0]))
    );

// Four consecutive shift cycles clear the register.
    check_four_shifts_clear_register: assert property (
        @(posedge CLK) ((!LOAD)[*4]) |=> (Q == 4'b0000)
    );

endmodule

rtl:
module nor_and_gate (
    input A, B, C, D,
    output Y
);

    // Local signals
    wire nor_out, and_out;

    // NOR gate
    nor (nor_out, A, B);

    // AND gate
    and (and_out, nor_out, C, D);

    // Output buffer
    buf (Y, and_out);

endmodule

sva:
module nor_and_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

// Y must implement the full combinational function.
    check_output_function: assert property (
        @(posedge clk) Y == ((~(A | B)) & C & D)
    );

// If either NOR input is high, the output must be low.
    check_a_or_b_blocks_output: assert property (
        @(posedge clk) (A || B) |-> !Y
    );

// If C is low, the AND stage must force the output low.
    check_c_low_blocks_output: assert property (
        @(posedge clk) !C |-> !Y
    );

// If D is low, the AND stage must force the output low.
    check_d_low_blocks_output: assert property (
        @(posedge clk) !D |-> !Y
    );

// When A and B are low, Y must match C AND D.
    check_ab_low_reduces_to_cd: assert property (
        @(posedge clk) (!A && !B) |-> (Y == (C && D))
    );

// A high output requires both NOR inputs low and both AND inputs high.
    check_high_output_requires_all_enables: assert property (
        @(posedge clk) Y |-> (!A && !B && C && D)
    );

endmodule

rtl:
module full_adder (
    input A,
    input B,
    input Cin,
    output Sum,
    output Cout
);

    wire w1, w2, w3;

    assign w1 = A ^ B;
    assign Sum = w1 ^ Cin;
    assign w2 = A & B;
    assign w3 = w1 & Cin;
    assign Cout = w2 | w3;

endmodule

module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire c1, c2, c3;

    full_adder FA0 (
        .A(A[0]),
        .B(B[0]),
        .Cin(Cin),
        .Sum(Sum[0]),
        .Cout(c1)
    );

    full_adder FA1 (
        .A(A[1]),
        .B(B[1]),
        .Cin(c1),
        .Sum(Sum[1]),
        .Cout(c2)
    );

    full_adder FA2 (
        .A(A[2]),
        .B(B[2]),
        .Cin(c2),
        .Sum(Sum[2]),
        .Cout(c3)
    );

    full_adder FA3 (
        .A(A[3]),
        .B(B[3]),
        .Cin(c3),
        .Sum(Sum[3]),
        .Cout(Cout)
    );

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout
);

// Sum[0] matches the bit-0 full-adder equation.
    check_sum_bit0_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// Sum[2] matches the bit-2 ripple-carry equation.
    check_sum_bit2_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[2] == (A[2] ^ B[2] ^
                       ((A[1] & B[1]) |
                        ((A[1] ^ B[1]) &
                         ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))
    );

// Sum[3] matches the bit-3 ripple-carry equation.
    check_sum_bit3_equation: assert property (
        @(posedge clk) disable iff (1'b0)
            Sum[3] == (A[3] ^ B[3] ^
                       ((A[2] & B[2]) |
                        ((A[2] ^ B[2]) &
                         ((A[1] & B[1]) |
                          ((A[1] ^ B[1]) &
                           ((A[0] & B[0]) | ((A[0] ^ B[0]) & Cin)))))))
    );

endmodule

rtl:
module small_fifo_cntr (
    input aclr,       // Asynchronous clear input
    input clock,      // Clock input
    input cnt_en,     // Counter enable input
    input updown,     // Up/down counter select input
    output [2:0] q,   // Counter output
    input sclr        // Synchronous clear input
);

    // Internal registers
    reg [2:0] q_reg;

    // Counter logic
    always @ (posedge clock or posedge aclr) begin
        if (aclr) begin
            q_reg <= 3'b0;
        end else if (sclr) begin
            q_reg <= 3'b0;
        end else if (cnt_en) begin
            if (updown) begin
                q_reg <= q_reg + 1'b1;
            end else begin
                q_reg <= q_reg - 1'b1;
            end
        end
    end

    // Output assignment
    assign q = q_reg;

endmodule

sva:
module small_fifo_cntr_sva (
    input logic       aclr,
    input logic       clock,
    input logic       cnt_en,
    input logic       updown,
    input logic [2:0] q,
    input logic       sclr
);

// Sampled async clear forces q low by the next clock.
    check_aclr_clears_q: assert property (
        @(posedge clock)
        aclr |=> (q == 3'b000)
    );

// Sync clear forces q low on the following cycle.
    check_sclr_clears_q: assert property (
        @(posedge clock) disable iff (aclr)
        sclr |=> (q == 3'b000)
    );

// Sync clear overrides an enabled count.
    check_sclr_priority_over_count: assert property (
        @(posedge clock) disable iff (aclr)
        sclr && cnt_en |=> (q == 3'b000)
    );

// q increments by one when enabled to count up.
    check_count_up: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && cnt_en && updown |=> (q == ($past(q) + 3'b001))
    );

// q decrements by one when enabled to count down.
    check_count_down: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && cnt_en && !updown |=> (q == ($past(q) - 3'b001))
    );

// q holds its value when no clear or count is requested.
    check_hold_when_disabled: assert property (
        @(posedge clock) disable iff (aclr)
        !sclr && !cnt_en |=> (q == $past(q))
    );

endmodule

rtl:
module my_module(
    input clk,
    input [3:0] data_in,
    output reg data_out
);

    reg [3:0] data_reg;
    wire [3:0] data_wire;

    always @(posedge clk) begin
        data_reg <= data_in;
    end

    assign data_wire = data_reg;

    always @(*) begin
        if (data_wire <= 5) begin
            data_out = 1;
        end else begin
            data_out = 0;
        end
    end

endmodule

sva:
module my_module_sva (
    input logic       clk,
    input logic [3:0] data_in,
    input logic       data_out
);

// Sampled inputs at or below 5 must drive the output high on the next cycle.
    check_low_or_equal_threshold_drives_high: assert property (
        @(posedge clk) (data_in <= 4'd5) |=> (data_out == 1'b1)
    );

// Sampled inputs above 5 must drive the output low on the next cycle.
    check_above_threshold_drives_low: assert property (
        @(posedge clk) (data_in > 4'd5) |=> (data_out == 1'b0)
    );

// The output must match the previous cycle's sampled input compared against 5.
    check_output_matches_previous_input: assert property (
        @(posedge clk) 1'b1 |=> (data_out == (($past(data_in) <= 4'd5) ? 1'b1 : 1'b0))
    );

// The threshold comparison must include the boundary value 5.
    check_boundary_five_is_high: assert property (
        @(posedge clk) (data_in == 4'd5) |=> (data_out == 1'b1)
    );

// The first value above the threshold, 6, must drive the output low.
    check_boundary_six_is_low: assert property (
        @(posedge clk) (data_in == 4'd6) |=> (data_out == 1'b0)
    );

endmodule

rtl:
module top_module( 
    input wire [7:0] in_hi,
    input wire [7:0] in_lo,
    output wire [16:0] out );

    wire parity_bit;
    wire [15:0] half_word;

    // Concatenate the two input bytes into a half-word
    assign half_word = {in_hi, in_lo};

    // Generate parity bit using XOR gate
    assign parity_bit = ^half_word;

    // Append parity bit to half-word output
    assign out = {half_word, parity_bit};

endmodule

sva:
module top_module_sva (
    input logic        clk,
    input logic [7:0]  in_hi,
    input logic [7:0]  in_lo,
    input logic [16:0] out
);

// Upper output byte mirrors in_hi.
    check_hi_byte_mapping: assert property (
        @(posedge clk) out[16:9] == in_hi
    );

// Lower output byte mirrors in_lo.
    check_lo_byte_mapping: assert property (
        @(posedge clk) out[8:1] == in_lo
    );

// The upper 16 output bits are the concatenated input bytes.
    check_half_word_concat: assert property (
        @(posedge clk) out[16:1] == {in_hi, in_lo}
    );

// The parity bit matches the reduction XOR of both input bytes.
    check_parity_from_inputs: assert property (
        @(posedge clk) out[0] == ^({in_hi, in_lo})
    );

// The full output is the concatenated half-word with its parity bit.
    check_full_output_encoding: assert property (
        @(posedge clk) out == {in_hi, in_lo, ^({in_hi, in_lo})}
    );

// The parity bit equals the parity of the upper 16 output bits.
    check_parity_consistency: assert property (
        @(posedge clk) out[0] == ^(out[16:1])
    );

// The 17-bit output has even overall parity.
    check_even_output_parity: assert property (
