    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1
);

// X equals the implemented OR-of-ANDs function.
    check_output_equation: assert property (
        @(posedge clk) X == ((A1 & A2) | (B1 & B2) | C1)
