module shift_register_sva (
    input logic       clk,
    input logic       reset,
    input logic       shift_in,
    input logic       shift,
    input logic [7:0] data_out
);

// Sampling reset high clears the register by the next clock sample.
    check_reset_clears_data_out: assert property (
        @(posedge clk) reset |=> (data_out == 8'b0)
    );

// With shift high, the next value shifts in a zero at bit 0.
    check_shift_mode_updates_full_register: assert property (
        @(posedge clk) disable iff (reset)
        shift |=> (data_out == { $past(data_out[6:0]), 1'b0 })
    );

// With shift low, the next value shifts in shift_in at bit 0.
    check_load_mode_updates_full_register: assert property (
        @(posedge clk) disable iff (reset)
        !shift |=> (data_out == { $past(data_out[6:0]), $past(shift_in) })
    );

// Upper bits always come from the previous lower bits.
    check_upper_bits_always_shift: assert property (
        @(posedge clk) disable iff (reset)
        1'b1 |=> (data_out[7:1] == $past(data_out[6:0]))
    );

// In shift mode, the next LSB is always zero.
    check_shift_mode_inserts_zero: assert property (
        @(posedge clk) disable iff (reset)
        shift |=> (data_out[0] == 1'b0)
    );

// In non-shift mode, the next LSB captures shift_in.
    check_load_mode_captures_shift_in: assert property (
        @(posedge clk) disable iff (reset)
        !shift |=> (data_out[0] == $past(shift_in))
    );

endmodule

rtl:
module absolute_counter (
    input clk,
    input rst,
    input en,
    input ld,
    input signed [31:0] in,
    input [3:0] load_data,
    output [35:0] out
);

    // Absolute value module
    wire [31:0] abs_val;
    assign abs_val = (in < 0) ? -in : in;

    // Binary counter module
    reg [3:0] counter;
    always @(posedge clk) begin
        if (rst) begin
            counter <= 4'b0000;
        end else if (en) begin
            counter <= counter + 1;
        end else if (ld) begin
            counter <= load_data;
        end
    end

    // Output module
    assign out = abs_val + {32'b0, counter};

endmodule

sva:
module absolute_counter_sva (
    input logic clk,
    input logic rst,
    input logic en,
    input logic ld,
    input logic signed [31:0] in,
    input logic [3:0] load_data,
    input logic [35:0] out
);

// After a reset cycle, the counter contribution is cleared.
    check_reset_clears_counter: assert property (
        @(posedge clk)
        rst |=> (out == {4'b0000, ((in < 32'sd0) ? -in : in)})
    );

// The output is always the absolute input plus a 4-bit counter value.
    check_counter_contribution_range: assert property (
        @(posedge clk) disable iff (rst)
        (out >= {4'b0000, ((in < 32'sd0) ? -in : in)}) &&
        ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) <= 36'd15)
    );

// When en is high, the counter increments modulo 16 on the next cycle.
    check_enable_increments_counter: assert property (
        @(posedge clk) disable iff (rst)
        en |=> ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) ==
                (($past(out - {4'b0000, ((in < 32'sd0) ? -in : in)}) + 36'd1) & 36'hF))
    );

// When ld is high and en is low, the next counter value comes from load_data.
    check_load_updates_counter: assert property (
        @(posedge clk) disable iff (rst)
        (!en && ld) |=> (out == ({4'b0000, ((in < 32'sd0) ? -in : in)} + {32'b0, $past(load_data)}))
    );

// When neither en nor ld is high, the counter value holds.
    check_hold_preserves_counter: assert property (
        @(posedge clk) disable iff (rst)
        (!en && !ld) |=> ((out - {4'b0000, ((in < 32'sd0) ? -in : in)}) ==
                          $past(out - {4'b0000, ((in < 32'sd0) ? -in : in)}))
    );

endmodule

