module up_down_counter (
    input UD,
    input RST,
    input clk,
    output reg [3:0] Q,
    output reg OVF
);

always @ (posedge clk or negedge RST) begin
    if (RST == 0) begin
        Q <= 4'b0;
        OVF <= 0;
    end
    else if (UD == 1) begin
        if (Q == 4'hF) begin
            Q <= 4'b0;
            OVF <= 1;
        end
        else begin
            Q <= Q + 1;
            OVF <= 0;
        end
    end
    else begin
        if (Q == 4'b0) begin
            Q <= 4'hF;
            OVF <= 1;
        end
        else begin
            Q <= Q - 1;
            OVF <= 0;
        end
    end
end

endmodule

sva:
module up_down_counter_sva (
    input logic       UD,
    input logic       RST,
    input logic       clk,
    input logic [3:0] Q,
    input logic       OVF
);

// Reset forces Q and OVF low.
    check_reset_clears_state: assert property (
        @(posedge clk) !RST |-> ((Q == 4'h0) && (OVF == 1'b0))
    );

// Counting up below 15 increments Q and clears OVF.
    check_count_up_increment: assert property (
        @(posedge clk) disable iff (!RST)
        (UD && (Q != 4'hF)) |=> ((Q == ($past(Q) + 4'h1)) && (OVF == 1'b0))
    );

// Counting up at 15 wraps Q to 0 and sets OVF.
    check_count_up_wrap: assert property (
