sva:
module mux2_1_sva (
    input logic       clk,
    input logic [7:0] input1,
    input logic [7:0] input2,
    input logic       select,
    input logic [7:0] selected_out
);

// Output matches the RTL mux expression on every sample.
    check_selected_out_matches_mux: assert property (
        @(posedge clk) selected_out === (select ? input2 : input1)
    );

// A low select routes input1 to the output.
    check_select_low_routes_input1: assert property (
        @(posedge clk) (select === 1'b0) |-> (selected_out === input1)
    );

// A high select routes input2 to the output.
    check_select_high_routes_input2: assert property (
        @(posedge clk) (select === 1'b1) |-> (selected_out === input2)
    );

// If both inputs are identical, the output matches that common value.
    check_equal_inputs_match_output: assert property (
        @(posedge clk) (input1 === input2) |-> (selected_out === input1)
    );

// A select change with stable data updates the output to the newly selected input.
    check_select_change_updates_output: assert property (
        @(posedge clk) ($changed(select) && $stable(input1) && $stable(input2)) |-> (selected_out === (select ? input2 : input1))
    );

endmodule

rtl:
module shift_register (
    input [3:0] DATA_IN,
    input SHIFT_EN,
    input LOAD_EN,
    input CLK,
    output [3:0] DATA_OUT
);

reg [3:0] register;

always @(posedge CLK) begin
    if (LOAD_EN) begin
        register <= DATA_IN;
    end else if (SHIFT_EN) begin
        register <= {register[2:0], register[3]};
    end
end

assign DATA_OUT = register;

endmodule

sva:
module shift_register_sva (
    input logic [3:0] DATA_IN,
    input logic       SHIFT_EN,
    input logic       LOAD_EN,
    input logic       CLK,
    input logic [3:0] DATA_OUT
);

// LOAD_EN captures DATA_IN on the next cycle.
    check_load_captures_input: assert property (
        @(posedge CLK) LOAD_EN |=> (DATA_OUT == $past(DATA_IN))
    );

// LOAD_EN has priority over SHIFT_EN when both are high.
    check_load_priority_over_shift: assert property (
        @(posedge CLK) (LOAD_EN && SHIFT_EN) |=> (DATA_OUT == $past(DATA_IN))
    );

// SHIFT_EN rotates the register left with wraparound when LOAD_EN is low.
    check_shift_rotate_left: assert property (
        @(posedge CLK) (!LOAD_EN && SHIFT_EN) |=> (
            (DATA_OUT[3] == $past(DATA_OUT[2])) &&
            (DATA_OUT[2] == $past(DATA_OUT[1])) &&
            (DATA_OUT[1] == $past(DATA_OUT[0])) &&
            (DATA_OUT[0] == $past(DATA_OUT[3]))
        )
    );

// With both enables low, DATA_OUT holds its value.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD_EN && !SHIFT_EN) |=> (DATA_OUT == $past(DATA_OUT))
    );

endmodule

module Immediate_Extend_sva (
    input logic        clk,
    input logic [31:0] data_out,
    input logic [2:0]  load,
    input logic [15:0] data_in
);

// The RTL always drives a 16-bit value that is zero-extended to 32 bits.
    check_upper_half_zero: assert property (
        @(posedge clk) data_out[31:16] == 16'h0000
    );

// load 0 places a sign-replicated byte in the low 16 bits.
    check_load0_byte_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd0) |-> (data_out == {16'h0000, {8{data_in[7]}}, data_in[7:0]})
    );

// load 1 places a sign-replicated nibble in the low 16 bits.
    check_load1_nibble_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd1) |-> (data_out == {16'h0000, {12{data_in[3]}}, data_in[3:0]})
    );

// load 2 places a sign-replicated 11-bit field in the low 16 bits.
    check_load2_eleven_bit_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd2) |-> (data_out == {16'h0000, {5{data_in[10]}}, data_in[10:0]})
    );

// load 3 zero-extends data_in[3:0] into data_out.
    check_load3_nibble_zero_extend: assert property (
        @(posedge clk)
        (load == 3'd3) |-> (data_out == {28'b0, data_in[3:0]})
    );

// load 4 zero-extends data_in[7:0] into data_out.
    check_load4_byte_zero_extend: assert property (
        @(posedge clk)
        (load == 3'd4) |-> (data_out == {24'b0, data_in[7:0]})
    );

// load 5 places a sign-replicated 5-bit field in the low 16 bits.
    check_load5_five_bit_sign_extend: assert property (
        @(posedge clk)
        (load == 3'd5) |-> (data_out == {16'h0000, {11{data_in[4]}}, data_in[4:0]})
    );

// load 6 or 7 places data_in[4:2] in the low three bits.
    check_load67_extract_bits_4_to_2: assert property (
        @(posedge clk)
        ((load == 3'd6) || (load == 3'd7)) |-> (data_out == {29'b0, data_in[4:2]})
    );

endmodule

rtl:
module counter (
  input clk,
  input reset,
  output reg [3:0] count
);

  always @(posedge clk or negedge reset) begin
    if (!reset) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       reset,
    input logic [3:0] count
);

// Count must be zero whenever reset is asserted.
    check_reset_clears_count: assert property (
        @(posedge clk) !reset |-> (count == 4'd0)
    );

// Count is still zero on the first sampled cycle after reset was low.
    check_post_reset_sample_is_zero: assert property (
        @(posedge clk) disable iff (!reset)
        $past(!reset) |-> (count == 4'd0)
    );

// After a reset-high cycle, count either increments or was asynchronously cleared to zero.
    check_count_increments_or_async_clears: assert property (
        @(posedge clk) disable iff (!reset)
        $past(reset) |-> ((count == 4'd0) || (count == ($past(count) + 4'd1)))
    );

