module OAI21B2HD4X (AN, BN, C, Z);

input AN;
input BN;
input C;

output Z;

wire I0_out;
wire I1_out;

and I0 (I0_out, AN, BN);
not I1 (I1_out, I0_out);
and I2 (Z, I1_out, C);

endmodule

sva:
module OAI21B2HD4X_assertions (
    input logic clk,
    input logic AN,
    input logic BN,
    input logic C,
    input logic Z
);

// Z matches the implemented combinational function.
    check_boolean_function: assert property (
        @(posedge clk) Z == ((~(AN & BN)) & C)
    );

// C low forces Z low.
    check_c_low_forces_z_low: assert property (
        @(posedge clk) !C |-> !Z
    );

// AN and BN both high block the output when C is high.
    check_an_bn_high_block_output: assert property (
        @(posedge clk) (C && AN && BN) |-> !Z
    );

// AN low with C high makes Z high.
    check_an_low_allows_output: assert property (
        @(posedge clk) (C && !AN) |-> Z
    );

// BN low with C high makes Z high.
    check_bn_low_allows_output: assert property (
        @(posedge clk) (C && !BN) |-> Z
    );

// A high Z requires C to be high.
    check_z_high_requires_c_high: assert property (
        @(posedge clk) Z |-> C
    );

// A high Z requires the AN/BN AND term to be false.
    check_z_high_requires_inverted_and: assert property (
        @(posedge clk) Z |-> !(AN && BN)
    );

endmodule

rtl:
module sky130_fd_sc_hd__fa(
    input A,
    input B,
    input CIN,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output COUT,
    output SUM
);

    wire W1;
    wire W2;
    wire W3;

    // XOR gates
    assign W1 = A ^ B;
    assign SUM = W1 ^ CIN;

    // AND gates
    assign W2 = A & B;
    assign W3 = CIN & W1;

    // OR gate
    assign COUT = W2 | W3;

endmodule

sva:
module sky130_fd_sc_hd__fa_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic CIN,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic COUT,
    input logic SUM
);

// SUM is the XOR of A, B, and CIN.
    check_sum_xor: assert property (
        @(posedge clk) SUM == (A ^ B ^ CIN)
    );

// COUT matches the carry logic implemented in the RTL.
    check_cout_logic: assert property (
        @(posedge clk) COUT == ((A & B) | (CIN & (A ^ B)))
    );

// The outputs together equal the 2-bit sum of the three 1-bit inputs.
    check_full_adder_result: assert property (
        @(posedge clk) {COUT, SUM} == ({1'b0, A} + {1'b0, B} + {1'b0, CIN})
    );

// When A and B are equal, SUM follows CIN.
    check_sum_matches_cin_when_ab_equal: assert property (
        @(posedge clk) (!(A ^ B)) |-> (SUM == CIN)
    );

// When A and B differ, SUM is the inverse of CIN.
    check_sum_inverts_cin_when_ab_differs: assert property (
        @(posedge clk) (A ^ B) |-> (SUM == ~CIN)
    );

// With CIN low, carry reduces to A AND B.
    check_cout_reduces_to_and_when_cin_low: assert property (
        @(posedge clk) (!CIN) |-> (COUT == (A & B))
    );

// With CIN high, carry reduces to A OR B.
    check_cout_reduces_to_or_when_cin_high: assert property (
        @(posedge clk) CIN |-> (COUT == (A | B))
    );

// If both A and B are low, carry must be low.
    check_cout_low_when_ab_low: assert property (
        @(posedge clk) ((!A) && (!B)) |-> (!COUT)
    );

// If both A and B are high, carry must be high.
    check_cout_high_when_ab_high: assert property (
        @(posedge clk) (A && B) |-> COUT
    );

endmodule

