module up_counter(clk, rst, count);
    input clk, rst;
    output reg [3:0] count;

    always @(posedge clk) begin
        if (rst) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module up_counter_sva(
    input logic clk,
    input logic rst,
    input logic [3:0] count
);

// Reset drives count to zero on the following cycle.
    check_reset_clears_count: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// If reset remains asserted, count stays at zero.
    check_reset_holds_zero: assert property (
        @(posedge clk) rst |=> (rst -> (count == 4'd0))
    );

// After reset deasserts, the first sampled count is zero.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk) rst |=> (!rst -> (count == 4'd0))
    );

// Across consecutive non-reset cycles, count increments by one.
    check_count_increments: assert property (
        @(posedge clk) disable iff (rst) !rst |=> (count == ($past(count) + 4'd1))
    );

// The 4-bit counter wraps from 15 back to 0.
    check_count_rollover: assert property (
        @(posedge clk) disable iff (rst) (!rst && (count == 4'hf)) |=> (count == 4'h0)
    );

endmodule

rtl:
module comparator_8bit (
  input [7:0] A,
  input [7:0] B,
  output reg equal,
  output reg greater_than,
  output reg less_than
);

  always @(*) begin
    if (A == B) begin
      equal = 1;
      greater_than = 0;
      less_than = 0;
    end
    else if (A > B) begin
      equal = 0;
      greater_than = 1;
      less_than = 0;
    end
    else begin
      equal = 0;
      greater_than = 0;
      less_than = 1;
    end
  end

endmodule

sva:
module comparator_8bit_sva (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic equal,
    input logic greater_than,
    input logic less_than
);

// Equal inputs select only equal.
    check_equal_case: assert property (
        @(posedge clk) (A == B) |-> (equal && !greater_than && !less_than)
    );

// A greater than B selects only greater_than.
    check_greater_case: assert property (
        @(posedge clk) (A > B) |-> (!equal && greater_than && !less_than)
    );

// A less than B selects only less_than.
    check_less_case: assert property (
        @(posedge clk) (A < B) |-> (!equal && !greater_than && less_than)
    );

// equal and greater_than cannot be high together.
    check_equal_greater_mutex: assert property (
        @(posedge clk) !(equal && greater_than)
    );

// equal and less_than cannot be high together.
    check_equal_less_mutex: assert property (
        @(posedge clk) !(equal && less_than)
    );

// greater_than and less_than cannot be high together.
    check_greater_less_mutex: assert property (
        @(posedge clk) !(greater_than && less_than)
    );

// One result output must always be asserted.
    check_result_present: assert property (
        @(posedge clk) (equal || greater_than || less_than)
    );

endmodule

rtl:
module Ripple_Carry_Adder(
  input [3:0] A,
  input [3:0] B,
  input Cin,
  output [3:0] S,
  output Cout
);

  wire [3:0] sum;  //intermediate sum bits
  wire [3:0] carry;  //intermediate carry bits

  //full adder for least significant bit
  Full_Adder FA0 (
    .A(A[0]),
    .B(B[0]),
    .Cin(Cin),
    .S(sum[0]),
    .Cout(carry[0])
  );

  //full adder for second least significant bit
  Full_Adder FA1 (
    .A(A[1]),
    .B(B[1]),
    .Cin(carry[0]),
    .S(sum[1]),
    .Cout(carry[1])
  );

  //full adder for third least significant bit
  Full_Adder FA2 (
    .A(A[2]),
    .B(B[2]),
    .Cin(carry[1]),
    .S(sum[2]),
    .Cout(carry[2])
  );

  //full adder for most significant bit
  Full_Adder FA3 (
    .A(A[3]),
    .B(B[3]),
    .Cin(carry[2]),
    .S(sum[3]),
    .Cout(Cout)
  );

  assign S = sum;  //output sum bits

endmodule

//full adder module
module Full_Adder(
  input A,
  input B,
  input Cin,
  output S,
  output Cout
);

  assign S = A ^ B ^ Cin;  //XOR of inputs
  assign Cout = (A & B) | (Cin & (A ^ B));  //OR of ANDs

endmodule

sva:
module Ripple_Carry_Adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] S,
    input logic Cout
);

// Overall output matches 4-bit addition with carry in.
    check_total_sum: assert property (
        @(posedge clk) {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Bit 0 sum is the XOR of A[0], B[0], and Cin.
    check_lsb_sum: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Bit 1 sum uses the carry generated by bit 0.
    check_bit1_sum: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ ((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))))
    );

// Bit 2 sum uses the carry out of the lower two bits.
    check_bit2_sum: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ (({1'b0, A[1:0]} + {1'b0, B[1:0]} + Cin) >= 3'd4))
    );

// Bit 3 sum uses the carry out of the lower three bits.
    check_bit3_sum: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ (({1'b0, A[2:0]} + {1'b0, B[2:0]} + Cin) >= 4'd8))
    );

// Cout is the carry out of the full 4-bit addition.
    check_cout_consistency: assert property (
        @(posedge clk) Cout == (({1'b0, A} + {1'b0, B} + Cin) >= 5'd16)
    );

// Zero plus zero with no carry in produces zero.
    check_zero_addition: assert property (
        @(posedge clk) ((A == 4'd0) && (B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == 5'd0)
    );

// Adding zero on B with no carry in passes A through.
    check_add_zero_rhs: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, A})
    );

// Adding zero on A with no carry in passes B through.
    check_add_zero_lhs: assert property (
        @(posedge clk) ((A == 4'd0) && (Cin == 1'b0)) |-> ({Cout, S} == {1'b0, B})
    );

// With B at zero, Cin increments A by one.
    check_increment_with_cin: assert property (
        @(posedge clk) ((B == 4'd0) && (Cin == 1'b1)) |-> ({Cout, S} == ({1'b0, A} + 5'd1))
    );

endmodule

