    input logic       clk
);

// Select 00 routes in[0] to out.
    check_sel_00_routes_in0: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// Select 01 routes in[1] to out.
    check_sel_01_routes_in1: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// Select 10 routes in[2] to out.
    check_sel_10_routes_in2: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// Select 11 routes in[3] to out.
    check_sel_11_routes_in3: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

endmodule

module fifo_counter_sva (
    input logic clk,
    input logic empty,
    input logic ge2_free,
    input logic ge3_free,
    input logic [1:0] input_tm_cnt,
    input logic [4:0] fifo_cnt_inc
);

// Output matches the RTL priority function.
    check_full_function: assert property (
        @(posedge clk)
        fifo_cnt_inc == (
            empty ? {3'b000, input_tm_cnt} :
            ((ge3_free && (input_tm_cnt == 2'b11)) ? 5'd2 :
             ((ge2_free && (input_tm_cnt >= 2'd2)) ? 5'd1 :
              ((input_tm_cnt >= 2'd1) ? 5'd0 : 5'b11111)))
        )
    );

// When empty is high, the output passes through input_tm_cnt.
    check_empty_pass_through: assert property (
        @(posedge clk)
        empty |-> (fifo_cnt_inc == {3'b000, input_tm_cnt})
    );

// The empty branch has priority over the later branches.
    check_empty_priority: assert property (
        @(posedge clk)
        (empty && ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd3)
    );

// For non-empty and count 3 with ge3_free, the output is 2.
    check_ge3_free_count3: assert property (
        @(posedge clk)
        (!empty && ge3_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd2)
    );

// The ge3_free branch overrides ge2_free when both are true.
    check_ge3_priority_over_ge2: assert property (
        @(posedge clk)
        (!empty && ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd2)
    );

// For non-empty and count 2 with ge2_free, the output is 1.
    check_ge2_free_count2: assert property (
        @(posedge clk)
        (!empty && ge2_free && (input_tm_cnt == 2'b10)) |-> (fifo_cnt_inc == 5'd1)
    );

// For count 3 without ge3_free but with ge2_free, the output is 1.
    check_count3_ge2_without_ge3: assert property (
        @(posedge clk)
        (!empty && !ge3_free && ge2_free && (input_tm_cnt == 2'b11)) |-> (fifo_cnt_inc == 5'd1)
    );

// For non-empty and count 1, the output falls through to 0.
    check_count1_maps_zero: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'b01)) |-> (fifo_cnt_inc == 5'd0)
    );

// For non-empty and count 2 without ge2_free, the output is 0.
    check_count2_without_ge2_maps_zero: assert property (
        @(posedge clk)
        (!empty && !ge2_free && (input_tm_cnt == 2'b10)) |-> (fifo_cnt_inc == 5'd0)
    );

// For non-empty and count 0, the output is all ones.
    check_count0_maps_all_ones: assert property (
        @(posedge clk)
        (!empty && (input_tm_cnt == 2'b00)) |-> (fifo_cnt_inc == 5'b11111)
    );

// The output only takes values produced by the RTL.
    check_output_legal_values: assert property (
        @(posedge clk)
        (fifo_cnt_inc == 5'd0)  ||
        (fifo_cnt_inc == 5'd1)  ||
        (fifo_cnt_inc == 5'd2)  ||
        (fifo_cnt_inc == 5'd3)  ||
        (fifo_cnt_inc == 5'b11111)
    );

endmodule

rtl:
module comparator(
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] C
);

// Comparing A and B
always @(*) begin
    if(A == B) begin
        C = 2'b00;
    end
    else if(A > B) begin
        C = 2'b01;
    end
    else begin
        C = 2'b10;
    end
end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] C
);

// When A equals B, output must be 00.
    check_equal_implies_code_00: assert property (
        @(posedge clk) disable iff (1'b0) (A == B) |-> (C == 2'b00)
    );

// When A greater than B, output must be 01.
    check_greater_implies_code_01: assert property (
        @(posedge clk) disable iff (1'b0) (A > B) |-> (C == 2'b01)
    );

// When A less than B, output must be 10.
    check_less_implies_code_10: assert property (
        @(posedge clk) disable iff (1'b0) (A < B) |-> (C == 2'b10)
    );

// Output 00 only occurs when A equals B.
    check_code_00_implies_equal: assert property (
        @(posedge clk) disable iff (1'b0) (C == 2'b00) |-> (A == B)
    );

// Output 01 only occurs when A greater than B.
    check_code_01_implies_greater: assert property (
        @(posedge clk) disable iff (1'b0) (C == 2'b01) |-> (A > B)
    );

// Output 10 only occurs when A less than B.
    check_code_10_implies_less: assert property (
        @(posedge clk) disable iff (1'b0) (C == 2'b10) |-> (A < B)
    );

// Output must never be 11.
    check_output_not_11: assert property (
        @(posedge clk) disable iff (1'b0) (C != 2'b11)
    );

// When A != B, output must not be 00.
    check_neq_implies_not_00: assert property (
        @(posedge clk) disable iff (1'b0) (A != B) |-> (C != 2'b00)
    );

endmodule

