module sky130_fd_sc_hvl__nand3_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C
);

// When all inputs are 1, Y must be 0 (NAND3 truth).
    check_all_ones_drives_low: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && C == 1'b1) |-> (Y == 1'b0)
    );

// If A is 0, Y must be 1 (NAND3 truth).
    check_a_zero_forces_high: assert property (
        @(posedge clk) (A == 1'b0) |-> (Y == 1'b1)
    );

// If B is 0, Y must be 1 (NAND3 truth).
    check_b_zero_forces_high: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == 1'b1)
    );

// If C is 0, Y must be 1 (NAND3 truth).
    check_c_zero_forces_high: assert property (
        @(posedge clk) (C == 1'b0) |-> (Y == 1'b1)
    );

// Y can be 0 only when A, B, and C are all 1.
    check_only_low_if_all_ones: assert property (
        @(posedge clk) (Y == 1'b0) |-> (A == 1'b1 && B == 1'b1 && C == 1'b1)
    );

// If Y is 1, not all inputs are 1.
    check_high_implies_not_all_ones: assert property (
        @(posedge clk) (Y == 1'b1) |-> !((A == 1'b1) && (B == 1'b1) && (C == 1'b1))
    );

// A falling edge on Y implies all inputs are 1 now.
    check_y_fall_requires_all_ones: assert property (
        @(posedge clk) $fell(Y) |-> (A == 1'b1 && B == 1'b1 && C == 1'b1)
    );

// A rising edge on Y implies at least one input is 0 now.
    check_y_rise_requires_any_zero: assert property (
        @(posedge clk) $rose(Y) |-> (A == 1'b0 || B == 1'b0 || C == 1'b0)
    );

endmodule

module dff_async_reset_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic q
);

// Q matches previous D on cycles following a non-reset cycle.
    check_capture_from_d_prev_not_reset: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) == 1'b1) |-> (q == $past(d))
    );

// Q is 0 on any cycle immediately following a cycle with reset low.
    check_q_zero_after_prev_reset_low: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) == 1'b0) |-> (q == 1'b0)
    );

// Rising edge on D with reset high drives Q to 1 on the next clock.
    check_d_rise_sets_q_next: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && $rose(d)) |=> (q == 1'b1)
    );

// Falling edge on D with reset high drives Q to 0 on the next clock.
    check_d_fall_clears_q_next: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && $fell(d)) |=> (q == 1'b0)
    );

// When reset high and D equals current Q, Q holds its value next cycle.
    check_q_holds_when_d_equals_q: assert property (
        @(posedge clk) disable iff (!reset)
            (reset && (d == q)) |=> (q == $past(q))
    );

// With no reset over two cycles and stable D, Q remains stable across cycles.
    check_q_stable_when_d_stable: assert property (
        @(posedge clk) disable iff (!reset)
            (($past(reset) == 1'b1) && (reset == 1'b1) && (d == $past(d))) |=> (q == $past(q))
    );

endmodule

