module magnitude_comparator (
    input [3:0] A,
    input [3:0] B,
    output reg greater_or_equal
);

  always @ (A, B) begin
    if (A >= B) begin
      greater_or_equal <= 1;
    end else begin
      greater_or_equal <= 0;
    end
  end

endmodule

