module MUX21 (A, B, Sel, Z);
input A;
input B;
input Sel;
output Z;

  reg Z;

  always @ (A, B, Sel)
    begin
      if (Sel == 0)
        Z = A;
      else
        Z = B;
    end

endmodule

sva:
module MUX21_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic Sel,
    input logic Z
);

// Z equals selected input based on Sel each cycle.
    check_mux_function: assert property (
        @(posedge CLK) Z == (Sel ? B : A)
    );

// When Sel is 0, Z must equal A.
    check_sel0_mapping: assert property (
        @(posedge CLK) (Sel == 1'b0) |-> (Z == A)
    );

// When Sel is 1, Z must equal B.
    check_sel1_mapping: assert property (
        @(posedge CLK) (Sel == 1'b1) |-> (Z == B)
    );

// On Sel rising edge, Z reflects B in the same cycle.
    check_rose_sel_selects_B: assert property (
        @(posedge CLK) $rose(Sel) |-> (Z == B)
    );

// On Sel falling edge, Z reflects A in the same cycle.
    check_fell_sel_selects_A: assert property (
        @(posedge CLK) $fell(Sel) |-> (Z == A)
    );

endmodule

rtl:
module value_converter(
  input [3:0] input_val,
  output reg [2:0] output_val
);

always @(*) begin
  case(input_val)
    4'd5, 4'd6: output_val = 3'd7;
    default: output_val = input_val[2:0];
  endcase
end

endmodule

sva:
module value_converter_sva (
    // DUT ports
    input logic [3:0] input_val,
    input logic [2:0] output_val,
    // Sampling clock for SVA (DUT has no clock/reset; purely combinational)
    input logic clk
);

// Output equals 7 for input 5 or 6; else equals input[2:0].
    check_output_functional_mapping: assert property (
        @(posedge clk) output_val == (((input_val == 4'd5) || (input_val == 4'd6)) ? 3'd7 : input_val[2:0])
    );

// When input is 5 or 6, output must be 7.
    check_special_cases_to_7: assert property (
        @(posedge clk) ((input_val == 4'd5) || (input_val == 4'd6)) |-> (output_val == 3'd7)
    );

// For inputs other than 5 or 6, output must equal input[2:0].
    check_default_passthrough: assert property (
        @(posedge clk) !((input_val == 4'd5) || (input_val == 4'd6)) |-> (output_val == input_val[2:0])
    );

endmodule

rtl:
module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire sel1_not, sel0_not;
    assign sel1_not = ~sel[1];
    assign sel0_not = ~sel[0];

    wire w0, w1, w2, w3;
    assign w0 = in[0] & sel0_not & sel1_not;
    assign w1 = in[1] & sel0_not & sel[1];
    assign w2 = in[2] & sel[0] & sel1_not;
    assign w3 = in[3] & sel[0] & sel[1];

    assign out = w0 | w1 | w2 | w3;

endmodule

sva:
module mux4to1_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);

// For sel=00, out mirrors in[0].
    check_sel_00: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// For sel=11, out mirrors in[3].
    check_sel_11: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Structural equivalence to the sum-of-products implementation.
    check_structural_equivalence: assert property (
        @(posedge clk)
            out == ((in[0] & ~sel[0] & ~sel[1]) |
                    (in[1] & ~sel[0] &  sel[1]) |
                    (in[2] &  sel[0] & ~sel[1]) |
                    (in[3] &  sel[0] &  sel[1]))
    );

// If all inputs are 0, out must be 0.
    check_zero_inputs_zero_out: assert property (
        @(posedge clk) (in == 4'b0000) |-> (out == 1'b0)
    );

// If all inputs are 1, out must be 1.
    check_allones_inputs_one_out: assert property (
        @(posedge clk) (in == 4'b1111) |-> (out == 1'b1)
    );

endmodule

rtl:
module decoder_3to8 (
    input A,
    input B,
    input C,
    output reg Y0,
    output reg Y1,
    output reg Y2,
    output reg Y3,
    output reg Y4,
    output reg Y5,
    output reg Y6,
    output reg Y7
);

always @ (A or B or C) begin
    Y0 = ~(A | B | C);
    Y1 = ~(A | B | ~C);
    Y2 = ~(A | ~B | C);
    Y3 = ~(A | ~B | ~C);
    Y4 = ~(~A | B | C);
    Y5 = ~(~A | B | ~C);
    Y6 = ~(~A | ~B | C);
    Y7 = ~(~A | ~B | ~C);
end

endmodule

sva:
module decoder_3to8_sva (
    // DUT ports
    input logic A,
    input logic B,
    input logic C,
    input logic Y0,
    input logic Y1,
    input logic Y2,
    input logic Y3,
    input logic Y4,
    input logic Y5,
    input logic Y6,
    input logic Y7,
    // Sampling clock for SVA (RTL has no clock/reset)
    input logic clk
);

// No clock/reset in RTL; assertions are sampled on clk without reset gating.
    // Purely combinational 3-to-8 decoder: Y[i] is one-hot minterm of A,B,C.

    // Y0 equals ~(A | B | C)
    check_y0_definition: assert property (
        @(posedge clk) Y0 == ~(A | B | C)
    );

// Y1 equals ~(A | B | ~C)
    check_y1_definition: assert property (
        @(posedge clk) Y1 == ~(A | B | ~C)
    );

// Y2 equals ~(A | ~B | C)
    check_y2_definition: assert property (
        @(posedge clk) Y2 == ~(A | ~B | C)
    );

// Y3 equals ~(A | ~B | ~C)
    check_y3_definition: assert property (
        @(posedge clk) Y3 == ~(A | ~B | ~C)
    );

// Y4 equals ~(~A | B | C)
    check_y4_definition: assert property (
        @(posedge clk) Y4 == ~(~A | B | C)
    );

// Y5 equals ~(~A | B | ~C)
    check_y5_definition: assert property (
        @(posedge clk) Y5 == ~(~A | B | ~C)
    );

// Y6 equals ~(~A | ~B | C)
    check_y6_definition: assert property (
        @(posedge clk) Y6 == ~(~A | ~B | C)
    );

// Y7 equals ~(~A | ~B | ~C)
    check_y7_definition: assert property (
        @(posedge clk) Y7 == ~(~A | ~B | ~C)
    );

// Exactly one output is HIGH for any A,B,C
    check_onehot_outputs: assert property (
        @(posedge clk) $onehot({Y7,Y6,Y5,Y4,Y3,Y2,Y1,Y0})
    );

// Outputs cover all cases (OR of all Y is 1)
    check_outputs_cover_all: assert property (
        @(posedge clk) (|{Y7,Y6,Y5,Y4,Y3,Y2,Y1,Y0}) == 1'b1
    );

endmodule

