);

// While rst is asserted, the following cycle's count is 0 (synchronous reset).
    check_zero_during_reset: assert property (
        @(posedge clk) rst |=> (count == 8'h00)
    );

endmodule

rtl:
module parity_generator (
  input in1,
  input in2,
  input in3,
  input in4,
  output reg parity
);

  always @ (in1, in2, in3, in4) begin
    if ((in1 + in2 + in3 + in4) % 2 == 0)
      parity <= 0;
    else
      parity <= 1;
  end

endmodule

sva:
module parity_generator_sva (
    input logic CLK,       // External sampling clock for SVA
    input logic RESETn,    // External active-low reset for SVA gating
    input logic in1,
    input logic in2,
    input logic in3,
    input logic in4,
    input logic parity
);

///// Functional parity checks /////
    // Parity equals XOR of inputs (odd parity).
    check_parity_matches_xor: assert property (
        @(posedge CLK) disable iff (!RESETn) parity == (in1 ^ in2 ^ in3 ^ in4)
    );

// Exactly one input HIGH implies parity HIGH.
    check_onehot_high: assert property (
        @(posedge CLK) disable iff (!RESETn) $onehot({in1,in2,in3,in4}) |-> (parity == 1'b1)
    );

// Exactly two inputs HIGH implies parity LOW.
    check_two_high_low: assert property (
        @(posedge CLK) disable iff (!RESETn) ((in1 + in2 + in3 + in4) == 2) |-> (parity == 1'b0)
    );

// Exactly three inputs HIGH implies parity HIGH.
    check_three_high: assert property (
        @(posedge CLK) disable iff (!RESETn) ((in1 + in2 + in3 + in4) == 3) |-> (parity == 1'b1)
    );

// All inputs equal (all 0 or all 1) implies parity LOW.
    check_all_equal_low: assert property (
        @(posedge CLK) disable iff (!RESETn) ((in1 == in2) && (in2 == in3) && (in3 == in4)) |-> (parity == 1'b0)
    );

endmodule

rtl:
module rotator_mux(
    input clk,
    input load,
    input [1:0] ena,
    input [99:0] data,
    input [2:0] sel, 
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    output reg [7:0] out);

    reg [99:0] shift_reg;
    reg [7:0] mux_out;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= data;
        end else if (ena[0]) begin
            shift_reg <= {shift_reg[98:0], shift_reg[99]};
        end else if (ena[1]) begin
            shift_reg <= {shift_reg[0], shift_reg[98:1]};
        end
    end

    always @* begin
        case (sel)
            3'b000: mux_out = data0;
            3'b001: mux_out = data1;
            3'b010: mux_out = data2;
            3'b011: mux_out = data3;
            3'b100: mux_out = data4;
            3'b101: mux_out = data5;
            default: mux_out = 8'b0;
        endcase
    end

    always @* begin
        case (ena)
            2'b00: out = mux_out;
            2'b01: out = {mux_out[3:0], mux_out[3:0]};
            2'b10: out = {mux_out[7:4], mux_out[3:0]};
            2'b11: out = {mux_out[7:4], mux_out[3:0]};
            default: out = 8'b0;
        endcase
    end

endmodule

