  input [3:0] in2,
  output reg [1:0] out
);

  always @ (in1, in2) begin
    if (in1 == in2) begin
      out <= 2'b00;
    end else if (in1 > in2) begin
      out <= 2'b01;
    end else begin
      out <= 2'b10;
    end
  end

