module top_module(
  input [31:0] a,
  input [31:0] b,
  output [31:0] sum
);
  wire cin;
  wire cout;

  // Carry select adder
  adder32 adder(
    .a(a),
    .b(b),
    .cin(cin),
    .sum(sum),
    .cout(cout)
  );

  assign cin = 1'b0;
endmodule

