// When C_N is 1, X must be 1.
    check_cn_dominates: assert property (
        @(posedge CLK) C_N |-> (X == 1'b1)
    );

// When C_N is 0, X must equal A & B.
    check_cn0_means_and: assert property (
        @(posedge CLK) (!C_N) |-> (X == (A & B))
    );

// When C_N is 0 and A is 0, X must be 0.
    check_cn0_a0_forces_x0: assert property (
        @(posedge CLK) (!C_N && !A) |-> (X == 1'b0)
    );

// When C_N is 0 and B is 0, X must be 0.
    check_cn0_b0_forces_x0: assert property (
        @(posedge CLK) (!C_N && !B) |-> (X == 1'b0)
    );

// When both A and B are 1, X must be 1.
    check_ab_high_implies_x1: assert property (
        @(posedge CLK) (A && B) |-> (X == 1'b1)
    );

// If X is 1, then at least one of A, B, or C_N is 1.
    check_x_implies_any_input_or_cn: assert property (
        @(posedge CLK) X |-> (A | B | C_N)
    );

// If X is 1, then A or C_N must be 1.
    check_x_implies_a_or_cn: assert property (
        @(posedge CLK) X |-> (A | C_N)
    );

// If X is 1, then B or C_N must be 1.
    check_x_implies_b_or_cn: assert property (
        @(posedge CLK) X |-> (B | C_N)
    );

endmodule

rtl:
module sky130_fd_sc_hdll__xor2b (
    input  A,
    input  B,
    input  C,
    output X
);

    wire  A_xor_B;
    wire  A_or_B;

    assign A_xor_B = A ^ B;
    assign A_or_B  = A | B;

    assign X = (C == 1'b1) ? A_xor_B : A_or_B;

endmodule

sva:
module sky130_fd_sc_hdll__xor2b_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X
);

// X matches the RTL equation: C ? (A^B) : (A|B)
    check_function_equation: assert property (
        @(posedge clk) X == (C ? (A ^ B) : (A | B))
    );

// When C is 1, X is A xor B
    check_select_high_is_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (X == (A ^ B))
    );

// When C is 0, X is A or B
    check_select_low_is_or: assert property (
        @(posedge clk) (C == 1'b0) |-> (X == (A | B))
    );

// With C=0 and A==B, X equals A
    check_c_low_equal_inputs_pass_through: assert property (
        @(posedge clk) (C == 1'b0) && (A == B) |-> (X == A)
    );

// If A=0 and B=0, X must be 0
    check_both_zero_results_zero: assert property (
        @(posedge clk) (A == 1'b0) && (B == 1'b0) |-> (X == 1'b0)
    );

// If A=1, B=1, and C=1, then X must be 0
    check_both_one_c_high_results_zero: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) && (C == 1'b1) |-> (X == 1'b0)
    );

// If A=1, B=1, and C=0, then X must be 1
    check_both_one_c_low_results_one: assert property (
        @(posedge clk) (A == 1'b1) && (B == 1'b1) && (C == 1'b0) |-> (X == 1'b1)
    );

// With C=1, differing inputs imply X=1
    check_c_high_inputs_differ_results_one: assert property (
        @(posedge clk) (C == 1'b1) && (A != B) |-> (X == 1'b1)
    );

// With C=1, equal inputs imply X=0
    check_c_high_inputs_equal_results_zero: assert property (
        @(posedge clk) (C == 1'b1) && (A == B) |-> (X == 1'b0)
    );

// With C=0, any input high implies X=1
    check_c_low_any_one_results_one: assert property (
        @(posedge clk) (C == 1'b0) && ((A == 1'b1) || (B == 1'b1)) |-> (X == 1'b1)
    );

endmodule

rtl:
module mux_2to1(
    input in0,
    input in1,
    input sel,
    output out
);

    wire not_sel;
    assign not_sel = ~sel;

    assign out = (in0 & not_sel) | (in1 & sel);

endmodule

sva:
module mux_2to1_sva (
    input logic clk,   // Sampling clock for assertions (RTL has no clock/reset)
    input logic in0,
    input logic in1,
    input logic sel,
    input logic out
);

// Function: out implements a 2:1 mux: out = (in0 & ~sel) | (in1 & sel).
    check_mux_equation: assert property (
        @(posedge clk) out == ((in0 & ~sel) | (in1 & sel))
    );

// When sel=0, out equals in0.
    check_sel0_path: assert property (
        @(posedge clk) (!sel) |-> (out == in0)
    );

// When sel=1, out equals in1.
    check_sel1_path: assert property (
        @(posedge clk) (sel) |-> (out == in1)
    );

// If inputs are equal, out matches that value.
    check_equal_inputs_passthrough: assert property (
        @(posedge clk) (in0 == in1) |-> (out == in0)
    );

// On sel rising edge, out immediately selects in1.
    check_sel_rise_selects_in1: assert property (
        @(posedge clk) $rose(sel) |-> (out == in1)
    );

// On sel falling edge, out immediately selects in0.
    check_sel_fall_selects_in0: assert property (
        @(posedge clk) $fell(sel) |-> (out == in0)
    );

endmodule

rtl:
module counter (
    input CLK,
    input RST,
    output reg [3:0] Q
);

    always @(posedge CLK) begin
        if (RST) begin
            Q <= 4'b0;
        end else begin
            Q <= Q + 1;
        end
    end

endmodule

sva:
module counter_sva (
    input logic CLK,
    input logic RST,
    input logic [3:0] Q
);

///// Reset behavior /////
    // When RST is high, Q must be 0 on the next cycle.
    check_reset_clears_Q_next: assert property (
        @(posedge CLK) RST |=> (Q == 4'h0)
    );

// If RST is high in two consecutive cycles, Q must be 0 in the second cycle.
    check_Q_zero_while_reset_held: assert property (
        @(posedge CLK) (RST && $past(RST)) |-> (Q == 4'h0)
    );

// On a rising edge of RST, Q must be 0 on the next cycle.
    check_next_after_reset_assert_zero: assert property (
        @(posedge CLK) $rose(RST) |=> (Q == 4'h0)
    );

// When not in reset, Q must change every cycle (no hold).
    check_counter_advances_each_cycle: assert property (
        @(posedge CLK) disable iff (RST) 1'b1 |=> (Q != $past(Q))
    );

// When not in reset and Q is 0xF, it wraps to 0 on the next cycle.
    check_wrap_from_max_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hF) |=> (Q == 4'h0)
    );

// When not in reset and Q is 0xE, it becomes 0xF on the next cycle.
    check_increment_from_E_to_F_when_not_reset: assert property (
        @(posedge CLK) disable iff (RST) (Q == 4'hE) |=> (Q == 4'hF)
    );

endmodule

module d_flip_flop_as_sva (
  input logic clk,
  input logic as,
  input logic [7:0] d,
  input logic [7:0] q
);

// Clock: clk (posedge). No explicit reset. q updates to d when as==0; holds when as==1.

  // When as is LOW, q captures d on the next clock.
  check_load_on_as_low: assert property (
    @(posedge clk) (~as) |=> (q == $past(d))
  );

// When as is HIGH, q holds its previous value on the next clock.
  check_hold_when_as_high: assert property (
    @(posedge clk) (as) |=> (q == $past(q))
  );

// If as is LOW and d differs from current q, q must change next cycle.
  check_update_changes_when_data_diff: assert property (
    @(posedge clk) (~as && (d != q)) |=> (q != $past(q))
  );

// If as is LOW and d equals current q, q must not change next cycle.
  check_update_no_change_when_data_same: assert property (
    @(posedge clk) (~as && (d == q)) |=> (q == $past(q))
  );

// While holding (as HIGH), changes on d do not affect q.
  check_data_changes_do_not_affect_when_as_high: assert property (
    @(posedge clk) (as && $changed(d)) |=> (q == $past(q))
  );

// On a falling edge of as, q captures d on the next clock.
  check_fall_as_triggers_update: assert property (
    @(posedge clk) $fell(as) |=> (q == $past(d))
  );

// On a rising edge of as, q must hold on the next clock.
  check_rise_as_holds_value: assert property (
    @(posedge clk) $rose(as) |=> (q == $past(q))
  );

endmodule

rtl:
module bram_controller(clk, reset, btn, wea, addra);

  input wire clk, reset, btn;
  output reg wea;
  output reg [3:0] addra;

  localparam [1:0]
  idle = 2'b00,
  leer = 2'b01,
  fin  = 2'b10;

  reg [1:0] state_reg;
  reg [3:0] counter;

  always@(posedge clk, posedge reset)
    if(reset)
      begin
        addra<=0;
        counter<=0;	
        state_reg<=idle;
        wea<=0;
      end
  else begin

    case(state_reg)

      idle:
        if(btn==1'b1)begin
          state_reg<=leer;
        end

      leer:
        begin
          wea<=0;
          counter<=counter+1'b1;
          state_reg<=fin;
        end

      fin:begin

        addra<=addra+1'b1;
        if(counter==4'b1111)begin
          counter<=0;
        end
        state_reg<=idle;
      end	

    endcase
  end

endmodule

sva:
module bram_controller_sva (
    input logic clk,
    input logic reset,
    input logic btn,
    input logic wea,
    input logic [3:0] addra,
    input logic [1:0] state_reg,
    input logic [3:0] counter
);

///// WEA behavior /////
    // WEA is always 0 after reset.
    check_wea_const_zero: assert property (
        @(posedge clk) disable iff (reset)
            wea == 1'b0
    );

endmodule

module Cfu_sva (
  input logic               cmd_valid,
  input logic               cmd_ready,
  input logic [9:0]         cmd_payload_function_id,
  input logic [31:0]        cmd_payload_inputs_0,
  input logic [31:0]        cmd_payload_inputs_1,
  input logic               rsp_valid,
  input logic               rsp_ready,
  input logic [31:0]        rsp_payload_outputs_0,
  input logic               reset,
  input logic               clk
);

// rsp_valid must mirror cmd_valid each cycle.
    check_rsp_valid_mirror: assert property (
        @(posedge clk) disable iff (reset) (rsp_valid == cmd_valid)
    );

// cmd_ready must mirror rsp_ready each cycle.
    check_cmd_ready_mirror: assert property (
        @(posedge clk) disable iff (reset) (cmd_ready == rsp_ready)
    );

// When select=0, output routes inputs_0.
    mux_select0_routes_in0: assert property (
        @(posedge clk) disable iff (reset) (!cmd_payload_function_id[0]) |-> (rsp_payload_outputs_0 == cmd_payload_inputs_0)
    );

// When select=1, output routes inputs_1.
    mux_select1_routes_in1: assert property (
        @(posedge clk) disable iff (reset) (cmd_payload_function_id[0]) |-> (rsp_payload_outputs_0 == cmd_payload_inputs_1)
    );

// Output equals the ternary mux of select and inputs.
    mux_function_equivalence: assert property (
        @(posedge clk) disable iff (reset) (rsp_payload_outputs_0 == (cmd_payload_function_id[0] ? cmd_payload_inputs_1 : cmd_payload_inputs_0))
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] data,
    input [1:0] shift_amount,
    output reg [3:0] result
);

always @(*) begin
    case(shift_amount)
        2'b00: result = data;
        2'b01: result = {data[2:0], 1'b0};
        2'b10: result = {data[1:0], 2'b00};
        2'b11: result = 4'b0000;
    endcase
end

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,
    input logic [3:0] data,
    input logic [1:0] shift_amount,
    input logic [3:0] result
);

// Result matches the full case-defined function for all shift_amount values.
    check_function_complete: assert property (
        @(posedge CLK)
            ((shift_amount == 2'b00) && (result == data)) ||
            ((shift_amount == 2'b01) && (result == {data[2:0], 1'b0})) ||
            ((shift_amount == 2'b10) && (result == {data[1:0], 2'b00})) ||
            ((shift_amount == 2'b11) && (result == 4'b0000))
    );

// No shift: result equals data when shift_amount == 2'b00.
    check_no_shift_passthrough: assert property (
        @(posedge CLK) (shift_amount == 2'b00) |-> (result == data)
    );

// Shift by 1: result equals {data[2:0], 1'b0} when shift_amount == 2'b01.
    check_shift1_concat: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result == {data[2:0], 1'b0})
    );

// Shift by 2: result equals {data[1:0], 2'b00} when shift_amount == 2'b10.
    check_shift2_concat: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result == {data[1:0], 2'b00})
    );

// Shift by 3 (2'b11): result is 4'b0000 regardless of data.
    check_shift3_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b11) |-> (result == 4'b0000)
    );

// Shift by 1: LSB is forced to 0.
    check_shift1_lsb_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result[0] == 1'b0)
    );

// Shift by 2: two LSBs are forced to 0.
    check_shift2_lsbs_zero: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result[1:0] == 2'b00)
    );

// Shift by 1: upper bits map to data[2:0].
    check_shift1_upper_map: assert property (
        @(posedge CLK) (shift_amount == 2'b01) |-> (result[3:1] == data[2:0])
    );

// Shift by 2: upper two bits map to data[1:0].
    check_shift2_upper_map: assert property (
        @(posedge CLK) (shift_amount == 2'b10) |-> (result[3:2] == data[1:0])
    );

endmodule

module top_module_sva (
    input logic clk,
    input logic rst_n,
    input logic write_en,
    input logic [7:0] write_addr,
    input logic [3:0] write_data,
    input logic read_en,
    input logic [7:0] read_addr,
    input logic [3:0] mux_in_0,
    input logic [3:0] mux_in_1,
    input logic [3:0] mux_in_2,
    input logic [3:0] mux_in_3,
    input logic [1:0] mux_sel,
    input logic [3:0] out
);

// During reset, out must be cleared to 0.
    check_reset_clears_out: assert property (
        @(posedge clk) !rst_n |-> (out == 4'b0000)
    );

// When read_en is LOW, out holds its previous value.
    check_out_holds_without_read: assert property (
        @(posedge clk) disable iff (!rst_n) (!read_en) |=> (out == $past(out))
    );

// With read_en HIGH and mux_sel==01, out captures mux_in_0 on next cycle.
    check_read_sel_01_routes_mux_in_0: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b01)) |=> (out == $past(mux_in_0))
    );

// With read_en HIGH and mux_sel==10, out captures mux_in_1 on next cycle.
    check_read_sel_10_routes_mux_in_1: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b10)) |=> (out == $past(mux_in_1))
    );

// With read_en HIGH and mux_sel==11, out captures mux_in_2 on next cycle.
    check_read_sel_11_routes_mux_in_2: assert property (
        @(posedge clk) disable iff (!rst_n) (read_en && (mux_sel == 2'b11)) |=> (out == $past(mux_in_2))
    );

endmodule

rtl:
module sky130_fd_sc_hdll__o21ba (
    X   ,
    A1  ,
    A2  ,
    B1_N
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nor0_out  ;
    wire nor1_out_X;

    nor nor0 (nor0_out  , A1, A2         );
    nor nor1 (nor1_out_X, B1_N, nor0_out );
    buf buf0 (X         , nor1_out_X     );

endmodule

sva:
module sky130_fd_sc_hdll__o21ba_sva (
    input  logic CLK,
    input  logic X,
    input  logic A1,
    input  logic A2,
    input  logic B1_N
);

// Functional equivalence: X == (~B1_N) & (A1 | A2).
    check_function_equation: assert property (
        @(posedge CLK) X == ((~B1_N) & (A1 | A2))
    );

// When B1_N is HIGH, X must be LOW.
    check_x_low_when_B1_N_high: assert property (
        @(posedge CLK) (B1_N == 1'b1) |-> (X == 1'b0)
    );

// When both A1 and A2 are LOW, X must be LOW.
    check_x_low_when_A1_A2_low: assert property (
        @(posedge CLK) ((A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// When B1_N is LOW, X equals (A1 | A2).
    check_x_equals_or_under_enable: assert property (
        @(posedge CLK) (B1_N == 1'b0) |-> (X == (A1 | A2))
    );

// If X is HIGH, B1_N must be LOW.
    check_x_high_implies_B1_N_low: assert property (
        @(posedge CLK) (X == 1'b1) |-> (B1_N == 1'b0)
    );

// If X is HIGH, at least one of A1 or A2 must be HIGH.
    check_x_high_implies_A1_or_A2_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A1 || A2)
    );

// If B1_N is LOW and A1 is HIGH, X must be HIGH.
    check_x_high_when_B1_N_low_and_A1_high: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

// If B1_N is LOW and A2 is HIGH, X must be HIGH.
    check_x_high_when_B1_N_low_and_A2_high: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A2 == 1'b1)) |-> (X == 1'b1)
    );

// If B1_N is LOW and both A1 and A2 are LOW, X must be LOW.
    check_x_low_when_enable_and_inputs_low: assert property (
        @(posedge CLK) ((B1_N == 1'b0) && (A1 == 1'b0) && (A2 == 1'b0)) |-> (X == 1'b0)
    );

// If X is LOW, then either B1_N is HIGH or both A1 and A2 are LOW.
    check_x_low_implies_block_or_both_low: assert property (
        @(posedge CLK) (X == 1'b0) |-> (B1_N || ((A1 == 1'b0) && (A2 == 1'b0)))
    );

endmodule

rtl:
module d_latch (
    input GATE,
    input CLK,
    input D,
    output Q
);

    reg q;

    always @(posedge CLK) begin
        if (!GATE) begin
            q <= D;
        end
    end

    assign Q = q;

endmodule

sva:
module d_latch_sva (
    input logic CLK,
    input logic GATE,
    input logic D,
    input logic Q
);

// When GATE is high, Q holds its previous sampled value into the next cycle.
    check_hold_when_gate_high: assert property (
        @(posedge CLK) GATE |=> (Q == $past(Q))
    );

// If GATE is high and D toggles, Q still holds its previous value into the next cycle.
    check_hold_when_gate_high_even_if_d_toggles: assert property (
        @(posedge CLK) (GATE && (D != $past(D))) |=> (Q == $past(Q))
    );

endmodule

rtl:
module mux4to1 (
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

always @(*) begin
  case(sel)
    2'b00: out = in[0];
    2'b01: out = in[1];
    2'b10: out = in[2];
    2'b11: out = in[3];
  endcase
end

endmodule

sva:
module mux4to1_sva (
    input logic clk,        // External clock for sampling assertions (RTL has no clock/reset)
    input logic [3:0] in,
    input logic [1:0] sel,
    input logic out
);

// Out equals the input bit indexed by sel.
    check_out_matches_index: assert property (
        @(posedge clk) out == in[sel]
    );

// When sel==00, out must equal in[0].
    check_sel_00_mapping: assert property (
        @(posedge clk) (sel == 2'b00) |-> (out == in[0])
    );

// When sel==01, out must equal in[1].
    check_sel_01_mapping: assert property (
        @(posedge clk) (sel == 2'b01) |-> (out == in[1])
    );

// When sel==10, out must equal in[2].
    check_sel_10_mapping: assert property (
        @(posedge clk) (sel == 2'b10) |-> (out == in[2])
    );

// When sel==11, out must equal in[3].
    check_sel_11_mapping: assert property (
        @(posedge clk) (sel == 2'b11) |-> (out == in[3])
    );

// Out equals SOP decode of sel and inputs (structural equivalence).
    check_sop_equivalence: assert property (
        @(posedge clk) out ==
            ((~sel[1] & ~sel[0] & in[0]) |
             (~sel[1] &  sel[0] & in[1]) |
             ( sel[1] & ~sel[0] & in[2]) |
             ( sel[1] &  sel[0] & in[3]))
    );

endmodule

rtl:
module my_or_gate (
    X   ,
    A   ,
    B   ,
    C   ,
    D_N ,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A   ;
    input  B   ;
    input  C   ;
    input  D_N ;
