module adder_4bit_carry (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

  wire [3:0] s; // intermediate sum
  wire c1, c2, c3; // intermediate carry signals

  // generate the intermediate sum and carry signals
  full_adder fa0(a[0], b[0], cin, s[0], c1);
  full_adder fa1(a[1], b[1], c1, s[1], c2);
  full_adder fa2(a[2], b[2], c2, s[2], c3);
  full_adder fa3(a[3], b[3], c3, s[3], cout);

  // assign the outputs
  assign sum = s;

endmodule

// full adder module
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

  assign sum = a ^ b ^ cin;
  assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module adder_4bit_carry_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

///// Functional correctness /////
    // Combined {cout,sum} equals arithmetic a + b + cin (5-bit).
    check_addition_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// LSB sum matches XOR of a[0], b[0], and cin.
    check_sum_lsb_xor: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// When inputs are all zero, outputs are zero.
    check_zero_inputs_zero_outputs: assert property (
        @(posedge clk) (a == 4'b0 && b == 4'b0 && cin == 1'b0) |-> (sum == 4'b0 && cout == 1'b0)
    );

// Adding zero on b with cin=0 returns a and no carry.
    check_identity_b_zero_cin_zero: assert property (
        @(posedge clk) (b == 4'b0 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero on a with cin=0 returns b and no carry.
    check_identity_a_zero_cin_zero: assert property (
        @(posedge clk) (a == 4'b0 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

// With b==0, result equals a + cin (proper 5-bit sum).
    check_b_zero_add_cin: assert property (
        @(posedge clk) (b == 4'b0) |-> ({cout, sum} == ({1'b0, a} + cin))
    );

///// Corner cases /////
    // Max operands with cin=0 produce sum=14 and carry=1.
    check_max_plus_zero: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b0) |-> (sum == 4'he && cout == 1'b1)
    );

// Max operands with cin=1 produce sum=15 and carry=1.
    check_max_plus_one: assert property (
        @(posedge clk) (a == 4'hF && b == 4'hF && cin == 1'b1) |-> (sum == 4'hf && cout == 1'b1)
    );

// When a[0]==b[0], LSB of sum equals cin.
    check_lsb_when_a0_eq_b0: assert property (
        @(posedge clk) (a[0] == b[0]) |-> (sum[0] == cin)
    );

endmodule

rtl:
module interrupt(
	input clock,

	input IEN_d,
	input IOF_d,
	input RTI_d,
	input branch_d,
	input IRQ,
	input [11:0] PC,

	output reg branch_ISR,
	output reg [11:0] ISR_adr
	);

	reg [11:0] return_adr;

	reg IEN_reg;
	reg IRQ_reg;
	reg I;

	initial begin
		IEN_reg = 0;
		return_adr = 0;
	end


	always @(posedge clock) begin
		if (IEN_d == 1)
			IEN_reg = 1;
		if (IOF_d == 1)
			IEN_reg = 0;

		if (I == 1) begin
			IEN_reg = 0;
			return_adr = PC;
		end

		IRQ_reg = IRQ;
	end

	always @(*) begin
		I <= IEN_reg & IRQ_reg & ~branch_d;
		if (I == 1) begin
			branch_ISR <= 1;
			ISR_adr <= 12'h1;
		end
		else if (RTI_d == 1) begin
			branch_ISR <= 1;
			ISR_adr <= return_adr;
		end
		else begin
			branch_ISR <= 0;
			ISR_adr <= 0;
		end
	end



endmodule

module top_module (
    input CLK,
    input RST,
    input CLR,
    input LD,
    input [3:0] DATA,
    output reg [4:0] Q
);

reg [3:0] binary_counter;
reg [3:0] async_counter;

always @(posedge CLK) begin
    if (RST) begin
        binary_counter <= 4'b0000;
    end else begin
        binary_counter <= binary_counter + 1;
    end
end

always @(posedge CLK) begin
    if (CLR) begin
        async_counter <= 4'b0000;
    end else if (LD) begin
        async_counter <= DATA;
    end else begin
        async_counter <= async_counter + 1;
    end
end

always @* begin
    Q = binary_counter + async_counter;
end

endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic RST,
    input logic CLR,
    input logic LD,
    input logic [3:0] DATA,
    input logic [4:0] Q
);

///// Combinational output range /////
    // Q is the 5-bit sum of two 4-bit counters; it can never exceed 30.
    check_q_within_valid_range: assert property (
        @(posedge CLK) disable iff (RST) (Q <= 5'd30)
    );

///// Reset and clear interactions (synchronous, active-high) /////
    // If both RST and CLR are HIGH in a cycle, Q must be 0 in the next cycle.
    check_both_resets_force_zero_next: assert property (
        @(posedge CLK) (RST && CLR) |=> (Q == 5'd0)
    );

// If RST is HIGH and CLR is LOW and LD is HIGH, Q loads DATA next cycle.
    check_rst_and_ld_loads_data_next: assert property (
        @(posedge CLK) (RST && !CLR && LD) |=> (Q == $past(DATA))
    );

// If RST is HIGH and CLR is LOW (LD don't care), Q is in 0..15 next cycle.
    check_rst_without_clr_bounds_next: assert property (
        @(posedge CLK) (RST && !CLR) |=> (Q <= 5'd15)
    );

// If CLR is HIGH (regardless of LD), Q is in 0..15 next cycle (RST not asserted).
    check_clr_bounds_next: assert property (
        @(posedge CLK) disable iff (RST) (CLR) |=> (Q <= 5'd15)
    );

// When RST and CLR and LD are all HIGH together, Q still goes to 0 next cycle (CLR priority over LD and RST forces binary_counter to 0).
    check_ld_ignored_when_both_resets: assert property (
        @(posedge CLK) (RST && CLR && LD) |=> (Q == 5'd0)
    );

///// Free-running behavior when no controls are asserted /////
    // With no RST/CLR/LD and Q <= 14, both 4-bit counters increment without wrap so Q increases by 2 next cycle.
    check_increment_by_two_when_small: assert property (
        @(posedge CLK) disable iff (RST)
            (!RST && !CLR && !LD && (Q <= 5'd14)) |=> (Q == ($past(Q) + 5'd2))
    );

// With two consecutive cycles of no RST/CLR/LD and Q <= 13 at the first, Q increases by 4 after two cycles (no wrap in either counter).
    check_two_cycle_increment_when_small: assert property (
        @(posedge CLK) disable iff (RST)
            ((!RST && !CLR && !LD && (Q <= 5'd13)) ##1 (!RST && !CLR && !LD)) |=> (Q == ($past(Q, 2) + 5'd4))
    );

///// Persistence under sustained resets /////
    // If both RST and CLR hold HIGH for two consecutive cycles, Q remains 0 one cycle later as well.
    check_zero_persists_while_both_resets_hold: assert property (
        @(posedge CLK) ((RST && CLR) ##1 (RST && CLR)) |=> (Q == 5'd0)
    );

endmodule

