module dffc_6 ( clk, reset, d, q );
	input clk;
	input reset;
	input [5:0] d;
	output [5:0] q;
	reg [5:0] q;

	always @(posedge clk or negedge reset) begin
		if (!reset) begin
			q <= 6'b0;
		end
		else begin
			q <= d;
		end
	end
endmodule

sva:
module dffc_6_sva (
    input logic clk,
    input logic reset,
    input logic [5:0] d,
    input logic [5:0] q
);

// q must be 0 whenever reset is asserted (active-low).
    check_reset_forces_zero: assert property (
        @(posedge clk) (reset == 1'b0) |-> (q == 6'b0)
    );

// On a falling edge of reset, q is 0 at this clock sample.
    check_zero_on_reset_fall_sample: assert property (
        @(posedge clk) $fell(reset) |-> (q == 6'b0)
    );

// On a rising edge of reset, q is 0 at this clock sample.
    check_zero_on_reset_rise_sample: assert property (
        @(posedge clk) $rose(reset) |-> (q == 6'b0)
    );

// With reset high in consecutive cycles, q equals last cycle's d.
    check_capture_d_when_reset_high: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> (q == $past(d))
    );

// First clock after reset release captures the d value from the release cycle.
    check_first_cycle_after_release_captures_d: assert property (
        @(posedge clk) disable iff (!reset) $rose(reset) |-> ##1 (q == $past(d))
    );

// If d held constant over the last two cycles (no reset), q does not change.
    check_stability_when_d_unchanged: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset,2) && $past(reset) && ($past(d) == $past(d,2))) |-> (q == $past(q))
    );

// If q changes (no reset), the change was caused by a change in d in the prior cycle.
    check_q_change_requires_d_change: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset,2) && $past(reset) && (q != $past(q))) |-> ($past(d) != $past(d,2))
    );

// When reset is high, next cycle's q equals this cycle's d (if reset stays high).
    check_next_cycle_captures_d_when_reset_high: assert property (
        @(posedge clk) disable iff (!reset) reset |-> ##1 (q == $past(d))
    );

endmodule

rtl:
module sync_merge (
    input wire r1,
    input wire r2,
    input wire a1,
    input wire a2,
    output reg r0,
    output reg a0
);

    always @(*) begin
        if (r1 == 1'b0 && r2 == 1'b0) begin
            r0 = 1'b0;
            a0 = 1'b0;
        end else if (r1 == 1'b1 && r2 == 1'b0) begin
            r0 = 1'b1;
            a0 = a1;
        end else if (r1 == 1'b0 && r2 == 1'b1) begin
            r0 = 1'b1;
            a0 = a2;
        end else if (r1 == 1'b1 && r2 == 1'b1) begin
            r0 = 1'b0;
            a0 = 1'b0;
        end
    end

endmodule

sva:
module sync_merge_sva (
    input logic clk,
    input logic r1,
    input logic r2,
    input logic a1,
    input logic a2,
    input logic r0,
    input logic a0
);

// r0 is XOR of r1 and r2.
    check_r0_xor: assert property (
        @(posedge clk) r0 == (r1 ^ r2)
    );

// When both r1 and r2 are LOW, outputs are LOW.
    check_both_low_behavior: assert property (
        @(posedge clk) (r1 == 1'b0 && r2 == 1'b0) |-> (r0 == 1'b0 && a0 == 1'b0)
    );

// When only r1 is HIGH, r0 is HIGH and a0 passes a1.
    check_r1_only_behavior: assert property (
        @(posedge clk) (r1 == 1'b1 && r2 == 1'b0) |-> (r0 == 1'b1 && a0 == a1)
    );

// When only r2 is HIGH, r0 is HIGH and a0 passes a2.
    check_r2_only_behavior: assert property (
        @(posedge clk) (r1 == 1'b0 && r2 == 1'b1) |-> (r0 == 1'b1 && a0 == a2)
    );

// When both r1 and r2 are HIGH, outputs are LOW.
    check_both_high_behavior: assert property (
        @(posedge clk) (r1 == 1'b1 && r2 == 1'b1) |-> (r0 == 1'b0 && a0 == 1'b0)
    );

// If r0 is LOW, a0 must be LOW.
    check_r0_low_implies_a0_low: assert property (
        @(posedge clk) (r0 == 1'b0) |-> (a0 == 1'b0)
    );

// a0 can be HIGH only when exactly one request is HIGH.
    check_a0_high_only_if_one_req: assert property (
        @(posedge clk) (a0 == 1'b1) |-> (r1 ^ r2)
    );

// On r1 rising when r2 is LOW, r0 is HIGH and a0 passes a1.
    check_rise_r1_when_r2_low: assert property (
        @(posedge clk) ($rose(r1) && (r2 == 1'b0)) |-> (r0 == 1'b1 && a0 == a1)
    );

// On r2 rising when r1 is LOW, r0 is HIGH and a0 passes a2.
    check_rise_r2_when_r1_low: assert property (
        @(posedge clk) ($rose(r2) && (r1 == 1'b0)) |-> (r0 == 1'b1 && a0 == a2)
    );

// On r1 falling when r2 is HIGH, r0 is HIGH and a0 passes a2.
    check_fall_r1_when_r2_high: assert property (
        @(posedge clk) ($fell(r1) && (r2 == 1'b1)) |-> (r0 == 1'b1 && a0 == a2)
    );

endmodule

rtl:
module adder_4bit(
  input [3:0] A,
  input [3:0] B,
  input S,
  output [3:0] C
);

  assign C = S ? A - B : A + B;

endmodule

sva:
module adder_4bit_sva (
    input logic clk,           // External clock for sampling assertions
    input logic [3:0] A,
    input logic [3:0] B,
    input logic S,
    input logic [3:0] C
);

///// Functional correctness /////
    // When S==0, C must equal A + B (4-bit wrap).
    check_add_mode_correct: assert property (
        @(posedge clk) (S == 1'b0) |-> (C == (A + B))
    );

// When S==1, C must equal A - B (4-bit wrap).
    check_sub_mode_correct: assert property (
        @(posedge clk) (S == 1'b1) |-> (C == (A - B))
    );

///// X-propagation /////
    // If A,B,S are all known (no X/Z), then C must be known.
    check_known_output_with_known_inputs: assert property (
        @(posedge clk) (!$isunknown({A,B,S})) |-> (!$isunknown(C))
    );

///// Algebraic identities (direct consequences of + and -) /////
    // In add mode, adding zero B passes A through.
    check_add_zero_B_passthru: assert property (
        @(posedge clk) (S == 1'b0 && B == 4'h0) |-> (C == A)
    );

// In add mode, adding zero A passes B through.
    check_add_zero_A_passthru: assert property (
        @(posedge clk) (S == 1'b0 && A == 4'h0) |-> (C == B)
    );

// In sub mode, subtracting zero B passes A through.
    check_sub_zero_B_passthru: assert property (
        @(posedge clk) (S == 1'b1 && B == 4'h0) |-> (C == A)
    );

// In sub mode, subtracting equal operands yields zero.
    check_sub_equal_inputs_zero: assert property (
        @(posedge clk) (S == 1'b1 && A == B) |-> (C == 4'h0)
    );

endmodule

rtl:
module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT,
    output reg LT
);

    always @(*) begin
        if (A == B) begin
            EQ = 1;
            GT = 0;
            LT = 0;
        end else if (A > B) begin
            EQ = 0;
            GT = 1;
            LT = 0;
        end else begin
            EQ = 0;
            GT = 0;
            LT = 1;
        end
    end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic EQ,
    input logic GT,
    input logic LT
);

// No clock/reset in DUT; combinational. Assertions sample on external clk with no reset gating.
    // Behavior: EQ iff A==B, GT iff A>B, LT iff A<B; exactly one output is HIGH.

    // Outputs EQ and GT are mutually exclusive.
    check_mutex_eq_gt: assert property (
        @(posedge clk) !(EQ && GT)
    );

// Outputs EQ and LT are mutually exclusive.
    check_mutex_eq_lt: assert property (
        @(posedge clk) !(EQ && LT)
    );

// Outputs GT and LT are mutually exclusive.
    check_mutex_gt_lt: assert property (
        @(posedge clk) !(GT && LT)
    );

// At least one of EQ/GT/LT must be HIGH.
    check_not_all_zero: assert property (
        @(posedge clk) (EQ || GT || LT)
    );

// When A equals B, outputs reflect equality.
    check_map_equal: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

// When A is greater than B, outputs reflect greater-than.
    check_map_greater: assert property (
        @(posedge clk) (A > B) |-> (!EQ && GT && !LT)
    );

// When A is less than B, outputs reflect less-than.
    check_map_less: assert property (
        @(posedge clk) (A < B) |-> (!EQ && !GT && LT)
    );

// If EQ is HIGH, inputs must be equal.
    check_eq_implies_relation: assert property (
        @(posedge clk) EQ |-> (A == B)
    );

// If GT is HIGH, A must be greater than B.
    check_gt_implies_relation: assert property (
        @(posedge clk) GT |-> (A > B)
    );

// If LT is HIGH, A must be less than B.
    check_lt_implies_relation: assert property (
        @(posedge clk) LT |-> (A < B)
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic up_down,
    input logic reset,
    input logic [3:0] q
