// On a clock where reset=1, q must be 0 on the next clock.
    check_reset_to_zero_next: assert property (
        @(posedge clk) reset |=> (q == 4'd0)
    );

// While reset is held high across clocks, q stays 0.
    check_reset_held_forces_zero: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (q == 4'd0)
    );

endmodule

rtl:
module adder (
    input [15:0] A,
    input [15:0] B,
    input CIN,
    output [15:0] SUM,
    output COUT
);

    assign {COUT, SUM} = A + B + CIN;

endmodule

sva:
module adder_sva (
    input logic CLK,
    input logic [15:0] A,
    input logic [15:0] B,
    input logic CIN,
    input logic [15:0] SUM,
    input logic COUT
);

///// Functional equivalence to RTL /////
    // SUM equals the 16-bit truncated result of A + B + CIN.
    check_sum_matches_add: assert property (
        @(posedge CLK) SUM == (A + B + CIN)
    );

///// Basic pass-through scenarios /////
    // With B==0 and CIN==0, SUM passes A and COUT stays zero.
    check_pass_through_a: assert property (
        @(posedge CLK) (B == 16'h0000) && (CIN == 1'b0) |-> (SUM == A) && (COUT == 1'b0)
    );

// With A==0 and CIN==0, SUM passes B and COUT stays zero.
    check_pass_through_b: assert property (
        @(posedge CLK) (A == 16'h0000) && (CIN == 1'b0) |-> (SUM == B) && (COUT == 1'b0)
    );

// With A==0 and B==0, SUM equals CIN and COUT stays zero.
    check_only_cin: assert property (
        @(posedge CLK) (A == 16'h0000) && (B == 16'h0000) |-> (SUM == {15'b0, CIN}) && (COUT == 1'b0)
    );

///// Bit-level consequence /////
    // LSB of SUM equals parity of LSBs and CIN for 16-bit addition.
    check_sum_bit0_parity: assert property (
        @(posedge CLK) SUM[0] == (A[0] ^ B[0] ^ CIN)
    );

///// Commutativity reflection /////
    // The computed SUM is commutative in A and B.
    check_sum_commutative: assert property (
        @(posedge CLK) (A + B + CIN) == (B + A + CIN)
    );

endmodule

module shift_reg_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic shift_left,
    input logic shift_right,
    input logic [15:0] data_in,
    input logic [15:0] data_out
);

// Load updates data_out with data_in on next cycle.
    check_load_updates_data_out: assert property (
        @(posedge clk) disable iff (reset) (past_valid && load) |=> (data_out == $past(data_in))
    );

// Load has priority over any shift signals.
    check_load_priority_over_shifts: assert property (
        @(posedge clk) disable iff (reset) (past_valid && load && (shift_left || shift_right)) |=> (data_out == $past(data_in))
    );

// Shift-left updates data_out with left-shifted previous value, LSB filled with 0.
    check_shift_left_updates: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out == { $past(data_out[14:0]), 1'b0 })
    );

// Shift-left inserts 0 into bit 0.
    check_shift_left_inserts_zero_lsb: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out[0] == 1'b0)
    );

// Shift-left moves bits [14:0] into [15:1].
    check_shift_left_moves_upper_bits: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left) |=> (data_out[15:1] == $past(data_out[14:0]))
    );

// Shift-right updates data_out with right-shifted previous value, MSB filled with 0.
    check_shift_right_updates: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out == { 1'b0, $past(data_out[15:1]) })
    );

// Shift-right inserts 0 into bit 15.
    check_shift_right_inserts_zero_msb: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out[15] == 1'b0)
    );

// Shift-right moves bits [15:1] into [14:0].
    check_shift_right_moves_lower_bits: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && shift_right) |=> (data_out[14:0] == $past(data_out[15:1]))
    );

// When both shifts are asserted (no load), left shift takes priority.
    check_shift_conflict_left_wins: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && shift_left && shift_right) |=> (data_out == { $past(data_out[14:0]), 1'b0 })
    );

// With no operation requested, data_out holds its value.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset) (past_valid && !load && !shift_left && !shift_right) |=> (data_out == $past(data_out))
    );

endmodule

rtl:
module custom_logic (
    output Y,
    input  A1,
    input  A2,
    input  B1_N
);

    // Local signals
    wire not_B1_N;
    wire and0_out;
    wire and1_out;
    wire or0_out;
    wire nand0_out_Y;

    // Gate-level primitives
    not  u_not_B1_N (not_B1_N, B1_N);
    and  u_and0     (and0_out, A1, A2);
    and  u_and1     (and1_out, not_B1_N, and0_out);
    or   u_or0      (or0_out, A1, A2);
    nand u_nand0    (nand0_out_Y, and1_out, or0_out);
    buf  u_buf0     (Y, nand0_out_Y);

endmodule

sva:
module custom_logic_sva (
    input logic CLK,
    input logic A1,
    input logic A2,
    input logic B1_N,
    input logic Y,
    // Internal nets from RTL (optional to bind)
    input logic not_B1_N,
    input logic and0_out,
    input logic and1_out,
    input logic or0_out,
    input logic nand0_out_Y
);

///// Gate-level correctness /////
    // not_B1_N is the inversion of B1_N.
    check_not_B1N_inversion: assert property (
        @(posedge CLK) not_B1_N == ~B1_N
    );

// and0_out is A1 AND A2.
    check_and0_function: assert property (
        @(posedge CLK) and0_out == (A1 & A2)
    );

// and1_out is not_B1_N AND and0_out.
    check_and1_function: assert property (
        @(posedge CLK) and1_out == (not_B1_N & and0_out)
    );

// or0_out is A1 OR A2.
    check_or0_function: assert property (
        @(posedge CLK) or0_out == (A1 | A2)
    );

// nand0_out_Y is NAND of and1_out and or0_out.
    check_nand0_function: assert property (
        @(posedge CLK) nand0_out_Y == ~(and1_out & or0_out)
    );

// Y is a buffered version of nand0_out_Y.
    check_buf_to_Y: assert property (
        @(posedge CLK) Y == nand0_out_Y
    );

///// Functional equivalence and implications on top-level ports /////
    // Y equals (B1_N | ~A1 | ~A2) (simplified function).
    check_simplified_function: assert property (
        @(posedge CLK) Y == (B1_N | ~A1 | ~A2)
    );

endmodule

rtl:
module mux5to1 (
    out,
    in0,
    in1,
    in2,
    in3,
    in4,
    sel
);

    output out;
    input in0;
    input in1;
    input in2;
    input in3;
    input in4;
    input [2:0] sel;

    assign out = (sel == 3'b000) ? in0 :
                 (sel == 3'b001) ? in1 :
                 (sel == 3'b010) ? in2 :
                 (sel == 3'b011) ? in3 :
                 (sel == 3'b100) ? in4 :
                 1'b0;

endmodule

sva:
module mux5to1_sva (
    input logic CLK,
    input logic RESETn,
    input logic out,
    input logic in0,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic in4,
    input logic [2:0] sel
);

// When sel==000, out equals in0.
    check_mux_sel_000: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b000) |-> (out == in0)
    );

// When sel==001, out equals in1.
    check_mux_sel_001: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b001) |-> (out == in1)
    );

// When sel==010, out equals in2.
    check_mux_sel_010: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b010) |-> (out == in2)
    );

// When sel==011, out equals in3.
    check_mux_sel_011: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b011) |-> (out == in3)
    );

// When sel==100, out equals in4.
    check_mux_sel_100: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel == 3'b100) |-> (out == in4)
    );

// For sel 101/110/111, out is 0.
    check_mux_invalid_sel_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (sel inside {3'b101,3'b110,3'b111}) |-> (out == 1'b0)
    );

// Out equals the RTL conditional chain.
    check_mux_function_equivalence: assert property (
        @(posedge CLK) disable iff (!RESETn)
            out == ((sel == 3'b000) ? in0 :
                    (sel == 3'b001) ? in1 :
                    (sel == 3'b010) ? in2 :
                    (sel == 3'b011) ? in3 :
                    (sel == 3'b100) ? in4 :
                    1'b0)
    );

endmodule

rtl:
module top_module (
    input clk,
    input reset,      // Synchronous active-high reset
    input [7:0] d1,   // 8-bit input for the first register
    input [7:0] d2,   // 8-bit input for the second register
    output [7:0] q    // 8-bit output from the functional module
);

    reg [7:0] reg1, reg2;
    wire [7:0] diff;

    // Registers with synchronous reset
    always @(posedge clk) begin
        if (reset) begin
            reg1 <= 8'd0;
            reg2 <= 8'd0;
        end else begin
            reg1 <= d1;
            reg2 <= d2;
        end
    end

    // Difference calculator
    assign diff = reg1 - reg2;

    // Output
    assign q = diff;

endmodule

sva:
module top_module_sva (
    input logic clk,
    input logic reset,       // Synchronous active-high reset
    input logic [7:0] d1,
    input logic [7:0] d2,
