module two_bit_comparator(
    input [1:0] a,
    input [1:0] b,
    output out
);

wire n1, n2, n3, n4, n5;

assign n1 = ~(a[1] & b[1]);
assign n2 = ~(a[1] & b[0]);
assign n3 = ~(a[0] & b[1]);
assign n4 = ~(a[0] & b[0]);
assign n5 = ~(n1 & n2 & n3 & n4);

assign out = n5;

endmodule

sva:
module two_bit_comparator_sva (
    input logic clk,
    input logic [1:0] a,
    input logic [1:0] b,
    input logic out
);

///// Functional equivalence /////
    // out equals AND of the OR-reductions of a and b.
    check_out_eq_and_of_ors: assert property (
        @(posedge clk) disable iff (1'b0) out == ((a[1] | a[0]) & (b[1] | b[0]))
    );

// out equals the sum-of-products of all a/b bit pairs.
    check_out_eq_sum_of_products: assert property (
        @(posedge clk) disable iff (1'b0) out == ((a[1] & b[1]) | (a[1] & b[0]) | (a[0] & b[1]) | (a[0] & b[0]))
    );

///// Necessary conditions /////
    // If a is zero, out must be zero.
    check_a_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (a == 2'b00) |-> (out == 1'b0)
    );

// If b is zero, out must be zero.
    check_b_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (b == 2'b00) |-> (out == 1'b0)
    );

// If out is one, both a and b must be non-zero.
    check_out1_implies_nonzero_inputs: assert property (
        @(posedge clk) disable iff (1'b0) (out == 1'b1) |-> ((a != 2'b00) && (b != 2'b00))
    );

// If out is zero, at least one of a or b must be zero.
    check_out0_implies_one_zero: assert property (
        @(posedge clk) disable iff (1'b0) (out == 1'b0) |-> ((a == 2'b00) || (b == 2'b00))
    );

///// Sufficient conditions /////
    // If both a and b are non-zero, out must be one.
    check_nonzero_inputs_force_out1: assert property (
        @(posedge clk) disable iff (1'b0) ((a != 2'b00) && (b != 2'b00)) |-> (out == 1'b1)
    );

// If exactly one of a or b is zero, out must be zero.
    check_exactly_one_zero_forces_out0: assert property (
        @(posedge clk) disable iff (1'b0) (((a == 2'b00) ^ (b == 2'b00))) |-> (out == 1'b0)
    );

endmodule

module Counter_sva (
    input logic clk,
    input logic reset,          // active-low reset
    input logic count_en,
    input logic [31:0] max_count,
    input logic [31:0] count
);

///// Reset behavior /////
    // While reset is asserted (low), count must be 0.
    reset_drives_zero: assert property (
        @(posedge clk) !reset |-> (count == 32'd0)
    );

// On reset deassertion edge, count is 0 in that cycle.
    zero_on_reset_release: assert property (
        @(posedge clk) $rose(reset) |-> (count == 32'd0)
    );

///// Counting behavior /////
    // When disabled, the counter holds its value.
    hold_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
            (!count_en) |=> (count == $past(count))
    );

// When enabled, next value is +1 unless at max_count, then it wraps to 0.
    update_when_enabled: assert property (
        @(posedge clk) disable iff (!reset)
            (count_en) |=> (count == (($past(count) == $past(max_count)) ? 32'd0 : ($past(count) + 32'd1)))
    );

// Any change between cycles (out of reset) requires enable in the previous cycle.
    change_requires_enable: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && (count != $past(count))) |-> $past(count_en)
    );

// If enabled at all-ones and not equal to max_count, next value wraps to 0 via +1 overflow.
    overflow_wrap_to_zero: assert property (
        @(posedge clk) disable iff (!reset)
            (count_en && (count == 32'hFFFF_FFFF) && (count != max_count)) |=> (count == 32'd0)
    );

// If next value is 0 with enable high previously, cause is wrap-to-zero or max_count match.
    enabled_zero_next_cycle_has_cause: assert property (
        @(posedge clk) disable iff (!reset)
            ($past(reset) && $past(count_en) && (count == 32'd0)) |-> (($past(count) == $past(max_count)) || ($past(count) == 32'hFFFF_FFFF))
    );

endmodule

rtl:
module mux_4to1 (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input clk,   // Added clock input
    output [3:0] out
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(in0, in1, in2, in3, sel) begin
    case (sel)
        2'b00: stage1_out <= in0;
        2'b01: stage1_out <= in1;
        2'b10: stage1_out <= in2;
        2'b11: stage1_out <= in3;
    endcase
end

always @(posedge clk) begin
    stage2_out <= stage1_out;
end

assign out = stage2_out;

endmodule

