    check_bn_one_implies_y_eq_not_a: assert property (
        @(posedge CLK) (B_N == 1'b1) |-> (Y === (~A))
    );

// When A is 0, Y equals B_N (4-state aware).
    check_a_zero_implies_y_eq_bn: assert property (
        @(posedge CLK) (A == 1'b0) |-> (Y === B_N)
    );

