    input  logic        clk,   // sampling clock for assertions (RTL has no clock)
    input  logic [3:0]  a,
    input  logic [3:0]  b,
    input  logic        cin,
    input  logic [3:0]  sum,
    input  logic        cout
);

// RTL is purely combinational with no reset; wrapper adds clk for property sampling.

    // sum[0] implements (a0 ^ b0) ^ cin.
    check_sum0_def: assert property (
        @(posedge clk) sum[0] == ((a[0] ^ b[0]) ^ cin)
    );

// sum[1] implements (a1 ^ b1) ^ (a0 & b0).
    check_sum1_def: assert property (
        @(posedge clk) sum[1] == ((a[1] ^ b[1]) ^ (a[0] & b[0]))
    );

// sum[2] implements (a2 ^ b2) ^ (a1 & b1).
    check_sum2_def: assert property (
        @(posedge clk) sum[2] == ((a[2] ^ b[2]) ^ (a[1] & b[1]))
    );

// sum[3] implements (a3 ^ b3) ^ (a2 & b2).
    check_sum3_def: assert property (
        @(posedge clk) sum[3] == ((a[3] ^ b[3]) ^ (a[2] & b[2]))
    );

// cout implements (a2 ^ b2) | (a3 ^ b3).
    check_cout_def: assert property (
        @(posedge clk) cout == ((a[2] ^ b[2]) | (a[3] ^ b[3]))
    );

// When a0 equals b0, sum[0] equals cin.
    sum0_when_equal_inputs0: assert property (
        @(posedge clk) (a[0] == b[0]) |-> (sum[0] == cin)
    );

// When a0 differs from b0, sum[0] equals ~cin.
    sum0_when_diff_inputs0: assert property (
        @(posedge clk) (a[0] != b[0]) |-> (sum[0] == ~cin)
    );

// When a1 equals b1, sum[1] equals (a0 & b0).
    sum1_when_equal_inputs1: assert property (
        @(posedge clk) (a[1] == b[1]) |-> (sum[1] == (a[0] & b[0]))
    );

// When a1 differs from b1, sum[1] equals ~(a0 & b0).
    sum1_when_diff_inputs1: assert property (
        @(posedge clk) (a[1] != b[1]) |-> (sum[1] == ~(a[0] & b[0]))
    );

// If upper-bit pairs are equal, cout must be 0.
    cout_zero_when_top_pairs_equal: assert property (
        @(posedge clk) ((a[2] == b[2]) && (a[3] == b[3])) |-> (cout == 1'b0)
    );

// If any upper-bit pair differs, cout must be 1.
    cout_one_when_any_top_pair_diff: assert property (
        @(posedge clk) ((a[2] != b[2]) || (a[3] != b[3])) |-> (cout == 1'b1)
    );

endmodule

rtl:
module top_module (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] SUM,
    output reg OVERFLOW,
    output reg EQUAL,
    output reg GREATER_THAN,
    output reg LESS_THAN
);

    wire [3:0] add_sub_out;
    wire [1:0] comp_out;
    reg overflow_int;

    reg carry_in;

    adder_subtractor add_sub (
        .A(A),
        .B(B),
        .SUBTRACT(SUBTRACT),
        .OUT(add_sub_out),
        .OVERFLOW(overflow_int)
    );

    comparator_2bit comp (
        .A(A),
        .B(B),
        .OUT(comp_out)
    );

    always @* begin
        SUM <= add_sub_out;
        OVERFLOW <= overflow_int;
        EQUAL <= (comp_out == 2'b01);
        GREATER_THAN <= (comp_out == 2'b10);
        LESS_THAN <= (comp_out == 2'b00);
    end
endmodule
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input SUBTRACT,
    output reg [3:0] OUT,
    output reg OVERFLOW
);

    wire [3:0] twos_comp_B = (~B) + 1;

    always @* begin
        OUT <= A;
        OVERFLOW <= 0;
        if (SUBTRACT) begin
            OUT <= A + twos_comp_B;
        end else begin
            OUT <= A + B;
        end
        if (A >= OUT && SUBTRACT) begin
            OVERFLOW <= 1;
        end else if (A <= OUT && !SUBTRACT) begin
            OVERFLOW <= 1;
        end
    end
endmodule
module comparator_2bit (
    input [3:0] A,
    input [3:0] B,
    output reg [1:0] OUT
);

    always @(*) begin
        if (A > B) begin
            OUT <= 2'b10;
        end else if (A < B) begin
            OUT <= 2'b00;
        end else begin
            OUT <= 2'b01;
        end
    end
endmodule

sva:
module top_module_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUBTRACT,
    input logic [3:0] SUM,
    input logic OVERFLOW,
    input logic EQUAL,
    input logic GREATER_THAN,
    input logic LESS_THAN
);

///// SUM behavior /////
    // When not subtracting, SUM equals A + B (4-bit wrap).
    check_sum_add: assert property (
        @(posedge CLK) (!SUBTRACT) |-> (SUM == (A + B))
    );

// When subtracting, SUM equals A + (~B) + 1 (two's complement, 4-bit wrap).
    check_sum_sub: assert property (
        @(posedge CLK) (SUBTRACT) |-> (SUM == (A + (~B) + 4'b0001))
    );

// When subtracting and A == B, SUM is zero.
    check_sum_sub_equal_zero: assert property (
        @(posedge CLK) (SUBTRACT && (A == B)) |-> (SUM == 4'b0000)
    );

///// Comparator flags (EQUAL/GREATER_THAN/LESS_THAN) /////
    // Comparator flags are one-hot.
    check_compare_onehot: assert property (
        @(posedge CLK) $onehot({EQUAL, GREATER_THAN, LESS_THAN})
    );

// If A == B, only EQUAL is asserted.
    check_equal_when_AeqB: assert property (
        @(posedge CLK) (A == B) |-> (EQUAL && !GREATER_THAN && !LESS_THAN)
    );

// If EQUAL is asserted, then A == B.
    check_AeqB_when_equal: assert property (
        @(posedge CLK) (EQUAL) |-> (A == B)
    );

// If A > B, only GREATER_THAN is asserted.
    check_gt_when_AgtB: assert property (
        @(posedge CLK) (A > B) |-> (GREATER_THAN && !EQUAL && !LESS_THAN)
    );

// If GREATER_THAN is asserted, then A > B.
    check_AgtB_when_gt: assert property (
        @(posedge CLK) (GREATER_THAN) |-> (A > B)
    );

// If A < B, only LESS_THAN is asserted.
    check_lt_when_AltB: assert property (
        @(posedge CLK) (A < B) |-> (LESS_THAN && !EQUAL && !GREATER_THAN)
    );

// If LESS_THAN is asserted, then A < B.
    check_AltB_when_lt: assert property (
        @(posedge CLK) (LESS_THAN) |-> (A < B)
    );

endmodule

rtl:
module majority_gate (
    input A, B, C, D,
    output Y
);

wire AB, AC, AD, BC, BD, CD;

assign AB = A & B;
assign AC = A & C;
assign AD = A & D;
assign BC = B & C;
assign BD = B & D;
assign CD = C & D;

assign Y = (AB | AC | AD | BC | BD | CD);

endmodule

sva:
module majority_gate_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

// Y equals the OR of all pairwise ANDs of A,B,C,D.
    check_y_equation: assert property (
        @(posedge CLK) Y == ((A & B) | (A & C) | (A & D) | (B & C) | (B & D) | (C & D))
    );

// If A and B are HIGH together, Y must be HIGH.
    pair_AB_implies_Y: assert property (
        @(posedge CLK) (A & B) |-> Y
    );

// If A and C are HIGH together, Y must be HIGH.
    pair_AC_implies_Y: assert property (
        @(posedge CLK) (A & C) |-> Y
    );

// If A and D are HIGH together, Y must be HIGH.
    pair_AD_implies_Y: assert property (
        @(posedge CLK) (A & D) |-> Y
    );

// If B and C are HIGH together, Y must be HIGH.
    pair_BC_implies_Y: assert property (
        @(posedge CLK) (B & C) |-> Y
    );

// If B and D are HIGH together, Y must be HIGH.
    pair_BD_implies_Y: assert property (
        @(posedge CLK) (B & D) |-> Y
    );

// If C and D are HIGH together, Y must be HIGH.
    pair_CD_implies_Y: assert property (
        @(posedge CLK) (C & D) |-> Y
    );

// When all inputs are LOW, Y must be LOW.
    all_zero_implies_zero: assert property (
        @(posedge CLK) !(A | B | C | D) |-> !Y
    );

// When exactly one input is HIGH, Y must be LOW.
    onehot_implies_zero: assert property (
        @(posedge CLK) $onehot({A,B,C,D}) |-> !Y
    );

// When all inputs are HIGH, Y must be HIGH.
    all_one_implies_one: assert property (
        @(posedge CLK) (A & B & C & D) |-> Y
    );

endmodule

rtl:
module ones_complement(
    input [3:0] in,
    output [3:0] out
);

assign out = ~in;


endmodule

sva:
module ones_complement_sva (
    input logic clk,          // sampling clock (DUT has no clock/reset)
    input logic [3:0] in,
    input logic [3:0] out
);

// out equals bitwise NOT of in.
    check_out_equals_bitwise_not_in: assert property (
        @(posedge clk) out == ~in
    );

// out XOR in is all ones.
    check_xor_all_ones: assert property (
        @(posedge clk) (out ^ in) == 4'hF
    );

// out OR in is all ones.
    check_or_all_ones: assert property (
        @(posedge clk) (out | in) == 4'hF
    );

// out AND in is all zeros.
    check_and_all_zeros: assert property (
        @(posedge clk) (out & in) == 4'h0
    );

// Bit 0 is complemented.
    check_bit0_complement: assert property (
        @(posedge clk) out[0] == ~in[0]
    );

// Bit 1 is complemented.
    check_bit1_complement: assert property (
        @(posedge clk) out[1] == ~in[1]
    );

// Bit 2 is complemented.
    check_bit2_complement: assert property (
        @(posedge clk) out[2] == ~in[2]
    );

// Bit 3 is complemented.
    check_bit3_complement: assert property (
        @(posedge clk) out[3] == ~in[3]
    );

// out is never equal to in.
    check_never_equal: assert property (
        @(posedge clk) out != in
    );

endmodule

rtl:
module signal_converter (
    input [3:0] in_signal,
    output reg [1:0] out_signal
);

always @(*) begin
    case(in_signal)
        4'd0: out_signal = 2'b00;
        4'd1: out_signal = 2'b00;
        4'd2: out_signal = 2'b00;
        4'd3: out_signal = 2'b00;
        4'd4: out_signal = 2'b01;
        4'd5: out_signal = 2'b01;
        4'd6: out_signal = 2'b01;
        4'd7: out_signal = 2'b01;
        4'd8: out_signal = 2'b10;
        4'd9: out_signal = 2'b10;
        4'd10: out_signal = 2'b10;
        default: out_signal = 2'b11;
    endcase
end

endmodule

sva:
module signal_converter_sva (
    input logic CLK,
    input logic [3:0] in_signal,
    input logic [1:0] out_signal
);

// in_signal 0..3 must map to 2'b00
    check_map_0_to_3_is_00: assert property (
        @(posedge CLK) (in_signal inside {[4'd0:4'd3]}) |-> (out_signal == 2'b00)
    );

// in_signal 4..7 must map to 2'b01
    check_map_4_to_7_is_01: assert property (
        @(posedge CLK) (in_signal inside {[4'd4:4'd7]}) |-> (out_signal == 2'b01)
    );

// in_signal 8..10 must map to 2'b10
    check_map_8_to_10_is_10: assert property (
        @(posedge CLK) (in_signal inside {[4'd8:4'd10]}) |-> (out_signal == 2'b10)
    );

// in_signal 11..15 must map to 2'b11 (default)
    check_map_11_to_15_is_11: assert property (
        @(posedge CLK) (in_signal inside {[4'd11:4'd15]}) |-> (out_signal == 2'b11)
    );

// 2'b00 output implies in_signal is 0..3
    check_rev_00_implies_0_to_3: assert property (
        @(posedge CLK) (out_signal == 2'b00) |-> (in_signal inside {[4'd0:4'd3]})
    );

// 2'b01 output implies in_signal is 4..7
    check_rev_01_implies_4_to_7: assert property (
        @(posedge CLK) (out_signal == 2'b01) |-> (in_signal inside {[4'd4:4'd7]})
    );

// 2'b10 output implies in_signal is 8..10
    check_rev_10_implies_8_to_10: assert property (
        @(posedge CLK) (out_signal == 2'b10) |-> (in_signal inside {[4'd8:4'd10]})
    );

// 2'b11 output implies in_signal is 11..15
    check_rev_11_implies_11_to_15: assert property (
        @(posedge CLK) (out_signal == 2'b11) |-> (in_signal inside {[4'd11:4'd15]})
    );

endmodule

rtl:
module WB_intercon(master_STB, master_DAT_I, master_DAT_O, master_ACK, master_WE, master_ADDR, slave_STB, slave_ACK, slave_WE, slave_DAT_I, slave_DAT_O, slave_ADDR);
    input wire master_STB, master_WE;
    input wire [31: 0] master_DAT_I, master_ADDR;
    input wire [511: 0] slave_DAT_I;
    input wire [15: 0] slave_ACK;
    output wire [31: 0] master_DAT_O, slave_DAT_O, slave_ADDR;
    output reg [15: 0] slave_STB;
    output wire master_ACK, slave_WE;

    assign master_ACK = slave_ACK[master_ADDR[31: 28]];
    assign slave_DAT_O = master_DAT_I;
    assign slave_WE = master_WE;

    wire [31: 0] slaves_DAT[0: 15];

    assign slaves_DAT[0] = slave_DAT_I[31: 0];
    assign slaves_DAT[1] = slave_DAT_I[63: 32];
    assign slaves_DAT[2] = slave_DAT_I[95: 64];
    assign slaves_DAT[3] = slave_DAT_I[127: 96];
    assign slaves_DAT[4] = slave_DAT_I[159: 128];
    assign slaves_DAT[5] = slave_DAT_I[191: 160];
    assign slaves_DAT[6] = slave_DAT_I[223: 192];
    assign slaves_DAT[7] = slave_DAT_I[255: 224];
    assign slaves_DAT[8] = slave_DAT_I[287: 256];
    assign slaves_DAT[9] = slave_DAT_I[319: 288];
    assign slaves_DAT[10] = slave_DAT_I[351: 320];
    assign slaves_DAT[11] = slave_DAT_I[383: 352];
    assign slaves_DAT[12] = slave_DAT_I[415: 384];
    assign slaves_DAT[13] = slave_DAT_I[447: 416];
    assign slaves_DAT[14] = slave_DAT_I[479: 448];
    assign slaves_DAT[15] = slave_DAT_I[511: 480]; 

    assign master_DAT_O = slaves_DAT[master_ADDR[31: 28]];
    assign slave_ADDR = {4'b0, master_ADDR[27: 0]};

    always @* begin
        slave_STB = 0;
        slave_STB[master_ADDR[31: 28]] = master_STB;
    end

endmodule

sva:
module WB_intercon_sva (
    input logic master_STB,
    input logic master_WE,
    input logic [31:0] master_DAT_I,
    input logic [31:0] master_ADDR,
    input logic [511:0] slave_DAT_I,
    input logic [15:0] slave_ACK,
    input logic [31:0] master_DAT_O,
    input logic [31:0] slave_DAT_O,
    input logic [31:0] slave_ADDR,
    input logic [15:0] slave_STB,
    input logic master_ACK,
    input logic slave_WE
);

///// Combinational mapping checks sampled on master_STB edge /////
    // master_ACK equals the selected slave_ACK bit indexed by master_ADDR[31:28].
    check_master_ack_select: assert property (
        @(posedge master_STB) master_ACK == slave_ACK[master_ADDR[31:28]]
    );

// slave_ADDR is {4'b0, master_ADDR[27:0]}.
    check_slave_addr_map: assert property (
        @(posedge master_STB) slave_ADDR == {4'b0, master_ADDR[27:0]}
    );

// slave_DAT_O passes through master_DAT_I.
    check_slave_dat_o_passthrough: assert property (
        @(posedge master_STB) slave_DAT_O == master_DAT_I
    );

// slave_WE passes through master_WE.
    check_slave_we_passthrough: assert property (
        @(posedge master_STB) slave_WE == master_WE
    );

// slave_STB equals one-hot of selected index when master_STB=1, else zero.
    check_slave_stb_exact_pattern: assert property (
        @(posedge master_STB) slave_STB == (master_STB ? (16'h1 << master_ADDR[31:28]) : 16'h0)
    );

// The selected slave_STB bit equals master_STB.
    check_slave_stb_selected_bit: assert property (
        @(posedge master_STB) slave_STB[master_ADDR[31:28]] == master_STB
    );

// All unselected slave_STB bits are zero.
    check_slave_stb_unselected_zero: assert property (
        @(posedge master_STB) (slave_STB & ~(16'h1 << master_ADDR[31:28])) == 16'h0
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] in,
    input [1:0] shift_amt,
    input dir,
    output reg [3:0] out
);

    always @(*) begin
        case (dir)
            0: out = in << shift_amt;
            1: out = in >> shift_amt;
        endcase
    end

endmodule

sva:
module barrel_shifter_sva (
    input logic CLK,              // sampling clock for assertions (DUT has no clock/reset)
    input logic [3:0] in,
    input logic [1:0] shift_amt,
    input logic dir,
    input logic [3:0] out
);

// DUT is pure combinational: dir==0 => out=in<<shift_amt; dir==1 => out=in>>shift_amt.

    // Out equals the selected shift function of inputs each cycle.
    check_out_comb_function: assert property (
        @(posedge CLK) out == (dir ? (in >> shift_amt) : (in << shift_amt))
    );

// Shift-by-zero is a passthrough regardless of direction.
    check_shift0_passthrough: assert property (
        @(posedge CLK) (shift_amt == 2'd0) |-> (out == in)
    );

// Left shift by 1: LSB becomes 0; upper bits shift up by one.
    check_left_shift_by1: assert property (
        @(posedge CLK) (dir == 1'b0 && shift_amt == 2'd1) |-> (out[0] == 1'b0 && out[3:1] == in[2:0])
    );

// Left shift by 2: two LSBs become 0; upper two bits shift up by two.
    check_left_shift_by2: assert property (
        @(posedge CLK) (dir == 1'b0 && shift_amt == 2'd2) |-> (out[1:0] == 2'b00 && out[3:2] == in[1:0])
    );

// Left shift by 3: lower three bits become 0; MSB takes in[0].
    check_left_shift_by3: assert property (
        @(posedge CLK) (dir == 1'b0 && shift_amt == 2'd3) |-> (out[2:0] == 3'b000 && out[3] == in[0])
    );

// Right shift by 1: MSB becomes 0; lower bits shift down by one.
    check_right_shift_by1: assert property (
        @(posedge CLK) (dir == 1'b1 && shift_amt == 2'd1) |-> (out[3] == 1'b0 && out[2:0] == in[3:1])
    );

// Right shift by 2: two MSBs become 0; lower two bits shift down by two.
    check_right_shift_by2: assert property (
        @(posedge CLK) (dir == 1'b1 && shift_amt == 2'd2) |-> (out[3:2] == 2'b00 && out[1:0] == in[3:2])
    );

// Right shift by 3: upper three bits become 0; LSB takes in[3].
    check_right_shift_by3: assert property (
        @(posedge CLK) (dir == 1'b1 && shift_amt == 2'd3) |-> (out[3:1] == 3'b000 && out[0] == in[3])
    );

endmodule

rtl:
module final_output (
    input clk,
    input reset,
    input d,
    input rise,
    input down,
    output q_out
);

reg q = 0;
always @(posedge clk) begin
    if (reset) begin
        q <= 0;
    end else begin
        if (rise) begin
            q <= 1;
        end else if (down) begin
            q <= 0;
        end
    end
end

assign q_out = q;

endmodule

sva:
module final_output_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic rise,
    input logic down,
    input logic q_out
);

// Clock: clk; Reset: reset (active-high synchronous).
    // Sequential flop: rise sets 1, else if down sets 0, else hold; q_out mirrors flop.

    // During reset, output is forced low.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (q_out == 1'b0)
    );

endmodule

rtl:
module mux_2to1 (
    out,
    in0,
    in1,
    sel
);

    output out;
    input in0;
    input in1;
    input sel;

    assign out = (sel == 1'b0) ? in0 : in1;

endmodule

sva:
module mux_2to1_sva (
    input logic CLK,
    input logic RESETn,
    input logic out,
    input logic in0,
    input logic in1,
    input logic sel
);

// Out equals the selected input each cycle.
    check_mux_function: assert property (
        @(posedge CLK) disable iff (!RESETn) out == (sel ? in1 : in0)
    );

// If inputs are equal, out equals that value regardless of sel.
    equal_inputs_bypass_sel: assert property (
        @(posedge CLK) disable iff (!RESETn) (in0 == in1) |-> (out == in0)
    );

endmodule

