module clock_gate (CLK, EN, TE, ENCLK);

  input CLK, EN, TE;
  output reg ENCLK;

  always @ (posedge CLK) begin
    if (EN && !TE) begin
      ENCLK <= CLK;
    end else begin
      ENCLK <= 1'b0;
    end
  end

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

// When not enabled (EN==0 or TE==1), ENCLK must be 0 on the next clock.
    check_not_enabled_clears_next: assert property (
        @(posedge CLK) !(EN && !TE) |=> (ENCLK == 1'b0)
    );

// TE overrides EN: if both EN and TE are 1, ENCLK must be 0 next clock.
    check_te_overrides_en: assert property (
        @(posedge CLK) (EN && TE) |=> (ENCLK == 1'b0)
    );

// If not enabled for two consecutive cycles, ENCLK must be 0 on the second cycle.
    check_two_cycle_not_enabled_keeps_low: assert property (
        @(posedge CLK) !(EN && !TE) ##1 !(EN && !TE) |-> (ENCLK == 1'b0)
    );

// If TE is high for two consecutive cycles, ENCLK must be 0 on the second cycle.
    check_two_cycle_te_keeps_low: assert property (
        @(posedge CLK) TE ##1 TE |-> (ENCLK == 1'b0)
    );

endmodule

rtl:
module SB_WARMBOOT (
  input BOOT,
  input S1,
  input S0,
  input clk,  // Added clock input
  output reg VALID
);

  // Define the four possible states
  parameter STATE_0 = 2'b00;
  parameter STATE_1 = 2'b01;
  parameter STATE_2 = 2'b10;
  parameter STATE_3 = 2'b11;

  // Define the state and next_state variables
  reg [1:0] state, next_state;

  // Define the state transition logic
  always @(*) begin
    case (state)
      STATE_0: begin
        if (BOOT) begin
          next_state = STATE_0;
        end else if (!S1 && S0) begin
          next_state = STATE_1;
        end else begin
          next_state = STATE_0;
        end
      end
      STATE_1: begin
        if (BOOT) begin
          next_state = STATE_0;
        end else if (S1 && !S0) begin
          next_state = STATE_2;
        end else begin
          next_state = STATE_1;
        end
      end
      STATE_2: begin
        if (BOOT) begin
          next_state = STATE_0;
        end else if (S1 && S0) begin
          next_state = STATE_3;
        end else begin
          next_state = STATE_2;
        end
      end
      STATE_3: begin
        if (BOOT) begin
          next_state = STATE_0;
        end else if (!S1 && !S0) begin
          next_state = STATE_0;
        end else begin
          next_state = STATE_3;
        end
      end
    endcase
  end

  // Define the output logic
  always @(*) begin
    if (state == STATE_0 || state == STATE_1 || state == STATE_2 || state == STATE_3) begin
      VALID = 1'b1;
    end else begin
      VALID = 1'b0;
    end
  end

  // Update the state variable
  always @(posedge clk) begin
    if (BOOT) begin
      state <= STATE_0;
    end else begin
      state <= next_state;
    end
  end

endmodule

sva:
module SB_WARMBOOT_sva (
    input logic BOOT,
    input logic S1,
    input logic S0,
    input logic clk,
    input logic VALID,
    input logic [1:0] state,
    input logic [1:0] next_state
);

///// Output behavior /////
    // VALID remains HIGH when not in reset.
    valid_always_high_run: assert property (
        @(posedge clk) disable iff (BOOT) (VALID == 1'b1)
    );

// VALID never falls when not in reset.
    valid_no_fall_run: assert property (
        @(posedge clk) disable iff (BOOT) !$fell(VALID)
    );

// After reset deasserts, VALID is HIGH.
    valid_after_reset_release: assert property (
        @(posedge clk) $fell(BOOT) |-> (VALID == 1'b1)
    );

endmodule

rtl:
module abs_value (
  input signed [31:0] in,
  output reg [31:0] out
);

  always @(*) begin
    if (in < 0) begin
      out = (~in) + 1;
    end
    else begin
      out = in;
    end
  end

endmodule

sva:
module abs_value_sva (
    input logic CLK,
    input logic signed [31:0] in,
    input logic [31:0] out
);

// For negative input, output equals two's complement of input.
    check_neg_twos_complement: assert property (
        @(posedge CLK) (in < 0) |-> (out == ((~in) + 32'sd1))
    );

// For non-negative input, output equals input.
    check_nonneg_passthrough: assert property (
        @(posedge CLK) (in >= 0) |-> (out == in)
    );

// Functional equivalence to the conditional expression in RTL.
    check_function_equivalence: assert property (
        @(posedge CLK) out == ((in < 0) ? ((~in) + 32'sd1) : in)
    );

// For negative input, output plus input sums to zero (mod 32 bits).
    check_neg_sum_zero: assert property (
        @(posedge CLK) (in < 0) |-> ((out + in) == 32'h0000_0000)
    );

// Zero input maps to zero output.
    check_zero_maps_to_zero: assert property (
        @(posedge CLK) (in == 32'sh0000_0000) |-> (out == 32'h0000_0000)
    );

// Minimum negative value maps to itself after two's complement.
    check_minint_maps_to_self: assert property (
        @(posedge CLK) (in == 32'sh8000_0000) |-> (out == 32'h8000_0000)
    );

// For non-negative input, output MSB is zero.
    check_nonneg_out_msb_zero: assert property (
        @(posedge CLK) (in >= 0) |-> (out[31] == 1'b0)
    );

// For negative non-minint input, output MSB is zero (positive magnitude).
    check_neg_nonmin_out_msb_zero: assert property (
        @(posedge CLK) ((in < 0) && (in != 32'sh8000_0000)) |-> (out[31] == 1'b0)
    );

endmodule

