module dff_3input_sva (
    input logic clk,
    input logic reset,
    input logic set,
    input logic [2:0] data,
    input logic q
);

// During active-low reset, q must be 0.
    check_reset_forces_zero: assert property (
        @(posedge clk) !reset |-> (q == 1'b0)
    );

// If reset was low on the previous cycle, q must be 0 now.
    check_prev_reset_low_q_zero: assert property (
        @(posedge clk) $past(!reset) |-> (q == 1'b0)
    );

// With reset high, set=1 drives q to 1 on the next cycle.
    check_set_forces_one_next: assert property (
        @(posedge clk) disable iff (!reset) set |=> (q == 1'b1)
    );

// With reset high and set=0, q updates to data[2]&data[1]&data[0] on the next cycle.
    check_data_and_updates_next: assert property (
        @(posedge clk) disable iff (!reset) !set |=> (q == (data[2] & data[1] & data[0]))
    );

// When the prior cycle was out of reset, q equals (set ? 1 : &data) from the prior cycle.
    check_next_state_equation: assert property (
        @(posedge clk) disable iff (!reset) $past(reset) |-> ( q == ( $past(set) ? 1'b1 : (& $past(data)) ) )
    );

// If q is 1 now, last cycle must have been out of reset and (set==1 or data==3'b111).
    check_q_one_has_valid_cause: assert property (
        @(posedge clk) disable iff (!reset) (q == 1'b1) |-> ( $past(reset) && ( $past(set) || (& $past(data)) ) )
    );

// If last cycle had reset high, set=0, and data did not all assert, q must be 0 now.
    check_q_zero_when_prev_inputs_zero: assert property (
        @(posedge clk) disable iff (!reset) ( $past(reset) && !$past(set) && !(& $past(data)) ) |-> (q == 1'b0)
    );

endmodule

rtl:
module priority_encoder (
  input [3:0] in,
  output reg [1:0] pos
);

  always @*
  begin
    case(in)
      4'b0001: pos = 0;
      4'b0010: pos = 1;
      4'b0100: pos = 2;
      4'b1000: pos = 3;
      default: pos = 0;
    endcase
  end

endmodule

sva:
module priority_encoder_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] pos
);

// 0001 maps to position 0.
    encode_in_0001_to_pos0: assert property (
        @(posedge clk) (in == 4'b0001) |-> (pos == 2'd0)
    );

// 0010 maps to position 1.
    encode_in_0010_to_pos1: assert property (
        @(posedge clk) (in == 4'b0010) |-> (pos == 2'd1)
    );

// 0100 maps to position 2.
    encode_in_0100_to_pos2: assert property (
        @(posedge clk) (in == 4'b0100) |-> (pos == 2'd2)
    );

// 1000 maps to position 3.
    encode_in_1000_to_pos3: assert property (
        @(posedge clk) (in == 4'b1000) |-> (pos == 2'd3)
    );

// Any non-listed input maps to 0 (default case).
    encode_default_to_pos0: assert property (
        @(posedge clk) (in != 4'b0001 && in != 4'b0010 && in != 4'b0100 && in != 4'b1000) |-> (pos == 2'd0)
    );

// If pos is 1 then input must be 0010.
    reverse_pos1_implies_0010: assert property (
        @(posedge clk) (pos == 2'd1) |-> (in == 4'b0010)
    );

// If pos is 2 then input must be 0100.
    reverse_pos2_implies_0100: assert property (
        @(posedge clk) (pos == 2'd2) |-> (in == 4'b0100)
    );

// If pos is 3 then input must be 1000.
    reverse_pos3_implies_1000: assert property (
        @(posedge clk) (pos == 2'd3) |-> (in == 4'b1000)
    );

// If pos is 0 then input cannot be 0010/0100/1000.
    reverse_pos0_excludes_1_2_3: assert property (
        @(posedge clk) (pos == 2'd0) |-> (in != 4'b0010 && in != 4'b0100 && in != 4'b1000)
    );

endmodule

rtl:
module rippleCounter(clk, rst_n, out);
    input clk, rst_n;
    output [3:0] out;

    reg [3:0] count;

    always @(posedge clk, negedge rst_n) begin
        if(!rst_n) begin
            count <= 4'b0;
        end else begin
            if(count == 4'b1111) begin
                count <= 4'b0;
            end else begin
                count <= count + 1;
            end
        end
    end

    assign out = count;

endmodule

