module d_ff (
  input D,
  input CLK,
  input RESET,
  output Q
);

reg Q_reg;

always @(posedge CLK, posedge RESET) begin
  if (RESET) begin
    Q_reg <= 1'b0;
  end else begin
    Q_reg <= D;
  end
end

