module c17_sva (
    input logic clk,        // Sampling clock for assertions (DUT has no clock/reset)
    input logic N1, N2, N3, N6, N7,
    input logic N22, N23
);

// Combinational DUT: no reset; outputs are pure functions of inputs.
    // N22 depends on N1,N2,N3,N6; N23 depends on N2,N3,N6,N7.

    // N22 equals its combinational definition from primary inputs.
    check_n22_functional_eq: assert property (
        @(posedge clk) disable iff (1'b0)
        N22 === ~( (~(N1 & N3)) & (~(N2 & (~(N3 & N6)))) )
    );

// N23 equals its combinational definition from primary inputs.
    check_n23_functional_eq: assert property (
        @(posedge clk) disable iff (1'b0)
        N23 === ~( (~(N2 & (~(N3 & N6)))) & (~((~(N3 & N6)) & N7)) )
    );

// If N1 and N3 are both 1 then N22 must be 1 (since N10=0).
    check_n22_high_when_n1_and_n3: assert property (
        @(posedge clk) disable iff (1'b0)
        (N1 & N3) |-> (N22 == 1'b1)
    );

// When N2 is 0, N22 reduces to N1 & N3.
    check_n22_eq_when_n2_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (N2 == 1'b0) |-> (N22 === (N1 & N3))
    );

// When N3 is 0, N22 reduces to N2.
    check_n22_eq_when_n3_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (N3 == 1'b0) |-> (N22 === N2)
    );

// When N3=1 and N6=0, N22 reduces to N1 | N2.
    check_n22_eq_when_n3_and_n6_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (N3 == 1'b1 && N6 == 1'b0) |-> (N22 === (N1 | N2))
    );

// If N2=1 and either N3=0 or N6=0 then N23 must be 1 (since N16=0).
    check_n23_high_when_n2_and_not_n3n6: assert property (
        @(posedge clk) disable iff (1'b0)
        (N2 == 1'b1 && ((N3 == 1'b0) || (N6 == 1'b0))) |-> (N23 == 1'b1)
    );

// If N7=1 and either N3=0 or N6=0 then N23 must be 1 (since N19=0).
    check_n23_high_when_n7_and_not_n3n6: assert property (
        @(posedge clk) disable iff (1'b0)
        (N7 == 1'b1 && ((N3 == 1'b0) || (N6 == 1'b0))) |-> (N23 == 1'b1)
    );

// If N3=1 and N6=1 then N23 must be 0 (since N16=1 and N19=1).
    check_n23_zero_when_n3_and_n6: assert property (
        @(posedge clk) disable iff (1'b0)
        (N3 == 1'b1 && N6 == 1'b1) |-> (N23 == 1'b0)
    );

// When N7 is 0, N23 reduces to N2 & ~(N3 & N6).
    check_n23_eq_when_n7_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        (N7 == 1'b0) |-> (N23 === (N2 & ~(N3 & N6)))
    );

endmodule

module simple_counter_sva (
  input logic clk,
  input logic rst_n,
  input logic en,
  input logic [3:0] count
);

// Clock: clk; Reset: rst_n active-low, synchronous
  // Sequential counter: increments on clk when en=1; holds when en=0; wraps 15->0

  // During reset, count is 0.
  reset_value: assert property (
    @(posedge clk) !rst_n |-> (count == 4'b0000)
  );

// On the cycle reset is asserted, count is driven to 0.
  sync_reset_effect: assert property (
    @(posedge clk) $fell(rst_n) |-> (count == 4'h0)
  );

endmodule

module counter_sva (
  input logic clk,
  input logic rst,
  input logic dir,
  input logic [7:0] count
);

// While reset is asserted, count must be 0.
  check_reset_forces_zero: assert property (
    @(posedge clk) rst |-> (count == 8'd0)
  );

// When dir=1 and count is not 255, next count increments by 1.
  check_up_increments_when_not_max: assert property (
    @(posedge clk) disable iff (rst) (dir && (count != 8'd255)) |=> (count == $past(count) + 8'd1)
  );

// When dir=1 and count is 255, next count wraps to 0.
  check_up_wraps_at_255: assert property (
    @(posedge clk) disable iff (rst) (dir && (count == 8'd255)) |=> (count == 8'd0)
  );

// When dir=0 and count is not 0, next count decrements by 1.
  check_down_decrements_when_not_min: assert property (
    @(posedge clk) disable iff (rst) (!dir && (count != 8'd0)) |=> (count == $past(count) - 8'd1)
  );

// When dir=0 and count is 0, next count wraps to 255.
  check_down_wraps_at_0: assert property (
    @(posedge clk) disable iff (rst) (!dir && (count == 8'd0)) |=> (count == 8'd255)
  );

// Out of reset, count changes every cycle.
  check_count_changes_each_cycle: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> (count != $past(count))
  );

// Out of reset, LSB toggles every cycle (±1 update).
  check_lsb_toggles_each_cycle: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> (count[0] != $past(count[0]))
  );

// Step size is always ±1 modulo 256 out of reset.
  check_step_is_plus_or_minus_one: assert property (
    @(posedge clk) disable iff (rst) 1'b1 |=> ((count == $past(count) + 8'd1) || (count == $past(count) - 8'd1))
  );

endmodule

