module sky130_fd_sc_lp__a21bo_sva (
    input logic CLK,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N
);

// Functional equivalence: X == (~B1_N) | (A1 & A2).
    check_functional_equivalence: assert property (
        @(posedge CLK) X == ((~B1_N) | (A1 & A2))
    );

// B1_N low forces X high regardless of A1/A2.
    check_b1n_low_forces_x_high: assert property (
        @(posedge CLK) (B1_N == 1'b0) |-> (X == 1'b1)
    );

// When B1_N is high, X equals A1 & A2.
    check_b1n_high_passes_and: assert property (
        @(posedge CLK) (B1_N == 1'b1) |-> (X == (A1 & A2))
    );

// With B1_N high and A1 low, X must be low.
    check_a1_low_clears_x_when_b1n_high: assert property (
        @(posedge CLK) (B1_N && !A1) |-> (X == 1'b0)
    );

// With B1_N high and A2 low, X must be low.
    check_a2_low_clears_x_when_b1n_high: assert property (
        @(posedge CLK) (B1_N && !A2) |-> (X == 1'b0)
    );

// With B1_N high and both A1 and A2 high, X must be high.
    check_both_high_sets_x_when_b1n_high: assert property (
        @(posedge CLK) (B1_N && A1 && A2) |-> (X == 1'b1)
    );

// If X is low then B1_N is high and not both A1 and A2 are high.
    check_x_low_implies_conditions: assert property (
        @(posedge CLK) (X == 1'b0) |-> (B1_N && !(A1 && A2))
    );

// If X is high then either B1_N is low or both A1 and A2 are high.
    check_x_high_implies_conditions: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((!B1_N) || (A1 && A2))
    );

endmodule

rtl:
module comparator_and_xor (
  input [3:0] in1,
  input [3:0] in2,
  output reg [1:0] out,
  output [3:0] xor_out
);

  // Comparator logic
  always @* begin
    if (in1 == in2) begin
      out = 2'b00;
    end else if (in1 > in2) begin
      out = 2'b01;
    end else begin
      out = 2'b10;
    end
  end

  // XOR logic
  assign xor_out = in1 ^ in2;

endmodule

sva:
module comparator_and_xor_sva (
    input logic clk,           // verification clock for sampling assertions
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [1:0] out,
    input logic [3:0] xor_out
);

// No reset in RTL; assertions use disable iff(1'b0). Purely combinational behavior.

    // Equal inputs drive out = 2'b00.
    check_out_eq_sets_00: assert property (
        @(posedge clk) disable iff (1'b0) (in1 == in2) |-> (out == 2'b00)
    );

// in1 > in2 drives out = 2'b01.
    check_out_gt_sets_01: assert property (
        @(posedge clk) disable iff (1'b0) (in1 > in2) |-> (out == 2'b01)
    );

// in1 < in2 drives out = 2'b10.
    check_out_lt_sets_10: assert property (
        @(posedge clk) disable iff (1'b0) (in1 < in2) |-> (out == 2'b10)
    );

// out is never 2'b11.
    check_out_never_11: assert property (
        @(posedge clk) disable iff (1'b0) (out != 2'b11)
    );

// out == 2'b00 implies inputs are equal.
    check_out00_implies_eq: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b00) |-> (in1 == in2)
    );

// out == 2'b01 implies in1 > in2.
    check_out01_implies_gt: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b01) |-> (in1 > in2)
    );

// out == 2'b10 implies in1 < in2.
    check_out10_implies_lt: assert property (
        @(posedge clk) disable iff (1'b0) (out == 2'b10) |-> (in1 < in2)
    );

// xor_out equals bitwise XOR of in1 and in2.
    check_xor_definition: assert property (
        @(posedge clk) disable iff (1'b0) (xor_out == (in1 ^ in2))
    );

// Equal inputs imply xor_out is zero.
    check_eq_implies_xor_zero: assert property (
        @(posedge clk) disable iff (1'b0) (in1 == in2) |-> (xor_out == 4'b0000)
    );

// xor_out zero implies out == 2'b00.
    check_xor_zero_implies_out00: assert property (
        @(posedge clk) disable iff (1'b0) (xor_out == 4'b0000) |-> (out == 2'b00)
    );

endmodule

