    check_generate_bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (g0 == (in1[0] & in2[0])) &&
        (g1 == (in1[1] & in2[1])) &&
        (g2 == (in1[2] & in2[2])) &&
        (g3 == (in1[3] & in2[3])) &&
        (g4 == (in1[4] & in2[4])) &&
        (g5 == (in1[5] & in2[5])) &&
        (g6 == (in1[6] & in2[6]))
    );

// p[i] equals in1[i] ^ in2[i] for bits 0..6.
    check_propagate_bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (p0 == (in1[0] ^ in2[0])) &&
        (p1 == (in1[1] ^ in2[1])) &&
        (p2 == (in1[2] ^ in2[2])) &&
        (p3 == (in1[3] ^ in2[3])) &&
        (p4 == (in1[4] ^ in2[4])) &&
        (p5 == (in1[5] ^ in2[5])) &&
        (p6 == (in1[6] ^ in2[6]))
    );

// c[i] equals g[i-1] for i=1..7.
    check_carry_mapping_c_eq_g: assert property (
        @(posedge clk) disable iff (!reset_n)
        (c1 == g0) && (c2 == g1) && (c3 == g2) &&
        (c4 == g3) && (c5 == g4) && (c6 == g5) && (c7 == g6)
    );

// temp1 is the 1-bit addition result of in1[0] + in2[0].
    check_temp1_add: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp1[0] == p0) && (temp1[1] == g0)
    );

// temp2 is in1[1] + in2[1] + c1 (sum and carry).
    check_temp2_add3bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp2[0] == (p1 ^ c1)) && (temp2[1] == (g1 | (p1 & c1)))
    );

// temp3 is in1[2] + in2[2] + c2 (sum and carry).
    check_temp3_add3bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp3[0] == (p2 ^ c2)) && (temp3[1] == (g2 | (p2 & c2)))
    );

// temp4 is in1[3] + in2[3] + c3 (sum and carry).
    check_temp4_add3bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp4[0] == (p3 ^ c3)) && (temp4[1] == (g3 | (p3 & c3)))
    );

// temp5 is in1[4] + in2[4] + c4 (sum and carry).
    check_temp5_add3bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp5[0] == (p4 ^ c4)) && (temp5[1] == (g4 | (p4 & c4)))
    );

// temp6 is in1[5] + in2[5] + c5 (sum and carry).
    check_temp6_add3bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp6[0] == (p5 ^ c5)) && (temp6[1] == (g5 | (p5 & c5)))
    );

// temp7 is in1[6] + in2[6] + c6 (sum and carry).
    check_temp7_add3bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp7[0] == (p6 ^ c6)) && (temp7[1] == (g6 | (p6 & c6)))
    );

// temp8 is in1[7] + in2[7] + c7 (sum and carry).
    check_temp8_add3bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (temp8[0] == ((in1[7] ^ in2[7]) ^ c7)) &&
        (temp8[1] == ((in1[7] & in2[7]) | ((in1[7] ^ in2[7]) & c7)))
    );

// res is concatenation of temp bits per RTL mapping.
    check_res_concatenation: assert property (
        @(posedge clk) disable iff (!reset_n)
        res == {temp8[1:0], temp7[0], temp6[0], temp5[0], temp4[0], temp3[0], temp2[0], temp1[0]}
    );

endmodule

rtl:
module nor_gate(
    input A,
    input B,
    output Z
);

    assign Z = ~(A | B);

endmodule

sva:
module nor_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Z
);

// Z implements NOR of A and B.
    check_nor_function: assert property (
        @(posedge clk) Z === ~(A | B)
    );

// Z equals (~A & ~B) (De Morgan consistency).
    check_demorgan_equivalence: assert property (
        @(posedge clk) Z === ((~A) & (~B))
    );

// Z can be HIGH only when both inputs are LOW.
    check_Z_high_only_if_inputs_low: assert property (
        @(posedge clk) (Z === 1'b1) |-> ((A === 1'b0) && (B === 1'b0))
    );

// When both inputs are LOW, Z must be HIGH.
    check_inputs_low_imply_Z_high: assert property (
        @(posedge clk) ((A === 1'b0) && (B === 1'b0)) |-> (Z === 1'b1)
    );

// If A is HIGH, Z must be LOW.
    check_A_high_implies_Z_low: assert property (
        @(posedge clk) (A === 1'b1) |-> (Z === 1'b0)
    );

// If B is HIGH, Z must be LOW.
    check_B_high_implies_Z_low: assert property (
        @(posedge clk) (B === 1'b1) |-> (Z === 1'b0)
    );

// If both inputs are HIGH, Z must be LOW.
    check_both_inputs_high_implies_Z_low: assert property (
        @(posedge clk) ((A === 1'b1) && (B === 1'b1)) |-> (Z === 1'b0)
    );

// If Z is LOW, at least one input must be HIGH.
    check_Z_low_implies_any_input_high: assert property (
        @(posedge clk) (Z === 1'b0) |-> ((A === 1'b1) || (B === 1'b1))
    );

endmodule

rtl:
module sky130_fd_sc_lp__nand4 (
    Y,
    A,
    B,
    C,
    D
);

    output Y;
    input  A;
    input  B;
    input  C;
    input  D;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire nand0_out_Y;

    nand nand0 (nand0_out_Y, D, C, B, A     );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module sky130_fd_sc_lp__nand4_sva (
    input logic CLK,   // Sampling clock (DUT has no clock/reset; purely combinational)
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y
);

///// Functional equivalence /////
    // Y equals the 4-input NAND of A,B,C,D.
    check_y_is_nand4: assert property (
        @(posedge CLK) Y == ~(A & B & C & D)
    );

///// Truth table implications /////
    // If all inputs are 1, Y must be 0.
    check_all_ones_implies_y0: assert property (
        @(posedge CLK) (A && B && C && D) |-> (Y == 1'b0)
    );

// If A is 0, Y must be 1.
    check_a0_implies_y1: assert property (
        @(posedge CLK) (A == 1'b0) |-> (Y == 1'b1)
    );

// If B is 0, Y must be 1.
    check_b0_implies_y1: assert property (
        @(posedge CLK) (B == 1'b0) |-> (Y == 1'b1)
    );

// If C is 0, Y must be 1.
    check_c0_implies_y1: assert property (
        @(posedge CLK) (C == 1'b0) |-> (Y == 1'b1)
    );

// If D is 0, Y must be 1.
    check_d0_implies_y1: assert property (
        @(posedge CLK) (D == 1'b0) |-> (Y == 1'b1)
    );

// Y can be 0 only when all inputs are 1.
    check_y0_implies_all_ones: assert property (
        @(posedge CLK) (Y == 1'b0) |-> (A && B && C && D)
    );

///// Edge-driven behavior when last input goes HIGH /////
    // When A rises and B,C,D are stably 1, Y must be 0.
    check_y_fall_when_A_rises_last: assert property (
        @(posedge CLK) $rose(A) && B && C && D && $past(B) && $past(C) && $past(D) |-> (Y == 1'b0)
    );

// When B rises and A,C,D are stably 1, Y must be 0.
    check_y_fall_when_B_rises_last: assert property (
        @(posedge CLK) $rose(B) && A && C && D && $past(A) && $past(C) && $past(D) |-> (Y == 1'b0)
    );

// When C rises and A,B,D are stably 1, Y must be 0.
    check_y_fall_when_C_rises_last: assert property (
        @(posedge CLK) $rose(C) && A && B && D && $past(A) && $past(B) && $past(D) |-> (Y == 1'b0)
    );

// When D rises and A,B,C are stably 1, Y must be 0.
    check_y_fall_when_D_rises_last: assert property (
        @(posedge CLK) $rose(D) && A && B && C && $past(A) && $past(B) && $past(C) |-> (Y == 1'b0)
    );

endmodule

