sva:
module sky130_fd_sc_lp__a211o_sva (
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic C1
);

// No clock or reset in RTL; pure combinational. Sample on input edges.

    // At A1 rising edge, X equals (A1&A2)|B1|C1.
    check_func_on_posedge_A1: assert property (
        @(posedge A1) X == ((A1 & A2) | B1 | C1)
    );

// At A1 falling edge, X equals (A1&A2)|B1|C1.
    check_func_on_negedge_A1: assert property (
        @(negedge A1) X == ((A1 & A2) | B1 | C1)
    );

// At A2 rising edge, X equals (A1&A2)|B1|C1.
    check_func_on_posedge_A2: assert property (
        @(posedge A2) X == ((A1 & A2) | B1 | C1)
    );

// At A2 falling edge, X equals (A1&A2)|B1|C1.
    check_func_on_negedge_A2: assert property (
        @(negedge A2) X == ((A1 & A2) | B1 | C1)
    );

// At B1 rising edge, X equals (A1&A2)|B1|C1.
    check_func_on_posedge_B1: assert property (
        @(posedge B1) X == ((A1 & A2) | B1 | C1)
    );

// At B1 falling edge, X equals (A1&A2)|B1|C1.
    check_func_on_negedge_B1: assert property (
        @(negedge B1) X == ((A1 & A2) | B1 | C1)
    );

// At C1 rising edge, X equals (A1&A2)|B1|C1.
    check_func_on_posedge_C1: assert property (
        @(posedge C1) X == ((A1 & A2) | B1 | C1)
    );

// At C1 falling edge, X equals (A1&A2)|B1|C1.
    check_func_on_negedge_C1: assert property (
        @(negedge C1) X == ((A1 & A2) | B1 | C1)
    );

endmodule

module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [1:0] S,
    input logic [3:0] B
);

///// Functional mapping (combinational, sampled on clk) /////
    // B matches the RTL expression for all A,S.
    check_functional_mapping: assert property (
        @(posedge clk)
            B == ( S[0]
                   ? ( (S[1] ? {2'b00, A[3], A[3]} : {A[1:0], A[3:2]}) >> 1 )
                   :   (S[1] ? {2'b00, A[3], A[3]} : {A[1:0], A[3:2]}) )
    );

// For S == 2'b00: B = {A1, A0, A3, A2}.
    check_case_S_00: assert property (
        @(posedge clk) (S == 2'b00) |-> (B == {A[1], A[0], A[3], A[2]})
    );

// For S == 2'b01: B = {0, A1, A0, A3}.
    check_case_S_01: assert property (
        @(posedge clk) (S == 2'b01) |-> (B == {1'b0, A[1], A[0], A[3]})
    );

// For S == 2'b10: B = {0, 0, A3, A3}.
    check_case_S_10: assert property (
        @(posedge clk) (S == 2'b10) |-> (B == {2'b00, A[3], A[3]})
    );

// For S == 2'b11: B = {0, 0, 0, A3}.
    check_case_S_11: assert property (
        @(posedge clk) (S == 2'b11) |-> (B == {3'b000, A[3]})
    );

///// Basic invariants derived from the RTL /////
    // When shifting by 1 (S[0]==1), B[3] must be 0 (logical right shift).
    check_shift1_msb_zero: assert property (
        @(posedge clk) S[0] |-> (B[3] == 1'b0)
    );

// When S[1]==1, upper two bits of B are always 0 (due to temp composition).
    check_s1_upper_zero: assert property (
        @(posedge clk) S[1] |-> (B[3:2] == 2'b00)
    );

// For S == 2'b10, low two bits of B are identical.
    check_s10_lowpair_equal: assert property (
        @(posedge clk) (S == 2'b10) |-> (B[1] == B[0])
    );

// For S == 2'b11, B[2:1] are 0.
    check_s11_mid_zero: assert property (
        @(posedge clk) (S == 2'b11) |-> (B[2:1] == 2'b00)
    );

endmodule

rtl:
module t_order_a (
   m_from_clk_lev1_r, n_from_clk_lev2, o_from_com_levs11, o_from_comandclk_levs12,
   clk, a_to_clk_levm3, b_to_clk_levm1, c_com_levs10, d_to_clk_levm2, one
   );

   input clk;
   input [7:0] a_to_clk_levm3;
   input [7:0] b_to_clk_levm1;
   input [7:0] c_com_levs10;
   input [7:0] d_to_clk_levm2;
   input [7:0] one;
   output [7:0] m_from_clk_lev1_r;
   output [7:0] n_from_clk_lev2;
   output [7:0] o_from_com_levs11;
   output [7:0] o_from_comandclk_levs12;


   reg [7:0]		m_from_clk_lev1_r;
   wire [7:0] a_to_clk_levm1;
   wire [7:0] a_to_clk_levm2;
   wire [7:0] c_com_levs11;
   reg [7:0]  o_from_comandclk_levs12;
   wire [7:0]  n_from_clk_lev2;
   wire [7:0]  n_from_clk_lev3;

   assign     a_to_clk_levm1 = a_to_clk_levm2 + d_to_clk_levm2;
   assign     a_to_clk_levm2 = a_to_clk_levm3 + 0;

   always @ (posedge clk) begin
      m_from_clk_lev1_r <= a_to_clk_levm1 + b_to_clk_levm1;
   end

   assign c_com_levs11 = c_com_levs10 + one;
   always @ (c_com_levs11 or n_from_clk_lev3) o_from_comandclk_levs12 = c_com_levs11 + n_from_clk_lev3;
   assign n_from_clk_lev2 = m_from_clk_lev1_r;
   assign n_from_clk_lev3 = n_from_clk_lev2;
   wire [7:0] o_from_com_levs11 = c_com_levs10 + 1;

endmodule

sva:
module t_order_a_sva (
    input logic clk,
    input logic [7:0] a_to_clk_levm3,
    input logic [7:0] b_to_clk_levm1,
    input logic [7:0] c_com_levs10,
    input logic [7:0] d_to_clk_levm2,
    input logic [7:0] one,
    input logic [7:0] m_from_clk_lev1_r,
    input logic [7:0] n_from_clk_lev2,
    input logic [7:0] o_from_com_levs11,
    input logic [7:0] o_from_comandclk_levs12
);

// n_from_clk_lev2 is a combinational mirror of m_from_clk_lev1_r.
    check_n_mirrors_m: assert property (
        @(posedge clk) n_from_clk_lev2 == m_from_clk_lev1_r
    );

// o_from_com_levs11 is c_com_levs10 + 1 (8-bit wrap).
    check_o_com_plus1: assert property (
        @(posedge clk) o_from_com_levs11 == (c_com_levs10 + 8'd1)
    );

// o_from_comandclk_levs12 equals (c_com_levs10 + one) + n_from_clk_lev2 (combinational).
    check_o_andclk_sum_with_n: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ((c_com_levs10 + one) + n_from_clk_lev2)
    );

// By transitivity (n == m), o_from_comandclk_levs12 also equals (c_com_levs10 + one) + m_from_clk_lev1_r.
    check_o_andclk_sum_with_m: assert property (
        @(posedge clk) o_from_comandclk_levs12 == ((c_com_levs10 + one) + m_from_clk_lev1_r)
    );

endmodule

rtl:
module complement_concat (
    input [15:0] data_in,
    output reg [31:0] comp_concat_out
);

    always @(*) begin
        comp_concat_out = {data_in, ~data_in};
    end

endmodule

sva:
module complement_concat_sva (
    input logic CLK,
    input logic RESETn,
    input logic [15:0] data_in,
    input logic [31:0] comp_concat_out
);

// Output equals input concatenated with its bitwise complement.
    check_concat_exact: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out == {data_in, ~data_in}
    );

// Upper 16 bits mirror data_in.
    check_upper_matches_input: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out[31:16] == data_in
    );

// Lower 16 bits are bitwise complement of data_in.
    check_lower_is_complement: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out[15:0] == ~data_in
    );

// Upper half is bitwise complement of lower half.
    check_upper_complements_lower: assert property (
        @(posedge CLK) disable iff (!RESETn)
            comp_concat_out[31:16] == ~comp_concat_out[15:0]
    );

// Lower half XOR input is all ones.
    check_lower_xor_all_ones: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (comp_concat_out[15:0] ^ data_in) == 16'hFFFF
    );

// Pairwise OR across halves is all ones.
    check_pairwise_or_ones: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (comp_concat_out[31:16] | comp_concat_out[15:0]) == 16'hFFFF
    );

// Pairwise AND across halves is all zeros.
    check_pairwise_and_zeros: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (comp_concat_out[31:16] & comp_concat_out[15:0]) == 16'h0000
    );

// No X/Z on output when input has no X/Z.
    check_no_unknown_when_input_known: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (!$isunknown(data_in)) |-> (!$isunknown(comp_concat_out))
    );

endmodule

rtl:
module hazard_unit
    (
        input   wire[4:0]   rs_ex_mem_hz_i,
        input   wire[4:0]   rt_ex_mem_hz_i,
        input   wire[4:0]   rd_mem_wb_hz_i,
        input   wire[4:0]   rd_wb_ret_hz_i,
        input   wire        mem_to_reg_ex_mem_hz_i,
        input   wire        reg_wr_mem_wb_hz_i,
        input   wire        reg_wr_wb_ret_hz_i,
        input   wire        branch_taken_ex_mem_hz_i,
        input   wire        jump_iss_ex_hz_i,
        input   wire        brn_pred_ex_mem_hz_i,
        output  wire        stall_fetch_hz_o,
        output  wire        stall_iss_hz_o,
        output  wire        flush_ex_hz_o,
        output  wire        flush_iss_hz_o,
        output  wire[1:0]   fwd_p1_ex_mem_hz_o,
        output  wire[1:0]   fwd_p2_ex_mem_hz_o
    );

    wire        stall_fetch_hz;
    wire        stall_iss_hz;
    wire        flush_ex_hz;
    wire        flush_iss_hz;
    wire[1:0]   fwd_p1_ex_mem_hz;
    wire[1:0]   fwd_p2_ex_mem_hz;

    assign  stall_fetch_hz_o    = stall_fetch_hz;
    assign  stall_iss_hz_o      = stall_iss_hz;
    assign  flush_ex_hz_o       = flush_ex_hz;
    assign  flush_iss_hz_o      = flush_iss_hz;
    assign  fwd_p1_ex_mem_hz_o  = fwd_p1_ex_mem_hz; 
    assign  fwd_p2_ex_mem_hz_o  = fwd_p2_ex_mem_hz; 

    assign  fwd_p1_ex_mem_hz = (reg_wr_mem_wb_hz_i & |rd_mem_wb_hz_i &
                               (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) ? 2'b10 
                               : (reg_wr_wb_ret_hz_i &  |rd_wb_ret_hz_i &                       
                                 (rd_wb_ret_hz_i == rs_ex_mem_hz_i)) ? 2'b01 
                                 : 2'b00;
    assign  fwd_p2_ex_mem_hz = (reg_wr_mem_wb_hz_i & |rd_mem_wb_hz_i &
                               (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) ? 2'b10 
                               : (reg_wr_wb_ret_hz_i & |rd_wb_ret_hz_i &
                                 (rd_wb_ret_hz_i == rt_ex_mem_hz_i)) ? 2'b01 
                                 : 2'b00;
    assign stall_fetch_hz = 1'b0;
    assign stall_iss_hz = 1'b0;
    assign flush_ex_hz = branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i;
    assign flush_iss_hz = (branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i) | jump_iss_ex_hz_i;

endmodule

sva:
module hazard_unit_sva (
    input logic CLK,
    input logic RESETn,
    input logic [4:0] rs_ex_mem_hz_i,
    input logic [4:0] rt_ex_mem_hz_i,
    input logic [4:0] rd_mem_wb_hz_i,
    input logic [4:0] rd_wb_ret_hz_i,
    input logic       mem_to_reg_ex_mem_hz_i,
    input logic       reg_wr_mem_wb_hz_i,
    input logic       reg_wr_wb_ret_hz_i,
    input logic       branch_taken_ex_mem_hz_i,
    input logic       jump_iss_ex_hz_i,
    input logic       brn_pred_ex_mem_hz_i,
    input logic       stall_fetch_hz_o,
    input logic       stall_iss_hz_o,
    input logic       flush_ex_hz_o,
    input logic       flush_iss_hz_o,
    input logic [1:0] fwd_p1_ex_mem_hz_o,
    input logic [1:0] fwd_p2_ex_mem_hz_o
);

///// Stall outputs /////
    // stall_fetch_hz_o is always 0.
    check_stall_fetch_const_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (stall_fetch_hz_o == 1'b0)
    );

// stall_iss_hz_o is always 0.
    check_stall_iss_const_zero: assert property (
        @(posedge CLK) disable iff (!RESETn) (stall_iss_hz_o == 1'b0)
    );

///// Flush logic /////
    // flush_ex_hz_o equals branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i.
    check_flush_ex_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_ex_hz_o == (branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i))
    );

// flush_iss_hz_o equals (branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i) | jump_iss_ex_hz_i.
    check_flush_iss_definition: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_iss_hz_o == ((branch_taken_ex_mem_hz_i & ~brn_pred_ex_mem_hz_i) | jump_iss_ex_hz_i))
    );

// flush_ex implies taken and mispredicted.
    check_flush_ex_implies_taken_mispred: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_ex_hz_o |-> (branch_taken_ex_mem_hz_i && !brn_pred_ex_mem_hz_i))
    );

// flush_ex implies flush_iss (since flush_iss = flush_ex | jump).
    check_flush_ex_implies_flush_iss: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (flush_ex_hz_o |-> flush_iss_hz_o)
    );

// jump sets flush_iss.
    check_jump_sets_flush_iss: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (jump_iss_ex_hz_i |-> flush_iss_hz_o)
    );

///// Forwarding for operand 1 (rs_ex_mem_hz_i) /////
    // If MEM/WB writes matching nonzero rd, select 2'b10.
    check_fwd_p1_memwb_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i))
             |-> (fwd_p1_ex_mem_hz_o == 2'b10))
    );

// If MEM/WB is not selected and WB/RET writes matching nonzero rd, select 2'b01.
    check_fwd_p1_wbret_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
               (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i)))
             |-> (fwd_p1_ex_mem_hz_o == 2'b01))
    );

// If neither source matches, select 2'b00.
    check_fwd_p1_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
               !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i)))
             |-> (fwd_p1_ex_mem_hz_o == 2'b00))
    );

// If 2'b10 is selected, MEM/WB match condition holds.
    check_fwd_p1_when_10_implies_memwb: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p1_ex_mem_hz_o == 2'b10)
             |-> (reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)))
    );

// If 2'b01 is selected, MEM/WB not selected and WB/RET match holds.
    check_fwd_p1_when_01_implies_wbret: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p1_ex_mem_hz_o == 2'b01)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
                  (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i))))
    );

// If 2'b00 is selected, neither match holds.
    check_fwd_p1_when_00_implies_none: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p1_ex_mem_hz_o == 2'b00)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rs_ex_mem_hz_i)) &&
                  !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rs_ex_mem_hz_i))))
    );

// fwd_p1 encoding never 2'b11.
    check_fwd_p1_never_11: assert property (
        @(posedge CLK) disable iff (!RESETn)
            (fwd_p1_ex_mem_hz_o inside {2'b00,2'b01,2'b10})
    );

///// Forwarding for operand 2 (rt_ex_mem_hz_i) /////
    // If MEM/WB writes matching nonzero rd, select 2'b10.
    check_fwd_p2_memwb_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i))
             |-> (fwd_p2_ex_mem_hz_o == 2'b10))
    );

// If MEM/WB is not selected and WB/RET writes matching nonzero rd, select 2'b01.
    check_fwd_p2_wbret_select: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
               (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i)))
             |-> (fwd_p2_ex_mem_hz_o == 2'b01))
    );

// If neither source matches, select 2'b00.
    check_fwd_p2_default_zero: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
               !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i)))
             |-> (fwd_p2_ex_mem_hz_o == 2'b00))
    );

// If 2'b10 is selected, MEM/WB match condition holds.
    check_fwd_p2_when_10_implies_memwb: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p2_ex_mem_hz_o == 2'b10)
             |-> (reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)))
    );

// If 2'b01 is selected, MEM/WB not selected and WB/RET match holds.
    check_fwd_p2_when_01_implies_wbret: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p2_ex_mem_hz_o == 2'b01)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
                  (reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i))))
    );

// If 2'b00 is selected, neither match holds.
    check_fwd_p2_when_00_implies_none: assert property (
        @(posedge CLK) disable iff (!RESETn)
            ((fwd_p2_ex_mem_hz_o == 2'b00)
             |-> (!(reg_wr_mem_wb_hz_i && (|rd_mem_wb_hz_i) && (rd_mem_wb_hz_i == rt_ex_mem_hz_i)) &&
                  !(reg_wr_wb_ret_hz_i && (|rd_wb_ret_hz_i) && (rd_wb_ret_hz_i == rt_ex_mem_hz_i))))
