rtl:
module bitwise_op (x, y, z, o);

	input [31:0] x, y, z;
	output [31:0] o;

	wire [31:0] temp;

	assign temp = y ^ z;
	assign o = z ^ (x & temp);

endmodule

sva:
module bitwise_op_sva (
    // Environment clock for sampling; DUT has no clock/reset (pure combinational)
    input logic clk,
    // DUT ports
    input logic [31:0] x,
    input logic [31:0] y,
    input logic [31:0] z,
    input logic [31:0] o
);

// o matches the RTL expression exactly.
    check_output_matches_rtl_expr: assert property (
        @(posedge clk) o == (z ^ (x & (y ^ z)))
    );

// o is equivalent to a bitwise mux: x ? y : z.
    check_mux_equivalence: assert property (
        @(posedge clk) o == ((x & y) | (~x & z))
    );

// The XOR of o and z equals x masked with (y^z).
    check_xor_mask_relation: assert property (
        @(posedge clk) (o ^ z) == (x & (y ^ z))
    );

// When x is all zeros, o must pass through z.
    check_pass_through_when_x_zero: assert property (
        @(posedge clk) (x == 32'b0) |-> (o == z)
    );

// When x is all ones, o must equal y.
    check_select_y_when_x_all_ones: assert property (
        @(posedge clk) (x == 32'hFFFF_FFFF) |-> (o == y)
    );

// When y equals z, o must equal z.
    check_when_y_equals_z: assert property (
        @(posedge clk) (y == z) |-> (o == z)
    );

// When z is all zeros, o reduces to x & y.
    check_when_z_zero: assert property (
        @(posedge clk) (z == 32'b0) |-> (o == (x & y))
    );

// When y is all zeros, o reduces to (~x) & z.
    check_when_y_zero: assert property (
        @(posedge clk) (y == 32'b0) |-> (o == ((~x) & z))
    );

// Bits selected by x must match y (masked equality).
    check_y_path_mask: assert property (
        @(posedge clk) (o & x) == (y & x)
    );

// Bits not selected by x must match z (masked equality).
    check_z_path_mask: assert property (
        @(posedge clk) (o & ~x) == (z & ~x)
    );

endmodule

rtl:
module full_adder(a, b, c_in, sum, c_out, p, g);
   input a, b, c_in;
   output sum, c_out, p, g;

   assign {c_out, sum} = a + b + c_in;
   assign p = a & b;
   assign g = a ^ b; // Corrected the expression for g
endmodule

sva:
module full_adder_sva (
    input logic clk,
    input logic a,
    input logic b,
    input logic c_in,
    input logic sum,
    input logic c_out,
    input logic p,
    input logic g
);

// Sum and carry must equal the 2-bit addition of a, b, and c_in.
    check_add_result: assert property (
        @(posedge clk) {c_out, sum} == (a + b + c_in)
    );

// p equals logical AND of a and b.
    check_p_and: assert property (
        @(posedge clk) p == (a & b)
    );

// g equals logical XOR of a and b.
    check_g_xor: assert property (
        @(posedge clk) g == (a ^ b)
    );

// sum equals XOR of a, b, and c_in.
    check_sum_triple_xor: assert property (
        @(posedge clk) sum == (a ^ b ^ c_in)
    );

// c_out equals majority of a, b, and c_in.
    check_cout_majority: assert property (
        @(posedge clk) c_out == ((a & b) | (a & c_in) | (b & c_in))
    );

// sum equals g XOR c_in.
    check_sum_g_xor_cin: assert property (
        @(posedge clk) sum == (g ^ c_in)
    );

// c_out equals p OR (g AND c_in).
    check_cout_p_or_gcin: assert property (
        @(posedge clk) c_out == (p | (g & c_in))
    );

// p and g cannot be HIGH at the same time.
    check_p_g_mutex: assert property (
        @(posedge clk) !(p & g)
    );

// If p is HIGH (a&b=1), then sum equals c_in and c_out is 1.
    check_when_p_high: assert property (
        @(posedge clk) p |-> (sum == c_in) && (c_out == 1'b1)
    );

// If g is HIGH (a^b=1), then sum is ~c_in and c_out equals c_in.
    check_when_g_high: assert property (
        @(posedge clk) g |-> (sum == ~c_in) && (c_out == c_in)
    );

endmodule

rtl:
module SyncCounter(
    input clk,
    input rst,
    output reg [3:0] count,
    output [3:0] leds
);

always @(posedge clk) begin
    if (rst) begin
        count <= 4'b0;
    end else begin
        count <= count + 1;
    end
end

assign leds = count;

endmodule

sva:
module SyncCounter_sva (
    input logic clk,
    input logic rst,
    input logic [3:0] count,
    input logic [3:0] leds
);

// leds must always mirror count.
    check_leds_mirror_count: assert property (
        @(posedge clk) disable iff (rst) (leds == count)
    );

// Synchronous reset drives count to 0 on the next cycle.
    check_reset_clears_count_next: assert property (
        @(posedge clk) rst |=> (count == 4'd0)
    );

// If reset is held across consecutive cycles, count remains 0.
    check_reset_held_keeps_zero: assert property (
        @(posedge clk) ($past(rst) && rst) |-> (count == 4'd0)
    );

// Synchronous reset drives leds to 0 on the next cycle.
    check_reset_clears_leds_next: assert property (
        @(posedge clk) rst |=> (leds == 4'd0)
    );

endmodule

module binary_counter_sva (
    input logic clk,
    input logic reset,
    input logic count_up,
    input logic [3:0] count
);

// Reset drives count to zero at each clock.
    reset_forces_zero: assert property (
        @(posedge clk) reset |-> (count == 4'h0)
    );

// While reset is held across cycles, count stays at 0 and stable.
    hold_zero_while_reset: assert property (
        @(posedge clk) (reset && $past(reset)) |-> (count == 4'h0) && (count == $past(count))
    );

// Up-wrap: from 0xF to 0 when count_up is 1.
    check_wrap_up: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && $past(count_up) && ($past(count) == 4'hF) |-> (count == 4'h0)
    );

// If result is F, prior state/direction must be E with up or 0 with down.
    check_f_predecessors: assert property (
        @(posedge clk) disable iff (reset) $past(!reset) && (count == 4'hF) |->
            ( ($past(count_up) && ($past(count) == 4'hE)) || (!$past(count_up) && ($past(count) == 4'h0)) )
    );

endmodule

rtl:
module flip_flop(
    input CLK,
    input D,
    input SCD,
    input SCE,
    input SET_B,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Q,
    output Q_N
);

    reg [1:0] state;
    // Declare next_state as a reg type to make it a valid l-value
    reg [1:0] next_state;

    // Define the state transitions
    always @(*) begin
        case(state)
            2'b00: begin
                next_state = {SCD, SCE};
            end
            2'b01: begin
                next_state = {SCD, ~SET_B};
            end
            2'b10: begin
                next_state = {~SCE, SET_B};
            end
            2'b11: begin
                next_state = {~SCE, ~SET_B};
            end
        endcase
    end

    // Define the output functions
    assign Q = (state == 2'b10 || state == 2'b11) ? 1'b1 : 1'b0;
    assign Q_N = ~Q;

    // Define the state machine
    always @(posedge CLK) begin
        state <= next_state;
    end

endmodule

sva:
module flip_flop_sva (
    input logic CLK,
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic SET_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic Q,
    input logic Q_N
);

///// Output relationship /////
    // Q_N is always the logical inverse of Q.
    check_qn_is_inverse_of_q: assert property (
        @(posedge CLK) Q_N == ~Q
    );

///// Next-state behavior of Q /////
    // If Q=1 and SCE=0, Q stays 1 next cycle.
    check_hold_one_when_sce_low: assert property (
        @(posedge CLK) (Q && (SCE == 1'b0)) |=> (Q == 1'b1)
    );

// If Q=1 and SCE=1, Q becomes 0 next cycle.
    check_clear_when_sce_high: assert property (
        @(posedge CLK) (Q && (SCE == 1'b1)) |=> (Q == 1'b0)
    );

// If Q=0 and SCD=1, Q becomes 1 next cycle.
    check_set_when_scd_high: assert property (
        @(posedge CLK) ((!Q) && (SCD == 1'b1)) |=> (Q == 1'b1)
    );

// If Q=0 and SCD=0, Q stays 0 next cycle.
    check_hold_zero_when_scd_low: assert property (
        @(posedge CLK) ((!Q) && (SCD == 1'b0)) |=> (Q == 1'b0)
    );

endmodule

rtl:
module counter(input clk, input reset, input in, output p);
	reg [5-1:0] r;
	always @(posedge clk or posedge reset) begin
		if(reset)
			r <= 0;
		else begin
			if(r)
				r <= r + 5'b1;
			if(in)
				r <= 1;
		end
	end
	assign p = r == 20;
endmodule

