);

// Note: DUT has no clock/reset; assertions sample on external clk with active-low reset.

    // Out must equal bitwise OR of inputs.
    check_vector_or_equivalence: assert property (
        @(posedge clk) disable iff (!rst_n) out == (a | b)
    );

// If both inputs are zero, output must be zero.
    check_zero_inputs_zero_output: assert property (
        @(posedge clk) disable iff (!rst_n) ((a == 32'b0) && (b == 32'b0)) |-> (out == 32'b0)
    );

// When a is zero, out must equal b.
    check_pass_through_when_a_zero: assert property (
        @(posedge clk) disable iff (!rst_n) (a == 32'b0) |-> (out == b)
    );

// When b is zero, out must equal a.
    check_pass_through_when_b_zero: assert property (
        @(posedge clk) disable iff (!rst_n) (b == 32'b0) |-> (out == a)
    );

// When a equals b, out must equal a (idempotent OR).
    check_idempotent_when_inputs_equal: assert property (
        @(posedge clk) disable iff (!rst_n) (a == b) |-> (out == a)
    );

// Out cannot have 1s where both inputs are 0.
    check_out_subset_of_or_inputs: assert property (
        @(posedge clk) disable iff (!rst_n) ((out & ~(a | b)) == 32'b0)
    );

// Any input 1s must appear in out.
    check_inputs_cover_output: assert property (
        @(posedge clk) disable iff (!rst_n) (((a | b) & ~out) == 32'b0)
    );

endmodule

rtl:
module logic_function (
    input A, B, Ci,
    output S, Co
);

wire n9, n10, n11;

assign n11 = ~(A ^ B);
assign S = ~(Ci ^ n11);
assign n10 = A & B & Ci;
assign n9 = ~(A & B);
assign Co = ~(n10 & n9);

endmodule

sva:
module logic_function_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);

// S equals ~(Ci ^ ~(A ^ B)) as coded.
    check_sum_xnor_chain: assert property (
        @(posedge CLK) S == ~(Ci ^ ~(A ^ B))
    );

// S equals three-input XOR of A, B, and Ci.
    check_sum_triple_xor: assert property (
        @(posedge CLK) S == (A ^ B ^ Ci)
    );

// When A and B are equal, S mirrors Ci.
    check_sum_when_AeqB: assert property (
        @(posedge CLK) (A == B) |-> (S == Ci)
    );

// When A and B differ, S is the inverse of Ci.
    check_sum_when_AneB: assert property (
        @(posedge CLK) (A != B) |-> (S == ~Ci)
    );

// S ^ Ci equals A ^ B (rearranged XOR identity).
    check_sum_xor_relation: assert property (
        @(posedge CLK) (S ^ Ci) == (A ^ B)
    );

// Co equals ~( (A & B & Ci) & ~(A & B) ) as coded.
    check_carry_expr: assert property (
        @(posedge CLK) Co == ~((A & B & Ci) & ~(A & B))
    );

// Co is constant HIGH for all input combinations (logic simplification).
    check_carry_const_high: assert property (
        @(posedge CLK) Co == 1'b1
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] data_in,
    input [1:0] control,
    output [3:0] data_out
);

    reg [3:0] temp;

    always @(*) begin
        case (control)
            2'b00: temp = {data_in[2:0], 1'b0};
            2'b01: temp = {1'b0, data_in[3:1]};
            2'b10: temp = {data_in[2:0], data_in[3]};
            2'b11: temp = {data_in[3], data_in[3:1]};
        endcase
    end

    assign data_out = temp;

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] data_in,
    input logic [1:0] control,
    input logic [3:0] data_out
);

// Clock: none in RTL; assertions use external clk. Reset: none. Logic: purely combinational.

    // control=00: logical left shift by 1 with zero fill.
    check_sll_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b00) |-> (data_out == {data_in[2:0], 1'b0})
    );

// control=01: logical right shift by 1 with zero fill.
    check_srl_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b01) |-> (data_out == {1'b0, data_in[3:1]})
    );

// control=10: rotate left by 1.
    check_rol_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b10) |-> (data_out == {data_in[2:0], data_in[3]})
    );

// control=11: arithmetic right shift by 1 (sign extension).
    check_asr_result: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b11) |-> (data_out == {data_in[3], data_in[3:1]})
    );

// For SLL (00), LSB must be zero (zero-fill).
    check_sll_zero_lsb: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b00) |-> (data_out[0] == 1'b0)
    );

// For SRL (01), MSB must be zero (zero-fill).
    check_srl_zero_msb: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b01) |-> (data_out[3] == 1'b0)
    );

// For ROL (10), LSB equals prior MSB.
    check_rol_lsb_is_msb: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b10) |-> (data_out[0] == data_in[3])
    );

// For ASR (11), MSB equals sign bit.
    check_asr_msb_is_sign: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b11) |-> (data_out[3] == data_in[3])
    );

// For ASR (11), bit2 equals sign bit after shift.
    check_asr_bit2_is_sign: assert property (
        @(posedge clk) disable iff (1'b0) (control == 2'b11) |-> (data_out[2] == data_in[3])
    );

endmodule

rtl:
module sky130_fd_sc_ls__and4 (
    X,
    A,
    B,
    C,
    D
);

    output X;
    input  A;
    input  B;
    input  C;
    input  D;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire and0_out_X;

    and and0 (and0_out_X, A, B, C, D     );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_ls__and4_sva (
    input logic CLK,  // external sampling clock (RTL has no clock)
    input logic X,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

// Function: X equals A & B & C & D at every sample.
    check_function_equivalence: assert property (
        @(posedge CLK) X == (A & B & C & D)
    );

// When X is HIGH, all inputs must be HIGH.
    check_x_high_implies_all_high: assert property (
        @(posedge CLK) (X == 1'b1) |-> (A && B && C && D)
    );

// When all inputs are HIGH, X must be HIGH.
    check_all_inputs_high_implies_x_high: assert property (
        @(posedge CLK) (A && B && C && D) |-> (X == 1'b1)
    );

// A rising edge on X requires all inputs HIGH in the same cycle.
    check_rose_x_requires_all_high: assert property (
        @(posedge CLK) $rose(X) |-> (A && B && C && D)
    );

// A falling edge on X requires at least one input LOW in the same cycle.
    check_fell_x_requires_some_low: assert property (
        @(posedge CLK) $fell(X) |-> !(A && B && C && D)
    );

endmodule

module dff_with_set_sva (
    input logic CLK,
    input logic D,
    input logic SET,
    input logic Q
);

// Q on the next cycle equals 1 if SET was 1, else D from the previous cycle.
    q_next_matches_function: assert property (
        @(posedge CLK) 1'b1 |-> ##1 (Q == ($past(SET) ? 1'b1 : $past(D)))
    );

// SET takes priority: if SET is 1, Q is 1 on the next cycle.
    set_forces_q_high_next: assert property (
        @(posedge CLK) SET |=> (Q == 1'b1)
    );

// When SET is 0 and D is 1, Q is 1 on the next cycle.
    data1_updates_q_next_when_no_set: assert property (
        @(posedge CLK) (!SET && (D == 1'b1)) |=> (Q == 1'b1)
    );

// When SET is 0 and D is 0, Q is 0 on the next cycle.
    data0_updates_q_next_when_no_set: assert property (
        @(posedge CLK) (!SET && (D == 1'b0)) |=> (Q == 1'b0)
    );

endmodule

rtl:
module parity_check (
    input A,
    input B,
    input C,
    input D,
    output parity
);

    wire ab, cd, abcd;

    xor(ab, A, B);
    xor(cd, C, D);
    xor(abcd, ab, cd);
    assign parity = abcd;

endmodule

sva:
module parity_check_sva (
    input logic CLK,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic parity
);

// parity equals XOR of all inputs
    check_parity_function: assert property (
        @(posedge CLK) parity == (A ^ B ^ C ^ D)
    );

