module mux_4_1_sva (
    // Analysis: no clock/reset in RTL; pure combinational 4:1 mux built from 2:1; Y = S1 ? (S0?D:C) : (S0?B:A)
    input logic clk,   // sampling clock for assertions
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1
);

// Y matches the composed 4:1 mux function.
    check_functional_equivalence: assert property (
        @(posedge clk) Y == (S1 ? (S0 ? D : C) : (S0 ? B : A))
    );

// When S1=0,S0=0, Y selects A.
    check_select_00_selects_A: assert property (
        @(posedge clk) (!S1 && !S0) |-> (Y == A)
    );

// When S1=0,S0=1, Y selects B.
    check_select_01_selects_B: assert property (
        @(posedge clk) (!S1 && S0) |-> (Y == B)
    );

// When S1=1,S0=0, Y selects C.
    check_select_10_selects_C: assert property (
        @(posedge clk) (S1 && !S0) |-> (Y == C)
    );

// When S1=1,S0=1, Y selects D.
    check_select_11_selects_D: assert property (
        @(posedge clk) (S1 && S0) |-> (Y == D)
    );

endmodule

rtl:
module adder_subtractor(
    input [3:0] A, B,
    input C,
    output [3:0] S,
    output Cout
);

wire [3:0] B_neg;
assign B_neg = (~B) + 1;

assign S = (C) ? (A + B_neg) : (A + B);
assign Cout = (C) ? (A >= B) : (A + B >= 16);

endmodule

sva:
module adder_subtractor_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic C,
    input logic [3:0] S,
    input logic Cout
);

// Addition mode: S equals A + B (4-bit result).
    check_sum_add_mode: assert property (
        @(posedge clk) (!C) |-> (S == (A + B))
    );

// Subtraction mode: S equals A + (~B + 1) (two's complement, 4-bit).
    check_sum_sub_mode: assert property (
        @(posedge clk) C |-> (S == (A + ((~B) + 4'd1)))
    );

// Addition mode: Cout equals (A + B >= 16) as coded (with 4-bit sum semantics).
    check_cout_add_mode_expr: assert property (
        @(posedge clk) (!C) |-> (Cout == ((A + B) >= 32'd16))
    );

// Subtraction mode: Cout indicates no borrow (A >= B).
    check_cout_sub_mode_expr: assert property (
        @(posedge clk) C |-> (Cout == (A >= B))
    );

// Subtraction mode: when A == B, result is zero and no borrow.
    check_sub_equal_inputs_zero: assert property (
        @(posedge clk) (C && (A == B)) |-> (S == 4'd0 && Cout == 1'b1)
    );

// Addition mode: when B == 0, pass-through A to S.
    check_add_b_zero_passthrough: assert property (
        @(posedge clk) (!C && (B == 4'd0)) |-> (S == A)
    );

// Addition mode: when B == 0, Cout is zero per coded compare.
    check_add_b_zero_no_carry: assert property (
        @(posedge clk) (!C && (B == 4'd0)) |-> (Cout == 1'b0)
    );

// Addition mode: when A == 0, pass-through B to S.
    check_add_a_zero_passthrough: assert property (
        @(posedge clk) (!C && (A == 4'd0)) |-> (S == B)
    );

// Subtraction mode: when B == 0, pass-through A to S.
    check_sub_b_zero_passthrough: assert property (
        @(posedge clk) (C && (B == 4'd0)) |-> (S == A)
    );

// Subtraction mode: when B == 0, Cout is one (A >= 0).
    check_sub_b_zero_no_borrow: assert property (
        @(posedge clk) (C && (B == 4'd0)) |-> (Cout == 1'b1)
    );

endmodule

rtl:
module controlunit(input [5:0] imemout,output brnch,output memorywrite,output memoryread,output alusrc,output regw,output regdst,output aluop,output memtoreg);
reg brnch,memorywrite,memoryread,aluop;
reg memtoreg,alusrc,regw,regdst;

always @ ( imemout )
begin
	if(imemout[5:0] == 6'b000000)
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b1;
		regdst = 1'b1;
		aluop = 1'b1;
		memtoreg = 1'b1;
	end
	else
	if(imemout[5:0] == 6'b100011)
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b1;
		alusrc = 1'b1;
		regw = 1'b1;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else
	if(imemout[5:0] == 6'b101011)
	begin
		brnch = 1'b0;
		memorywrite = 1'b1;
		memoryread = 1'b0;
		alusrc = 1'b1;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else
	if(imemout[5:0] == 6'b000100)
	begin
		brnch = 1'b1;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
	else
	begin
		brnch = 1'b0;
		memorywrite = 1'b0;
		memoryread = 1'b0;
		alusrc = 1'b0;
		regw = 1'b0;
		regdst = 1'b0;
		aluop = 1'b0;
		memtoreg = 1'b0;
	end
end

endmodule

sva:
module controlunit_sva (
    input  logic        clk,
    input  logic        reset_n,
    input  logic [5:0]  imemout,
    input  logic        brnch,
    input  logic        memorywrite,
    input  logic        memoryread,
    input  logic        alusrc,
    input  logic        regw,
    input  logic        regdst,
    input  logic        aluop,
    input  logic        memtoreg
);

// R-type decode drives exact outputs.
    check_decode_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_RTYPE) |-> (brnch==1'b0 && memorywrite==1'b0 && memoryread==1'b0 && alusrc==1'b0 && regw==1'b1 && regdst==1'b1 && aluop==1'b1 && memtoreg==1'b1)
    );

// LW decode drives exact outputs.
    check_decode_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_LW) |-> (brnch==1'b0 && memorywrite==1'b0 && memoryread==1'b1 && alusrc==1'b1 && regw==1'b1 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

// SW decode drives exact outputs.
    check_decode_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_SW) |-> (brnch==1'b0 && memorywrite==1'b1 && memoryread==1'b0 && alusrc==1'b1 && regw==1'b0 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

// BEQ decode drives exact outputs.
    check_decode_beq: assert property (
        @(posedge clk) disable iff (!reset_n)
        (imemout == OPC_BEQ) |-> (brnch==1'b1 && memorywrite==1'b0 && memoryread==1'b0 && alusrc==1'b0 && regw==1'b0 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

// Default decode (all other opcodes) drives all zeros.
    check_decode_default: assert property (
        @(posedge clk) disable iff (!reset_n)
        ((imemout != OPC_RTYPE) && (imemout != OPC_LW) && (imemout != OPC_SW) && (imemout != OPC_BEQ))
        |-> (brnch==1'b0 && memorywrite==1'b0 && memoryread==1'b0 && alusrc==1'b0 && regw==1'b0 && regdst==1'b0 && aluop==1'b0 && memtoreg==1'b0)
    );

// Read and write to memory are never both asserted.
    check_rd_wr_mutex: assert property (
        @(posedge clk) disable iff (!reset_n)
        !(memoryread && memorywrite)
    );

// ALUOP high occurs only for R-type.
    check_aluop_only_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        aluop |-> (imemout == OPC_RTYPE)
    );

// REGDST high occurs only for R-type.
    check_regdst_only_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        regdst |-> (imemout == OPC_RTYPE)
    );

// MEMTOREG high occurs only for R-type.
    check_memtoreg_only_rtype: assert property (
        @(posedge clk) disable iff (!reset_n)
        memtoreg |-> (imemout == OPC_RTYPE)
    );

// ALUSRC high occurs only for LW or SW.
    check_alusrc_lw_or_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        alusrc |-> ((imemout == OPC_LW) || (imemout == OPC_SW))
    );

// REGW high occurs only for R-type or LW.
    check_regw_rtype_or_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        regw |-> ((imemout == OPC_RTYPE) || (imemout == OPC_LW))
    );

// MEMORYREAD implies LW opcode.
    check_memoryread_implies_lw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memoryread |-> (imemout == OPC_LW)
    );

// MEMORYWRITE implies SW opcode.
    check_memorywrite_implies_sw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memorywrite |-> (imemout == OPC_SW)
    );

// BRNCH implies BEQ opcode and no memory access.
    check_branch_implies_beq_no_mem: assert property (
        @(posedge clk) disable iff (!reset_n)
        brnch |-> ((imemout == OPC_BEQ) && !memoryread && !memorywrite)
    );

// MEMTOREG high implies REGW high and no MEMORYREAD.
    check_memtoreg_implies_regw: assert property (
        @(posedge clk) disable iff (!reset_n)
        memtoreg |-> (regw && !memoryread)
    );

endmodule

rtl:
module comparator (
    input [3:0] A,
    input [3:0] B,
    output reg EQ,
    output reg GT,
    output reg LT
);

    always @(*) begin
        if (A == B) begin
            EQ = 1;
            GT = 0;
            LT = 0;
        end else if (A > B) begin
            EQ = 0;
            GT = 1;
            LT = 0;
        end else begin
            EQ = 0;
            GT = 0;
            LT = 1;
        end
    end

endmodule

sva:
module comparator_sva (
    input  logic        CLK,   // Sampling clock for assertions (DUT is combinational)
    input  logic [3:0]  A,
    input  logic [3:0]  B,
    input  logic        EQ,
    input  logic        GT,
    input  logic        LT
);

///// Comparator behavior /////
    // Exactly one of EQ/GT/LT must be HIGH.
    check_outputs_onehot: assert property (
        @(posedge CLK) $onehot({EQ, GT, LT})
    );

// When A == B, outputs must be EQ=1, GT=0, LT=0.
    check_equal_maps_to_EQ: assert property (
        @(posedge CLK) (A == B) |-> (EQ && !GT && !LT)
    );

// When A > B, outputs must be EQ=0, GT=1, LT=0.
    check_greater_maps_to_GT: assert property (
        @(posedge CLK) (A > B) |-> (!EQ && GT && !LT)
    );

// When A < B, outputs must be EQ=0, GT=0, LT=1.
    check_less_maps_to_LT: assert property (
        @(posedge CLK) (A < B) |-> (!EQ && !GT && LT)
    );

// If EQ is 1, then A must equal B.
    check_EQ_implies_equal: assert property (
        @(posedge CLK) EQ |-> (A == B)
    );

// If GT is 1, then A must be greater than B.
    check_GT_implies_greater: assert property (
        @(posedge CLK) GT |-> (A > B)
    );

// If LT is 1, then A must be less than B.
    check_LT_implies_less: assert property (
        @(posedge CLK) LT |-> (A < B)
    );

// Outputs are never all zero.
    check_not_all_zero: assert property (
        @(posedge CLK) (EQ || GT || LT)
    );

endmodule

rtl:
module snps_clock_gate_high_d_ff_en_w32_0_8 (
    input CLK,
    input EN,
    input TE,
    output ENCLK
);

    TLATNTSCAX2TS latch (
        .E(EN),
        .SE(TE),
        .CK(CLK),
        .ECK(ENCLK)
    );

endmodule

module TLATNTSCAX2TS (
    input E,
    input SE,
    input CK,
    output reg ECK
);
always @ (posedge CK)
    begin
        if (SE)
            ECK <= E;
