module alu_4bit_sva (
    input logic CLK,
    input logic [3:0] Z,
    input logic [1:0] op,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C
);

// For op=00, Z equals 4-bit A+B.
    check_add_correct: assert property (
        @(posedge CLK) (op == 2'b00) |-> (Z == (A + B))
    );

// For op=00, Z-B equals A modulo 16.
    check_add_inverse: assert property (
        @(posedge CLK) (op == 2'b00) |-> ((Z - B) == A)
    );

// For op=01, Z equals 4-bit A-B.
    check_sub_correct: assert property (
        @(posedge CLK) (op == 2'b01) |-> (Z == (A - B))
    );

// For op=01, Z+B equals A modulo 16.
    check_sub_inverse: assert property (
        @(posedge CLK) (op == 2'b01) |-> ((Z + B) == A)
    );

// For op=10, Z equals A & B.
    check_and_correct: assert property (
        @(posedge CLK) (op == 2'b10) |-> (Z == (A & B))
    );

// For op=10, Z can only have bits set that are set in A.
    check_and_subset_A: assert property (
        @(posedge CLK) (op == 2'b10) |-> ((Z & ~A) == 4'b0000)
    );

// For op=10, Z can only have bits set that are set in B.
    check_and_subset_B: assert property (
        @(posedge CLK) (op == 2'b10) |-> ((Z & ~B) == 4'b0000)
    );

// For op=11, Z equals A | B.
    check_or_correct: assert property (
        @(posedge CLK) (op == 2'b11) |-> (Z == (A | B))
    );

// For op=11, all bits set in A must be set in Z.
    check_or_superset_A: assert property (
        @(posedge CLK) (op == 2'b11) |-> ((~Z & A) == 4'b0000)
    );

// For op=11, all bits set in B must be set in Z.
    check_or_superset_B: assert property (
        @(posedge CLK) (op == 2'b11) |-> ((~Z & B) == 4'b0000)
    );

endmodule

module multi_input_output_sva (
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [7:0] C,
    input logic [7:0] D,
    input logic [7:0] E,
    input logic [7:0] F,
    input logic [7:0] G,
    input logic [7:0] H,
    input logic [7:0] Y
);

///// Functional correctness /////
    // Y equals (A+B)-(C+D)+(E+F)-(G+H) with 8-bit wrap.
    check_y_definition: assert property (
        @(posedge A[0]) Y == (A + B) - (C + D) + (E + F) - (G + H)
    );

// All inputs zero yields Y=0.
    check_y_all_zero_input: assert property (
        @(posedge A[0]) ((A==8'h00)&&(B==8'h00)&&(C==8'h00)&&(D==8'h00)&&(E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y==8'h00)
    );

// If B..H are zero, Y passes A.
    check_y_passthrough_A_when_others_zero: assert property (
        @(posedge A[0]) ((B==8'h00)&&(C==8'h00)&&(D==8'h00)&&(E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y==A)
    );

// If pairwise inputs match (A=C,B=D,E=G,F=H), Y is zero.
    check_y_zero_when_pairs_equal: assert property (
        @(posedge A[0]) ((A==C)&&(B==D)&&(E==G)&&(F==H))
        |-> (Y==8'h00)
    );

// If E=F=G=H=0, Y=(A+B)-(C+D).
    check_y_when_EFGH_zero: assert property (
        @(posedge A[0]) ((E==8'h00)&&(F==8'h00)&&(G==8'h00)&&(H==8'h00))
        |-> (Y == (A + B) - (C + D))
    );

// If G=H=0, Y=(A+B)-(C+D)+(E+F).
    check_y_when_GH_zero: assert property (
        @(posedge A[0]) ((G==8'h00)&&(H==8'h00))
        |-> (Y == (A + B) - (C + D) + (E + F))
    );

// If A=B=C=D=0, Y=(E+F)-(G+H).
    check_y_when_ABCD_zero: assert property (
        @(posedge A[0]) ((A==8'h00)&&(B==8'h00)&&(C==8'h00)&&(D==8'h00))
        |-> (Y == (E + F) - (G + H))
    );

///// Algebraic cancellation checks (mod-256 arithmetic) /////
    // Adding back (G+H) cancels the final subtraction.
    check_cancel_gh_addback: assert property (
        @(posedge A[0]) (Y + (G + H)) == ( (A + B) - (C + D) + (E + F) )
    );

// Adding back (G+H) then subtracting (E+F) cancels the last two pairs.
    check_cancel_gh_then_ef: assert property (
        @(posedge A[0]) ((Y + (G + H)) - (E + F)) == ( (A + B) - (C + D) )
    );

// After canceling GH and EF and adding (C+D), recover (A+B).
    check_recover_ab: assert property (
        @(posedge A[0]) (((Y + (G + H)) - (E + F)) + (C + D)) == (A + B)
    );

endmodule

