rtl:
module d_flipflop_with_setreset(input D, SET_B, VPWR, VGND, VPB, VNB, CLK,
                                output Q, Q_N);

    // Internal signals
    wire S;
    wire R;

    // Set/reset circuitry
    assign S = ~SET_B & VPB & VNB;
    assign R = SET_B & VPB & VNB;

    // D latch
    reg Q_reg;
    always @(posedge CLK)
    begin
        if (S) Q_reg <= 1'b1;
        else if (R) Q_reg <= 1'b0;
        else Q_reg <= D;
    end

    // Output
    assign Q = Q_reg;
    assign Q_N = ~Q_reg;

endmodule

sva:
module d_flipflop_with_setreset_sva (
    input logic D,
    input logic SET_B,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB,
    input logic CLK,
    input logic Q,
    input logic Q_N
);

// Q_N is always the complement of Q.
    check_qn_is_complement: assert property (
        @(posedge CLK) (Q_N == ~Q)
    );

// S and R are never both asserted.
    check_sr_mutex: assert property (
        @(posedge CLK) !(S && R)
    );

// Exactly one of S or R asserted iff VPB & VNB is HIGH.
    check_sr_xor_matches_power: assert property (
        @(posedge CLK) ((S ^ R) == (VPB & VNB))
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic reset,
    input logic up_down,
    input logic load,
    input logic [3:0] data_in,
    input logic [3:0] count
);

// Reset high forces count to zero at the clock edge.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 4'b0000)
    );

// With load asserted (no reset), next count captures data_in.
    check_load_captures_data: assert property (
        @(posedge clk) disable iff (reset) load |=> (count == $past(data_in))
    );

// With load deasserted and up_down=1 (no reset), next count increments by 1 (mod 16).
    check_increment_when_up: assert property (
        @(posedge clk) disable iff (reset) (!load && up_down) |=> (count == ($past(count) + 4'd1))
    );

// With load deasserted and up_down=0 (no reset), next count decrements by 1 (mod 16).
    check_decrement_when_down: assert property (
        @(posedge clk) disable iff (reset) (!load && !up_down) |=> (count == ($past(count) - 4'd1))
    );

endmodule

module add_sub_sva (
    input logic CLK,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic SUB,
    input logic [3:0] RESULT
);

// RESULT equals add or subtract modulo 16 based on SUB.
    check_result_function: assert property (
        @(posedge CLK) RESULT == (SUB ? ((A - B) & 5'h0F) : ((A + B) & 5'h0F))
    );

// When SUB=0, RESULT is A+B modulo 16.
    check_add_when_sub0: assert property (
        @(posedge CLK) (SUB == 1'b0) |-> (RESULT == ((A + B) & 5'h0F))
    );

// When SUB=1, RESULT is A-B modulo 16.
    check_sub_when_sub1: assert property (
        @(posedge CLK) (SUB == 1'b1) |-> (RESULT == ((A - B) & 5'h0F))
    );

// With SUB=0 and B=0, RESULT equals A.
    check_add_identity_B_zero: assert property (
        @(posedge CLK) (SUB == 1'b0 && B == 4'h0) |-> (RESULT == A)
    );

// With SUB=0 and A=0, RESULT equals B.
    check_add_identity_A_zero: assert property (
        @(posedge CLK) (SUB == 1'b0 && A == 4'h0) |-> (RESULT == B)
    );

// With SUB=1 and B=0, RESULT equals A.
    check_sub_identity_B_zero: assert property (
        @(posedge CLK) (SUB == 1'b1 && B == 4'h0) |-> (RESULT == A)
    );

// With SUB=1 and A=B, RESULT is zero.
    check_sub_self_subtract_zero: assert property (
        @(posedge CLK) (SUB == 1'b1 && A == B) |-> (RESULT == 4'h0)
    );

// With SUB=1 and A=0, RESULT equals (16 - B) modulo 16.
    check_sub_A_zero_twos_comp: assert property (
        @(posedge CLK) (SUB == 1'b1 && A == 4'h0) |-> (RESULT == ((5'd16 - B) & 5'h0F))
    );

// With SUB=0 and B=1, RESULT is A+1 modulo 16.
    check_add_increment_by_one: assert property (
        @(posedge CLK) (SUB == 1'b0 && B == 4'h1) |-> (RESULT == ((A + 4'h1) & 5'h0F))
    );

// With SUB=1 and B=1, RESULT is A-1 modulo 16.
    check_sub_decrement_by_one: assert property (
        @(posedge CLK) (SUB == 1'b1 && B == 4'h1) |-> (RESULT == ((A - 4'h1) & 5'h0F))
    );

endmodule

module dff_set_sva (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic SET_B
);

// Analysis:
    // - Clock: CLK (posedge)
    // - Async set: SET_B active-low; drives Q=1 when low
    // - Logic: sequential (DFF with asynchronous set)
    // - Behavior: if SET_B==0 -> Q=1 asynchronously; else on posedge CLK -> Q captures D

    ///// Asynchronous set behavior /////
    // When SET_B is LOW, Q must be driven HIGH.
    check_async_set_dominates: assert property (
        @(posedge CLK) (SET_B == 1'b0) |-> (Q == 1'b1)
    );

// On the first clock after SET_B rises (release), Q captures D from the release edge.
    check_capture_after_set_release: assert property (
        @(posedge CLK) disable iff (!SET_B) $rose(SET_B) |-> ##1 (Q == $past(D,1))
    );

///// Sanity constraints derived from RTL /////
    // Q cannot be 0 while SET_B is LOW.
    check_Q_zero_implies_set_deasserted: assert property (
        @(posedge CLK) (Q == 1'b0) |-> (SET_B == 1'b1)
    );

endmodule

