sva:
module divider_sva (
    input logic CLK,
    input logic [3:0] data_in,
    input logic [1:0] data_out
);

// Analysis: No clock or reset in RTL; pure combinational always @*. Assertions are sampled on external CLK.
    // Analysis: Maps data_in 0-2->00, 3-5->01, 6-8->10, 9-11->11; 12-15 hit default->00.

    // 0..2 must map to 2'b00.
    map_0_to_2_is_00: assert property (
        @(posedge CLK) (data_in inside {4'd0,4'd1,4'd2}) |-> (data_out == 2'b00)
    );

// 3..5 must map to 2'b01.
    map_3_to_5_is_01: assert property (
        @(posedge CLK) (data_in inside {4'd3,4'd4,4'd5}) |-> (data_out == 2'b01)
    );

// 6..8 must map to 2'b10.
    map_6_to_8_is_10: assert property (
        @(posedge CLK) (data_in inside {4'd6,4'd7,4'd8}) |-> (data_out == 2'b10)
    );

// 9..11 must map to 2'b11.
    map_9_to_11_is_11: assert property (
        @(posedge CLK) (data_in inside {4'd9,4'd10,4'd11}) |-> (data_out == 2'b11)
    );

// 12..15 hit default and must map to 2'b00.
    map_12_to_15_default_is_00: assert property (
        @(posedge CLK) (data_in >= 4'd12) |-> (data_out == 2'b00)
    );

// If output is 2'b00, input must be 0..2 or 12..15.
    reverse_00_inputs: assert property (
        @(posedge CLK) (data_out == 2'b00) |-> (data_in inside {4'd0,4'd1,4'd2,4'd12,4'd13,4'd14,4'd15})
    );

// If output is 2'b01, input must be 3..5.
    reverse_01_inputs: assert property (
        @(posedge CLK) (data_out == 2'b01) |-> (data_in inside {4'd3,4'd4,4'd5})
    );

// If output is 2'b10, input must be 6..8.
    reverse_10_inputs: assert property (
        @(posedge CLK) (data_out == 2'b10) |-> (data_in inside {4'd6,4'd7,4'd8})
    );

// If output is 2'b11, input must be 9..11.
    reverse_11_inputs: assert property (
        @(posedge CLK) (data_out == 2'b11) |-> (data_in inside {4'd9,4'd10,4'd11})
    );

endmodule

rtl:
module logic_operation (
    input [1:0] logic_op_x,
    input [31:0] operand_0_x,
    input [31:0] operand_1_x,
    output [31:0] logic_result_x
);

reg [31:0] temp_result;

always @*
begin
    case (logic_op_x)
        2'b00: temp_result = operand_0_x & operand_1_x;
        2'b01: temp_result = operand_0_x | operand_1_x;
        2'b10: temp_result = operand_0_x ^ operand_1_x;
        default: temp_result = 0;
    endcase
end

assign logic_result_x = temp_result;

endmodule

sva:
module logic_operation_sva (
    input logic clk,
    input logic [1:0] logic_op_x,
    input logic [31:0] operand_0_x,
    input logic [31:0] operand_1_x,
    input logic [31:0] logic_result_x
);

// AND opcode yields bitwise AND of operands.
    check_and_mapping: assert property (
        @(posedge clk) (logic_op_x == 2'b00) |-> (logic_result_x == (operand_0_x & operand_1_x))
    );

// OR opcode yields bitwise OR of operands.
    check_or_mapping: assert property (
        @(posedge clk) (logic_op_x == 2'b01) |-> (logic_result_x == (operand_0_x | operand_1_x))
    );

// XOR opcode yields bitwise XOR of operands.
    check_xor_mapping: assert property (
        @(posedge clk) (logic_op_x == 2'b10) |-> (logic_result_x == (operand_0_x ^ operand_1_x))
    );

// Default opcode (2'b11) yields zero.
    check_default_zero: assert property (
        @(posedge clk) (logic_op_x == 2'b11) |-> (logic_result_x == 32'h0000_0000)
    );

// AND absorbing element: if any operand is zero, result is zero.
    check_and_zero_absorbing: assert property (
        @(posedge clk) (logic_op_x == 2'b00 && ((operand_0_x == 32'h0000_0000) || (operand_1_x == 32'h0000_0000))) |-> (logic_result_x == 32'h0000_0000)
    );

// AND identity with all-ones on operand_0 passes operand_1.
    check_and_ones_identity_op0: assert property (
        @(posedge clk) (logic_op_x == 2'b00 && (operand_0_x == 32'hFFFF_FFFF)) |-> (logic_result_x == operand_1_x)
    );

// AND identity with all-ones on operand_1 passes operand_0.
    check_and_ones_identity_op1: assert property (
        @(posedge clk) (logic_op_x == 2'b00 && (operand_1_x == 32'hFFFF_FFFF)) |-> (logic_result_x == operand_0_x)
    );

// OR absorbing element: if any operand is all-ones, result is all-ones.
    check_or_ones_absorbing: assert property (
        @(posedge clk) (logic_op_x == 2'b01 && ((operand_0_x == 32'hFFFF_FFFF) || (operand_1_x == 32'hFFFF_FFFF))) |-> (logic_result_x == 32'hFFFF_FFFF)
    );

// XOR with equal operands yields zero.
    check_xor_equal_operands_zero: assert property (
        @(posedge clk) (logic_op_x == 2'b10 && (operand_0_x == operand_1_x)) |-> (logic_result_x == 32'h0000_0000)
    );

endmodule

module shift_and_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic [2:0] load_data,
    input logic [1:0] and_input,
    input logic out,
    input logic [2:0] shift_reg
);

// Synchronous active-high reset clears shift_reg to zero in the cycle reset is 1.
    reset_clears_shift_reg: assert property (
        @(posedge clk) reset |-> (shift_reg == 3'b000)
    );

// If any and_input bit is 0, out must be 0.
    out_zero_when_any_input_zero: assert property (
        @(posedge clk) disable iff (reset) ((and_input[0] == 1'b0) || (and_input[1] == 1'b0)) |-> (out == 1'b0)
    );

// After a load, next-cycle out uses the loaded LSB.
    out_reflects_loaded_lsb: assert property (
        @(posedge clk) disable iff (reset) load |=> (out == (and_input[0] & and_input[1] & $past(load_data[0])))
    );

endmodule

module dff_sva (
    input logic D,
    input logic C,
    input logic S,
    input logic R,
    input logic Q
);

// Clock: C posedge. S: sync set (active-high). R: sync reset (active-high). Sequential flop.

    // S asserted at clock edge forces Q=1 on next clock.
    check_set_forces_one: assert property (
        @(posedge C) S |=> (Q == 1'b1)
    );

// R asserted without S forces Q=0 on next clock.
    check_reset_forces_zero_when_not_set: assert property (
        @(posedge C) (!S && R) |=> (Q == 1'b0)
    );

// When both S and R asserted, S has priority and Q=1 next clock.
    check_set_has_priority_over_reset: assert property (
        @(posedge C) (S && R) |=> (Q == 1'b1)
    );

// With neither S nor R, Q_next equals prior D.
    check_follows_d_when_no_sr: assert property (
        @(posedge C) disable iff (R) (!S && !R) |=> (Q == $past(D))
    );

// With neither S nor R and D==Q, Q holds its value.
    check_hold_when_no_sr_and_d_eq_q: assert property (
        @(posedge C) disable iff (R) (!S && !R && (D == Q)) |=> $stable(Q)
    );

// With neither S nor R and D!=Q, Q toggles to prior D.
    check_toggle_when_no_sr_and_d_neq_q: assert property (
        @(posedge C) disable iff (R) (!S && !R && (D != Q)) |=> (Q != $past(Q) && Q == $past(D))
    );

// Next-state equation: Q_next = (S ? 1 : (R ? 0 : D)).
    check_next_state_equation: assert property (
