    power_good #(
        .PWRGOOD_WIDTH(1)
    ) \pwrgood_pp0 (
        .Y(Y),
        .VPWR(VPWR),
        .VGND(VGND),
        .VPB(VPB),
        .VNB(VNB)
    );

