module power_good #(
    parameter PWRGOOD_WIDTH = 1
)(
    output [PWRGOOD_WIDTH - 1:0] Y,
    input VPWR,
    input VGND,
    input VPB,
    input VNB
);

    assign Y = (VPWR > VGND) ? VPB : VNB;

