module register_sva (
    input logic CLK,
    input logic SET,
    input logic RESET,
    input logic [3:0] D,
    input logic [3:0] Q
);

// Clk: CLK (posedge). RESET is synchronous, active-HIGH. Logic is sequential (flop with conditional load).

    ///// Functional behavior /////
    // Only SET asserted (no RESET): Q loads 4'hF on next cycle.
    set_only_loads_ones: assert property (
        @(posedge CLK) disable iff (RESET) (SET && !RESET) |=> (Q == 4'hF)
    );

// Only RESET asserted (no SET): Q loads 4'h0 on next cycle.
    reset_only_loads_zeros: assert property (
        @(posedge CLK) (RESET && !SET) |=> (Q == 4'h0)
    );

// Both asserted: Q loads D on next cycle.
    both_high_loads_d: assert property (
        @(posedge CLK) (SET && RESET) |=> (Q == D)
    );

// Rising SET with RESET low: Q loads 4'hF on next cycle.
    set_rise_loads_ones: assert property (
        @(posedge CLK) disable iff (RESET) ($rose(SET) && !RESET) |=> (Q == 4'hF)
    );

// Rising RESET with SET low: Q loads 4'h0 on next cycle.
    reset_rise_loads_zeros: assert property (
        @(posedge CLK) ($rose(RESET) && !SET) |=> (Q == 4'h0)
    );

endmodule

module d_ff_sva (
    input logic clk,
    input logic reset,
    input logic d,
    input logic q,
    input logic q_n
);

// q_n must be the logical inverse of q when not in reset.
    check_qn_is_inverse_of_q: assert property (
        @(posedge clk) disable iff (!reset) (q_n == ~q)
    );

// If reset is LOW at this cycle, q must be 0 on the next cycle.
    check_reset_low_clears_q_next: assert property (
        @(posedge clk) (!reset) |=> (q == 1'b0)
    );

// If reset was LOW on the previous cycle, q must be 0 now.
    check_prev_reset_low_q_is_zero_now: assert property (
        @(posedge clk) $past(!reset) |-> (q == 1'b0)
    );

// If reset is LOW at this cycle, q_n must be 1 on the next cycle.
    check_reset_low_sets_qn_next: assert property (
        @(posedge clk) (!reset) |=> (q_n == 1'b1)
    );

// If reset was LOW on the previous cycle, q_n must be 1 now.
    check_prev_reset_low_qn_is_one_now: assert property (
        @(posedge clk) $past(!reset) |-> (q_n == 1'b1)
    );

// q and q_n must never be equal when not in reset.
    check_q_and_qn_never_equal: assert property (
        @(posedge clk) disable iff (!reset) (q != q_n)
    );

endmodule

