  wire c1, c2, c3;

  FA_1 fa1 ( .A(A[0]), .B(B[0]), .Ci(Ci), .S(S[0]), .Co(c1) );
  FA_1 fa2 ( .A(A[1]), .B(B[1]), .Ci(c1), .S(S[1]), .Co(c2) );
