    check_eq_on_posedge_VPWR: assert property (
        @(posedge VPWR) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

// On VPWR falling edge, X equals ((A&B&C)==VPWR) && (VGND==0).
    check_eq_on_negedge_VPWR: assert property (
        @(negedge VPWR) X == (((A & B & C) == VPWR) && (VGND == 1'b0))
    );

