        |-> (out == $past(out))
    );

// Isolation: with sel==11 stable, changes on in0/in1/in2 do not affect out.
    check_isolation_sel11: assert property (
        @(posedge CLK)
            ($past(sel) == 2'b11 && sel == 2'b11 && in3 == $past(in3) &&
             ((in0 != $past(in0)) || (in1 != $past(in1)) || (in2 != $past(in2))))
        |-> (out == $past(out))
