);

// Sum equals 8-bit addition of a and b (modulo 256).
    check_sum_is_add: assert property (
        @(posedge CLK) sum == (a + b)
    );

// If a is zero, sum equals b.
    check_zero_a_identity: assert property (
        @(posedge CLK) (a == 8'h00) |-> (sum == b)
