                else if (state == 2'b01) state <= 2'b10; 
                else if (state == 2'b10) state <= 2'b00; 
                else state <= 2'b10;
                end
            2'b01: begin if (state == 2'b00) state <= state;
                    else if (state == 2'b01) state <= 2'b11;
