rtl:
module sky130_fd_sc_ms__sdfbbn (
    D      , // moved to the beginning of the list
    SCD    ,
    SCE    ,
    CLK    ,
    SET_B  ,
    RESET_B,
    Q      ,
    Q_N    ,
    VPWR   ,
    VGND   ,
    VPB    ,
    VNB
);

    input  D      ;
    input  SCD    ;
    input  SCE    ;
    input  CLK    ;
    input  SET_B  ;
    input  RESET_B;
    output Q      ;
    output Q_N    ;
    input  VPWR   ;
    input  VGND   ;
    input  VPB    ;
    input  VNB    ;

    reg Q_N;  // Removed assignment to Q_N from reg type to wire type

    // Inverted the Q output to match the Q_N output
    assign Q = ~Q_N;

    reg [1:0] state;

    always @ (posedge CLK) begin
        if (SET_B == 1'b0) begin
            Q_N <= 1'b1;
        end
        if (RESET_B == 1'b0) begin
            Q_N <= 1'b0;
        end
        if (SCE) begin
            Q_N <= D;
        end
        if (SCD) begin
            Q_N <= 1'b0;
        end
    end

endmodule

sva:
module sky130_fd_sc_ms__sdfbbn_sva (
    input logic D,
    input logic SCD,
    input logic SCE,
    input logic CLK,
    input logic SET_B,
    input logic RESET_B,
    input logic Q,
    input logic Q_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

// Clock: CLK. Resets: SET_B, RESET_B (active-low, synchronous).
    // Sequential FF with priority: SCD > SCE > !RESET_B > !SET_B. Q = ~Q_N.

    // Q is always inverse of Q_N.
    check_q_inverts_qn: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (Q == ~Q_N)
    );

// SCD high forces Q_N to 0 on the next cycle.
    check_scd_forces_zero: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) SCD |=> (Q_N == 1'b0)
    );

// With SCE high and SCD low, Q_N loads D on the next cycle.
    check_sce_loads_d_no_scd: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SCE && !SCD) |=> (Q_N == $past(D))
    );

// With RESET_B low and no later overrides, Q_N goes to 0 on the next cycle.
    check_reset_forces_zero_when_unoverridden: assert property (
        @(posedge CLK) (RESET_B == 1'b0) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b0)
    );

// With SET_B low and no later overrides, Q_N goes to 1 on the next cycle.
    check_set_forces_one_when_unoverridden: assert property (
        @(posedge CLK) (SET_B == 1'b0) && (RESET_B == 1'b1) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b1)
    );

// If SET_B and RESET_B both low (no SCE/SCD), RESET_B wins driving 0.
    check_reset_overrides_set: assert property (
        @(posedge CLK) (SET_B == 1'b0) && (RESET_B == 1'b0) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == 1'b0)
    );

// If RESET_B low and SCE high (no SCD), SCE overrides and Q_N loads D.
    check_sce_overrides_reset: assert property (
        @(posedge CLK) (RESET_B == 1'b0) && (SCE == 1'b1) && (SCD == 1'b0) |=> (Q_N == $past(D))
    );

// When SET_B, RESET_B deasserted and SCE/SCD low, Q_N holds its value.
    check_hold_when_no_ctrls: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SET_B == 1'b1) && (RESET_B == 1'b1) && (SCE == 1'b0) && (SCD == 1'b0) |=> (Q_N == $past(Q_N))
    );

// After SCE load (no SCD), Q reflects ~D on next cycle.
    check_q_updates_after_sce: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) (SCE && !SCD) |=> (Q == ~$past(D))
    );

// After SCD high, Q goes to 1 on the next cycle.
    check_q_one_after_scd: assert property (
        @(posedge CLK) disable iff (!SET_B || !RESET_B) SCD |=> (Q == 1'b1)
    );

endmodule

rtl:
module mux4to1 (
  input [3:0] in,
  input [1:0] sel,
  output reg out
);

  always @ (sel or in) begin
    case (sel)
      2'b00: out <= in[0];
      2'b01: out <= in[1];
      2'b10: out <= in[2];
      2'b11: out <= in[3];
    endcase
  end

endmodule

sva:
module mux4to1_sva (
  input logic CLK,
  input logic [3:0] in,
  input logic [1:0] sel,
  input logic out
);

// No clock/reset in RTL; sampled on external CLK. Combinational mux behavior.

  // Out equals the bit selected by sel.
  check_mux_function: assert property (
    @(posedge CLK) (out === in[sel])
  );

// When sel==00, out mirrors in[0].
  check_sel_00: assert property (
    @(posedge CLK) (sel == 2'b00) |-> (out === in[0])
  );

// When sel==01, out mirrors in[1].
  check_sel_01: assert property (
    @(posedge CLK) (sel == 2'b01) |-> (out === in[1])
  );

// When sel==10, out mirrors in[2].
  check_sel_10: assert property (
    @(posedge CLK) (sel == 2'b10) |-> (out === in[2])
  );

// When sel==11, out mirrors in[3].
  check_sel_11: assert property (
    @(posedge CLK) (sel == 2'b11) |-> (out === in[3])
  );

endmodule

rtl:
module and4b (
    input  A_N ,
    input  B   ,
    input  C   ,
    input  D   ,
    output X   ,
    input  VPB ,
    input  VPWR,
    input  VGND,
    input  VNB
);
    wire AB, CD, ABCD;

    // AND gates for AB and CD
    and gate_AB(AB, A_N, B);
    and gate_CD(CD, C, D);

    // AND gate for ABCD
    and gate_ABCD(ABCD, AB, CD);

    // Inverter for X
    not inv_X(X, ABCD);

endmodule

sva:
module and4b_sva (
    input logic CLK,   // external checker clock; DUT has no clock/reset
    input logic A_N,
    input logic B,
    input logic C,
    input logic D,
    input logic X,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

// X equals NAND of A_N, B, C, D.
    check_function_nand_equivalence: assert property (
        @(posedge CLK) X == ~(A_N & B & C & D)
    );

// When all inputs are HIGH, X must be LOW.
    check_all_high_implies_X_low: assert property (
        @(posedge CLK) (A_N && B && C && D) |-> (X == 1'b0)
    );

// When any input is LOW, X must be HIGH.
    check_any_low_implies_X_high: assert property (
        @(posedge CLK) ((!A_N) || (!B) || (!C) || (!D)) |-> (X == 1'b1)
    );

// If X is LOW, then all inputs must be HIGH.
    check_X_low_implies_all_high: assert property (
        @(posedge CLK) (X == 1'b0) |-> (A_N && B && C && D)
    );

// If X is HIGH, then at least one input is LOW.
    check_X_high_implies_any_low: assert property (
        @(posedge CLK) (X == 1'b1) |-> ((!A_N) || (!B) || (!C) || (!D))
    );

// With B,C,D HIGH, X equals NOT A_N.
    check_dep_A: assert property (
        @(posedge CLK) (B && C && D) |-> (X == ~A_N)
    );

// With A_N,C,D HIGH, X equals NOT B.
    check_dep_B: assert property (
        @(posedge CLK) (A_N && C && D) |-> (X == ~B)
    );

// With A_N,B,D HIGH, X equals NOT C.
    check_dep_C: assert property (
        @(posedge CLK) (A_N && B && D) |-> (X == ~C)
    );

// With A_N,B,C HIGH, X equals NOT D.
    check_dep_D: assert property (
        @(posedge CLK) (A_N && B && C) |-> (X == ~D)
    );

endmodule

rtl:
module bitwise_operators (
  input [7:0] in1,
  input [7:0] in2,
  output [7:0] out_and,
  output [7:0] out_or,
  output [7:0] out_xor,
  output [7:0] out_not
);

  assign out_and = in1 & in2;
  assign out_or = in1 | in2;
  assign out_xor = in1 ^ in2;
  assign out_not = ~in1;

endmodule

sva:
module bitwise_operators_sva (
  input logic CLK,
  input logic [7:0] in1,
  input logic [7:0] in2,
  input logic [7:0] out_and,
  input logic [7:0] out_or,
  input logic [7:0] out_xor,
  input logic [7:0] out_not
);

// out_and equals bitwise AND of inputs.
  check_out_and_function: assert property (
    @(posedge CLK) out_and == (in1 & in2)
  );

// out_or equals bitwise OR of inputs.
  check_out_or_function: assert property (
    @(posedge CLK) out_or == (in1 | in2)
  );

// out_xor equals bitwise XOR of inputs.
  check_out_xor_function: assert property (
    @(posedge CLK) out_xor == (in1 ^ in2)
  );

// out_not equals bitwise NOT of in1.
  check_out_not_function: assert property (
    @(posedge CLK) out_not == ~in1
  );

// De Morgan for OR: a|b == ~(~a & ~b).
  check_or_demorgan: assert property (
    @(posedge CLK) out_or == ~(~in1 & ~in2)
  );

// De Morgan for AND: a&b == ~(~a | ~b).
  check_and_demorgan: assert property (
    @(posedge CLK) out_and == ~(~in1 | ~in2)
  );

// OR equals (AND | XOR) for same operands.
  check_or_is_and_or_xor: assert property (
    @(posedge CLK) out_or == (out_and | out_xor)
  );

// XOR equals OR AND NOT(AND) for same operands.
  check_xor_is_or_andnot_and: assert property (
    @(posedge CLK) out_xor == (out_or & ~out_and)
  );

// AND and XOR are bitwise disjoint.
  check_and_xor_mutex: assert property (
    @(posedge CLK) (out_and & out_xor) == '0
  );

// in1 and its complement are bitwise disjoint.
  check_in1_out_not_mutex: assert property (
    @(posedge CLK) (in1 & out_not) == '0
  );

// in1 XOR ~in1 yields all ones.
  check_in1_xor_out_not_allones: assert property (
    @(posedge CLK) (in1 ^ out_not) == 8'hFF
  );

endmodule

module priority_encoder_sva (
    input logic clk,
    input logic [7:0] in,
    input logic [2:0] pos
);

// If in[7] is 1, pos must be 7 (highest priority).
    check_priority_bit7: assert property (
        @(posedge clk) in[7] |-> (pos == 3'd7)
    );

// If in[6] is 1 and in[7] is 0, pos must be 6.
    check_priority_bit6: assert property (
        @(posedge clk) (!in[7] && in[6]) |-> (pos == 3'd6)
    );

// If in[5] is 1 and in[7:6] are 0, pos must be 5.
    check_priority_bit5: assert property (
        @(posedge clk) ((in[7:6] == 2'b00) && in[5]) |-> (pos == 3'd5)
    );

// If in[4] is 1 and in[7:5] are 0, pos must be 4.
    check_priority_bit4: assert property (
        @(posedge clk) ((in[7:5] == 3'b000) && in[4]) |-> (pos == 3'd4)
    );

// If in[3] is 1 and in[7:4] are 0, pos must be 3.
    check_priority_bit3: assert property (
        @(posedge clk) ((in[7:4] == 4'b0000) && in[3]) |-> (pos == 3'd3)
    );

// If in[2] is 1 and in[7:3] are 0, pos must be 2.
    check_priority_bit2: assert property (
        @(posedge clk) ((in[7:3] == 5'b00000) && in[2]) |-> (pos == 3'd2)
    );

// If in[1] is 1 and in[7:2] are 0, pos must be 1.
    check_priority_bit1: assert property (
        @(posedge clk) ((in[7:2] == 6'b000000) && in[1]) |-> (pos == 3'd1)
    );

// If only in[0] is 1 (no higher bits), pos must be 0.
    check_priority_bit0: assert property (
        @(posedge clk) ((in[7:1] == 7'b0000000) && in[0]) |-> (pos == 3'd0)
    );

// If all inputs are 0, pos must be 0.
    check_zero_input: assert property (
        @(posedge clk) (in == 8'b0000_0000) |-> (pos == 3'd0)
    );

// If pos is 7, then in[7] must be 1.
    check_inverse_pos7_requires_in7: assert property (
        @(posedge clk) (pos == 3'd7) |-> in[7]
    );

// If pos is 6, then in[7] must be 0 and in[6] must be 1.
    check_inverse_pos6_requires_in6_and_no7: assert property (
        @(posedge clk) (pos == 3'd6) |-> (!in[7] && in[6])
    );

// If pos is 0, no higher bits [7:1] may be set.
    check_inverse_pos0_blocks_higher: assert property (
        @(posedge clk) (pos == 3'd0) |-> (in[7:1] == 7'b0000000)
    );

endmodule

rtl:
module counter_4bit(clk, rst, q);

input clk, rst;
output reg [3:0] q;

always @(posedge clk) begin
	if (rst == 1'b1) // Synchronous reset
		q <= 4'b0;
	else if (q == 4'b1111) // Counter rolls over to 0
		q <= 4'b0;
	else
		q <= q + 1; // Counter increments
end

endmodule

