		     SHIFT_LA = 1'b1;

			  SHIFT_LR = 1'b0;

			  LOGICAL_OP = 1'b0;

		end

		AND: begin 

		     OSEL = 2'b10;

		     SHIFT_LA = 1'b0;

			  SHIFT_LR = 1'b0;

			  LOGICAL_OP = 1'b1;

		end

		OR:  begin 

			  OSEL = 2'b10;

		     SHIFT_LA = 1'b0;

			  SHIFT_LR = 1'b0;

			  LOGICAL_OP = 1'b0;

		end

		default: begin 

			  OSEL = 2'b11;

		     SHIFT_LA = 1'b0;

