module salsa20_qr(
                 input wire [31 : 0]  y0,
                 input wire [31 : 0]  y1,
                 input wire [31 : 0]  y2,
                 input wire [31 : 0]  y3,

                 output wire [31 : 0] z0,
                 output wire [31 : 0] z1,
                 output wire [31 : 0] z2,
                 output wire [31 : 0] z3
                );

  reg [31 : 0] tmp_z0;
  reg [31 : 0] tmp_z1;
  reg [31 : 0] tmp_z2;
  reg [31 : 0] tmp_z3;


  assign z0 = tmp_z0;
  assign z1 = tmp_z1;
  assign z2 = tmp_z2;
  assign z3 = tmp_z3;


  always @*
    begin : qr
      reg [31 : 0] z0_0;
      reg [31 : 0] z1_0;
      reg [31 : 0] z2_0;
      reg [31 : 0] z3_0;

      z1_0   = (y0 + y3);
      tmp_z1 = {z1_0[24 : 0], z1_0[31 : 25]} ^ y1;

      z2_0   = (tmp_z1 + y0);
      tmp_z2 = {z2_0[22 : 0], z2_0[31 : 23]} ^ y2;

      z3_0   = (tmp_z2 + tmp_z1);
      tmp_z3 = {z3_0[18 : 0], z3_0[31 : 19]} ^ y3;

      z0_0   = (tmp_z3 + tmp_z2);
      tmp_z0 = {z0_0[13 : 0], z0_0[31 : 14]} ^ y0;
    end endmodule

sva:
module salsa20_qr_sva (
    input logic [31:0] y0,
    input logic [31:0] y1,
    input logic [31:0] y2,
    input logic [31:0] y3,

    input logic [31:0] z0,
    input logic [31:0] z1,
    input logic [31:0] z2,
    input logic [31:0] z3
);

// z1 equals rotl7(y0 + y3) XOR y1.
    check_z1_def: assert property (
        @(posedge y0[0]) z1 == (rotl7(y0 + y3) ^ y1)
    );

// z2 equals rotl9(z1 + y0) XOR y2.
    check_z2_def: assert property (
        @(posedge y0[0]) z2 == (rotl9(z1 + y0) ^ y2)
    );

// z3 equals rotl13(z2 + z1) XOR y3.
    check_z3_def: assert property (
        @(posedge y0[0]) z3 == (rotl13(z2 + z1) ^ y3)
    );

// z0 equals rotl18(z3 + z2) XOR y0.
    check_z0_def: assert property (
        @(posedge y0[0]) z0 == (rotl18(z3 + z2) ^ y0)
    );

// Inverse of z1 relation using right rotate.
    check_z1_inverse: assert property (
        @(posedge y0[0]) rotr7(z1 ^ y1) == (y0 + y3)
    );

// Inverse of z2 relation using right rotate.
    check_z2_inverse: assert property (
        @(posedge y0[0]) rotr9(z2 ^ y2) == (z1 + y0)
    );

// Inverse of z3 relation using right rotate.
    check_z3_inverse: assert property (
        @(posedge y0[0]) rotr13(z3 ^ y3) == (z2 + z1)
    );

// Inverse of z0 relation using right rotate.
    check_z0_inverse: assert property (
        @(posedge y0[0]) rotr18(z0 ^ y0) == (z3 + z2)
    );

endmodule

module comparator_2bit_sva (
    input logic clk,
    input logic [1:0] A,
    input logic [1:0] B,
    input logic [1:0] C
);

///// C[1] behavior /////
    // C[1] equals (A[1] & ~B[1]) per (A[1] > B[1]).
    check_c1_definition: assert property (
        @(posedge clk) C[1] == (A[1] & ~B[1])
    );

// When MSBs are equal, C[1] must be 0.
    check_c1_zero_when_msbs_equal: assert property (
        @(posedge clk) (A[1] == B[1]) |-> (C[1] == 1'b0)
    );

// When MSBs differ, C[1] equals A[1].
    check_c1_matches_a1_on_mismatch: assert property (
        @(posedge clk) (A[1] != B[1]) |-> (C[1] == A[1])
    );

///// C[0] behavior /////
    // When MSBs are equal, C[0] equals (A[0] >= B[0]).
    check_c0_when_msbs_equal: assert property (
        @(posedge clk) (A[1] == B[1]) |-> (C[0] == (A[0] >= B[0]))
    );

// When MSBs differ, C[0] equals ~C[1].
    check_c0_complement_when_msbs_differ: assert property (
        @(posedge clk) (A[1] != B[1]) |-> (C[0] == ~C[1])
    );

///// Output coding /////
    // Output is never 2'b11.
    check_c_never_11: assert property (
        @(posedge clk) (C != 2'b11)
    );

// If A[1]=1 and B[1]=0, output must be 2'b10.
    check_case_msbs_10: assert property (
        @(posedge clk) (A[1] && !B[1]) |-> (C == 2'b10)
    );

// If A[1]=0 and B[1]=1, output must be 2'b01.
    check_case_msbs_01: assert property (
        @(posedge clk) (!A[1] && B[1]) |-> (C == 2'b01)
    );

// If A[1]=0 and B[1]=0, C = {1'b0, (A[0] >= B[0])}.
    check_case_msbs_00: assert property (
        @(posedge clk) (!A[1] && !B[1]) |-> (C == {1'b0, (A[0] >= B[0])})
    );

// If A[1]=1 and B[1]=1, C = {1'b0, (A[0] >= B[0])}.
    check_case_msbs_11: assert property (
        @(posedge clk) (A[1] && B[1]) |-> (C == {1'b0, (A[0] >= B[0])})
    );

///// Temporal sanity /////
    // Any rise of C[1] implies A[1]=1 and B[1]=0 at that time.
    check_c1_rise_condition: assert property (
        @(posedge clk) $rose(C[1]) |-> (A[1] && !B[1])
    );

endmodule

