rtl:
module sky130_fd_sc_hdll__nand3 (
    Y,
    A,
    B,
    C
);

    output Y;
    input  A;
    input  B;
    input  C;

    wire nand0_out_Y;

    nand nand0 (nand0_out_Y, B, A, C        );
    buf  buf0  (Y          , nand0_out_Y    );

endmodule

sva:
module sky130_fd_sc_hdll__nand3_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C
);

// Y equals the 3-input NAND of A, B, C (including X/Z semantics).
    check_nand3_function: assert property (
        @(posedge clk) (Y === ~(A & B & C))
    );

// Y is LOW only when all inputs are HIGH.
    check_y0_only_when_all_high: assert property (
        @(posedge clk) (Y === 1'b0) |-> (A === 1'b1 && B === 1'b1 && C === 1'b1)
    );

// Y HIGH implies at least one input is LOW.
    check_y1_implies_any_zero: assert property (
        @(posedge clk) (Y === 1'b1) |-> (A === 1'b0 || B === 1'b0 || C === 1'b0)
    );

// A LOW forces Y HIGH regardless of other inputs.
    check_a_zero_forces_y_one: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b1)
    );

// B LOW forces Y HIGH regardless of other inputs.
    check_b_zero_forces_y_one: assert property (
        @(posedge clk) (B === 1'b0) |-> (Y === 1'b1)
    );

// C LOW forces Y HIGH regardless of other inputs.
    check_c_zero_forces_y_one: assert property (
        @(posedge clk) (C === 1'b0) |-> (Y === 1'b1)
    );

// With all inputs known (0/1), Y must be known (not X/Z).
    check_known_inputs_imply_known_y: assert property (
        @(posedge clk) (! $isunknown({A,B,C})) |-> (! $isunknown(Y))
    );

// Y is never high-impedance (buf is not tri-statable).
    check_y_never_z: assert property (
        @(posedge clk) (Y !== 1'bz)
    );

endmodule

rtl:
module my_module(
  input A1,
  input A2,
  input B,
  output O
);

  wire w0;

  or(w0, A1, A2);

  nand(O, w0, B);

endmodule

sva:
module my_module_sva (
    input logic A1,
    input logic A2,
    input logic B,
    input logic O
);

// No clock/reset in RTL; pure combinational: w0 = A1|A2; O = ~((A1|A2) & B).

    // O equals ~((A1|A2) & B) on A1 rising edge.
    check_func_eq_on_A1_rise: assert property (
        @(posedge A1) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on A1 falling edge.
    check_func_eq_on_A1_fall: assert property (
        @(negedge A1) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on A2 rising edge.
    check_func_eq_on_A2_rise: assert property (
        @(posedge A2) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on A2 falling edge.
    check_func_eq_on_A2_fall: assert property (
        @(negedge A2) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on B rising edge.
    check_func_eq_on_B_rise: assert property (
        @(posedge B) O == ~((A1 | A2) & B)
    );

// O equals ~((A1|A2) & B) on B falling edge.
    check_func_eq_on_B_fall: assert property (
        @(negedge B) O == ~((A1 | A2) & B)
    );

// If B is LOW, O must be HIGH (checked on A1 rising edge).
    check_B0_forces_O1_on_A1_rise: assert property (
        @(posedge A1) (B == 1'b0) |-> (O == 1'b1)
    );

// If B is LOW, O must be HIGH (checked on A2 rising edge).
    check_B0_forces_O1_on_A2_rise: assert property (
        @(posedge A2) (B == 1'b0) |-> (O == 1'b1)
    );

// If O is LOW when B is HIGH, at least one of A1/A2 must be HIGH (checked on B rising edge).
    check_O_low_requires_A1_or_A2_when_B_high: assert property (
        @(posedge B) (O == 1'b0) |-> ((A1 == 1'b1) || (A2 == 1'b1))
    );

endmodule

