module adder_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] Sum,
    input logic       Cout
);

// Bit 2 sum must use the ripple carry generated through bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        Sum[2] == (
            A[2] ^ B[2] ^
            (
                (A[1] & B[1]) |
                (
                    (A[1] ^ B[1]) &
                    (
                        (A[0] & B[0]) |
                        ((A[0] ^ B[0]) & Cin)
                    )
                )
            )
        )
    );

// Bit 3 sum must use the ripple carry generated through bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        Sum[3] == (
            A[3] ^ B[3] ^
            (
                (A[2] & B[2]) |
                (
                    (A[2] ^ B[2]) &
                    (
                        (A[1] & B[1]) |
                        (
                            (A[1] ^ B[1]) &
                            (
                                (A[0] & B[0]) |
                                ((A[0] ^ B[0]) & Cin)
                            )
                        )
                    )
                )
            )
        )
    );

endmodule

