sva:
module my_module_assertions (
    input logic Q,
    input logic CLK,
    input logic D,
    input logic DE,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

// When enabled, the next sampled Q equals the captured D.
    check_capture_when_enabled: assert property (
        @(posedge CLK) DE |=> (Q == $past(D))
    );

// When disabled, Q holds its previous sampled value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) !DE |=> (Q == $past(Q))
    );

// Any observed Q change requires DE high on the prior clock.
    check_change_requires_enable: assert property (
        @(posedge CLK) 1'b1 |=> ((Q != $past(Q)) |-> $past(DE))
    );

// Any observed Q change matches the prior sampled D.
    check_change_matches_captured_d: assert property (
        @(posedge CLK) 1'b1 |=> ((Q != $past(Q)) |-> (Q == $past(D)))
    );

// If enabled data already matches Q, Q stays unchanged.
    check_same_data_keeps_q: assert property (
        @(posedge CLK) DE && (D == Q) |=> (Q == $past(Q))
    );

// If enabled data differs from Q, Q updates to that data.
    check_new_data_updates_q: assert property (
        @(posedge CLK) DE && (D != Q) |=> ((Q == $past(D)) && (Q != $past(Q)))
    );

endmodule

module up_down_counter_sva (
    input logic clk,
    input logic up_down,
    input logic reset,
    input logic [2:0] count
);

// Active-high reset must drive count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |-> (count == 3'b000)
    );

// When up_down is high, count increments on the next clock.
    check_increment_when_up_down_high: assert property (
        @(posedge clk) disable iff (reset)
        up_down |=> (count == ($past(count) + 3'b001))
    );

// When up_down is low, count decrements on the next clock.
    check_decrement_when_up_down_low: assert property (
        @(posedge clk) disable iff (reset)
        !up_down |=> (count == ($past(count) - 3'b001))
    );

// Incrementing from the maximum value wraps back to zero.
    check_wrap_increment_from_max: assert property (
        @(posedge clk) disable iff (reset)
        (up_down && (count == 3'b111)) |=> (count == 3'b000)
    );

// Decrementing from zero wraps back to the maximum value.
    check_wrap_decrement_from_zero: assert property (
        @(posedge clk) disable iff (reset)
        (!up_down && (count == 3'b000)) |=> (count == 3'b111)
    );

endmodule

