module f3m_mux6_8bit_sva (
    input logic        clk,
    input logic [7:0]  v0,
    input logic [7:0]  v1,
    input logic [7:0]  v2,
    input logic [7:0]  v3,
    input logic [7:0]  v4,
    input logic [7:0]  v5,
    input logic        l0,
    input logic        l1,
    input logic        l2,
    input logic        l3,
    input logic        l4,
    input logic        l5,
    input logic        l6,
    input logic [7:0]  out
