// Y must implement the full 4:1 mux function.
    check_mux_function: assert property (
        @(posedge clk)
        Y == (((S1 == 1'b0) && (S0 == 1'b0)) ? A :
              ((S1 == 1'b0) && (S0 == 1'b1)) ? B :
              ((S1 == 1'b1) && (S0 == 1'b0)) ? C :
