    input logic D,
    input logic S,
    input logic R,
    input logic Q,
    input logic QN
);

// Clock: CK. No reset is present in the RTL.
    // Q is sequential; QN is combinationally driven as ~Q.

    // QN must always be the complement of Q.
    check_qn_complement: assert property (
        @(posedge CK) QN === ~Q
    );

// S asserted at a clock edge forces Q high on that update.
    check_sync_set: assert property (
        @(posedge CK) S |=> (Q === 1'b1)
    );

// When both S and R are asserted, set has priority.
    check_set_priority_over_reset: assert property (
        @(posedge CK) (S && R) |=> (Q === 1'b1)
    );

// R asserted without S forces Q low on that update.
    check_sync_reset: assert property (
        @(posedge CK) (!S && R) |=> (Q === 1'b0)
    );

// With S and R deasserted, D=1 is captured into Q.
    check_data_capture_one: assert property (
        @(posedge CK) (!S && !R && D) |=> (Q === 1'b1)
    );

// With S and R deasserted, D=0 is captured into Q.
    check_data_capture_zero: assert property (
        @(posedge CK) (!S && !R && !D) |=> (Q === 1'b0)
    );

endmodule

rtl:
module k580ww55(
    input clk, reset, we_n,
    input [1:0] addr,
    input [7:0] idata,
    output reg [7:0] odata,
    output reg [7:0] opa,
    output reg [7:0] opb,
    output reg [7:0] opc
);

always @(posedge clk or posedge reset) begin
    if (reset) begin
        odata <= 8'h00;
        opa <= 8'hFF;
        opb <= 8'hFF;
        opc <= 8'hFF;
    end else begin
        case (addr)
            2'b00: odata <= opa;
            2'b01: odata <= opb;
            2'b10: odata <= opc;
            2'b11: odata <= 8'h00;
        endcase

        if (~we_n) begin
            case (addr)
                2'b00: opa <= idata;
                2'b01: opb <= idata;
                2'b10: opc <= idata;
                2'b11: begin
                    opc[idata[3:1]] <= idata[0];
                end
            endcase
        end
    end
end

endmodule

sva:
module k580ww55_sva (
    input logic clk,
    input logic reset,
    input logic we_n,
    input logic [1:0] addr,
    input logic [7:0] idata,
    input logic [7:0] odata,
    input logic [7:0] opa,
    input logic [7:0] opb,
    input logic [7:0] opc
);

// Reset drives all outputs to their defined reset values.
    check_reset_values: assert property (
        @(posedge clk) reset |-> (odata == 8'h00 && opa == 8'hFF && opb == 8'hFF && opc == 8'hFF)
    );

// Address 00 makes odata reflect the previous opa value.
    check_odata_reads_opa: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b00) |=> (odata == $past(opa))
    );

// Address 01 makes odata reflect the previous opb value.
    check_odata_reads_opb: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b01) |=> (odata == $past(opb))
    );

// Address 10 makes odata reflect the previous opc value.
    check_odata_reads_opc: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b10) |=> (odata == $past(opc))
    );

// Address 11 makes odata return zero.
    check_odata_zero_on_ctrl_addr: assert property (
        @(posedge clk) disable iff (reset) (addr == 2'b11) |=> (odata == 8'h00)
    );

// A write to address 00 updates opa and leaves opb/opc unchanged.
    check_write_opa: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b00)) |=> (opa == $past(idata) && opb == $past(opb) && opc == $past(opc))
    );

// A write to address 01 updates opb and leaves opa/opc unchanged.
    check_write_opb: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b01)) |=> (opa == $past(opa) && opb == $past(idata) && opc == $past(opc))
    );

// A write to address 10 updates opc and leaves opa/opb unchanged.
    check_write_opc: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b10)) |=> (opa == $past(opa) && opb == $past(opb) && opc == $past(idata))
    );

// A write to address 11 updates only the selected opc bit.
    check_write_opc_bit: assert property (
        @(posedge clk) disable iff (reset)
        (!we_n && (addr == 2'b11)) |=> (
            opa == $past(opa) &&
            opb == $past(opb) &&
            opc == (($past(opc) & ~(8'h01 << $past(idata[3:1]))) |
                    ({8{$past(idata[0])}} &  (8'h01 << $past(idata[3:1]))))
        )
    );

// With write disabled, the output ports hold their previous values.
    check_no_write_holds_ports: assert property (
        @(posedge clk) disable iff (reset)
        we_n |=> (opa == $past(opa) && opb == $past(opb) && opc == $past(opc))
    );

endmodule

rtl:
module ripple_carry_adder_4bit (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire [4:0] c;

    assign c[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin
            full_adder_1bit fa (
                .a(a[i]),
                .b(b[i]),
                .cin(c[i]),
                .sum(sum[i]),
                .cout(c[i+1])
            );
        end
    endgenerate

    assign cout = c[4];

endmodule

module full_adder_1bit (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva:
module ripple_carry_adder_4bit_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

// Full 5-bit result must equal a + b + cin.
    check_full_result_matches_addition: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + cin)
    );

// Bit 0 sum must match the 1-bit full-adder XOR equation.
    check_lsb_sum_matches_full_adder: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum must use the carry generated from bit 0.
    check_bit1_sum_uses_bit0_carry: assert property (
        @(posedge clk) sum[1] == (a[1] ^ b[1] ^ ((a[0] & b[0]) | (a[0] & cin) | (b[0] & cin)))
    );

// Carry-out must indicate overflow of the 4-bit addition.
    check_cout_matches_overflow: assert property (
        @(posedge clk) cout == (({1'b0, a} + {1'b0, b} + cin) >= 5'd16)
    );

// Zero inputs must produce a zero result.
    check_zero_inputs_return_zero: assert property (
        @(posedge clk) ((a == 4'b0000) && (b == 4'b0000) && (cin == 1'b0)) |-> ((sum == 4'b0000) && (cout == 1'b0))
    );

// Adding zero with no carry-in must pass a through unchanged.
    check_a_passthrough_when_b_and_cin_are_zero: assert property (
        @(posedge clk) ((b == 4'b0000) && (cin == 1'b0)) |-> ((sum == a) && (cout == 1'b0))
    );

// Adding zero with no carry-in must pass b through unchanged.
    check_b_passthrough_when_a_and_cin_are_zero: assert property (
        @(posedge clk) ((a == 4'b0000) && (cin == 1'b0)) |-> ((sum == b) && (cout == 1'b0))
    );

// Maximum inputs must produce all ones with carry-out asserted.
    check_max_input_case: assert property (
        @(posedge clk) ((a == 4'b1111) && (b == 4'b1111) && (cin == 1'b1)) |-> ((sum == 4'b1111) && (cout == 1'b1))
    );

endmodule

