// 0xFF plus 0x01 must wrap to 0x00 on the 8-bit output.
    check_ff_plus_one_wraps: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'h01)) |-> (sum == 8'h00)
    );

// 0xFF plus 0xFF must produce 0xFE on the 8-bit output.
    check_ff_plus_ff: assert property (
        @(posedge clk) ((A == 8'hFF) && (B == 8'hFF)) |-> (sum == 8'hFE)
    );

endmodule

rtl:
module counter_3bit (
  input clk,
  input reset,
  input load,
  input [2:0] input_value,
  output reg [2:0] count
);

  always @ (posedge clk or negedge reset) begin
    if (!reset) begin
      count <= 3'b0;
    end else if (load) begin
      count <= input_value;
    end else if (count == 3'b111) begin
      count <= 3'b0;
    end else begin
      count <= count + 1;
    end
  end

endmodule

sva:
module counter_3bit_sva (
    input logic clk,
    input logic reset,
    input logic load,
    input logic [2:0] input_value,
    input logic [2:0] count
);

// A sampled low reset drives count to zero by the next clock.
    check_reset_drives_zero: assert property (
        @(posedge clk) !reset |=> (count == 3'b000)
    );

// A high load causes count to take the previous cycle's input value.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (!reset)
        load |=> (count == $past(input_value))
    );

// Load overrides wrap behavior when count is 7.
    check_load_priority_over_wrap: assert property (
        @(posedge clk) disable iff (!reset)
        (load && (count == 3'b111)) |=> (count == $past(input_value))
    );

// Without load, a count of 7 wraps back to 0.
    check_wrap_from_max: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (count == 3'b111)) |=> (count == 3'b000)
    );

// Without load, counts below 7 increment by one.
    check_increment_when_not_loaded: assert property (
        @(posedge clk) disable iff (!reset)
        (!load && (count != 3'b111)) |=> (count == ($past(count) + 3'b001))
    );

endmodule

rtl:
module NIOS_Sys_nios2_qsys_0_nios2_oci_fifocount_inc (
    input empty,
    input free2,
    input free3,
    input [1:0] tm_count,
    output reg [4:0] fifocount_inc
);

always @(*) begin
    if (empty) begin
        fifocount_inc = tm_count;
    end else if (free3 & (tm_count == 2'b11)) begin
        fifocount_inc = 2;
    end else if (free2 & (tm_count >= 2)) begin
        fifocount_inc = 1;
    end else if (tm_count >= 1) begin
        fifocount_inc = 0;
    end else begin
        fifocount_inc = 5'b11111;
    end
end

endmodule

sva:
module NIOS_Sys_nios2_qsys_0_nios2_oci_fifocount_inc_sva (
    input logic clk,
    input logic empty,
    input logic free2,
    input logic free3,
    input logic [1:0] tm_count,
    input logic [4:0] fifocount_inc
);

// Sample clock for this combinational DUT; RTL has no reset.

    // When empty is high, the output mirrors tm_count with zero extension.
    check_empty_passthrough: assert property (
        @(posedge clk)
        empty |-> (fifocount_inc == {3'b000, tm_count})
    );

// When not empty and tm_count is 0, the output is all ones.
    check_nonempty_tm_count_0: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd0)) |-> (fifocount_inc == 5'b11111)
    );

// When not empty and tm_count is 1, the output is zero.
    check_nonempty_tm_count_1: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd1)) |-> (fifocount_inc == 5'd0)
    );

// When not empty and tm_count is 2, free2 selects between 1 and 0.
    check_nonempty_tm_count_2: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd2)) |-> (fifocount_inc == (free2 ? 5'd1 : 5'd0))
    );

// When not empty and tm_count is 3, free3 has priority over free2.
    check_nonempty_tm_count_3: assert property (
        @(posedge clk)
        (!empty && (tm_count == 2'd3)) |-> (fifocount_inc == (free3 ? 5'd2 : (free2 ? 5'd1 : 5'd0)))
    );

endmodule

