module sgpr_simx_rd_port_mux (
  port0_rd_en,
  port0_rd_addr,

  port1_rd_en,
  port1_rd_addr,

  port2_rd_en,
  port2_rd_addr,

  port3_rd_en,
  port3_rd_addr,

  port4_rd_en,
  port4_rd_addr,

  port5_rd_en,
  port5_rd_addr,

  port6_rd_en,
  port6_rd_addr,

  port7_rd_en,
  port7_rd_addr,

  port_rd_data,

  rd_addr,
  rd_en,
  rd_data
);

  input         port0_rd_en;
  input [8:0]   port0_rd_addr;
  input         port1_rd_en;
  input [8:0]   port1_rd_addr;
  input         port2_rd_en;
  input [8:0]   port2_rd_addr;
  input         port3_rd_en;
  input [8:0]   port3_rd_addr;
  input         port4_rd_en;
  input [8:0]   port4_rd_addr;
  input         port5_rd_en;
  input [8:0]   port5_rd_addr;
  input         port6_rd_en;
  input [8:0]   port6_rd_addr;
  input         port7_rd_en;
  input [8:0]   port7_rd_addr;

  input [31:0]  rd_data;

  output [31:0] port_rd_data;
  output [8:0]  rd_addr;
  output rd_en;

  reg [8:0]     rd_addr;
  reg rd_en;

  assign port_rd_data = rd_data;

  always @ (
    port0_rd_en or
    port1_rd_en or
    port2_rd_en or
    port3_rd_en or
    port4_rd_en or
    port5_rd_en or
    port6_rd_en or
    port7_rd_en or
    port0_rd_addr or
    port1_rd_addr or
    port2_rd_addr or
    port3_rd_addr or
    port4_rd_addr or
    port5_rd_addr or
    port6_rd_addr or
    port7_rd_addr
  ) begin
    casex({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en})
      8'b0000_0001:
        begin
          rd_addr <= port0_rd_addr;
          rd_en <= 1'b1;
        end
      8'b0000_0010:
        begin
          rd_addr <= port1_rd_addr;
          rd_en <= 1'b1;
        end
      8'b0000_0100:
        begin
          rd_addr <= port2_rd_addr;
          rd_en <= 1'b1;
        end
      8'b0000_1000:
        begin
          rd_addr <= port3_rd_addr;
          rd_en <= 1'b1;
        end
      8'b0001_0000:
        begin
          rd_addr <= port4_rd_addr;
          rd_en <= 1'b1;
        end
      8'b0010_0000:
        begin
          rd_addr <= port5_rd_addr;
          rd_en <= 1'b1;
        end
      8'b0100_0000:
        begin
          rd_addr <= port6_rd_addr;
          rd_en <= 1'b1;
        end
      8'b1000_0000:
        begin
          rd_addr <= port7_rd_addr;
          rd_en <= 1'b1;
        end
      8'b0000_0000:
        begin
          rd_addr <= {9{1'bx}};
          rd_en <= 1'b0;
        end
      default:
        begin
          rd_addr <= {9{1'bx}};
          rd_en <= 1'bx;
        end
    endcase
  end

endmodule

sva:
module sgpr_simx_rd_port_mux_sva (
    input logic        clk,
    input logic        port0_rd_en,
    input logic [8:0]  port0_rd_addr,
    input logic        port1_rd_en,
    input logic [8:0]  port1_rd_addr,
    input logic        port2_rd_en,
    input logic [8:0]  port2_rd_addr,
    input logic        port3_rd_en,
    input logic [8:0]  port3_rd_addr,
    input logic        port4_rd_en,
    input logic [8:0]  port4_rd_addr,
    input logic        port5_rd_en,
    input logic [8:0]  port5_rd_addr,
    input logic        port6_rd_en,
    input logic [8:0]  port6_rd_addr,
    input logic        port7_rd_en,
    input logic [8:0]  port7_rd_addr,
    input logic [31:0] port_rd_data,
    input logic [8:0]  rd_addr,
    input logic        rd_en,
    input logic [31:0] rd_data
);

// port_rd_data is a direct pass-through of rd_data.
    check_port_rd_data_passthrough: assert property (
        @(posedge clk) port_rd_data === rd_data
    );

// When only port0 is enabled, rd_addr selects port0 and rd_en is asserted.
    check_port0_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0001)
        |-> ((rd_en === 1'b1) && (rd_addr === port0_rd_addr))
    );

// When only port1 is enabled, rd_addr selects port1 and rd_en is asserted.
    check_port1_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0010)
        |-> ((rd_en === 1'b1) && (rd_addr === port1_rd_addr))
    );

// When only port2 is enabled, rd_addr selects port2 and rd_en is asserted.
    check_port2_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0100)
        |-> ((rd_en === 1'b1) && (rd_addr === port2_rd_addr))
    );

// When only port3 is enabled, rd_addr selects port3 and rd_en is asserted.
    check_port3_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_1000)
        |-> ((rd_en === 1'b1) && (rd_addr === port3_rd_addr))
    );

// When only port4 is enabled, rd_addr selects port4 and rd_en is asserted.
    check_port4_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0001_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port4_rd_addr))
    );

// When only port5 is enabled, rd_addr selects port5 and rd_en is asserted.
    check_port5_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0010_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port5_rd_addr))
    );

// When only port6 is enabled, rd_addr selects port6 and rd_en is asserted.
    check_port6_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0100_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port6_rd_addr))
    );

// When only port7 is enabled, rd_addr selects port7 and rd_en is asserted.
    check_port7_select: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b1000_0000)
        |-> ((rd_en === 1'b1) && (rd_addr === port7_rd_addr))
    );

// When no ports are enabled, rd_en is deasserted.
    check_no_port_enabled: assert property (
        @(posedge clk)
        ({port7_rd_en,port6_rd_en,port5_rd_en,port4_rd_en,port3_rd_en,port2_rd_en,port1_rd_en,port0_rd_en} === 8'b0000_0000)
        |-> (rd_en === 1'b0)
    );

endmodule

module flip_flops_sva (
    input logic clk,
    input logic d,
    input logic j,
    input logic k,
    input logic t,
    input logic s,
    input logic r,
    input logic rst,
    input logic q_d,
    input logic q_jk,
    input logic q_t,
    input logic q_sr
);

// A sampled reset cycle clears all flip-flop outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk) rst |=> (q_d == 1'b0) && (q_jk == 1'b0) && (q_t == 1'b0) && (q_sr == 1'b0)
    );

// The D flip-flop captures d on each active clock edge.
    check_dff_captures_d: assert property (
        @(posedge clk) disable iff (rst) 1'b1 |=> (q_d == $past(d))
    );

// The JK flip-flop toggles when both j and k are high.
    check_jkff_toggles_when_jk_high: assert property (
        @(posedge clk) disable iff (rst) (j && k) |=> (q_jk == ~$past(q_jk))
    );

// The JK flip-flop holds its state when j and k are not both high.
    check_jkff_holds_when_not_jk_high: assert property (
        @(posedge clk) disable iff (rst) (!(j && k)) |=> (q_jk == $past(q_jk))
    );

// The T flip-flop toggles when t is high.
    check_tff_toggles_when_t_high: assert property (
        @(posedge clk) disable iff (rst) t |=> (q_t == ~$past(q_t))
    );

// The T flip-flop holds its state when t is low.
    check_tff_holds_when_t_low: assert property (
        @(posedge clk) disable iff (rst) (!t) |=> (q_t == $past(q_t))
    );

// The SR flip-flop sets when s is high and r is low.
    check_srff_sets_when_s_high_r_low: assert property (
        @(posedge clk) disable iff (rst) (s && !r) |=> (q_sr == 1'b1)
    );

// The SR flip-flop clears when s is low and r is high.
    check_srff_clears_when_s_low_r_high: assert property (
        @(posedge clk) disable iff (rst) (!s && r) |=> (q_sr == 1'b0)
    );

// The SR flip-flop holds its state when s and r are equal.
    check_srff_holds_when_s_equals_r: assert property (
        @(posedge clk) disable iff (rst) ((s && r) || (!s && !r)) |=> (q_sr == $past(q_sr))
    );

endmodule

