module adder4bit (A, B, Cin, Sum, Cout);
input [3:0] A, B;
input Cin;
output [3:0] Sum;
output Cout;

wire [3:0] C;

full_adder fa0(A[0], B[0], Cin, Sum[0], C[0]);
full_adder fa1(A[1], B[1], C[0], Sum[1], C[1]);
full_adder fa2(A[2], B[2], C[1], Sum[2], C[2]);
full_adder fa3(A[3], B[3], C[2], Sum[3], Cout);

endmodule
module full_adder (A, B, Cin, Sum, Cout);
input A, B, Cin;
output Sum, Cout;

wire x1, a1, a2;

xor (x1, A, B);
xor (Sum, x1, Cin);
and (a1, x1, Cin);
and (a2, A, B);
or (Cout, a1, a2);

endmodule

sva:
module adder4bit_sva (
    input logic [3:0] A,
    input logic [3:0] B,
    input logic Cin,
    input logic [3:0] Sum,
    input logic Cout,
    input logic clk
);

// The 5-bit output matches A + B + Cin.
    check_total_addition: assert property (
        @(posedge clk) {Cout, Sum} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// The LSB sum bit is the XOR of A[0], B[0], and Cin.
    check_lsb_sum: assert property (
        @(posedge clk) Sum[0] == (A[0] ^ B[0] ^ Cin)
    );

// With B at zero, the result is A plus Cin.
    check_add_zero_b: assert property (
        @(posedge clk) (B == 4'h0) |-> ({Cout, Sum} == ({1'b0, A} + Cin))
    );

// With A at zero, the result is B plus Cin.
    check_add_zero_a: assert property (
        @(posedge clk) (A == 4'h0) |-> ({Cout, Sum} == ({1'b0, B} + Cin))
    );

// If only bit 0 can contribute, bits above bit 1 must stay low.
    check_bit0_only_range: assert property (
        @(posedge clk) (A[3:1] == 3'b000 && B[3:1] == 3'b000) |-> (Sum[3:2] == 2'b00 && Cout == 1'b0)
    );

// Adding 1 to 4'hF must ripple a carry through all four stages.
    check_full_carry_propagation: assert property (
        @(posedge clk) (A == 4'hF && B == 4'h0 && Cin == 1'b1) |-> (Sum == 4'h0 && Cout == 1'b1)
    );

// A plus its bitwise complement with Cin set must produce zero with carry out.
    check_twos_complement_identity: assert property (
        @(posedge clk) (B == ~A && Cin == 1'b1) |-> (Sum == 4'h0 && Cout == 1'b1)
    );

// A plus its bitwise complement with Cin clear must produce 4'hF.
    check_complement_without_carry_in: assert property (
        @(posedge clk) (B == ~A && Cin == 1'b0) |-> (Sum == 4'hF && Cout == 1'b0)
    );

// With no lower-bit carry, the MSB stage behaves as a single full adder.
    check_msb_no_lower_carry: assert property (
        @(posedge clk) (A[2:0] == 3'b000 && B[2:0] == 3'b000 && Cin == 1'b0) |->
            (Sum[2:0] == 3'b000 && Sum[3] == (A[3] ^ B[3]) && Cout == (A[3] & B[3]))
    );

endmodule

rtl:
module mux_4to2 (
    X,
    A0,
    A1,
    A2,
    A3,
    S0,
    S1,
    EN
);

    output X;
    input A0;
    input A1;
    input A2;
    input A3;
    input S0;
    input S1;
    input EN;

    wire X0, X1;

    assign X0 = (S0 & S1) ? A3 : (S0 ? A2 : (S1 ? A1 : A0));
    assign X1 = (EN == 1'b0) ? X0 : 1'b0;
    assign X = X1;

endmodule

sva:
module mux_4to2_sva (
    input logic clk,
    input logic X,
    input logic A0,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic S0,
    input logic S1,
    input logic EN
);

// When disabled, the output must be forced low.
    check_disable_forces_zero: assert property (
        @(posedge clk) (EN == 1'b1) |-> (X == 1'b0)
    );

// When enabled with select 00, X must follow A0.
    check_select_a0_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b0 && S1 == 1'b0) |-> (X == A0)
    );

// When enabled with select 01, X must follow A1.
    check_select_a1_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b0 && S1 == 1'b1) |-> (X == A1)
    );

// When enabled with select 10, X must follow A2.
    check_select_a2_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b1 && S1 == 1'b0) |-> (X == A2)
    );

// When enabled with select 11, X must follow A3.
    check_select_a3_when_enabled: assert property (
        @(posedge clk) (EN == 1'b0 && S0 == 1'b1 && S1 == 1'b1) |-> (X == A3)
    );

// X must always match the implemented mux equation.
    check_output_matches_mux_equation: assert property (
        @(posedge clk)
        X == ((EN == 1'b0) ? ((S0 & S1) ? A3 : (S0 ? A2 : (S1 ? A1 : A0))) : 1'b0)
    );

endmodule

