    check_input_low_selects_out0: assert property (
        @(posedge clk) (in == 1'b0) |-> (out0 && !out1 && !out2 && !out3)
    );

// A high input selects only out3.
    check_input_high_selects_out3: assert property (
        @(posedge clk) (in == 1'b1) |-> (!out0 && !out1 && !out2 && out3)
    );

