module nand3b_inverted (
    Y,
    A,
    B,
    C,
    invert,
    out_inv
);

    output Y;
    input A;
    input B;
    input C;
    input invert;
    output out_inv;

    wire A_inverted;

    assign out_inv = ~A & invert | A & ~invert;
    assign A_inverted = ~A;

    nand (Y, A_inverted, B, C);

endmodule

sva:
module nand3b_inverted_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic invert,
    input logic out_inv
);

// out_inv matches its combinational equation.
    check_out_inv_equation: assert property (
        @(posedge clk) out_inv == ((~A & invert) | (A & ~invert))
    );

// out_inv passes A through when invert is low.
    check_out_inv_passthrough: assert property (
        @(posedge clk) !invert |-> (out_inv == A)
    );

// out_inv inverts A when invert is high.
    check_out_inv_inverted: assert property (
        @(posedge clk) invert |-> (out_inv == ~A)
    );

// Y matches the NAND of ~A, B, and C.
    check_y_equation: assert property (
        @(posedge clk) Y == ~(~A & B & C)
    );

// Y is high whenever A is high.
    check_y_high_when_a_high: assert property (
        @(posedge clk) A |-> Y
    );

// Y is high whenever B is low.
    check_y_high_when_b_low: assert property (
        @(posedge clk) !B |-> Y
    );

// Y is high whenever C is low.
    check_y_high_when_c_low: assert property (
        @(posedge clk) !C |-> Y
    );

// Y goes low when ~A, B, and C are all high.
    check_y_low_when_nand_inputs_high: assert property (
        @(posedge clk) (!A && B && C) |-> !Y
    );

// Y low implies the NAND input term is true.
    check_y_low_only_when_nand_inputs_high: assert property (
        @(posedge clk) !Y |-> (!A && B && C)
    );

endmodule

rtl:
module lfsr(
    input CLK,
    input RST_N,
    input START,
    input STOP,
    output reg [15:0] DATA_OUT
);

reg [15:0] state;

always @(posedge CLK) begin
    if (RST_N == 0) begin
        state <= 16'h0000;
        DATA_OUT <= 16'h0000;
    end else if (START) begin
        state <= 16'h0000;
        DATA_OUT <= state;
    end else if (STOP) begin
        state <= 16'h0000;
        DATA_OUT <= 16'h0000;
    end else begin
        state <= {state[13:0], state[15]^state[13]};
        DATA_OUT <= state;
    end
end

endmodule

sva:
module lfsr_sva(
    input logic        CLK,
    input logic        RST_N,
    input logic        START,
    input logic        STOP,
    input logic [15:0] DATA_OUT,
    input logic [15:0] state
);

// Reset clears state and DATA_OUT on the next clock.
    check_reset_clears_registers: assert property (
        @(posedge CLK) !RST_N |=> (state == 16'h0000) && (DATA_OUT == 16'h0000)
    );

endmodule

module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic       inc,
    input logic       dec,
    input logic [3:0] cnt
);

// Reset drives the counter to zero.
    check_reset_clears_count: assert property (
        @(posedge clk)
        rst |=> (cnt == 4'd0)
    );

// A single increment advances the count by one below 15.
    check_increment_advances_count: assert property (
        @(posedge clk) disable iff (rst)
        (inc && !dec && (cnt != 4'd15)) |=> (cnt == ($past(cnt) + 4'd1))
    );

// Increment wraps from 15 back to 0.
    check_increment_wraps_to_zero: assert property (
        @(posedge clk) disable iff (rst)
        (inc && !dec && (cnt == 4'd15)) |=> (cnt == 4'd0)
    );

// A single decrement reduces the count by one above 0.
    check_decrement_reduces_count: assert property (
        @(posedge clk) disable iff (rst)
        (dec && !inc && (cnt != 4'd0)) |=> (cnt == ($past(cnt) - 4'd1))
    );

// Decrement wraps from 0 back to 15.
    check_decrement_wraps_to_max: assert property (
        @(posedge clk) disable iff (rst)
        (dec && !inc && (cnt == 4'd0)) |=> (cnt == 4'd15)
    );

// With no increment or decrement, the count holds.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (rst)
        (!inc && !dec) |=> (cnt == $past(cnt))
    );

// With increment and decrement both high, the count holds.
    check_hold_when_both_asserted: assert property (
        @(posedge clk) disable iff (rst)
        (inc && dec) |=> (cnt == $past(cnt))
    );

endmodule

rtl:
module shift_and_zero(
    input [3:0] in,
    input rst,
    output reg [3:0] out
);

    always @ (in or rst) begin
        if (rst) begin
            out <= 4'b0;
        end else begin
            out <= {in[3:2], 2'b0};
        end
    end

endmodule

sva:
module shift_and_zero_sva (
    input logic       clk,
    input logic [3:0] in,
    input logic       rst,
    input logic [3:0] out
);

// Reset forces the output to zero.
    check_reset_zero: assert property (
        @(posedge clk) rst |-> (out == 4'b0000)
    );

// Outside reset, output is the upper two input bits followed by zeros.
    check_shift_mapping: assert property (
        @(posedge clk) disable iff (rst)
            (out == {in[3:2], 2'b00})
    );

// The low two output bits are always zero.
    check_low_bits_zero: assert property (
        @(posedge clk) (out[1:0] == 2'b00)
    );

// Outside reset, the high two output bits mirror the high input bits.
    check_upper_bits_match: assert property (
        @(posedge clk) disable iff (rst)
            (out[3:2] == in[3:2])
    );

endmodule

rtl:
module sky130_fd_sc_ls__fahcin (
    COUT,
    SUM ,
    A   ,
    B   ,
    CIN
);

    output COUT;
    output SUM ;
    input  A   ;
    input  B   ;
    input  CIN ;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire ci          ;
    wire xor0_out_SUM;
    wire a_b         ;
    wire a_ci        ;
    wire b_ci        ;
    wire or0_out_COUT;

    not not0 (ci          , CIN            );
    xor xor0 (xor0_out_SUM, A, B, ci       );
    buf buf0 (SUM         , xor0_out_SUM   );
    and and0 (a_b         , A, B           );
    and and1 (a_ci        , A, ci          );
    and and2 (b_ci        , B, ci          );
    or  or0  (or0_out_COUT, a_b, a_ci, b_ci);
    buf buf1 (COUT        , or0_out_COUT   );

endmodule

sva:
module sky130_fd_sc_ls__fahcin_sva (
    input logic clk,
    input logic COUT,
    input logic SUM,
    input logic A,
    input logic B,
    input logic CIN
);

// SUM matches A xor B xor inverted CIN.
    check_sum_function: assert property (
        @(posedge clk) SUM == (A ^ B ^ ~CIN)
    );

// COUT matches the majority of A, B, and inverted CIN.
    check_cout_function: assert property (
        @(posedge clk) COUT == ((A & B) | (A & ~CIN) | (B & ~CIN))
    );

// If both A and B are high, COUT must be high.
    check_cout_when_ab_high: assert property (
        @(posedge clk) (A && B) |-> COUT
    );

// If both A and B are low, COUT must be low.
    check_cout_when_ab_low: assert property (
        @(posedge clk) (!A && !B) |-> !COUT
    );

// With exactly one of A or B high, COUT follows inverted CIN.
    check_cout_single_high_input: assert property (
        @(posedge clk) (A ^ B) |-> (COUT == ~CIN)
    );

// With equal A and B, SUM follows inverted CIN.
    check_sum_equal_inputs: assert property (
        @(posedge clk) !(A ^ B) |-> (SUM == ~CIN)
    );

// With different A and B, SUM follows CIN.
    check_sum_different_inputs: assert property (
        @(posedge clk) (A ^ B) |-> (SUM == CIN)
    );

// When CIN is high, SUM is XOR and COUT is AND of A and B.
    check_cin_high_behavior: assert property (
        @(posedge clk) CIN |-> ((SUM == (A ^ B)) && (COUT == (A & B)))
    );

// When CIN is low, SUM is XNOR and COUT is OR of A and B.
    check_cin_low_behavior: assert property (
        @(posedge clk) !CIN |-> ((SUM == ~(A ^ B)) && (COUT == (A | B)))
    );

endmodule

rtl:
module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module add4 (
    input [3:0] a,
    input [3:0] b,
    input cin,
    output reg [3:0] sum,
    output cout
);

    wire [3:0] s;
    wire c1, c2, c3;

    full_adder fa1 (.a(a[0]), .b(b[0]), .cin(cin), .sum(s[0]), .cout(c1));
    full_adder fa2 (.a(a[1]), .b(b[1]), .cin(c1), .sum(s[1]), .cout(c2));
    full_adder fa3 (.a(a[2]), .b(b[2]), .cin(c2), .sum(s[2]), .cout(c3));
    full_adder fa4 (.a(a[3]), .b(b[3]), .cin(c3), .sum(s[3]), .cout(cout));

    always @(*) begin
        sum = s;
    end

endmodule

sva:
module add4_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

// The least-significant sum bit matches the first full-adder stage.
    check_lsb_sum_equation: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Zero plus zero with no carry-in produces zero and no carry-out.
    check_zero_addition: assert property (
        @(posedge clk)
        (a == 4'b0000 && b == 4'b0000 && cin == 1'b0)
        |-> (sum == 4'b0000 && cout == 1'b0)
    );

// Adding zero with no carry-in passes a through unchanged.
    check_a_passthrough_when_b_zero: assert property (
        @(posedge clk)
        (b == 4'b0000 && cin == 1'b0)
        |-> (sum == a && cout == 1'b0)
    );

// Adding zero with no carry-in passes b through unchanged.
    check_b_passthrough_when_a_zero: assert property (
        @(posedge clk)
        (a == 4'b0000 && cin == 1'b0)
        |-> (sum == b && cout == 1'b0)
    );

// A carry-in propagates through all four bits when a is all ones and b is zero.
    check_full_carry_propagation_from_cin: assert property (
        @(posedge clk)
        (a == 4'b1111 && b == 4'b0000 && cin == 1'b1)
        |-> (sum == 4'b0000 && cout == 1'b1)
    );

// The maximum input case produces all ones with carry-out asserted.
    check_maximum_addition_case: assert property (
        @(posedge clk)
        (a == 4'b1111 && b == 4'b1111 && cin == 1'b1)
        |-> (sum == 4'b1111 && cout == 1'b1)
    );

endmodule

module up_down_counter_assertions (
    input logic       CLK,
    input logic       LOAD,
    input logic       UP,
    input logic       DOWN,
    input logic [3:0] Q
);

// LOAD overrides the case update and clears Q.
    check_load_clears_q: assert property (
        @(posedge CLK) LOAD |=> (Q == 4'b0000)
    );

// With LOAD low and UP/DOWN=00, Q decrements.
    check_decrement_on_00: assert property (
        @(posedge CLK) (!LOAD && !UP && !DOWN) |=> (Q == ($past(Q) - 4'd1))
    );

// With LOAD low and UP/DOWN=01, Q increments.
    check_increment_on_01: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN) |=> (Q == ($past(Q) + 4'd1))
    );

// With LOAD low and UP/DOWN=10, Q holds.
    check_hold_on_10: assert property (
        @(posedge CLK) (!LOAD && UP && !DOWN) |=> (Q == $past(Q))
    );

// With LOAD low and UP/DOWN=11, Q holds.
    check_hold_on_11: assert property (
        @(posedge CLK) (!LOAD && UP && DOWN) |=> (Q == $past(Q))
    );

endmodule

module bitwise_op_sva (
    input logic       clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [2:0] ctrl,
    input logic [7:0] out
);

// Output always matches the selected case expression.
    check_output_function: assert property (
        @(posedge clk)
        out === ((ctrl === 3'b000) ? (A & B) :
                 (ctrl === 3'b001) ? (A | B) :
                 (ctrl === 3'b010) ? (A ^ B) :
                                     8'h00)
    );

// ctrl 000 selects the bitwise AND result.
    check_and_operation: assert property (
        @(posedge clk)
        (ctrl === 3'b000) |-> (out === (A & B))
    );

// ctrl 001 selects the bitwise OR result.
    check_or_operation: assert property (
        @(posedge clk)
        (ctrl === 3'b001) |-> (out === (A | B))
    );

// ctrl 010 selects the bitwise XOR result.
    check_xor_operation: assert property (
        @(posedge clk)
        (ctrl === 3'b010) |-> (out === (A ^ B))
    );

// All other ctrl values drive the default zero output.
    check_default_zero: assert property (
        @(posedge clk)
        (ctrl !== 3'b000 && ctrl !== 3'b001 && ctrl !== 3'b010) |-> (out === 8'h00)
    );

endmodule

