module add_sub_4bit (
    input [3:0] A,
    input [3:0] B,
    input C,
    output reg [3:0] out
);

    always @(*) begin
        if (C) begin
            out <= A + B;
        end else begin
            out <= A - B;
        end
    end

endmodule

