                  (((A[1] & B[1]) |
                    (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                     (A[1] ^ B[1]))) &
                   (A[2] ^ B[2]))))
    );

// Carry-out is the final carry from the ripple-carry chain.
    check_final_carry: assert property (
        @(posedge clk)
        Cout == ((A[3] & B[3]) |
                 (((A[2] & B[2]) |
                   (((A[1] & B[1]) |
                     (((A[0] & B[0]) | (Cin & (A[0] ^ B[0]))) &
                      (A[1] ^ B[1]))) &
