module two_bit_adder(
    input A, 
    input B, 
    input Cin, 
    output S, 
    output Cout
);

    wire w1, w2, w3;

    assign w1 = A ^ B;
    assign S = w1 ^ Cin;
    assign w2 = A & B;
    assign w3 = Cin & w1;
    assign Cout = w2 | w3;

endmodule

sva:
module two_bit_adder_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Cin,
    input logic S,
    input logic Cout
);

// Sum equals the XOR of the three inputs.
    check_sum_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        S == (A ^ B ^ Cin)
    );

// Carry equals the full-adder carry function.
    check_carry_equation: assert property (
        @(posedge clk) disable iff (1'b0)
        Cout == ((A & B) | (Cin & (A ^ B)))
    );

// With Cin low, the adder behaves like a half adder.
    check_cin_low_half_adder: assert property (
        @(posedge clk) disable iff (1'b0)
        (Cin == 1'b0) |-> ((S == (A ^ B)) && (Cout == (A & B)))
    );

// With Cin high, sum is XNOR and carry is OR.
    check_cin_high_behavior: assert property (
        @(posedge clk) disable iff (1'b0)
        (Cin == 1'b1) |-> ((S == ~(A ^ B)) && (Cout == (A | B)))
    );

// All-zero inputs produce zero sum and zero carry.
    check_all_zero_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A && !B && !Cin) |-> (!S && !Cout)
    );

// All-one inputs produce sum one and carry one.
    check_all_one_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        (A && B && Cin) |-> (S && Cout)
    );

// Any one-high input pattern produces sum one and no carry.
    check_single_high_input_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A && !B && !Cin) || (!A && B && !Cin) || (!A && !B && Cin))
        |-> (S && !Cout)
    );

// Any two-high input pattern produces no sum and carry one.
    check_two_high_input_case: assert property (
        @(posedge clk) disable iff (1'b0)
        ((A && B && !Cin) || (A && !B && Cin) || (!A && B && Cin))
        |-> (!S && Cout)
    );

endmodule

module twos_complement_assertions (
    input logic        clk,
    input logic [15:0] in,
    input logic        reset,
    input logic [31:0] out
);

// Reset forces the output to zero.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 32'h00000000)
    );

// Outside reset, the output matches the implemented concatenation.
    check_nonreset_output_encoding: assert property (
        @(posedge clk) disable iff (reset) (out == {in, {16{!in[15]}}})
    );

// Outside reset, the upper 16 bits mirror the input.
    check_nonreset_upper_half_matches_input: assert property (
        @(posedge clk) disable iff (reset) (out[31:16] == in)
    );

// Outside reset, a set input MSB makes the lower 16 bits all zero.
    check_negative_input_low_half_zero: assert property (
        @(posedge clk) disable iff (reset) in[15] |-> (out[15:0] == 16'h0000)
    );

// Outside reset, a clear input MSB makes the lower 16 bits all one.
    check_nonnegative_input_low_half_ones: assert property (
        @(posedge clk) disable iff (reset) !in[15] |-> (out[15:0] == 16'hFFFF)
    );

endmodule

