        1'b1 |=> (
            ({hsync_out, vsync_out, blnk_out, rgb_out} == 27'b0) ||
            ({hsync_out, vsync_out, blnk_out, rgb_out} ==
             $past({hsync_in, vsync_in, blnk_in, rgb_in}))
        )
    );

