    VPWR ,
    VGND
);

    output X   ;
    input  A   ;
    input  B   ;
    input  sel ;
    input  VPWR;
    input  VGND;

    wire sel_inv;
    assign sel_inv = ~sel;

    assign X = (sel & B) | (sel_inv & A);

endmodule

sva:
module mux_2to1_assertions (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic sel,
    input logic VPWR,
    input logic VGND
);

// X must match the implemented bitwise mux equation.
    check_mux_equation: assert property (
        @(posedge clk) X === ((sel & B) | ((~sel) & A))
    );

// With sel low and A known, X follows A.
    check_sel_low_selects_a: assert property (
        @(posedge clk) (sel === 1'b0 && !$isunknown(A)) |-> (X === A)
    );

// With sel high and B known, X follows B.
    check_sel_high_selects_b: assert property (
        @(posedge clk) (sel === 1'b1 && !$isunknown(B)) |-> (X === B)
    );

// With sel low and A unknown, X becomes unknown.
    check_sel_low_unknown_a_propagates: assert property (
        @(posedge clk) (sel === 1'b0 && $isunknown(A)) |-> $isunknown(X)
    );

// With sel high and B unknown, X becomes unknown.
    check_sel_high_unknown_b_propagates: assert property (
        @(posedge clk) (sel === 1'b1 && $isunknown(B)) |-> $isunknown(X)
    );

// If both data inputs are 0, X is forced low.
    check_both_zero_force_zero: assert property (
        @(posedge clk) (A === 1'b0 && B === 1'b0) |-> (X === 1'b0)
    );

endmodule

module shift_register_sva (
    input logic clk,
    input logic load,
    input logic control,
    input logic [7:0] data_in,
    input logic [7:0] data_out
);

// Load copies data_in into the register on the next clock.
    check_load_copies_input: assert property (
        @(posedge clk)
        load |=> (data_out == $past(data_in))
    );

// With load low and control high, the register rotates left by one bit.
    check_shift_left_rotate: assert property (
        @(posedge clk)
        (!load && control) |=> (data_out == {$past(data_out[6:0]), $past(data_out[7])})
    );

// With load low and control low, the register rotates right by one bit.
    check_shift_right_rotate: assert property (
        @(posedge clk)
        (!load && !control) |=> (data_out == {$past(data_out[0]), $past(data_out[7:1])})
    );

// Every clock follows the RTL next-state update function.
    check_next_state_function: assert property (
        @(posedge clk)
        1'b1 |=> (
            data_out == (
                $past(load) ? $past(data_in) :
                ($past(control) ? {$past(data_out[6:0]), $past(data_out[7])}
                                : {$past(data_out[0]), $past(data_out[7:1])})
            )
        )
    );

endmodule

rtl:
module sky130_fd_sc_ls__o21ba (
    X   ,
    A1  ,
    A2  ,
    B1_N,
    VPWR,
    VGND,
    VPB ,
    VNB
);

    output X   ;
    input  A1  ;
    input  A2  ;
    input  B1_N;
    input  VPWR;
    input  VGND;
    input  VPB ;
    input  VNB ;

    wire A;
    wire B;
    wire C;
    wire D;
    wire E;
    wire F;

    assign A = A1 & A2;
    assign B = ~B1_N;
    assign C = ~VPWR;
    assign D = VGND;
    assign E = VPB & ~VNB;
    assign F = ~VPB & VNB;

    assign X = A & B & C & ~D & (E | F);

endmodule

sva:
module sky130_fd_sc_ls__o21ba_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1_N,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

// External sampling clock; DUT is purely combinational and has no reset.

    // X must match the exact RTL combinational equation.
    check_x_matches_equation: assert property (
        @(posedge clk)
        X === (A1 & A2 & ~B1_N & ~VPWR & ~VGND & ((VPB & ~VNB) | (~VPB & VNB)))
    );

// All required true conditions must drive X high.
    check_full_enable_drives_x_high: assert property (
        @(posedge clk)
        (A1 === 1'b1 && A2 === 1'b1 && B1_N === 1'b0 && VPWR === 1'b0 && VGND === 1'b0 &&
         (((VPB === 1'b1) && (VNB === 1'b0)) || ((VPB === 1'b0) && (VNB === 1'b1))))
        |-> (X === 1'b1)
    );

// A1 low forces X low.
    check_a1_low_forces_x_low: assert property (
        @(posedge clk)
        (A1 === 1'b0) |-> (X === 1'b0)
    );

// A2 low forces X low.
    check_a2_low_forces_x_low: assert property (
        @(posedge clk)
        (A2 === 1'b0) |-> (X === 1'b0)
    );

// B1_N high forces X low.
    check_b1n_high_forces_x_low: assert property (
        @(posedge clk)
        (B1_N === 1'b1) |-> (X === 1'b0)
    );

// VPWR high forces X low.
    check_vpwr_high_forces_x_low: assert property (
        @(posedge clk)
        (VPWR === 1'b1) |-> (X === 1'b0)
    );

// VGND high forces X low.
    check_vgnd_high_forces_x_low: assert property (
        @(posedge clk)
        (VGND === 1'b1) |-> (X === 1'b0)
    );

// Equal body-bias pins force X low.
    check_equal_body_pins_force_x_low: assert property (
        @(posedge clk)
        (((VPB === 1'b0) && (VNB === 1'b0)) || ((VPB === 1'b1) && (VNB === 1'b1)))
        |-> (X === 1'b0)
    );

// X high implies every enabling input condition is satisfied.
    check_x_high_implies_required_conditions: assert property (
        @(posedge clk)
        (X === 1'b1)
        |-> (A1 === 1'b1 && A2 === 1'b1 && B1_N === 1'b0 && VPWR === 1'b0 && VGND === 1'b0 &&
             (((VPB === 1'b1) && (VNB === 1'b0)) || ((VPB === 1'b0) && (VNB === 1'b1))))
    );

endmodule

