module and_gate(
    input A,
    input B,
    input C,
    input D,
    output Y,
    input VPWR,
    input VGND
);

    wire temp1, temp2, temp3;
    and and1 (
        temp1,
        A,
        B
    );
    and and2 (
        temp2,
        temp1,
        C
    );
    and and3 (
        temp3,
        temp2,
        D
    );
    assign Y = temp3;

endmodule

sva:
module and_gate_sva (
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic Y,
    input logic VPWR,
    input logic VGND,
    input logic clk
);

// Y must equal the AND of all four data inputs.
    check_output_equation: assert property (
        @(posedge clk) Y == (A & B & C & D)
    );

// All four HIGH inputs must drive Y HIGH.
    check_all_inputs_high_drive_output_high: assert property (
        @(posedge clk) (A & B & C & D) |-> Y
    );

// A HIGH Y requires all four data inputs to be HIGH.
    check_output_high_requires_all_inputs_high: assert property (
        @(posedge clk) Y |-> (A & B & C & D)
    );

// Any LOW data input must force Y LOW.
    check_any_low_input_forces_output_low: assert property (
        @(posedge clk) (!A || !B || !C || !D) |-> !Y
    );

endmodule

rtl:
module delay_gate_4stage (
    input clk,
    input A,
    output X
);

    reg [3:0] delay_reg;
    wire delayed_A;

    assign delayed_A = delay_reg[3];

    always @(posedge clk) begin
        delay_reg <= {delay_reg[2:0], A};
    end

    assign X = delayed_A;

endmodule

sva:
module delay_gate_4stage_sva (
    input logic clk,
    input logic A,
    input logic X
);

// X equals A sampled four clocks earlier.
    check_four_cycle_delay: assert property (
        @(posedge clk) 1'b1 |-> ##4 (X == $past(A, 4))
    );

// A high sample must appear at X four clocks later.
    check_high_propagation: assert property (
        @(posedge clk) A |-> ##4 X
    );

// A low sample must appear at X four clocks later.
    check_low_propagation: assert property (
        @(posedge clk) !A |-> ##4 !X
    );

endmodule

rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input C_in,
    output [3:0] S,
    output C_out
);

    wire [3:0] c1, c2, c3;

    // First column
    assign c1[0] = A[0] & B[0];
    assign S[0] = A[0] ^ B[0] ^ C_in;

    // Second column
    assign c1[1] = A[1] ^ B[1];
    assign c2[1] = c1[0] & c1[1];
    assign S[1] = A[1] ^ B[1] ^ C_in;
    assign C_out = c1[0] & c1[1] | A[1] & B[1];

    // Third column
    assign c1[2] = A[2] ^ B[2];
    assign c2[2] = c1[1] & c1[2];
    assign c3[2] = c2[1] ^ c2[2];
    assign S[2] = A[2] ^ B[2] ^ C_in;

    // Fourth column
    assign c1[3] = A[3] ^ B[3];
    assign c2[3] = c1[2] & c1[3];
    assign c3[3] = c2[2] ^ c2[3];
    assign S[3] = A[3] ^ B[3] ^ C_in;

endmodule

sva:
module four_bit_adder_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        C_in,
    input logic [3:0]  S,
    input logic        C_out
);

// S[0] matches the first sum assignment.
    check_sum_bit0_equation: assert property (
        @(posedge clk) S[0] == (A[0] ^ B[0] ^ C_in)
    );

// S[1] matches the second sum assignment.
    check_sum_bit1_equation: assert property (
        @(posedge clk) S[1] == (A[1] ^ B[1] ^ C_in)
    );

// S[2] matches the third sum assignment.
    check_sum_bit2_equation: assert property (
        @(posedge clk) S[2] == (A[2] ^ B[2] ^ C_in)
    );

// S[3] matches the fourth sum assignment.
    check_sum_bit3_equation: assert property (
        @(posedge clk) S[3] == (A[3] ^ B[3] ^ C_in)
    );

// The full sum bus matches the per-bit XOR structure.
    check_sum_vector_equation: assert property (
        @(posedge clk) S == ((A ^ B) ^ {4{C_in}})
    );

// With C_in low, S reduces to A XOR B.
    check_sum_when_cin_low: assert property (
        @(posedge clk) (C_in == 1'b0) |-> (S == (A ^ B))
    );

// With C_in high, S is the inverse of A XOR B.
    check_sum_when_cin_high: assert property (
        @(posedge clk) (C_in == 1'b1) |-> (S == ~(A ^ B))
    );

// C_out matches the RTL carry expression.
    check_cout_equation: assert property (
        @(posedge clk) C_out == ((((A[0] & B[0]) & (A[1] ^ B[1])) | (A[1] & B[1])))
    );

// A generate on bit 1 forces C_out high.
    check_cout_from_bit1_generate: assert property (
        @(posedge clk) (A[1] & B[1]) |-> (C_out == 1'b1)
    );

// The lower carry-propagate term forces C_out high.
    check_cout_from_low_propagate: assert property (
        @(posedge clk) ((A[0] & B[0]) & (A[1] ^ B[1])) |-> (C_out == 1'b1)
    );

// If neither carry term is present, C_out stays low.
    check_cout_low_when_no_carry_term: assert property (
        @(posedge clk) (!(A[1] & B[1]) && !((A[0] & B[0]) & (A[1] ^ B[1]))) |-> (C_out == 1'b0)
    );

endmodule

rtl:
module BCD_to_Binary (
  input [3:0] bcd,
  output reg [7:0] bin
);

  always @(*) begin
    case(bcd)
      4'b0000: bin = 8'b00000000;
      4'b0001: bin = 8'b00000001;
      4'b0010: bin = 8'b00000010;
      4'b0011: bin = 8'b00000011;
      4'b0100: bin = 8'b00000100;
      4'b0101: bin = 8'b00000101;
      4'b0110: bin = 8'b00000110;
      4'b0111: bin = 8'b00000111;
      4'b1000: bin = 8'b00001000;
      4'b1001: bin = 8'b00001001;
      default: bin = 8'b11111111; // The default case should output all 1s (binary 255) to indicate an error.
    endcase
  end

endmodule

sva:
