module ir_recieve(
clk, rst, sda, recieve_status,recieved_data
);
input clk;
input rst;
input sda;
output recieve_status;
output [10:0] recieved_data;

reg[1:0] sda_reg;
wire falling_edge;
wire rising_edge;
reg[10:0] recieved_data;
reg[7:0] cyc_cnt;
reg[7:0] start_cnt;
reg recieve_status;
reg [31:0] time_cnt;
reg [2:0] start_bits;
reg data_start;

always @(posedge clk or negedge rst)begin
	if(!rst)begin
		start_bits <= 'h0;
		start_cnt <= 'h0;
		end
	else begin
		if(falling_edge && start_cnt < 'd3)begin
			start_bits[start_cnt]<= 1'b1;
			start_cnt <= start_cnt + 1'b1;
		end
		else begin
			start_bits <= start_bits;
			start_cnt <= start_cnt;
		end
	end
end

always @(posedge clk or negedge rst)begin
	if(!rst)begin
		time_cnt <= 'h0;
		cyc_cnt <= 'h0;
		data_start <= 'h0;
	end
	else begin
		if(start_bits == 3'b111 && data_start == 0 && time_cnt < 'd44500)
			time_cnt <= time_cnt + 1'b1;
		else if(start_bits == 3'b111 && data_start == 0 && time_cnt == 'd44500)begin
			time_cnt <= 'h0;
			data_start <= 'h1;
		end
		else begin
		if(start_bits == 3'b111 && time_cnt < 'd89000 && cyc_cnt < 'd11 && data_start == 1)begin
			time_cnt <= time_cnt + 1'b1;
			end
		else if(start_bits == 3'b111 && time_cnt == 'd89000 && cyc_cnt < 'd11 && data_start == 1)begin
			time_cnt <= 'h0;
			cyc_cnt <= cyc_cnt + 1'b1;
			end
		 else begin
			time_cnt <= time_cnt;
			cyc_cnt <= cyc_cnt;
			data_start <= data_start;
		 end
		 end
	end
end

always @(posedge clk or negedge rst)begin
	if(!rst)
		sda_reg <= 2'b11;
	else begin
		sda_reg[0] <= sda;
		sda_reg[1] <= sda_reg[0];
	end
end

assign falling_edge = (sda_reg[1:0] == 2'b10) ? 1'b1 : 1'b0;
assign rising_edge = (sda_reg[1:0] == 2'b01) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst)begin
	if(!rst)begin
		recieved_data <= 'h0;
	end
	else begin
		if(falling_edge && time_cnt > 'd30000 && time_cnt < 'd60000 && cyc_cnt < 'd11)begin
			recieved_data[cyc_cnt] <= 1'b1;
		end
		else if(rising_edge && time_cnt > 'd30000 && time_cnt < 'd60000 && cyc_cnt < 'd11)begin
			recieved_data[cyc_cnt] <= 1'b0;
		end
		else begin
			recieved_data <= recieved_data;
		end
	end
end

always @(posedge clk or negedge rst)begin
	if(!rst)
		recieve_status <= 1'b0;
	else
		recieve_status <= ( recieved_data == 11'b00011110101) ? 1'b1 : 1'b0;
		end 
endmodule

sva:
module ir_recieve_assertions (
    input logic        clk,
    input logic        rst,
    input logic        sda,
    input logic        recieve_status,
    input logic [10:0] recieved_data,
    input logic [1:0]  sda_reg,
    input logic        falling_edge,
    input logic        rising_edge,
    input logic [7:0]  cyc_cnt,
    input logic [7:0]  start_cnt,
    input logic [31:0] time_cnt,
    input logic [2:0]  start_bits,
    input logic        data_start
);

// The SDA synchronizer shifts in the sampled SDA value each clock.
    check_sda_shift_register: assert property (
        @(posedge clk) disable iff (!rst)
        (sda_reg[0] == $past(sda)) &&
        (sda_reg[1] == $past(sda_reg[0]))
    );

// falling_edge is asserted only for the 2'b10 SDA history pattern.
    check_falling_edge_decode: assert property (
        @(posedge clk) disable iff (!rst)
        (falling_edge == (sda_reg == 2'b10))
    );

// rising_edge is asserted only for the 2'b01 SDA history pattern.
    check_rising_edge_decode: assert property (
        @(posedge clk) disable iff (!rst)
        (rising_edge == (sda_reg == 2'b01))
    );

// A qualifying falling edge sets the indexed start bit and increments start_cnt.
    check_start_capture_update: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(falling_edge) && ($past(start_cnt) < 8'd3)) |->
            (start_cnt == ($past(start_cnt) + 8'd1)) &&
            (start_bits == ($past(start_bits) | (3'b001 << $past(start_cnt))))
    );

// Without a qualifying falling edge, start_bits and start_cnt hold their values.
    check_start_capture_hold: assert property (
        @(posedge clk) disable iff (!rst)
        !($past(falling_edge) && ($past(start_cnt) < 8'd3)) |->
            (start_cnt == $past(start_cnt)) &&
            (start_bits == $past(start_bits))
    );

// The timing state stays idle until all three start bits have been seen.
    check_timer_idle_before_start: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) != 3'b111) |->
            (time_cnt == $past(time_cnt)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == $past(data_start))
    );

// Before data_start, time_cnt increments up to 44500.
    check_preamble_timer_increment: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && !$past(data_start) && ($past(time_cnt) < 32'd44500)) |->
            (time_cnt == ($past(time_cnt) + 32'd1)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b0)
    );

// At 44500 counts, the preamble timer resets and data_start asserts.
    check_preamble_done_sets_data_start: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && !$past(data_start) && ($past(time_cnt) == 32'd44500)) |->
            (time_cnt == 32'd0) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b1)
    );

// During data collection, time_cnt increments until the bit period completes.
    check_bit_timer_increment: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && $past(data_start) &&
         ($past(cyc_cnt) < 8'd11) && ($past(time_cnt) < 32'd89000)) |->
            (time_cnt == ($past(time_cnt) + 32'd1)) &&
            (cyc_cnt == $past(cyc_cnt)) &&
            (data_start == 1'b1)
    );

// At 89000 counts, the bit timer resets and cyc_cnt increments.
    check_bit_timer_wrap_advances_cycle: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(start_bits) == 3'b111 && $past(data_start) &&
         ($past(cyc_cnt) < 8'd11) && ($past(time_cnt) == 32'd89000)) |->
            (time_cnt == 32'd0) &&
            (cyc_cnt == ($past(cyc_cnt) + 8'd1)) &&
            (data_start == 1'b1)
    );

// A falling edge in the valid sample window writes a 1 into the current bit.
    check_falling_edge_samples_one: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(falling_edge) &&
         ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
         ($past(cyc_cnt) < 8'd11)) |->
            (recieved_data == ($past(recieved_data) | (11'h001 << $past(cyc_cnt))))
    );

// A rising edge in the valid sample window writes a 0 into the current bit.
    check_rising_edge_samples_zero: assert property (
        @(posedge clk) disable iff (!rst)
        ($past(rising_edge) &&
         ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
         ($past(cyc_cnt) < 8'd11)) |->
            (recieved_data == ($past(recieved_data) & ~(11'h001 << $past(cyc_cnt))))
    );

// Without a valid sample edge, recieved_data holds its value.
    check_data_hold_without_sample_edge: assert property (
        @(posedge clk) disable iff (!rst)
        !(($past(falling_edge) &&
           ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
           ($past(cyc_cnt) < 8'd11)) ||
          ($past(rising_edge) &&
           ($past(time_cnt) > 32'd30000) && ($past(time_cnt) < 32'd60000) &&
           ($past(cyc_cnt) < 8'd11))) |->
            (recieved_data == $past(recieved_data))
    );

// recieve_status reflects whether the previous recieved_data matched the fixed pattern.
    check_status_matches_previous_data: assert property (
        @(posedge clk) disable iff (!rst)
        (recieve_status == ((($past(recieved_data) == 11'b00011110101) ? 1'b1 : 1'b0)))
    );

endmodule

rtl:
module bitwise_logic(
  input in1,
  input in2,
  input in3,
  output out1
);

  wire not_in3;
  wire and_in1_in2;
  wire or_and_not;

  assign not_in3 = ~in3;
  assign and_in1_in2 = in1 & in2;
  assign or_and_not = and_in1_in2 | not_in3;

  assign out1 = or_and_not;

endmodule

sva:
module bitwise_logic_sva (
    input logic clk,
    input logic in1,
    input logic in2,
    input logic in3,
    input logic out1
);

// out1 must implement (in1 & in2) | ~in3.
    check_output_equation: assert property (
        @(posedge clk) out1 == ((in1 & in2) | (~in3))
    );

// A low in3 forces out1 high.
    check_in3_low_forces_out1_high: assert property (
        @(posedge clk) (in3 == 1'b0) |-> (out1 == 1'b1)
    );

// With in3 high, out1 reduces to in1 & in2.
    check_in3_high_reduces_to_and: assert property (
        @(posedge clk) (in3 == 1'b1) |-> (out1 == (in1 & in2))
    );

// Both data inputs high force out1 high.
    check_both_inputs_high_force_out1_high: assert property (
        @(posedge clk) ((in1 == 1'b1) && (in2 == 1'b1)) |-> (out1 == 1'b1)
    );

// With in3 high, a low in1 forces out1 low.
    check_in3_high_and_in1_low_force_out1_low: assert property (
        @(posedge clk) ((in3 == 1'b1) && (in1 == 1'b0)) |-> (out1 == 1'b0)
    );

// With in3 high, a low in2 forces out1 low.
    check_in3_high_and_in2_low_force_out1_low: assert property (
        @(posedge clk) ((in3 == 1'b1) && (in2 == 1'b0)) |-> (out1 == 1'b0)
    );

// A low out1 can occur only when in3 is high and one input is low.
    check_low_output_characterization: assert property (
        @(posedge clk) (out1 == 1'b0) |-> ((in3 == 1'b1) && ((in1 == 1'b0) || (in2 == 1'b0)))
    );

// If out1 is high while in3 is high, both inputs must be high.
    check_high_output_with_in3_high_requires_both_inputs: assert property (
        @(posedge clk) ((out1 == 1'b1) && (in3 == 1'b1)) |-> ((in1 == 1'b1) && (in2 == 1'b1))
    );

endmodule

module binary_counter_sva (
    input logic        clk,
    input logic        reset,
    input logic        count_en,
    input logic [31:0] max_count,
    input logic [31:0] load_val,
    input logic        load,
    input logic        count_dir,
    input logic [31:0] count_out
);

// Load writes load_val into count_out on the next clock, unless async reset clears it.
    check_load_updates_count: assert property (
        @(posedge clk) disable iff (reset)
        load |=> ((count_out == $past(load_val)) || (count_out == 32'd0))
    );

// Load takes priority over counting when both controls are asserted.
    check_load_has_priority_over_count: assert property (
        @(posedge clk) disable iff (reset)
        (load && count_en) |=> ((count_out == $past(load_val)) || (count_out == 32'd0))
    );

// Without load or count enable, count_out holds its value, unless async reset clears it.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!load && !count_en) |=> ((count_out == $past(count_out)) || (count_out == 32'd0))
    );

// When counting up at max_count, the counter wraps to zero.
    check_count_up_wraps_to_zero: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && count_dir && (count_out == max_count)) |=> (count_out == 32'd0)
    );

// When counting up below max_count, the counter increments by one, unless async reset clears it.
    check_count_up_increments: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && count_dir && (count_out != max_count))
        |=> ((count_out == ($past(count_out) + 32'd1)) || (count_out == 32'd0))
    );

// When counting down from zero, the counter wraps to max_count, unless async reset clears it.
    check_count_down_wraps_to_max: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && !count_dir && (count_out == 32'd0))
        |=> ((count_out == $past(max_count)) || (count_out == 32'd0))
    );

// When counting down above zero, the counter decrements by one, unless async reset clears it.
    check_count_down_decrements: assert property (
        @(posedge clk) disable iff (reset)
        (!load && count_en && !count_dir && (count_out != 32'd0))
        |=> ((count_out == ($past(count_out) - 32'd1)) || (count_out == 32'd0))
    );

endmodule

rtl:
module jk_flip_flop (
  input J,
  input K,
  input clk,
  output reg Q
);

  always @(posedge clk) begin
    case ({J,K})
      2'b00: Q <= Q;
      2'b01: Q <= 1'b0;
      2'b10: Q <= 1'b1;
      2'b11: Q <= ~Q;
    endcase
  end

endmodule

sva:
module jk_flip_flop_sva (
    input logic J,
    input logic K,
    input logic clk,
    input logic Q
);

// J=0 and K=0 must hold Q low.
    check_hold_low: assert property (
        @(posedge clk)
        (J === 1'b0 && K === 1'b0 && Q === 1'b0) |=> (Q === 1'b0)
    );

// J=0 and K=0 must hold Q high.
    check_hold_high: assert property (
        @(posedge clk)
        (J === 1'b0 && K === 1'b0 && Q === 1'b1) |=> (Q === 1'b1)
    );

// J=0 and K=1 must drive Q low.
    check_reset_output_low: assert property (
        @(posedge clk)
        (J === 1'b0 && K === 1'b1) |=> (Q === 1'b0)
    );

// J=1 and K=0 must drive Q high.
    check_set_output_high: assert property (
        @(posedge clk)
        (J === 1'b1 && K === 1'b0) |=> (Q === 1'b1)
    );

// J=1 and K=1 must toggle Q from low to high.
    check_toggle_low_to_high: assert property (
        @(posedge clk)
        (J === 1'b1 && K === 1'b1 && Q === 1'b0) |=> (Q === 1'b1)
    );

// J=1 and K=1 must toggle Q from high to low.
    check_toggle_high_to_low: assert property (
        @(posedge clk)
        (J === 1'b1 && K === 1'b1 && Q === 1'b1) |=> (Q === 1'b0)
    );

endmodule

rtl:
module mux4x1(A, B, C, D, S, Y);
  input [7:0] A, B, C, D;
  input [1:0] S;
  output reg [7:0] Y;

  always @ (S or A or B or C or D) begin
    case (S)
      2'b00: Y = A;
      2'b01: Y = B;
      2'b10: Y = C;
      2'b11: Y = D;
    endcase
  end

endmodule

sva:
module mux4x1_sva (
    input logic        clk,
    input logic [7:0]  A,
    input logic [7:0]  B,
    input logic [7:0]  C,
    input logic [7:0]  D,
    input logic [1:0]  S,
    input logic [7:0]  Y
);

// S=00 routes A to Y.
    check_select_a: assert property (
        @(posedge clk) (S === 2'b00) |-> (Y === A)
    );

// S=01 routes B to Y.
    check_select_b: assert property (
        @(posedge clk) (S === 2'b01) |-> (Y === B)
    );

// S=10 routes C to Y.
    check_select_c: assert property (
        @(posedge clk) (S === 2'b10) |-> (Y === C)
    );

// S=11 routes D to Y.
    check_select_d: assert property (
        @(posedge clk) (S === 2'b11) |-> (Y === D)
    );

endmodule

rtl:
module MUX(
    input clk,
	 input [7:0] Estado,
	 input [5:0] Cuenta_Segundos, 
	 input [5:0] Cuenta_Minutos, 
	 input [4:0] Cuenta_Horas, 
	 input [4:0] Cuenta_Year, 
	 input [3:0] Cuenta_Mes, 
	 input [6:0] Cuenta_Dia, 
	 output reg [7:0] Salida_1,
	 output reg [7:0] Salida_2, 
	 output reg [7:0] Salida_3 
    );

	 always @(posedge clk)
       if (Estado == 8'h6C || Estado == 8'h75)
		 begin
          Salida_1 <= Cuenta_Segundos;
			 Salida_2 <= Cuenta_Minutos;
			 Salida_3 <= Cuenta_Horas;
		 end
       else 
		 begin
          Salida_1 <= Cuenta_Year;
			 Salida_2 <= Cuenta_Mes;
			 Salida_3 <= Cuenta_Dia;
		 end 

endmodule

sva:
module MUX_sva (
    input logic        clk,
    input logic [7:0]  Estado,
    input logic [5:0]  Cuenta_Segundos,
    input logic [5:0]  Cuenta_Minutos,
    input logic [4:0]  Cuenta_Horas,
    input logic [4:0]  Cuenta_Year,
    input logic [3:0]  Cuenta_Mes,
    input logic [6:0]  Cuenta_Dia,
    input logic [7:0]  Salida_1,
    input logic [7:0]  Salida_2,
    input logic [7:0]  Salida_3
);

// Estado 6C selects seconds, minutes, and hours on the next cycle.
    check_estado_6c_selects_time: assert property (
        @(posedge clk)
        (Estado == 8'h6C) |=> (
            (Salida_1 == {2'b00, $past(Cuenta_Segundos)}) &&
            (Salida_2 == {2'b00, $past(Cuenta_Minutos)}) &&
            (Salida_3 == {3'b000, $past(Cuenta_Horas)})
        )
    );

// Estado 75 selects seconds, minutes, and hours on the next cycle.
    check_estado_75_selects_time: assert property (
        @(posedge clk)
        (Estado == 8'h75) |=> (
            (Salida_1 == {2'b00, $past(Cuenta_Segundos)}) &&
            (Salida_2 == {2'b00, $past(Cuenta_Minutos)}) &&
            (Salida_3 == {3'b000, $past(Cuenta_Horas)})
        )
    );

// All other Estado values select year, month, and day on the next cycle.
    check_other_estado_selects_date: assert property (
        @(posedge clk)
        (Estado != 8'h6C && Estado != 8'h75) |=> (
            (Salida_1 == {3'b000, $past(Cuenta_Year)}) &&
            (Salida_2 == {4'b0000, $past(Cuenta_Mes)}) &&
            (Salida_3 == {1'b0, $past(Cuenta_Dia)})
        )
    );

endmodule

rtl:
module nand4 (
  Y,
  A,
  B,
  C,
  D
);

  output Y;
  input A;
  input B;
  input C;
  input D;


  assign Y = ~( A & B & C & D);

endmodule

sva:
module nand4_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D
);

// Y must equal the NAND of all four inputs.
    check_nand_function: assert property (
        @(posedge clk) Y == ~(A & B & C & D)
    );

// When all inputs are HIGH, Y must be LOW.
    check_all_inputs_high_drive_y_low: assert property (
        @(posedge clk) (A & B & C & D) |-> !Y
    );

// If the inputs are not all HIGH, Y must be HIGH.
    check_not_all_inputs_high_drive_y_high: assert property (
        @(posedge clk) (~(A & B & C & D)) |-> Y
    );

// Y LOW can only occur when all inputs are HIGH.
    check_y_low_implies_all_inputs_high: assert property (
        @(posedge clk) !Y |-> (A & B & C & D)
    );

// Y HIGH means the inputs are not all HIGH.
    check_y_high_implies_not_all_inputs_high: assert property (
        @(posedge clk) Y |-> ~(A & B & C & D)
    );

endmodule

rtl:
module mux4to1_using_full_adders (
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    output [3:0] out
);

wire [3:0] add1_out, add2_out, add3_out;

// Pipeline stage 1
full_adder fa1(in0[0], in1[0], sel[0], add1_out[0], );
full_adder fa2(in0[1], in1[1], sel[0], add1_out[1], );
full_adder fa3(in0[2], in1[2], sel[0], add1_out[2], );
full_adder fa4(in0[3], in1[3], sel[0], add1_out[3], );

// Pipeline stage 2
full_adder fa5(in2[0], in3[0], sel[0], add2_out[0], );
full_adder fa6(in2[1], in3[1], sel[0], add2_out[1], );
full_adder fa7(in2[2], in3[2], sel[0], add2_out[2], );
full_adder fa8(in2[3], in3[3], sel[0], add2_out[3], );

// Pipeline stage 3
full_adder fa9(add1_out[0], add2_out[0], sel[1], add3_out[0], out[0]);
full_adder fa10(add1_out[1], add2_out[1], sel[1], add3_out[1], out[1]);
full_adder fa11(add1_out[2], add2_out[2], sel[1], add3_out[2], out[2]);
full_adder fa12(add1_out[3], add2_out[3], sel[1], add3_out[3], out[3]);

endmodule
module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

wire cin_temp;
assign cin_temp = a ^ b;
assign sum = cin_temp ^ cin;
assign cout = (a & b) | (cin & cin_temp);

endmodule

sva:
module mux4to1_using_full_adders_assertions (
    input logic       clk,
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic [3:0] out
);

// Out is the carry result of the third full-adder stage.
    check_out_matches_stage3_carry: assert property (
        @(posedge clk)
        out == (
            ((in0 ^ in1 ^ {4{sel[0]}}) & (in2 ^ in3 ^ {4{sel[0]}})) |
            ({4{sel[1]}} & ((in0 ^ in1 ^ {4{sel[0]}}) ^ (in2 ^ in3 ^ {4{sel[0]}})))
        )
    );

// With sel[1] low, out is the AND of the first two stage sums.
    check_sel1_low_uses_and_of_stage_sums: assert property (
        @(posedge clk)
        (sel[1] == 1'b0) |-> (
            out == ((in0 ^ in1 ^ {4{sel[0]}}) & (in2 ^ in3 ^ {4{sel[0]}}))
        )
    );

// With sel[1] high, out is the OR of the first two stage sums.
    check_sel1_high_uses_or_of_stage_sums: assert property (
        @(posedge clk)
        (sel[1] == 1'b1) |-> (
            out == ((in0 ^ in1 ^ {4{sel[0]}}) | (in2 ^ in3 ^ {4{sel[0]}}))
        )
    );

// sel=00 produces the AND of the pairwise XOR terms.
    check_sel00_and_of_xors: assert property (
        @(posedge clk)
        (sel == 2'b00) |-> (out == ((in0 ^ in1) & (in2 ^ in3)))
    );

// sel=01 produces the AND of the pairwise XNOR terms.
    check_sel01_and_of_xnors: assert property (
        @(posedge clk)
        (sel == 2'b01) |-> (out == ((in0 ~^ in1) & (in2 ~^ in3)))
    );

// sel=10 produces the OR of the pairwise XOR terms.
    check_sel10_or_of_xors: assert property (
        @(posedge clk)
        (sel == 2'b10) |-> (out == ((in0 ^ in1) | (in2 ^ in3)))
    );

// sel=11 produces the OR of the pairwise XNOR terms.
    check_sel11_or_of_xnors: assert property (
        @(posedge clk)
        (sel == 2'b11) |-> (out == ((in0 ~^ in1) | (in2 ~^ in3)))
    );

endmodule

rtl:
module sky130_fd_sc_ls__xnor2 (
    Y,
    A,
    B
);

    output Y;
    input  A;
    input  B;

    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire xnor0_out_Y;

    xnor xnor0 (xnor0_out_Y, A, B           );
    buf  buf0  (Y          , xnor0_out_Y    );

endmodule

sva:
module sky130_fd_sc_ls__xnor2_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Y
);

// Y implements the XNOR of A and B.
    check_xnor_equivalence: assert property (
        @(posedge clk) (Y == ~(A ^ B))
    );

// Equal inputs drive Y high.
    check_equal_inputs_drive_high: assert property (
        @(posedge clk) (A == B) |-> (Y == 1'b1)
    );

// Different inputs drive Y low.
    check_unequal_inputs_drive_low: assert property (
        @(posedge clk) (A != B) |-> (Y == 1'b0)
    );

// With B low, Y is the inverse of A.
    check_b_low_inverts_a: assert property (
        @(posedge clk) (B == 1'b0) |-> (Y == ~A)
    );

// With B high, Y matches A.
    check_b_high_matches_a: assert property (
        @(posedge clk) (B == 1'b1) |-> (Y == A)
    );

endmodule

rtl:
module sky130_fd_sc_hd__xor3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire xor0_out_X;

    xor xor0 (xor0_out_X, A, B, C        );
    buf buf0 (X         , xor0_out_X     );

endmodule

sva:
module sky130_fd_sc_hd__xor3_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

// X must equal the three-input XOR of A, B, and C.
    check_x_matches_xor3: assert property (
        @(posedge clk) X == (A ^ B ^ C)
    );

// With C low, X reduces to A XOR B.
    check_c_low_reduces_to_ab_xor: assert property (
        @(posedge clk) !C |-> (X == (A ^ B))
    );

// With C high, X is the inverse of A XOR B.
    check_c_high_inverts_ab_xor: assert property (
        @(posedge clk) C |-> (X == ~(A ^ B))
    );

// When A and B match, X must equal C.
    check_equal_ab_reduces_to_c: assert property (
        @(posedge clk) (A == B) |-> (X == C)
    );

// When A and B differ, X must equal the inverse of C.
    check_unequal_ab_inverts_c: assert property (
        @(posedge clk) (A != B) |-> (X == ~C)
    );

// All-zero inputs must drive X low.
    check_all_zero_drives_zero: assert property (
        @(posedge clk) (!A && !B && !C) |-> !X
    );

// All-one inputs must drive X high.
    check_all_one_drives_one: assert property (
        @(posedge clk) (A && B && C) |-> X
    );

endmodule

rtl:
module ring_counter_shift_register_decoder_mux (
    input clk,
    input d,
    input wire [15:0] in,
    output wire [7:0] out_hi,
    output wire [7:0] out_lo
);

reg [2:0] shift_reg;
wire [1:0] decoder_out;
wire [7:0] mux_out;

// Ring counter shift register
always @(posedge clk) begin
    shift_reg <= {shift_reg[1:0], d};
end

// Decoder
assign decoder_out = shift_reg[2:1];

// Multiplexer
assign mux_out = (decoder_out == 2'b00) ? in[7:0] :
                 (decoder_out == 2'b01) ? in[15:8] :
                 (decoder_out == 2'b10) ? in[7:0] :
                                         in[15:8];

// Output
assign out_hi = (decoder_out == 2'b01) ? mux_out : 8'b0;
assign out_lo = (decoder_out == 2'b10) ? mux_out : 8'b0;

endmodule

sva:
module ring_counter_shift_register_decoder_mux_sva (
    input logic        clk,
    input logic        d,
    input logic [15:0] in,
    input logic [7:0]  out_hi,
    input logic [7:0]  out_lo
);

// out_hi is always either zero or the upper input byte.
    check_out_hi_is_zero_or_upper_byte: assert property (
        @(posedge clk)
        ((out_hi == 8'b0) || (out_hi == in[15:8]))
    );

// out_lo is always either zero or the lower input byte.
    check_out_lo_is_zero_or_lower_byte: assert property (
        @(posedge clk)
        ((out_lo == 8'b0) || (out_lo == in[7:0]))
    );

// A nonzero out_hi requires out_lo to be zero.
    check_nonzero_out_hi_excludes_out_lo: assert property (
        @(posedge clk)
        (out_hi != 8'b0) |-> (out_lo == 8'b0)
    );

// A nonzero out_lo requires out_hi to be zero.
    check_nonzero_out_lo_excludes_out_hi: assert property (
        @(posedge clk)
        (out_lo != 8'b0) |-> (out_hi == 8'b0)
    );

endmodule

module mux_2to1_enable_sva (
    input logic       clk,
    input logic       reset,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic       en,
    input logic [7:0] out
);

// Reset drives the output low.
    check_reset_clears_out: assert property (
        @(posedge clk) !reset |-> (out == 8'b0)
    );

// Enabled logic selects a when a is nonzero.
    check_select_a_when_enabled_and_a_nonzero: assert property (
        @(posedge clk) disable iff (!reset)
        (en && (a != 8'b0)) |=> (out == $past(a))
    );

// Enabled logic selects b when a is zero.
    check_select_b_when_enabled_and_a_zero: assert property (
        @(posedge clk) disable iff (!reset)
        (en && (a == 8'b0)) |=> (out == $past(b))
    );

// Disabled logic clears the output.
    check_zero_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        (!en) |=> (out == 8'b0)
    );

// Output follows the previous cycle's full decision tree.
    check_full_next_state_function: assert property (
        @(posedge clk) disable iff (!reset)
        1'b1 |=> (out == ($past(en) ? (($past(a) != 8'b0) ? $past(a) : $past(b)) : 8'b0))
    );

endmodule

rtl:
module alu (
    input [3:0] data1,
    input [3:0] data2,
    input [1:0] op,
    output reg [3:0] q,
    input clk
);

reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    case(op)
        2'b00: stage1_out = data1 + data2;
        2'b01: stage1_out = data1 - data2;
        2'b10: stage1_out = data1 & data2;
        2'b11: stage1_out = data1 | data2;
    endcase
end

always @(posedge clk) begin
    q <= stage2_out;
    stage2_out <= stage1_out;
end

endmodule

sva:
module alu_sva (
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [1:0] op,
    input logic [3:0] q,
    input logic clk
);

// q reflects the add result from two cycles earlier.
    check_q_add_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ##2 (q == (($past(data1, 2) + $past(data2, 2)) & 4'hF))
    );

// q reflects the subtract result from two cycles earlier.
    check_q_sub_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ##2 (q == (($past(data1, 2) - $past(data2, 2)) & 4'hF))
    );

// q reflects the bitwise AND result from two cycles earlier.
    check_q_and_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b10) |-> ##2 (q == ($past(data1, 2) & $past(data2, 2)))
    );

// q reflects the bitwise OR result from two cycles earlier.
    check_q_or_two_cycle_latency: assert property (
        @(posedge clk)
        (op == 2'b11) |-> ##2 (q == ($past(data1, 2) | $past(data2, 2)))
    );

// q always matches the operation selected two cycles earlier.
    check_q_matches_selected_operation: assert property (
        @(posedge clk)
        1'b1 |-> ##2 (
            q == (
                ($past(op, 2) == 2'b00) ? ((($past(data1, 2) + $past(data2, 2)) & 4'hF)) :
                ($past(op, 2) == 2'b01) ? ((($past(data1, 2) - $past(data2, 2)) & 4'hF)) :
                ($past(op, 2) == 2'b10) ? (($past(data1, 2) & $past(data2, 2))) :
                                          (($past(data1, 2) | $past(data2, 2)))
            )
        )
    );

endmodule

rtl:
module Deco_Round_Mult(
	input wire [1:0] round_mode,
	input wire or_info, input wire xor_info, output reg ctrl );

always @*
  case ({xor_info,or_info,round_mode})
 4'b0101: ctrl <= 1'b0;

	4'b1101: ctrl <= 1'b1;

4'b0110: ctrl <= 1'b1;

	4'b1110: ctrl <= 1'b0;

   default: ctrl <= 1'b0; endcase

endmodule

sva:
module Deco_Round_Mult_sva (
    input logic clk,
    input logic [1:0] round_mode,
    input logic or_info,
    input logic xor_info,
    input logic ctrl
);

// ctrl is high for input encoding 1101.
    check_ctrl_high_on_1101: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} === 4'b1101) |-> (ctrl === 1'b1)
    );

// ctrl is high for input encoding 0110.
    check_ctrl_high_on_0110: assert property (
        @(posedge clk)
        ({xor_info, or_info, round_mode} === 4'b0110) |-> (ctrl === 1'b1)
    );

// ctrl is low for every encoding other than the two one-driving cases.
    check_ctrl_low_on_all_other_encodings: assert property (
        @(posedge clk)
        !(({xor_info, or_info, round_mode} === 4'b1101) ||
          ({xor_info, or_info, round_mode} === 4'b0110)) |-> (ctrl === 1'b0)
    );

// A high ctrl implies one of the two one-driving encodings.
    check_ctrl_high_only_on_defined_cases: assert property (
        @(posedge clk)
        (ctrl === 1'b1) |-> (({xor_info, or_info, round_mode} === 4'b1101) ||
                             ({xor_info, or_info, round_mode} === 4'b0110))
    );

endmodule

rtl:
module shift_left_2 (
    input [3:0] A,
    output [3:0] X
);

    wire [3:0] shifted_left;

    // Shift left by 2 bits using bitwise logic gates
    assign shifted_left[3] = A[1] & A[0];
    assign shifted_left[2] = A[0] & (~A[1]);
    assign shifted_left[1] = (~A[2]) & (~A[1]);
    assign shifted_left[0] = (~A[3]) & (~A[2]);

    // Assign output
    assign X = shifted_left;

endmodule

sva:
module shift_left_2_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] X
);

// X[3] matches the assigned AND of A[1] and A[0].
    check_x3_equation: assert property (
        @(posedge clk) X[3] == (A[1] & A[0])
    );

// X[2] matches the assigned AND of A[0] and the inverse of A[1].
    check_x2_equation: assert property (
        @(posedge clk) X[2] == (A[0] & (~A[1]))
    );

// X[1] matches the assigned AND of the inverses of A[2] and A[1].
    check_x1_equation: assert property (
        @(posedge clk) X[1] == ((~A[2]) & (~A[1]))
    );

// X[0] matches the assigned AND of the inverses of A[3] and A[2].
    check_x0_equation: assert property (
        @(posedge clk) X[0] == ((~A[3]) & (~A[2]))
    );

// X matches the complete combinational assignment from A.
    check_x_vector_equation: assert property (
        @(posedge clk) X == { (A[1] & A[0]), (A[0] & (~A[1])), ((~A[2]) & (~A[1])), ((~A[3]) & (~A[2])) }
    );

// X[3] and X[2] cannot both be high because they require opposite values of A[1].
    check_upper_bits_mutex: assert property (
        @(posedge clk) !(X[3] && X[2])
    );

endmodule

rtl:
module calculator (
   input [3:0] A,
   input [3:0] B,
   input [1:0] op,
   output reg [3:0] sum,
   output reg [3:0] diff,
   output reg [3:0] prod,
   output reg [3:0] quot
);

always @* begin
   case (op)
      2'b00: begin // addition
         sum = A + B;
         diff = 4'b0;
         prod = 4'b0;
         quot = 4'b0;
      end
      2'b01: begin // subtraction
         sum = 4'b0;
         diff = A - B;
         prod = 4'b0;
         quot = 4'b0;
      end
      2'b10: begin // multiplication
         sum = 4'b0;
         diff = 4'b0;
         prod = A * B;
         quot = 4'b0;
      end
      2'b11: begin // division
         sum = 4'b0;
         diff = 4'b0;
         prod = 4'b0;
         if (B == 4'b0) // division by zero
            quot = 4'b0;
         else
            quot = A / B;
      end
      default: begin // invalid op
         sum = 4'b0;
         diff = 4'b0;
         prod = 4'b0;
         quot = 4'b0;
      end
   endcase
end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [1:0] op,
    input logic [3:0] sum,
    input logic [3:0] diff,
    input logic [3:0] prod,
    input logic [3:0] quot
);

// Addition mode updates sum and clears the other outputs.
    check_addition_mode: assert property (
        @(posedge clk)
        (op == 2'b00) |-> ((sum  == ((A + B) & 4'hF)) &&
                           (diff == 4'h0) &&
                           (prod == 4'h0) &&
                           (quot == 4'h0))
    );

// Subtraction mode updates diff and clears the other outputs.
    check_subtraction_mode: assert property (
        @(posedge clk)
        (op == 2'b01) |-> ((sum  == 4'h0) &&
                           (diff == ((A - B) & 4'hF)) &&
                           (prod == 4'h0) &&
                           (quot == 4'h0))
    );

// Division by zero forces quot low and clears the other outputs.
    check_division_by_zero_mode: assert property (
        @(posedge clk)
        ((op == 2'b11) && (B == 4'h0)) |-> ((sum  == 4'h0) &&
                                            (diff == 4'h0) &&
                                            (prod == 4'h0) &&
                                            (quot == 4'h0))
    );

endmodule

rtl:
module calculator (
    input [3:0] reg_a,
    input [3:0] reg_b,
    input [1:0] op,
    input start,
    output reg [3:0] result
);

    always @ (op or start or reg_a or reg_b)
    begin
        case (op)
            2'b00: result = reg_a + reg_b;
            2'b01: result = reg_a - reg_b;
            2'b10: result = reg_a * reg_b;
            2'b11: result = reg_a / reg_b;
        endcase
    end

endmodule

sva:
module calculator_sva (
    input logic clk,
    input logic [3:0] reg_a,
    input logic [3:0] reg_b,
    input logic [1:0] op,
    input logic start,
    input logic [3:0] result
);

// clk is an external sampling clock because the RTL has no native clock or reset.

    // op=00 returns the truncated sum.
    check_add_result: assert property (
        @(posedge clk)
        (op == 2'b00) |-> (result == ((reg_a + reg_b) & 4'hf))
    );

// op=01 returns the truncated difference.
    check_subtract_result: assert property (
        @(posedge clk)
        (op == 2'b01) |-> (result == ((reg_a - reg_b) & 4'hf))
    );

endmodule

module shift_left_register_sva (
    input logic clk,
    input logic reset,
    input logic parallel_load,
    input logic shift,
    input logic [3:0] input_data,
    input logic [3:0] output_data
);

// Reset drives the register output to zero.
    check_reset_clears_output: assert property (
        @(posedge clk) reset |=> (output_data == 4'b0000)
    );

// Parallel load captures input_data on the next clock.
    check_parallel_load: assert property (
        @(posedge clk) disable iff (reset)
        parallel_load |=> (output_data == $past(input_data))
    );

// Shift moves the stored value left and inserts zero in the LSB.
    check_shift_left: assert property (
        @(posedge clk) disable iff (reset)
        (shift && !parallel_load) |=> (output_data == {$past(output_data[2:0]), 1'b0})
    );

// Parallel load has priority over shift when both are asserted.
    check_load_priority: assert property (
        @(posedge clk) disable iff (reset)
        (parallel_load && shift) |=> (output_data == $past(input_data))
    );

// The register holds its value when neither control is asserted.
    check_hold_when_idle: assert property (
        @(posedge clk) disable iff (reset)
        (!parallel_load && !shift) |=> (output_data == $past(output_data))
    );

endmodule

rtl:
module binary_to_gray(
  input [7:0] bin_in,
  output [7:0] gray_out
);

  wire [7:0] bin_to_gray; // Temporary variable to calculate binary code

  // Calculate binary code by xoring gray_out with shifted bin_to_gray
  assign gray_out = bin_in ^ ({bin_in[7], bin_in[7:1]});
  assign bin_to_gray = gray_out ^ ({gray_out[7], gray_out[7:1]});

endmodule

sva:
module binary_to_gray_sva (
    input logic       clk,
    input logic [7:0] bin_in,
    input logic [7:0] gray_out
);

// gray_out must match the implemented XOR/shift equation.
    check_gray_equation: assert property (
        @(posedge clk) gray_out == (bin_in ^ {bin_in[7], bin_in[7:1]})
    );

// The implemented MSB equation forces gray_out[7] low.
    check_gray_msb_zero: assert property (
        @(posedge clk) gray_out[7] == 1'b0
    );

// The lower seven bits must match adjacent-bit XORs from bin_in.
    check_gray_lower_bits_equation: assert property (
        @(posedge clk) gray_out[6:0] == (bin_in[6:0] ^ bin_in[7:1])
    );

// gray_out[6] is bin_in[6] XOR bin_in[7].
    check_gray_bit6_xor: assert property (
        @(posedge clk) gray_out[6] == (bin_in[6] ^ bin_in[7])
    );

// gray_out[5] is bin_in[5] XOR bin_in[6].
    check_gray_bit5_xor: assert property (
        @(posedge clk) gray_out[5] == (bin_in[5] ^ bin_in[6])
    );

// gray_out[4] is bin_in[4] XOR bin_in[5].
    check_gray_bit4_xor: assert property (
        @(posedge clk) gray_out[4] == (bin_in[4] ^ bin_in[5])
    );

// gray_out[3] is bin_in[3] XOR bin_in[4].
    check_gray_bit3_xor: assert property (
        @(posedge clk) gray_out[3] == (bin_in[3] ^ bin_in[4])
    );

// gray_out[2] is bin_in[2] XOR bin_in[3].
    check_gray_bit2_xor: assert property (
        @(posedge clk) gray_out[2] == (bin_in[2] ^ bin_in[3])
    );

// gray_out[1] is bin_in[1] XOR bin_in[2].
    check_gray_bit1_xor: assert property (
        @(posedge clk) gray_out[1] == (bin_in[1] ^ bin_in[2])
    );

// gray_out[0] is bin_in[0] XOR bin_in[1].
    check_gray_bit0_xor: assert property (
        @(posedge clk) gray_out[0] == (bin_in[0] ^ bin_in[1])
    );

endmodule

rtl:
module bitwise_and(
  input [3:0] X,
  input [3:0] Y,
  output reg [3:0] result,
  output reg greater_than_or_equal_to_5
);

  always @* begin
    result = X & Y;

    if (result >= 5) begin
      greater_than_or_equal_to_5 = 1;
    end else begin
      greater_than_or_equal_to_5 = 0;
    end
  end

endmodule

sva:
module bitwise_and_sva (
    input logic clk,
    input logic [3:0] X,
    input logic [3:0] Y,
    input logic [3:0] result,
    input logic greater_than_or_equal_to_5
);

// result must equal the bitwise AND of X and Y.
    check_result_matches_bitwise_and: assert property (
        @(posedge clk) result == (X & Y)
    );

// The flag must reflect whether result is at least 5.
    check_flag_matches_result_threshold: assert property (
        @(posedge clk) greater_than_or_equal_to_5 == (result >= 4'd5)
    );

// A high flag implies the result is 5 or greater.
    check_flag_high_implies_result_ge_5: assert property (
        @(posedge clk) greater_than_or_equal_to_5 |-> (result >= 4'd5)
    );

// A low flag implies the result is less than 5.
    check_flag_low_implies_result_lt_5: assert property (
        @(posedge clk) !greater_than_or_equal_to_5 |-> (result < 4'd5)
    );

// The flag must also match the threshold of the ANDed inputs directly.
    check_flag_matches_and_threshold: assert property (
        @(posedge clk) greater_than_or_equal_to_5 == ((X & Y) >= 4'd5)
    );

endmodule

rtl:
module clock_gate (CLK, EN, TE, ENCLK);
  input CLK, EN, TE;
  output ENCLK;

  reg ENCLK;

  always @ (posedge CLK) begin
    if (EN && TE) begin
      ENCLK <= 1'b1;
    end else begin
      ENCLK <= 1'b0;
    end
  end

endmodule

sva:
module clock_gate_sva (
    input logic CLK,
    input logic EN,
    input logic TE,
    input logic ENCLK
);

// ENCLK is asserted on the next clock when both EN and TE are high.
    check_enclk_asserts_when_en_and_te_high: assert property (
        @(posedge CLK) (EN && TE) |=> (ENCLK == 1'b1)
    );

// ENCLK is deasserted on the next clock when either EN or TE is low.
    check_enclk_deasserts_when_en_or_te_low: assert property (
        @(posedge CLK) (!EN || !TE) |=> (ENCLK == 1'b0)
    );

endmodule

module up_down_counter_sva (
    input logic       CLK,
    input logic       UP,
    input logic       DOWN,
    input logic       LOAD,
    input logic [3:0] in,
    input logic [3:0] OUT
);

// LOAD has highest priority and copies in to OUT.
    check_load_captures_input: assert property (
        @(posedge CLK) LOAD |=> (OUT == $past(in))
    );

// UP increments OUT when LOAD is low and OUT is not at max.
    check_count_up_step: assert property (
        @(posedge CLK) (!LOAD && UP && (OUT != 4'hF)) |=> (OUT == ($past(OUT) + 4'd1))
    );

// UP wraps OUT from 15 to 0 when LOAD is low.
    check_count_up_wrap: assert property (
        @(posedge CLK) (!LOAD && UP && (OUT == 4'hF)) |=> (OUT == 4'h0)
    );

// DOWN decrements OUT when selected and OUT is not zero.
    check_count_down_step: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (OUT != 4'h0)) |=> (OUT == ($past(OUT) - 4'd1))
    );

// DOWN wraps OUT from 0 to 15 when selected.
    check_count_down_wrap: assert property (
        @(posedge CLK) (!LOAD && !UP && DOWN && (OUT == 4'h0)) |=> (OUT == 4'hF)
    );

// OUT holds its value when no control input is asserted.
    check_hold_when_idle: assert property (
        @(posedge CLK) (!LOAD && !UP && !DOWN) |=> (OUT == $past(OUT))
    );

endmodule

module priority_encoder_sva (
    input logic clk,
    input logic [254:0] in,
    input logic [7:0] out
);

// Exact 0xFF low-byte pattern maps to 255.
    check_ff_maps_to_255: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFF)) |-> (out == 8'd255)
    );

// Exact 0xFE low-byte pattern maps to 254.
    check_fe_maps_to_254: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFE)) |-> (out == 8'd254)
    );

// Exact 0xFC low-byte pattern maps to 253.
    check_fc_maps_to_253: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hFC)) |-> (out == 8'd253)
    );

// Exact 0xF8 low-byte pattern maps to 252.
    check_f8_maps_to_252: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hF8)) |-> (out == 8'd252)
    );

// Exact 0xF0 low-byte pattern maps to 251.
    check_f0_maps_to_251: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hF0)) |-> (out == 8'd251)
    );

// Exact 0xE0 low-byte pattern maps to 250.
    check_e0_maps_to_250: assert property (
        @(posedge clk)
        ((in[254:8] == 247'd0) && (in[7:0] == 8'hE0)) |-> (out == 8'd250)
    );

// Any unlisted input pattern maps to 0.
    check_default_maps_to_0: assert property (
        @(posedge clk)
        !((in[254:8] == 247'd0) &&
          ((in[7:0] == 8'hFF) ||
           (in[7:0] == 8'hFE) ||
           (in[7:0] == 8'hFC) ||
           (in[7:0] == 8'hF8) ||
           (in[7:0] == 8'hF0) ||
           (in[7:0] == 8'hE0))) |-> (out == 8'd0)
    );

endmodule

rtl:
module MUX4 (
    A,
    B,
    C,
    D,
    S0,
    S1,
    Y
);
  input A, B, C, D, S0, S1;
  output Y;

  wire MUX0_out, MUX1_out;

  // Instantiating 2-to-1 multiplexers
  MUX2x1 MUX0 (
      .A (A),
      .B (B),
      .S (S0),
      .Q (MUX0_out)
  );

  MUX2x1 MUX1 (
      .A (C),
      .B (D),
      .S (S0),
      .Q (MUX1_out)
  );

  // Final 2-to-1 multiplexer
  MUX2x1 MUX2 (
      .A (MUX0_out),
      .B (MUX1_out),
      .S (S1),
      .Q (Y)
  );

endmodule

// 2-to-1 multiplexer building block
module MUX2x1 (
    A,
    B,
    S,
    Q
);
  input A, B, S;
  output Q;

  assign Q = (S == 1'b0) ? A : B;

endmodule

sva:
module MUX4_assertions (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1,
    input logic Y
);

// Y matches the nested mux equation implemented by the RTL.
    check_full_mux_equation: assert property (
        @(posedge clk)
        Y === ((S1 == 1'b0) ? ((S0 == 1'b0) ? A : B)
                            : ((S0 == 1'b0) ? C : D))
    );

// When S1 is low, Y must come from the A/B mux selected by S0.
    check_lower_pair_when_s1_low: assert property (
        @(posedge clk)
        (S1 === 1'b0) |-> (Y === ((S0 == 1'b0) ? A : B))
    );

// When S1 is high, Y must come from the C/D mux selected by S0.
    check_upper_pair_when_s1_high: assert property (
        @(posedge clk)
        (S1 === 1'b1) |-> (Y === ((S0 == 1'b0) ? C : D))
    );

// Selecting S1=0 and S0=0 routes A to Y.
    check_select_a_path: assert property (
        @(posedge clk)
        ((S1 === 1'b0) && (S0 === 1'b0)) |-> (Y === A)
    );

// Selecting S1=0 and S0=1 routes B to Y.
    check_select_b_path: assert property (
        @(posedge clk)
        ((S1 === 1'b0) && (S0 === 1'b1)) |-> (Y === B)
    );

// Selecting S1=1 and S0=0 routes C to Y.
    check_select_c_path: assert property (
        @(posedge clk)
        ((S1 === 1'b1) && (S0 === 1'b0)) |-> (Y === C)
    );

// Selecting S1=1 and S0=1 routes D to Y.
    check_select_d_path: assert property (
        @(posedge clk)
        ((S1 === 1'b1) && (S0 === 1'b1)) |-> (Y === D)
    );

endmodule

