module my_mux2 (
    X   ,
    A0  ,
    A1  ,
    S   
);

    output X   ;
    input  A0  ;
    input  A1  ;
    input  S   ;

    wire notS;
    wire and1;
    wire and2;

    not #(1) inv1(notS, S);
    and #(1) gate1(and1, A0, notS);
    and #(1) gate2(and2, A1, S);
    or #(1) gate3(X, and1, and2);

endmodule

sva:
module my_mux2_assertions (
    input logic clk,
    input logic X,
    input logic A0,
    input logic A1,
    input logic S
);

// X matches the implemented mux equation.
    check_mux_equation: assert property (
        @(posedge clk) X == ((A0 & ~S) | (A1 & S))
    );

// When S is low, X selects A0.
    check_select_a0_when_s_low: assert property (
        @(posedge clk) (S == 1'b0) |-> (X == A0)
    );

// When S is high, X selects A1.
    check_select_a1_when_s_high: assert property (
        @(posedge clk) (S == 1'b1) |-> (X == A1)
    );

// If both data inputs are low, X is low.
    check_output_low_when_both_inputs_low: assert property (
        @(posedge clk) ((A0 == 1'b0) && (A1 == 1'b0)) |-> (X == 1'b0)
    );

// If both data inputs are high, X is high.
    check_output_high_when_both_inputs_high: assert property (
        @(posedge clk) ((A0 == 1'b1) && (A1 == 1'b1)) |-> (X == 1'b1)
    );

// If both data inputs match, X equals that common value.
    check_output_matches_common_input: assert property (
        @(posedge clk) (A0 == A1) |-> (X == A0)
    );

// With A0 low and A1 high, X follows S.
    check_output_follows_s_for_01_inputs: assert property (
        @(posedge clk) ((A0 == 1'b0) && (A1 == 1'b1)) |-> (X == S)
    );

// With A0 high and A1 low, X follows inverted S.
    check_output_follows_not_s_for_10_inputs: assert property (
        @(posedge clk) ((A0 == 1'b1) && (A1 == 1'b0)) |-> (X == ~S)
    );

endmodule

rtl:
module simple_adder(
  input [7:0] a,
  input [7:0] b,
  input cin,
  output reg [7:0] sum,
  output reg cout
);

  wire [8:0] temp_sum;
  assign temp_sum = {1'b0, a} + {1'b0, b} + cin;

  // Check if overflow occurred
  always @(*) begin
    if (temp_sum[8] == 1) begin
      if (temp_sum[7] == 1) begin
        sum <= 8'b10000000; // -128 in 2's complement
      end else begin
        sum <= 8'b01111111; // 127 in 2's complement
      end
      cout <= 1;
    end else begin
      sum <= temp_sum[7:0];
      cout <= 0;
    end
  end

endmodule

sva:
module simple_adder_sva (
    input logic clk,
    input logic [7:0] a,
    input logic [7:0] b,
    input logic cin,
    input logic [7:0] sum,
    input logic cout
);

// No carry-out passes through the low 8-bit sum.
    check_no_carry_passthrough: assert property (
        @(posedge clk) !temp_sum[8] |-> (sum == temp_sum[7:0] && cout == 1'b0)
    );

// Carry-out with temp_sum[7] low saturates sum to 8'h7F.
    check_carry_msb0_saturates_7f: assert property (
        @(posedge clk) (temp_sum[8] && !temp_sum[7]) |-> (sum == 8'h7F && cout == 1'b1)
    );

// Carry-out with temp_sum[7] high saturates sum to 8'h80.
    check_carry_msb1_saturates_80: assert property (
        @(posedge clk) (temp_sum[8] && temp_sum[7]) |-> (sum == 8'h80 && cout == 1'b1)
    );

// cout matches the carry-out bit of the addition.
    check_cout_matches_carry: assert property (
        @(posedge clk) cout == temp_sum[8]
    );

// sum always matches the RTL's selected output value.
    check_sum_matches_selected_result: assert property (
        @(posedge clk) sum == (temp_sum[8] ? (temp_sum[7] ? 8'h80 : 8'h7F) : temp_sum[7:0])
    );

endmodule

