// LT must reflect unsigned less-than of A under B.
    check_lt_definition: assert property (
        @(posedge clk) LT == (A < B)
    );

// EQ and GT cannot be high together.
    check_eq_excludes_gt: assert property (
        @(posedge clk) !(EQ && GT)
    );

// EQ and LT cannot be high together.
    check_eq_excludes_lt: assert property (
        @(posedge clk) !(EQ && LT)
    );

// GT and LT cannot be high together.
    check_gt_excludes_lt: assert property (
        @(posedge clk) !(GT && LT)
    );

// One comparison result must always be true.
    check_total_order_covered: assert property (
        @(posedge clk) (EQ || GT || LT)
    );

// Equal inputs must drive only EQ high.
    check_equal_case_outputs: assert property (
        @(posedge clk) (A == B) |-> (EQ && !GT && !LT)
    );

// A greater than B must drive only GT high.
    check_greater_case_outputs: assert property (
        @(posedge clk) (A > B) |-> (GT && !EQ && !LT)
    );

// A less than B must drive only LT high.
    check_less_case_outputs: assert property (
        @(posedge clk) (A < B) |-> (LT && !EQ && !GT)
    );

endmodule

rtl:
module counter_mux (
  input clk,
  input reset,
  input enable,
  input control,
  input select,
  input [7:0] data_in,
  output reg [7:0] q
);

  reg [3:0] counter;
  wire [7:0] mux_out;

  // 4-bit counter with asynchronous reset and enable input
  always @(posedge clk or negedge reset) begin
    if (reset == 0) begin
      counter <= 0;
    end else if (enable) begin
      counter <= counter + 1;
    end
  end

  // Multiplexer that selects between the output of the counter and a constant value based on a control input
  assign mux_out = control ? 8'hFF : counter;

  // 2-to-1 multiplexer that selects between the output of the previous multiplexer and an 8-bit input data based on a select input
  always @(*) begin
    if (select) begin
      q <= data_in;
    end else begin
      q <= mux_out;
    end
  end

endmodule

sva:
module counter_mux_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic       control,
    input logic       select,
    input logic [7:0] data_in,
    input logic [7:0] q,
    input logic [3:0] counter
);

// Enabled counter increments by one on the next clock.
    check_counter_increments_on_enable: assert property (
        @(posedge clk) disable iff (!reset)
        enable |=> (counter == ($past(counter) + 4'd1))
    );

// Disabled counter holds its value on the next clock.
    check_counter_holds_when_disabled: assert property (
        @(posedge clk) disable iff (!reset)
        !enable |=> (counter == $past(counter))
    );

// Counter wraps from 4'hF to 4'h0 when enabled.
    check_counter_wraps_after_max: assert property (
        @(posedge clk) disable iff (!reset)
        (enable && (counter == 4'hF)) |=> (counter == 4'h0)
    );

// Select high makes q follow data_in.
    check_q_selects_data_in: assert property (
        @(posedge clk) disable iff (!reset)
        select |-> (q == data_in)
    );

// Select low and control high make q drive 8'hFF.
    check_q_selects_ff_on_control: assert property (
        @(posedge clk) disable iff (!reset)
        (!select && control) |-> (q == 8'hFF)
    );

// Select low and control low make q drive the zero-extended counter.
    check_q_selects_counter_on_control_low: assert property (
        @(posedge clk) disable iff (!reset)
        (!select && !control) |-> (q == {4'h0, counter})
    );

// During reset, the counter path drives zero on q.
    check_q_counter_path_zero_during_reset: assert property (
        @(posedge clk) (!reset && !select && !control) |-> (q == 8'h00)
    );

endmodule

module binary_counter_sva (
    input logic       CLK,
    input logic       RST,
    input logic       EN,
    input logic [3:0] q
);

// Reset drives q to zero by the following clock edge.
    check_reset_clears_q: assert property (
        @(posedge CLK) RST |=> (q == 4'b0000)
    );

// When enabled, q increments by one on the next clock.
    check_increment_when_enabled: assert property (
        @(posedge CLK) disable iff (RST)
        EN |=> (q == ($past(q) + 4'd1))
    );

// When disabled, q holds its value on the next clock.
    check_hold_when_disabled: assert property (
        @(posedge CLK) disable iff (RST)
        !EN |=> (q == $past(q))
    );

// A terminal count increment wraps q from 4'hF to 4'h0.
    check_wrap_from_max_count: assert property (
        @(posedge CLK) disable iff (RST)
        EN && (q == 4'hF) |=> (q == 4'h0)
    );

endmodule

