module decoder_3to8 (
    input [2:0] in,
    output [7:0] out
);

assign out[0] = ~(in[2] | in[1] | in[0]);
assign out[1] = ~(in[2] | in[1] | ~in[0]);
assign out[2] = ~(in[2] | ~in[1] | in[0]);
assign out[3] = ~(in[2] | ~in[1] | ~in[0]);
assign out[4] = ~(~in[2] | in[1] | in[0]);
assign out[5] = ~(~in[2] | in[1] | ~in[0]);
