    input logic in0,
    input logic in1,
    input logic in2,
    input logic [1:0] sel,
    input logic clr,
    input logic set,
    input logic out
);

// out matches the combinational priority mux function.
    check_mux_function: assert property (
        @(posedge clk)
        out == (set ? 1'b1 :
                (clr ? 1'b0 :
                 ((sel == 2'b00) ? in0 :
                  ((sel == 2'b01) ? in1 :
                   ((sel == 2'b10) ? in2 : 1'b0)))))
    );

// set has highest priority and forces out high.
    check_set_priority: assert property (
        @(posedge clk)
        set |-> (out == 1'b1)
    );

// clr forces out low when set is low.
    check_clr_priority: assert property (
        @(posedge clk)
        (!set && clr) |-> (out == 1'b0)
    );

