        (!set && !clr && (sel == 2'b10)) |-> (out == in2)
    );

// sel 11 forces out low when set and clr are low.
    check_sel_11_zero: assert property (
        @(posedge clk)
        (!set && !clr && (sel == 2'b11)) |-> (out == 1'b0)
    );

