module logic_function ( A, B, Ci, S, Co );
  input A, B, Ci;
  output S, Co;
  wire   n1, n2, n3, n4, n5, n6, n7, n8, n9, n10;

  xor ( n1, A, B );
  xor ( S, n1, Ci );
  and ( n2, A, B );
  and ( n3, n2, Ci );
  not ( n4, A );
  not ( n5, B );
  and ( n6, n4, n5 );
  and ( n7, n6, Ci );
  and ( n8, n4, B );
  and ( n9, A, n5 );
  and ( n10, n8, n9 );
  or ( Co, n3, n7, n10 );
endmodule

sva:
module logic_function_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic Ci,
    input logic S,
    input logic Co
);

// Sum output matches the XOR of A, B, and Ci.
    check_sum_function: assert property (
        @(posedge clk) S == (A ^ B ^ Ci)
    );

// Carry output matches Ci gated by A and B being equal.
    check_carry_function: assert property (
        @(posedge clk) Co == (Ci & ~(A ^ B))
    );

// Carry must be LOW whenever carry-in is LOW.
    check_carry_requires_ci: assert property (
        @(posedge clk) !Ci |-> !Co
    );

// Carry must be LOW whenever A and B differ.
    check_carry_low_when_inputs_differ: assert property (
        @(posedge clk) (A ^ B) |-> !Co
    );

// Carry follows Ci whenever A and B are equal.
    check_carry_follows_ci_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (Co == Ci)
    );

// Sum follows Ci whenever A and B are equal.
    check_sum_follows_ci_when_inputs_equal: assert property (
        @(posedge clk) (A == B) |-> (S == Ci)
    );

// Sum is the inverse of Ci whenever A and B differ.
    check_sum_inverts_ci_when_inputs_differ: assert property (
        @(posedge clk) (A != B) |-> (S == ~Ci)
    );

endmodule

module binary_up_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count
);

// Reset clears the counter to zero on the next clock.
    check_reset_clears_count: assert property (
        @(posedge clk) reset |=> (count == 4'h0)
    );

// When disabled without reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        (!enable) |=> (count == $past(count))
    );

// When enabled below max, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count != 4'hF)) |=> (count == ($past(count) + 4'h1))
    );

// When enabled at max, the counter wraps back to zero.
    check_wrap_when_max: assert property (
        @(posedge clk) disable iff (reset)
        (enable && (count == 4'hF)) |=> (count == 4'h0)
    );

endmodule

rtl:
module calculator(
    input  [31:0] a,
    input  [31:0] b,
    input  reset_n,
    output  reg [31:0] add,
    output  reg [31:0] sub,
    output  reg [31:0] mul,
    output  reg [31:0] div
);

    always @(a, b, reset_n) begin
        if(!reset_n) begin
            add <= 0;
            sub <= 0;
            mul <= 0;
            div <= 0;
        end else begin
            add <= a + b;
            sub <= a - b;
            mul <= a * b;
            if(b != 0) begin
                div <= a / b;
            end else begin
                div <= 0;
            end
        end
    end

endmodule

sva:
module calculator_sva (
    input logic        clk,
    input logic [31:0] a,
    input logic [31:0] b,
    input logic        reset_n,
    input logic [31:0] add,
    input logic [31:0] sub,
    input logic [31:0] mul,
    input logic [31:0] div
);

// External sampling clock; DUT logic is combinational with active-low reset_n.

    // Active-low reset forces all outputs to zero.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        (!reset_n) |-> ((add == 32'd0) && (sub == 32'd0) && (mul == 32'd0) && (div == 32'd0))
    );

// add must match the sum of a and b outside reset.
    check_add_matches_sum: assert property (
        @(posedge clk) disable iff (!reset_n)
        (add == (a + b))
    );

// sub must match the difference of a and b outside reset.
    check_sub_matches_difference: assert property (
        @(posedge clk) disable iff (!reset_n)
        (sub == (a - b))
    );

// div must be zero when the divisor is zero.
    check_div_zero_on_zero_divisor: assert property (
        @(posedge clk) disable iff (!reset_n)
        (b == 32'd0) |-> (div == 32'd0)
    );

endmodule

