module fulladder(a, b, cin, sum, cout);
    input a;
    input b;
    input cin;
    output sum;
    output cout;

    assign {cout, sum} = a + b + cin;
endmodule

module multiplier(
    input wire [3:0] in1,
    input wire [3:0] in2,
    output wire [7:0] out
);
    wire [23:0] con;

    fulladder f11(in1[0] & in2[0], 1'b0, 1'b0, out[0], con[0]);
    fulladder f12(in1[0] & in2[1], 1'b0, con[0], con[3], con[1]);
    fulladder f13(in1[0] & in2[2], 1'b0, con[1], con[4], con[2]);
    fulladder f14(in1[0] & in2[3], 1'b0, con[2], con[5], con[6]);
    fulladder f21(in1[1] & in2[0], con[3], 1'b0, out[1], con[7]);
    fulladder f22(in1[1] & in2[1], con[4], con[7], con[10], con[8]);
    fulladder f23(in1[1] & in2[2], con[5], con[8], con[11], con[9]);
    fulladder f24(in1[1] & in2[3], con[6], con[9], con[12], con[13]);
    fulladder f31(in1[2] & in2[0], con[10], 1'b0, out[2], con[14]);
    fulladder f32(in1[2] & in2[1], con[11], con[14], con[17], con[15]);
    fulladder f33(in1[2] & in2[2], con[12], con[15], con[18], con[16]);
    fulladder f34(in1[2] & in2[3], con[13], con[16], con[19], con[20]);
    fulladder f41(in1[3] & in2[0], con[17], 1'b0, out[3], con[21]);
    fulladder f42(in1[3] & in2[1], con[18], con[21], out[4], con[22]);
    fulladder f43(in1[3] & in2[2], con[19], con[22], out[5], con[23]);
    fulladder f44(in1[3] & in2[3], con[20], con[23], out[6], out[7]);
endmodule

sva:
module multiplier_sva (
    input logic       clk,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [7:0] out
);

// Bit 1 is the XOR of the first two cross products.
    check_bit1_partial_sum: assert property (
        @(posedge clk) out[1] == ((in1[1] & in2[0]) ^ (in1[0] & in2[1]))
    );

// Bit 2 includes the carry generated from bit 1 accumulation.
    check_bit2_partial_sum: assert property (
        @(posedge clk)
        out[2] == ((in1[2] & in2[0]) ^
                   (in1[1] & in2[1]) ^
                   (in1[0] & in2[2]) ^
                   ((in1[1] & in2[0]) & (in1[0] & in2[1])))
    );

// Multiplying by 8 shifts the second operand left by three.
    check_shift_by_msb_in1: assert property (
        @(posedge clk) (in1 == 4'h8) |-> (out == ({4'b0000, in2} << 3))
    );

// Multiplying by 8 shifts the first operand left by three.
    check_shift_by_msb_in2: assert property (
        @(posedge clk) (in2 == 4'h8) |-> (out == ({4'b0000, in1} << 3))
    );

endmodule

