rtl:
module execute_forwarding_register(
		input wire iCLOCK,
		input wire inRESET,
		input wire iRESET_SYNC,
		input wire iWB_GR_VALID,
		input wire [31:0] iWB_GR_DATA,
		input wire [4:0] iWB_GR_DEST,
		input wire iWB_GR_DEST_SYSREG,
		input wire iWB_SPR_VALID,
		input wire [31:0] iWB_SPR_DATA,
		input wire iWB_AUTO_SPR_VALID,
		input wire [31:0] iWB_AUTO_SPR_DATA,
		input wire [31:0] iCUUR_SPR_DATA,
		input wire iWB_FRCR_VALID,			
		input wire [63:0] iWB_FRCR_DATA,	
		input wire [63:0] iCUUR_FRCR_DATA,
		output wire oFDR_GR_VALID,
		output wire [31:0] oFDR_GR_DATA,
		output wire [4:0] oFDR_GR_DEST,
		output wire oFDR_GR_DEST_SYSREG,
		output wire oFDR_SPR_VALID,
		output wire [31:0] oFDR_SPR_DATA,
		output wire oFDR_FRCR_VALID,			
		output wire [63:0] oFDR_FRCR_DATA
	);

	reg b_ex_history_valid;
	reg [31:0] b_ex_history_data;
	reg [4:0] b_ex_history_destination;
	reg b_ex_history_destination_sysreg;
	reg b_fwdng_spr_valid;
	reg [31:0] b_fwdng_spr;

	reg b_fwdng_frcr_valid;
	reg [63:0] b_fwdng_frcr;



	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_ex_history_valid <= 1'h0;
			b_ex_history_data <= 32'h0;
			b_ex_history_destination <= 5'h0;
			b_ex_history_destination_sysreg <= 1'h0;
			end
		else if(iRESET_SYNC)begin
			b_ex_history_valid <= 1'h0;
			b_ex_history_data <= 32'h0;
			b_ex_history_destination <= 5'h0;
			b_ex_history_destination_sysreg <= 1'h0;
			end
		else begin
			if(iWB_GR_VALID)begin
				b_ex_history_valid <= iWB_GR_VALID;
				b_ex_history_data <= iWB_GR_DATA;
				b_ex_history_destination <= iWB_GR_DEST;
				b_ex_history_destination_sysreg <= iWB_GR_DEST_SYSREG;
				end
		end
	end

	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_fwdng_spr_valid <= 1'h0;
			b_fwdng_spr <= 32'h0;
		end
		else if(iRESET_SYNC)begin
			b_fwdng_spr_valid <= 1'h0;
			b_fwdng_spr <= 32'h0;
		end
		else begin
			if(iWB_SPR_VALID)begin
				b_fwdng_spr_valid <= iWB_SPR_VALID;
				b_fwdng_spr <= iWB_SPR_DATA;
			end
			else if(iWB_AUTO_SPR_VALID)begin
				b_fwdng_spr_valid <= iWB_SPR_VALID;
				b_fwdng_spr <= iWB_AUTO_SPR_DATA;
			end
			else begin
				b_fwdng_spr_valid <= 1'b1;
				b_fwdng_spr <= iCUUR_SPR_DATA;
			end
		end
	end

	always@(posedge iCLOCK or negedge inRESET)begin
		if(!inRESET)begin
			b_fwdng_frcr_valid <= 1'h0;
			b_fwdng_frcr <= 64'h0;
		end
		else if(iRESET_SYNC)begin
			b_fwdng_frcr_valid <= 1'h0;
			b_fwdng_frcr <= 64'h0;
		end
		else begin
			if(iWB_FRCR_VALID)begin
				b_fwdng_frcr_valid <= iWB_FRCR_VALID;
				b_fwdng_frcr <= iWB_FRCR_DATA;
			end
			else begin
				b_fwdng_frcr_valid <= 1'h1;
				b_fwdng_frcr <= iCUUR_FRCR_DATA;
			end
		end
	end



	assign oFDR_GR_VALID = b_ex_history_valid;
	assign oFDR_GR_DATA = b_ex_history_data;
	assign oFDR_GR_DEST = b_ex_history_destination;
	assign oFDR_GR_DEST_SYSREG = b_ex_history_destination_sysreg;
	assign oFDR_SPR_VALID = b_fwdng_spr_valid;
	assign oFDR_SPR_DATA = b_fwdng_spr;
	assign oFDR_FRCR_VALID = b_fwdng_frcr_valid;
	assign oFDR_FRCR_DATA = b_fwdng_frcr;


endmodule

sva:
module execute_forwarding_register_sva (
    input logic        iCLOCK,
    input logic        inRESET,
    input logic        iRESET_SYNC,
    input logic        iWB_GR_VALID,
    input logic [31:0] iWB_GR_DATA,
    input logic [4:0]  iWB_GR_DEST,
    input logic        iWB_GR_DEST_SYSREG,
    input logic        iWB_SPR_VALID,
    input logic [31:0] iWB_SPR_DATA,
    input logic        iWB_AUTO_SPR_VALID,
    input logic [31:0] iWB_AUTO_SPR_DATA,
    input logic [31:0] iCUUR_SPR_DATA,
    input logic        iWB_FRCR_VALID,
    input logic [63:0] iWB_FRCR_DATA,
    input logic [63:0] iCUUR_FRCR_DATA,
    input logic        oFDR_GR_VALID,
    input logic [31:0] oFDR_GR_DATA,
    input logic [4:0]  oFDR_GR_DEST,
    input logic        oFDR_GR_DEST_SYSREG,
    input logic        oFDR_SPR_VALID,
    input logic [31:0] oFDR_SPR_DATA,
    input logic        oFDR_FRCR_VALID,
    input logic [63:0] oFDR_FRCR_DATA
);

// Low async reset clears all forwarding outputs by the next clock sample.
    check_async_reset_clears_outputs: assert property (
        @(posedge iCLOCK)
        !inRESET |=> (
            (oFDR_GR_VALID == 1'b0) &&
            (oFDR_GR_DATA == 32'h0) &&
            (oFDR_GR_DEST == 5'h0) &&
            (oFDR_GR_DEST_SYSREG == 1'b0) &&
            (oFDR_SPR_VALID == 1'b0) &&
            (oFDR_SPR_DATA == 32'h0) &&
            (oFDR_FRCR_VALID == 1'b0) &&
            (oFDR_FRCR_DATA == 64'h0)
        )
    );

// High sync reset clears all forwarding outputs on the next clock.
    check_sync_reset_clears_outputs: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        iRESET_SYNC |=> (
            (oFDR_GR_VALID == 1'b0) &&
            (oFDR_GR_DATA == 32'h0) &&
            (oFDR_GR_DEST == 5'h0) &&
            (oFDR_GR_DEST_SYSREG == 1'b0) &&
            (oFDR_SPR_VALID == 1'b0) &&
            (oFDR_SPR_DATA == 32'h0) &&
            (oFDR_FRCR_VALID == 1'b0) &&
            (oFDR_FRCR_DATA == 64'h0)
        )
    );

// A valid GR write captures data and destination.
    check_gr_capture_on_valid: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_GR_VALID) |=> (
            (oFDR_GR_VALID == 1'b1) &&
            (oFDR_GR_DATA == $past(iWB_GR_DATA)) &&
            (oFDR_GR_DEST == $past(iWB_GR_DEST)) &&
            (oFDR_GR_DEST_SYSREG == $past(iWB_GR_DEST_SYSREG))
        )
    );

// Without a valid GR write, the GR forwarding state holds.
    check_gr_hold_without_write: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_GR_VALID) |=> (
            $stable(oFDR_GR_VALID) &&
            $stable(oFDR_GR_DATA) &&
            $stable(oFDR_GR_DEST) &&
            $stable(oFDR_GR_DEST_SYSREG)
        )
    );

// WB SPR write has priority and sets SPR valid.
    check_spr_capture_from_wb: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b1) &&
            (oFDR_SPR_DATA == $past(iWB_SPR_DATA))
        )
    );

// Auto SPR write forwards auto data and leaves valid low.
    check_spr_capture_from_auto: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_SPR_VALID && iWB_AUTO_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b0) &&
            (oFDR_SPR_DATA == $past(iWB_AUTO_SPR_DATA))
        )
    );

// Without SPR writes, current SPR data is forwarded with valid high.
    check_spr_forward_current_data: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_SPR_VALID && !iWB_AUTO_SPR_VALID) |=> (
            (oFDR_SPR_VALID == 1'b1) &&
            (oFDR_SPR_DATA == $past(iCUUR_SPR_DATA))
        )
    );

// A valid FRCR write captures FRCR data.
    check_frcr_capture_from_wb: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && iWB_FRCR_VALID) |=> (
            (oFDR_FRCR_VALID == 1'b1) &&
            (oFDR_FRCR_DATA == $past(iWB_FRCR_DATA))
        )
    );

// Without an FRCR write, current FRCR data is forwarded with valid high.
    check_frcr_forward_current_data: assert property (
        @(posedge iCLOCK) disable iff (!inRESET)
        (!iRESET_SYNC && !iWB_FRCR_VALID) |=> (
            (oFDR_FRCR_VALID == 1'b1) &&
            (oFDR_FRCR_DATA == $past(iCUUR_FRCR_DATA))
