module add_sub_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       SUB,
    input logic [3:0] SUM
);

// In add mode, SUM matches A + B.
    check_add_mode_result: assert property (
        @(posedge clk) (SUB == 1'b0) |-> (SUM == (A + B))
    );

// In subtract mode, SUM matches A - B.
    check_sub_mode_result: assert property (
        @(posedge clk) (SUB == 1'b1) |-> (SUM == (A - B))
    );

// With B equal to zero, SUM must equal A in either mode.
    check_zero_b_identity: assert property (
        @(posedge clk) (B == 4'b0000) |-> (SUM == A)
    );

// In subtract mode, equal operands must produce zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (SUB == 1'b1 && A == B) |-> (SUM == 4'b0000)
    );

endmodule

module calculator_assertions (
    input logic clk,
    input logic [7:0] A,
    input logic [7:0] B,
    input logic [1:0] opcode,
    input logic en,
    input logic [7:0] R
);

// No RTL clock/reset; sample this combinational logic on an external clock.

    // When disabled, the result is forced to zero.
    check_disable_forces_zero: assert property (
        @(posedge clk) !en |-> (R == 8'h00)
    );

// Opcode 00 performs 8-bit addition when enabled.
    check_addition_result: assert property (
        @(posedge clk) en && (opcode == 2'b00) |-> (R == ((A + B) & 8'hFF))
    );

// Opcode 01 performs 8-bit subtraction when enabled.
    check_subtraction_result: assert property (
        @(posedge clk) en && (opcode == 2'b01) |-> (R == ((A - B) & 8'hFF))
    );

endmodule

