    check_non_negative_passthrough: assert property (
        @(posedge clk) !in[3] |-> (out == in)
    );

// Inputs with MSB set are converted using two's complement.
    check_negative_twos_complement: assert property (
        @(posedge clk) in[3] |-> (out == ((~in) + 4'd1))
    );

