    check_x_matches_implemented_function: assert property (
        @(posedge clk)
        X == (
            (~A & B & ~C & ~D) |
            (~A & ~B & C & D) |
            (A & D & ~B & ~C) |
            (A & B & C & ~D) |
            (~A & ~B & C & ~D) |
            (D & ~B & C) |
            (~A & B & C & D) |
            (A & ~B & C & ~D) |
            (~A & ~B & C & ~D) |
            (A & B & C & D)
        )
    );

