module NIOS_SYSTEMV3_LCD (
  // inputs:
  address,
  begintransfer,
  clk,
  read,
  reset_n,
  write,
  writedata,

  // outputs:
  LCD_E,
  LCD_RS,
  LCD_RW,
  LCD_data
);

  output LCD_E;
  output LCD_RS;
  output LCD_RW;
  output [7:0] LCD_data;
  input [1:0] address;
  input begintransfer;
  input clk;
  input read;
  input reset_n;
  input write;
  input [7:0] writedata;

  reg [7:0] LCD_data;

  assign LCD_RW = ~address[0];
  assign LCD_RS = address[1];

  reg LCD_E;
  always @(posedge clk or negedge reset_n)
    if (~reset_n)
      LCD_E <= 1'b0;
    else if (read | write)
      LCD_E <= 1'b1;
    else
      LCD_E <= 1'b0;

  always @(posedge clk or negedge reset_n)
  begin
    if (~reset_n)
      LCD_data <= 0;
    else if (write)
      LCD_data <= writedata;
  end

endmodule

sva:
module NIOS_SYSTEMV3_LCD_sva (
    input logic [1:0] address,
    input logic       begintransfer,
    input logic       clk,
    input logic       read,
    input logic       reset_n,
    input logic       write,
    input logic [7:0] writedata,
    input logic       LCD_E,
    input logic       LCD_RS,
    input logic       LCD_RW,
    input logic [7:0] LCD_data
);

// LCD_RW is the inverse of address[0].
    check_lcd_rw_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
        (LCD_RW == ~address[0])
    );

// LCD_RS follows address[1].
    check_lcd_rs_decode: assert property (
        @(posedge clk) disable iff (!reset_n)
        (LCD_RS == address[1])
    );

// LCD_E is low while reset is asserted.
    check_lcd_e_reset_low: assert property (
        @(posedge clk)
        (!reset_n) |-> (LCD_E == 1'b0)
    );

// LCD_data is zero while reset is asserted.
    check_lcd_data_reset_zero: assert property (
        @(posedge clk)
        (!reset_n) |-> (LCD_data == 8'h00)
    );

// Any read or write drives LCD_E high on the next cycle.
    check_lcd_e_set_on_access: assert property (
        @(posedge clk) disable iff (!reset_n)
        (read || write) |=> (LCD_E == 1'b1)
    );

// No read or write drives LCD_E low on the next cycle.
    check_lcd_e_clear_without_access: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!read && !write) |=> (LCD_E == 1'b0)
    );

// A write captures writedata into LCD_data on the next cycle.
    check_lcd_data_capture_on_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        write |=> (LCD_data == $past(writedata))
    );

// Without a write, LCD_data holds its previous value.
    check_lcd_data_hold_without_write: assert property (
        @(posedge clk) disable iff (!reset_n)
        !write |=> (LCD_data == $past(LCD_data))
    );

endmodule

module SIPO_sva (
    input logic       clk,
    input logic       rst,
    input logic       SerialIn,
    input logic [3:0] BusOut
);

// A sampled reset cycle clears the parallel output by the next clock.
    check_reset_clears_busout: assert property (
        @(posedge clk) !rst |=> (BusOut == 4'b0000)
    );

// The sampled output remains zero on the first cycle after reset release.
    check_reset_release_keeps_zero_before_shift: assert property (
        @(posedge clk) (!rst ##1 rst) |-> (BusOut == 4'b0000)
    );

// In normal operation, the output shifts left and loads SerialIn into bit 0.
    check_shift_register_update: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut == { $past(BusOut[2:0]), $past(SerialIn) })
    );

// Bit 3 takes the previous value of bit 2.
    check_bit3_shift_from_bit2: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[3] == $past(BusOut[2]))
    );

// Bit 2 takes the previous value of bit 1.
    check_bit2_shift_from_bit1: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[2] == $past(BusOut[1]))
    );

// Bit 1 takes the previous value of bit 0.
    check_bit1_shift_from_bit0: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[1] == $past(BusOut[0]))
    );

// Bit 0 captures the previous SerialIn value.
    check_bit0_captures_serialin: assert property (
        @(posedge clk) disable iff (!rst)
        1'b1 |=> (BusOut[0] == $past(SerialIn))
    );

