module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (cin & (a ^ b));

endmodule

module adder(
    input [3:0] a,
    input [3:0] b,
    input cin,
    output [3:0] sum,
    output cout
);

    wire c1, c2, c3;

    full_adder fa1(.a(a[0]), .b(b[0]), .cin(cin), .sum(sum[0]), .cout(c1));
    full_adder fa2(.a(a[1]), .b(b[1]), .cin(c1), .sum(sum[1]), .cout(c2));
    full_adder fa3(.a(a[2]), .b(b[2]), .cin(c2), .sum(sum[2]), .cout(c3));
    full_adder fa4(.a(a[3]), .b(b[3]), .cin(c3), .sum(sum[3]), .cout(cout));

endmodule

sva:
module adder_sva (
    input logic       clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic       cin,
    input logic [3:0] sum,
    input logic       cout
);

// Sum bit 0 follows the first full-adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk)
        sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Sum bit 2 uses the carry from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (
                    ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) &
                    (a[1] ^ b[1])
                )
            )
        )
    );

// Sum bit 3 uses the carry from bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    (
                        (a[1] & b[1]) |
                        (
                            ((a[0] & b[0]) | (cin & (a[0] ^ b[0]))) &
                            (a[1] ^ b[1])
                        )
                    ) &
                    (a[2] ^ b[2])
                )
            )
        )
    );

// Adding zero with no carry-in passes operand a through.
    check_b_zero_passthrough: assert property (
        @(posedge clk)
        (b == 4'b0000 && cin == 1'b0) |-> (sum == a && cout == 1'b0)
    );

// Adding zero with no carry-in passes operand b through.
    check_a_zero_passthrough: assert property (
        @(posedge clk)
        (a == 4'b0000 && cin == 1'b0) |-> (sum == b && cout == 1'b0)
    );

endmodule

