rtl:
module pulse_generator (
    input D,
    input Q,
    output reg pulse
);

reg D_prev;

always @(posedge Q) begin
    if (D == 1'b1 && D_prev == 1'b0) begin
        pulse <= 1'b1;
    end else begin
        pulse <= 1'b0;
    end
    D_prev <= D;
end

endmodule

sva:
module pulse_generator_sva (
    input logic D,
    input logic Q,
    input logic pulse
);

// Clock: Q; reset: none; logic: sequential on posedge Q.

    // From the third sampled clock onward, pulse matches a prior sampled 0->1 on D.
    check_pulse_matches_prior_sampled_rise: assert property (
        @(posedge Q) (##2 1'b1) |-> (pulse == ($past(D) && !$past(D,2)))
    );

// A prior sampled low-to-high transition on D produces pulse.
    check_prior_low_to_high_generates_pulse: assert property (
        @(posedge Q) (##2 ($past(D) && !$past(D,2))) |-> pulse
    );

// Consecutive sampled highs on D do not retrigger pulse.
    check_prior_high_to_high_suppresses_pulse: assert property (
        @(posedge Q) (##2 ($past(D) && $past(D,2))) |-> !pulse
    );

// If D was low on the prior sampled clock, pulse is low now.
    check_prior_low_clears_pulse: assert property (
        @(posedge Q) (##1 (!$past(D))) |-> !pulse
    );

// pulse can only occur if D was high on the prior sampled clock.
    check_pulse_requires_prior_high_d: assert property (
        @(posedge Q) (##1 pulse) |-> $past(D)
    );

// Once established, pulse is only one sampled clock wide.
    check_pulse_is_single_cycle: assert property (
        @(posedge Q) (##1 pulse) |-> ##1 !pulse
    );

endmodule

rtl:
module up_counter(clk, rst, count);
  input clk;
  input rst;
  output reg [3:0] count;

  always @(posedge clk or negedge rst) begin
    if(!rst) begin
      count <= 4'b0;
    end else begin
      count <= count + 1;
    end
  end
endmodule

sva:
module up_counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

// Sequential 4-bit up-counter with asynchronous active-low reset.

    // A sampled reset cycle forces the next sampled count to zero.
    check_reset_drives_zero_next: assert property (
        @(posedge clk)
        !rst |=> (count == 4'h0)
    );

// After a sampled low-to-high reset transition, count is still zero before incrementing.
    check_reset_release_starts_from_zero: assert property (
        @(posedge clk)
        (!rst ##1 rst) |-> (count == 4'h0)
    );

// Below max, the next sampled count is either +1 or 0 if async reset intervenes.
    check_count_advances_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (count != 4'hF) |=> ((count == ($past(count) + 4'd1)) || (count == 4'h0))
    );

// At max, the 4-bit counter wraps to zero on the next sampled clock.
    check_count_wraps_from_max: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

// From zero, the next sampled count is either 1 or 0 if async reset intervenes.
    check_zero_advances_or_resets: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'h0) |=> ((count == 4'h1) || (count == 4'h0))
    );

endmodule

module alu_assertions (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic [2:0]  OP,
    input logic [3:0]  Y
);

// Addition opcode drives Y to A + B.
    check_add_result: assert property (
        @(posedge clk) (OP === 3'b000) |-> (Y == (A + B))
    );

// Subtraction opcode drives Y to A - B.
    check_sub_result: assert property (
        @(posedge clk) (OP === 3'b001) |-> (Y == (A - B))
    );

// AND opcode drives Y to A & B.
    check_and_result: assert property (
        @(posedge clk) (OP === 3'b010) |-> (Y == (A & B))
    );

// OR opcode drives Y to A | B.
    check_or_result: assert property (
        @(posedge clk) (OP === 3'b011) |-> (Y == (A | B))
    );

// XOR opcode drives Y to A ^ B.
    check_xor_result: assert property (
        @(posedge clk) (OP === 3'b100) |-> (Y == (A ^ B))
    );

endmodule

rtl:
module add_sub_4bit(
    input [3:0] A,
    input [3:0] B,
    input M,
    output [3:0] S
);

    wire [3:0] A_inv;
    wire [3:0] B_inv;
    wire [3:0] C_in;
    wire [3:0] S_add;
    wire [3:0] S_sub;

    //Invert B
    assign B_inv = ~B;

    //Create carry-in for subtraction
    assign C_in = M ? B_inv : 4'b0000;

    //Adder and subtractor
    assign S_add = A + B;
    assign S_sub = A + B_inv + C_in;

    //Select output based on mode
    assign S = M ? S_sub : S_add;

endmodule

sva:
module add_sub_4bit_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic M,
    input logic [3:0] S
);

// Output always matches the selected datapath result.
    check_output_matches_selected_result: assert property (
        @(posedge clk) S == (M ? S_sub : S_add)
    );

// In add mode, output is the 4-bit sum of A and B.
    check_add_mode_sum: assert property (
        @(posedge clk) !M |-> (S == S_add)
    );

// In M=1 mode, output follows the implemented A + ~B + C_in path.
    check_mode_one_sum: assert property (
        @(posedge clk) M |-> (S == S_sub)
    );

// In add mode with B at zero, output passes A through.
    check_add_mode_b_zero_passthrough: assert property (
        @(posedge clk) (!M && (B == 4'b0000)) |-> (S == A)
    );

// In add mode with A at zero, output passes B through.
    check_add_mode_a_zero_passthrough: assert property (
        @(posedge clk) (!M && (A == 4'b0000)) |-> (S == B)
    );

// In M=1 mode with B all ones, both inverted-B terms are zero.
    check_mode_one_all_ones_b_passthrough: assert property (
        @(posedge clk) (M && (B == 4'hF)) |-> (S == A)
    );

// In add mode, the LSB is the XOR of the input LSBs.
    check_add_mode_lsb_xor: assert property (
        @(posedge clk) !M |-> (S[0] == (A[0] ^ B[0]))
    );

// In M=1 mode, the LSB reduces to A[0].
    check_mode_one_lsb_tracks_a: assert property (
        @(posedge clk) M |-> (S[0] == A[0])
    );

endmodule

module traffic_light_sva (
    input logic clk,
    input logic [1:0] current_state,
    input logic pedestrian_button,
    input logic [1:0] next_state
);

// Green with a pedestrian request transitions to yellow.
    check_green_with_ped_to_yellow: assert property (
        @(posedge clk)
        (current_state == 2'b00 && pedestrian_button) |-> (next_state == 2'b01)
    );

// Green without a pedestrian request transitions to red.
    check_green_without_ped_to_red: assert property (
        @(posedge clk)
        (current_state == 2'b00 && !pedestrian_button) |-> (next_state == 2'b10)
    );

// Yellow always transitions to red.
    check_yellow_to_red: assert property (
        @(posedge clk)
        (current_state == 2'b01) |-> (next_state == 2'b10)
    );

// Red always transitions to green.
    check_red_to_green: assert property (
        @(posedge clk)
        (current_state == 2'b10) |-> (next_state == 2'b00)
    );

// Invalid state defaults to green.
    check_default_to_green: assert property (
        @(posedge clk)
        (current_state == 2'b11) |-> (next_state == 2'b00)
    );

// The next state is never the invalid encoding 2'b11.
    check_next_state_never_invalid: assert property (
        @(posedge clk)
        (1'b1) |-> (next_state != 2'b11)
    );

// Yellow output only occurs from green with a pedestrian request.
    check_yellow_output_source: assert property (
        @(posedge clk)
        (next_state == 2'b01) |-> (current_state == 2'b00 && pedestrian_button)
    );

// Green output only occurs from red or the default case.
    check_green_output_source: assert property (
        @(posedge clk)
        (next_state == 2'b00) |-> (current_state == 2'b10 || current_state == 2'b11)
    );

// Red output only occurs from yellow or green without a pedestrian request.
    check_red_output_source: assert property (
        @(posedge clk)
        (next_state == 2'b10) |-> (current_state == 2'b01 || (current_state == 2'b00 && !pedestrian_button))
    );

endmodule

rtl:
module shift_register (
    input [3:0] DATA_IN,
    input SHIFT_EN,
    input LOAD_EN,
    input CLK,
    output [3:0] DATA_OUT
);

reg [3:0] reg_data;

always @(posedge CLK) begin
    if (LOAD_EN) begin
        reg_data <= DATA_IN;
    end else if (SHIFT_EN) begin
        reg_data <= {reg_data[2:0], reg_data[3]};
    end
end

assign DATA_OUT = reg_data;

endmodule

sva:
module shift_register_sva (
    input logic [3:0] DATA_IN,
    input logic       SHIFT_EN,
    input logic       LOAD_EN,
    input logic       CLK,
    input logic [3:0] DATA_OUT
);

// A load updates the register with DATA_IN.
    check_load_captures_input: assert property (
        @(posedge CLK) LOAD_EN |=> (DATA_OUT == $past(DATA_IN))
    );

// Load takes priority when both load and shift are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge CLK) (LOAD_EN && SHIFT_EN) |=> (DATA_OUT == $past(DATA_IN))
    );

// A shift rotates the previous MSB into bit 0.
    check_shift_rotates_left: assert property (
        @(posedge CLK) (!LOAD_EN && SHIFT_EN) |=> (DATA_OUT == { $past(DATA_OUT[2:0]), $past(DATA_OUT[3]) })
    );

// With both enables low, the register holds its value.
    check_hold_when_disabled: assert property (
        @(posedge CLK) (!LOAD_EN && !SHIFT_EN) |=> (DATA_OUT == $past(DATA_OUT))
    );

endmodule

rtl:
module mux4to1(
