rtl:
module adder_subtractor (
    input [3:0] A,
    input [3:0] B,
    input C,
    output [3:0] Y
);

  wire [3:0] A_inv;
  wire [3:0] B_inv;
  wire [3:0] carry_in;
  wire [3:0] carry_out;

  assign A_inv = ~A;
  assign B_inv = ~B;
  assign carry_in[0] = C;
  assign carry_in[1] = C & A_inv[0];
  assign carry_in[2] = C & A_inv[1] & A_inv[0];
  assign carry_in[3] = C & A_inv[2] & A_inv[1] & A_inv[0];
  assign carry_out[0] = carry_in[0] & B[0];
  assign carry_out[1] = carry_in[1] & B[1];
  assign carry_out[2] = carry_in[2] & B[2];
  assign carry_out[3] = carry_in[3] & B[3];

  assign Y[0] = A[0] ^ B[0] ^ carry_out[0];
  assign Y[1] = A[1] ^ B[1] ^ carry_out[1];
  assign Y[2] = A[2] ^ B[2] ^ carry_out[2];
  assign Y[3] = A[3] ^ B[3] ^ carry_out[3];

endmodule

sva:
module adder_subtractor_sva (
    input logic        clk,
    input logic [3:0]  A,
    input logic [3:0]  B,
    input logic        C,
    input logic [3:0]  Y
);

// With C low, no carry path is active and Y is A XOR B.
    check_xor_mode: assert property (
        @(posedge clk) (!C) |-> (Y == (A ^ B))
    );

// With B at zero, all output bits pass through A.
    check_zero_b_passthrough: assert property (
        @(posedge clk) (B == 4'b0000) |-> (Y == A)
    );

// Bit 0 follows the implemented XOR and carry-out equation.
    check_bit0_equation: assert property (
        @(posedge clk) Y[0] == (A[0] ^ B[0] ^ (C & B[0]))
    );

// Bit 1 uses a carry term only when C is high and A[0] is low.
    check_bit1_equation: assert property (
        @(posedge clk) Y[1] == (A[1] ^ B[1] ^ (C & (~A[0]) & B[1]))
    );

// Bit 2 uses a carry term only when C is high and A[1:0] are low.
    check_bit2_equation: assert property (
        @(posedge clk) Y[2] == (A[2] ^ B[2] ^ (C & (~A[1]) & (~A[0]) & B[2]))
    );

// Bit 3 uses a carry term only when C is high and A[2:0] are low.
    check_bit3_equation: assert property (
        @(posedge clk) Y[3] == (A[3] ^ B[3] ^ (C & (~A[2]) & (~A[1]) & (~A[0]) & B[3]))
    );

// When C is high, bit 0 always collapses to A[0].
    check_c_mode_bit0_passthrough: assert property (
        @(posedge clk) C |-> (Y[0] == A[0])
    );

// When C is high and A[0] is low, bit 1 collapses to A[1].
    check_c_mode_bit1_passthrough: assert property (
        @(posedge clk) (C && (A[0] == 1'b0)) |-> (Y[1] == A[1])
    );

// When C is high and A[1:0] are low, bit 2 collapses to A[2].
    check_c_mode_bit2_passthrough: assert property (
        @(posedge clk) (C && (A[1:0] == 2'b00)) |-> (Y[2] == A[2])
    );

// When C is high and A[2:0] are low, bit 3 collapses to A[3].
    check_c_mode_bit3_passthrough: assert property (
        @(posedge clk) (C && (A[2:0] == 3'b000)) |-> (Y[3] == A[3])
    );

endmodule

rtl:
module mux4to1 (Y, A, B, C, D, S0, S1);
   input A, B, C, D, S0, S1;
   output Y;

   assign Y = (S1 & S0) ? D : (S1 & ~S0) ? C : (~S1 & S0) ? B : A;

endmodule

sva:
module mux4to1_assertions (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic S0,
    input logic S1
);

// Y must match the RTL mux expression on every sampled cycle.
    check_mux_expression: assert property (
        @(posedge clk)
        Y == ((S1 & S0) ? D : ((S1 & ~S0) ? C : (((~S1) & S0) ? B : A)))
    );

// Select 00 routes A to Y.
    check_select_00_routes_A: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == A)
    );

// Select 01 routes B to Y.
    check_select_01_routes_B: assert property (
        @(posedge clk)
        (!S1 && S0) |-> (Y == B)
    );

// Select 10 routes C to Y.
    check_select_10_routes_C: assert property (
        @(posedge clk)
        (S1 && !S0) |-> (Y == C)
    );

// Select 11 routes D to Y.
    check_select_11_routes_D: assert property (
        @(posedge clk)
        (S1 && S0) |-> (Y == D)
    );

endmodule

rtl:
module logic_gate (
    input A,
    input B,
    input [1:0] OP,
    output reg Y
);

    // Module logic
    wire and_out;
    wire or_out;
    wire xor_out;
    wire not_out;

    assign and_out = A & B;
    assign or_out = A | B;
    assign xor_out = A ^ B;
    assign not_out = ~A;

    always @(*) begin
        case (OP)
            2'b00: Y = and_out;
            2'b01: Y = or_out;
            2'b10: Y = xor_out;
            2'b11: Y = not_out;
        endcase
    end

endmodule

sva:
module logic_gate_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic [1:0] OP,
    input logic Y
);

// OP=00 selects the AND result.
    check_and_select: assert property (
        @(posedge clk) (OP == 2'b00) |-> (Y == (A & B))
    );

// OP=01 selects the OR result.
    check_or_select: assert property (
        @(posedge clk) (OP == 2'b01) |-> (Y == (A | B))
    );

// OP=10 selects the XOR result.
    check_xor_select: assert property (
        @(posedge clk) (OP == 2'b10) |-> (Y == (A ^ B))
    );

// OP=11 selects the inversion of A.
    check_not_select: assert property (
        @(posedge clk) (OP == 2'b11) |-> (Y == (~A))
    );

// Y always matches the function selected by OP.
    check_selected_function: assert property (
        @(posedge clk)
        Y == ((OP == 2'b00) ? (A & B) :
              (OP == 2'b01) ? (A | B) :
              (OP == 2'b10) ? (A ^ B) :
                              (~A))
    );

endmodule

