rtl:
module mux_3to1_with_outputs (
    input wire [2:0] in_vec,
    input wire sel,
    output wire [2:0] out_vec,
    output wire o2,
    output wire o1,
    output wire o0
);

wire [2:0] mux_out;
wire in_0, in_1, in_2;

assign in_0 = in_vec[0];
assign in_1 = in_vec[1];
assign in_2 = in_vec[2];

assign o0 = in_0;
assign o1 = in_1;
assign o2 = in_2;

assign mux_out = sel ? in_vec[2:1] : in_vec[1:0];

assign out_vec[0] = mux_out[0] | in_0;
assign out_vec[1] = mux_out[1] | in_1;
assign out_vec[2] = mux_out[2] | in_2;

endmodule

sva:
module mux_3to1_with_outputs_sva (
    input logic [2:0] in_vec,
    input logic sel,
    input logic [2:0] out_vec,
    input logic o2,
    input logic o1,
    input logic o0,
    input logic clk
);

// No RTL clock or reset; clk is only for assertion sampling.

    // o0 directly reflects in_vec[0].
    check_o0_pass_through: assert property (
        @(posedge clk) o0 == in_vec[0]
    );

// o1 directly reflects in_vec[1].
    check_o1_pass_through: assert property (
        @(posedge clk) o1 == in_vec[1]
    );

// o2 directly reflects in_vec[2].
    check_o2_pass_through: assert property (
        @(posedge clk) o2 == in_vec[2]
    );

// With sel low, out_vec matches in_vec.
    check_out_vec_sel_low: assert property (
        @(posedge clk) !sel |-> (out_vec == in_vec)
    );

// With sel high, out_vec preserves bit 2 and ORs adjacent lower bits.
    check_out_vec_sel_high: assert property (
        @(posedge clk) sel |-> (out_vec == {in_vec[2], (in_vec[2] | in_vec[1]), (in_vec[1] | in_vec[0])})
    );

endmodule

module my_and3_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic X,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

// X implements A & B & C.
    check_x_matches_and3: assert property (
        @(posedge clk) X == (A & B & C)
    );

// A low forces X low.
    check_a_low_forces_x_low: assert property (
        @(posedge clk) !A |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

// All three inputs high drive X high.
    check_all_inputs_high_drive_x_high: assert property (
        @(posedge clk) (A & B & C) |-> X
    );

// X high requires all three inputs high.
    check_x_high_requires_all_inputs_high: assert property (
        @(posedge clk) X |-> (A & B & C)
    );

// With B and C high, X follows A.
    check_x_follows_a_when_bc_high: assert property (
        @(posedge clk) (B & C) |-> (X == A)
    );

// With A and C high, X follows B.
    check_x_follows_b_when_ac_high: assert property (
        @(posedge clk) (A & C) |-> (X == B)
    );

// With A and B high, X follows C.
    check_x_follows_c_when_ab_high: assert property (
        @(posedge clk) (A & B) |-> (X == C)
    );

endmodule

rtl:
module top_module(
    input [3:0] in0,
    input [3:0] in1,
    input [3:0] in2,
    input [3:0] in3,
    input [1:0] sel,
    input       reset,
    output reg  [3:0] out_assign,
    output reg  [3:0] out_alwaysblock
);

wire [3:0] mux1_out, mux2_out;

assign mux1_out = (sel[0] == 1'b0) ? in0 : in1;
assign mux2_out = (sel[0] == 1'b0) ? in2 : in3;

always @(*) begin
    case (sel[1])
        1'b0: out_alwaysblock = mux1_out;
        1'b1: out_alwaysblock = mux2_out;
        default: out_alwaysblock = 4'b0;
    endcase
end

always @(posedge reset) begin
    if (reset) begin
        out_assign <= 4'b0;
    end else begin
        case (sel)
            2'b00: out_assign <= in0;
            2'b01: out_assign <= in1;
            2'b10: out_assign <= in2;
            2'b11: out_assign <= in3;
            default: out_assign <= 4'b0;
        endcase
    end
end

endmodule

sva:
module top_module_sva (
    input logic [3:0] in0,
    input logic [3:0] in1,
    input logic [3:0] in2,
    input logic [3:0] in3,
    input logic [1:0] sel,
    input logic       reset,
    input logic [3:0] out_assign,
    input logic [3:0] out_alwaysblock
);

// reset is active high and is the only edge-triggered signal.
    // out_alwaysblock is combinational; out_assign only updates on posedge reset.

    // out_alwaysblock selects in0 when sel is 2'b00.
    check_out_alwaysblock_sel_00: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b00) |-> (out_alwaysblock == in0)
    );

// out_alwaysblock selects in1 when sel is 2'b01.
    check_out_alwaysblock_sel_01: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b01) |-> (out_alwaysblock == in1)
    );

// out_alwaysblock selects in2 when sel is 2'b10.
    check_out_alwaysblock_sel_10: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b10) |-> (out_alwaysblock == in2)
    );

// out_alwaysblock selects in3 when sel is 2'b11.
    check_out_alwaysblock_sel_11: assert property (
        @(negedge reset) disable iff (reset)
        (sel === 2'b11) |-> (out_alwaysblock == in3)
    );

// out_alwaysblock drives zero on the case default branch.
    check_out_alwaysblock_default: assert property (
        @(negedge reset) disable iff (reset)
        ((sel[1] !== 1'b0) && (sel[1] !== 1'b1)) |-> (out_alwaysblock == 4'b0000)
    );

// After a prior reset assertion, out_assign is cleared to zero.
    check_out_assign_cleared_by_reset: assert property (
        @(negedge reset) disable iff (reset)
        !$isunknown($past(reset, 1, 1'b1, @(posedge reset))) |-> (out_assign == 4'b0000)
    );

endmodule

rtl:
module keypad_scanner (
    input clk,
    input [3:0] col,
    output reg [3:0] row
);

reg [3:0] row_pipe1, row_pipe2, row_pipe3;

always @(posedge clk) begin
    row_pipe1 <= row;
    row_pipe2 <= row_pipe1;
    row_pipe3 <= row_pipe2;

    case (col)
        4'b1110: row <= 4'b1110;
        4'b1101: row <= 4'b1101;
        4'b1011: row <= 4'b1011;
        4'b0111: row <= 4'b0111;
        default: row <= 4'b0000;
    endcase
end

endmodule

sva:
module keypad_scanner_sva (
    input logic       clk,
    input logic [3:0] col,
    input logic [3:0] row
);

// Column 1110 drives row 1110 on the following cycle.
    check_row_for_col_1110: assert property (
        @(posedge clk) (col == 4'b1110) |=> (row == 4'b1110)
    );

// Column 1101 drives row 1101 on the following cycle.
    check_row_for_col_1101: assert property (
        @(posedge clk) (col == 4'b1101) |=> (row == 4'b1101)
    );

// Column 1011 drives row 1011 on the following cycle.
    check_row_for_col_1011: assert property (
        @(posedge clk) (col == 4'b1011) |=> (row == 4'b1011)
    );

// Column 0111 drives row 0111 on the following cycle.
    check_row_for_col_0111: assert property (
        @(posedge clk) (col == 4'b0111) |=> (row == 4'b0111)
    );

// Any non-matching column value drives row to 0000 on the following cycle.
    check_row_default_for_other_cols: assert property (
        @(posedge clk)
        !((col == 4'b1110) ||
          (col == 4'b1101) ||
          (col == 4'b1011) ||
          (col == 4'b0111)) |=> (row == 4'b0000)
    );

// Row only takes values produced by the case statement.
    check_row_legal_values: assert property (
        @(posedge clk) 1'b1 |=> (
            (row == 4'b1110) ||
            (row == 4'b1101) ||
            (row == 4'b1011) ||
            (row == 4'b0111) ||
            (row == 4'b0000)
        )
    );

endmodule

rtl:
module signal_processing(
    input A1_N,
    input A2_N,
    input B1,
    input B2,
    output Y,
    input VPB,
    input VPWR,
    input VGND,
    input VNB
);

    wire B1_OR_B2;

    assign B1_OR_B2 = B1 | B2;

    assign Y = (A1_N & A2_N) ? B1_OR_B2 : (A1_N & ~A2_N) ? B1 : (~A1_N & A2_N) ? B2 : 0;

endmodule

sva:
module signal_processing_sva (
    input logic clk,
    input logic A1_N,
    input logic A2_N,
    input logic B1,
    input logic B2,
    input logic Y,
    input logic VPB,
    input logic VPWR,
    input logic VGND,
    input logic VNB
);

// No RTL reset exists; assertions are always active.
    // Y must match the RTL's full combinational expression.
    check_y_matches_rtl_expr: assert property (
        @(posedge clk) disable iff (1'b0)
        Y == ((A1_N & A2_N) ? (B1 | B2) :
              (A1_N & ~A2_N) ? B1 :
              (~A1_N & A2_N) ? B2 : 1'b0)
    );

// When both select inputs are high, Y is B1 OR B2.
    check_or_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N && A2_N) |-> (Y == (B1 | B2))
    );

// When only A1_N is high, Y follows B1.
    check_b1_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1_N && !A2_N) |-> (Y == B1)
    );

// When only A2_N is high, Y follows B2.
    check_b2_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1_N && A2_N) |-> (Y == B2)
    );

// When both select inputs are low, Y is forced low.
    check_no_path_selected: assert property (
        @(posedge clk) disable iff (1'b0)
        (!A1_N && !A2_N) |-> (Y == 1'b0)
    );

endmodule

rtl:
module sparc_exu_aluspr (
  input [63:0] rs1_data,
  input [63:0] rs2_data,
  input cin,
  output reg [63:0] spr_out
);

  always @* begin
    // ALU operation
    spr_out = (cin) ? rs1_data + rs2_data : rs1_data - rs2_data;
  end

endmodule

sva:
module sparc_exu_aluspr_sva (
    input logic        clk,
    input logic [63:0] rs1_data,
    input logic [63:0] rs2_data,
    input logic        cin,
    input logic [63:0] spr_out
);

// In add mode, spr_out must equal rs1_data plus rs2_data.
    check_add_mode_result: assert property (
        @(posedge clk) cin |-> (spr_out == (rs1_data + rs2_data))
    );

// In subtract mode, spr_out must equal rs1_data minus rs2_data.
    check_sub_mode_result: assert property (
        @(posedge clk) !cin |-> (spr_out == (rs1_data - rs2_data))
    );

// Subtracting equal operands must produce zero.
    check_sub_equal_operands_zero: assert property (
        @(posedge clk) (!cin && (rs1_data == rs2_data)) |-> (spr_out == 64'd0)
    );

// In add mode, adding zero on rs2_data must pass rs1_data through.
    check_add_zero_right_identity: assert property (
        @(posedge clk) (cin && (rs2_data == 64'd0)) |-> (spr_out == rs1_data)
    );

// In subtract mode, subtracting zero on rs2_data must pass rs1_data through.
    check_sub_zero_right_identity: assert property (
        @(posedge clk) (!cin && (rs2_data == 64'd0)) |-> (spr_out == rs1_data)
    );

endmodule

rtl:
module memory_module (
    // inputs:
    address,
    chipselect,
    clk,
    reset_n,
    write_n,
    writedata,

    // outputs:
    out_port,
    readdata
);

    output [3:0] out_port;
    output [31:0] readdata;
    input [1:0] address;
    input chipselect;
    input clk;
    input reset_n;
    input write_n;
    input [31:0] writedata;

    wire clk_en;
    reg [3:0] data_out;
    wire [3:0] out_port;
    wire [3:0] read_mux_out;
    wire [31:0] readdata;

    assign clk_en = 1;

    //s1, which is an e_avalon_slave
    assign read_mux_out = {4 {(address == 0)}} & data_out;

    always @(posedge clk or negedge reset_n) begin
        if (~reset_n) begin
            data_out <= 0;
        end else if (chipselect && ~write_n && (address == 0)) begin
            data_out <= writedata[3:0];
        end
    end

    assign readdata = {32'b0 | read_mux_out};
    assign out_port = data_out;

endmodule

sva:
module memory_module_sva (
    input logic [1:0]  address,
    input logic        chipselect,
    input logic        clk,
    input logic        reset_n,
    input logic        write_n,
    input logic [31:0] writedata,
    input logic [3:0]  out_port,
    input logic [31:0] readdata
);

// Active-low reset clears both outputs.
    reset_clears_outputs: assert property (
        @(posedge clk) !reset_n |-> ((out_port == 4'h0) && (readdata == 32'h0))
    );

// A selected write to address 0 loads the low nibble into out_port.
    write_addr0_updates_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[3:0]))
    );

// With chipselect low, out_port holds its previous value.
    no_chipselect_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!chipselect) |=> (out_port == $past(out_port))
    );

// When selected but not writing, out_port holds its previous value.
    write_high_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && write_n) |=> (out_port == $past(out_port))
    );

// Writes to nonzero addresses do not change out_port.
    write_nonzero_addr_ignored: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

// Address 0 returns out_port in the low nibble.
    read_addr0_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {28'h0, out_port})
    );

// Nonzero addresses return zero on readdata.
    read_nonzero_addr_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'h0)
    );

// readdata upper bits are always zero.
    readdata_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:4] == 28'h0)
    );

endmodule

rtl:
module comparator (
    input [3:0] A, B, C, D,
    output reg EQ, GT
);

    always @(*) begin
        if (A == B && C == D) begin
            EQ = 1'b1;
            GT = 1'b0;
        end else if (A > B || (A == B && C > D)) begin
            EQ = 1'b0;
            GT = 1'b1;
        end else begin
            EQ = 1'b0;
            GT = 1'b0;
        end
    end

endmodule

sva:
module comparator_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] C,
    input logic [3:0] D,
    input logic EQ,
    input logic GT
);

// Exact input match drives EQ high and GT low.
    check_equal_case: assert property (
        @(posedge clk) ((A == B) && (C == D)) |-> ((EQ == 1'b1) && (GT == 1'b0))
    );

// A greater than B drives GT high and EQ low.
    check_gt_a_greater: assert property (
        @(posedge clk) (A > B) |-> ((EQ == 1'b0) && (GT == 1'b1))
    );

// With A tied to B, C greater than D drives GT high and EQ low.
    check_gt_tiebreak_case: assert property (
        @(posedge clk) ((A == B) && (C > D)) |-> ((EQ == 1'b0) && (GT == 1'b1))
    );

// Lexicographically smaller inputs drive both outputs low.
    check_less_than_case: assert property (
        @(posedge clk) ((A < B) || ((A == B) && (C < D))) |-> ((EQ == 1'b0) && (GT == 1'b0))
    );

// EQ can only be high on an exact match.
    check_eq_only_on_exact_match: assert property (
        @(posedge clk) (EQ == 1'b1) |-> ((A == B) && (C == D))
    );

// GT can only be high on a lexicographic greater-than result.
    check_gt_only_on_greater_than: assert property (
        @(posedge clk) (GT == 1'b1) |-> ((A > B) || ((A == B) && (C > D)))
    );

// Both outputs low means the inputs are lexicographically smaller.
    check_zero_outputs_mean_less_than: assert property (
        @(posedge clk) ((EQ == 1'b0) && (GT == 1'b0)) |-> ((A < B) || ((A == B) && (C < D)))
    );

// EQ and GT are never asserted together.
    check_output_mutex: assert property (
        @(posedge clk) !((EQ == 1'b1) && (GT == 1'b1))
    );

endmodule

rtl:
module signed_mag_to_twos_comp (
    input [3:0] signed_mag,
    output reg [3:0] twos_comp
);

    always @(*) begin
        if (signed_mag[3] == 1) begin
            twos_comp = ~(signed_mag) + 1;
        end else begin
            twos_comp = signed_mag;
        end
    end

endmodule

sva:
module signed_mag_to_twos_comp_sva (
    input logic       clk,
    input logic [3:0] signed_mag,
    input logic [3:0] twos_comp
);

// Output matches the implemented conversion function.
    check_full_mapping: assert property (
        @(posedge clk)
        twos_comp == (signed_mag[3] ? ((~signed_mag) + 4'b0001) : signed_mag)
    );

// Non-negative inputs pass through unchanged.
    check_nonnegative_passthrough: assert property (
        @(posedge clk)
        !signed_mag[3] |-> (twos_comp == signed_mag)
    );

// Negative inputs use bitwise invert plus one on all four bits.
    check_negative_invert_plus_one: assert property (
        @(posedge clk)
        signed_mag[3] |-> (twos_comp == ((~signed_mag) + 4'b0001))
    );

endmodule

module counter_4bit_assertions (
    input logic clk,
    input logic reset,
    input logic enable,
    input logic [3:0] Q
);

// Clock: clk
    // Reset: reset, active high asynchronous

    // A sampled reset must leave the counter at zero by the next clock.
    check_reset_clears_q: assert property (
        @(posedge clk) reset |=> (Q == 4'b0000)
    );

// When disabled outside reset, the counter holds its value.
    check_hold_when_disabled: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (Q == $past(Q))
    );

// When enabled below 15, the counter increments by one.
    check_increment_when_enabled: assert property (
        @(posedge clk) disable iff (reset)
        enable && (Q != 4'hF) |=> (Q == ($past(Q) + 4'd1))
    );

// When enabled at 15, the counter wraps to zero.
    check_wrap_when_enabled_at_max: assert property (
        @(posedge clk) disable iff (reset)
        enable && (Q == 4'hF) |=> (Q == 4'h0)
    );

endmodule

module synchronous_counter_sva (
    input logic       clk,
    input logic       reset,
    input logic       enable,
    input logic [3:0] count
);

// Synchronous active-high reset clears the counter.
    check_reset_clears_count: assert property (
        @(posedge clk)
        reset |=> (count == 4'b0000)
    );

// When enabled below 15, the counter increments by one.
    check_enable_increments_count: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

// When enabled at 15, the counter wraps to zero.
    check_enable_wraps_count: assert property (
        @(posedge clk) disable iff (reset)
        enable && (count == 4'hF) |=> (count == 4'h0)
    );

// When not enabled, the counter holds its value.
    check_disable_holds_count: assert property (
        @(posedge clk) disable iff (reset)
        !enable |=> (count == $past(count))
    );

endmodule

rtl:
module my_module (
    output Y   ,
    input  A1  ,
    input  A2  ,
    input  A3  ,
    input  B1  
);

assign Y = (~A1 | ~A2 | ~A3) & B1;

endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic A3,
    input logic B1
);

// Y matches the implemented combinational equation.
    check_y_equation: assert property (
        @(posedge clk) Y == ((~A1 | ~A2 | ~A3) & B1)
    );

// Y must be low whenever B1 is low.
    check_y_low_when_b1_low: assert property (
        @(posedge clk) !B1 |-> !Y
    );

// Y must be low when all A inputs are high.
    check_y_low_when_all_a_high: assert property (
        @(posedge clk) (A1 && A2 && A3) |-> !Y
    );

// Y must be high when B1 is high and any A input is low.
    check_y_high_when_b1_high_and_any_a_low: assert property (
        @(posedge clk) (B1 && (!A1 || !A2 || !A3)) |-> Y
    );

// A high Y requires B1 to be high.
    check_y_implies_b1_high: assert property (
        @(posedge clk) Y |-> B1
    );

// A high Y requires at least one A input to be low.
    check_y_implies_any_a_low: assert property (
        @(posedge clk) Y |-> (!A1 || !A2 || !A3)
    );

endmodule

rtl:
module m2
  (
   input clk,
   input d,
   // Due to bug the below disable used to be ignored.
   // verilator lint_off UNOPT
   // verilator lint_off UNOPTFLAT
   output reg [1:0] q
   // verilator lint_on UNOPT
   // verilator lint_on UNOPTFLAT
   );

   always @(posedge clk) begin
      q[1] <= d;
      q[0] <= q[1];
   end

endmodule

sva:
module m2_assertions (
    input logic       clk,
    input logic       d,
    input logic [1:0] q
);

// q[1] captures d on the next sampled clock.
    check_q1_captures_d: assert property (
        @(posedge clk) 1'b1 |=> (q[1] == $past(d))
    );

// q[0] captures the previous value of q[1].
    check_q0_captures_q1: assert property (
        @(posedge clk) 1'b1 |=> (q[0] == $past(q[1]))
    );

// q[0] is d delayed by two clock cycles.
    check_q0_two_cycle_delay_of_d: assert property (
        @(posedge clk) 1'b1 |=> ##1 (q[0] == $past(d, 2))
    );

// q holds the two most recent sampled values of d.
    check_q_is_two_stage_shift_of_d: assert property (
        @(posedge clk) 1'b1 |=> ##1 (q == { $past(d), $past(d, 2) })
    );

endmodule

module d_ff_set_clr_sva (
    input logic CLK,
    input logic D,
    input logic SET,
    input logic CLR,
    input logic Q
);

// When SET and CLR are both high, SET has priority and Q becomes 1.
    check_set_priority_over_clear: assert property (
        @(posedge CLK) (SET && CLR) |=> (Q == 1'b1)
    );

// When only SET is high, Q becomes 1.
    check_set_drives_q_high: assert property (
        @(posedge CLK) (SET && !CLR) |=> (Q == 1'b1)
    );

// When SET is low and CLR is high, Q becomes 0.
    check_clear_drives_q_low: assert property (
        @(posedge CLK) (!SET && CLR) |=> (Q == 1'b0)
    );

// When SET and CLR are low, D=1 is captured into Q.
    check_capture_data_one: assert property (
        @(posedge CLK) (!SET && !CLR && D) |=> (Q == 1'b1)
    );

// When SET and CLR are low, D=0 is captured into Q.
    check_capture_data_zero: assert property (
        @(posedge CLK) (!SET && !CLR && !D) |=> (Q == 1'b0)
    );

endmodule

module add_module_assertions (
    input logic clk,
    input logic rst,
    input logic [15:0] in_data,
    input logic [15:0] out_data
);

// Reset drives the output to zero by the next sampled clock.
    check_reset_clears_out_next: assert property (
        @(posedge clk) !rst |=> (out_data == 16'h0000)
    );

// While reset stays asserted, the output remains zero.
    check_reset_holds_out_zero: assert property (
        @(posedge clk) (!rst && $past(!rst)) |-> (out_data == 16'h0000)
    );

// Each active clock loads input plus 16'h1234 into the output register.
    check_active_cycle_updates_sum: assert property (
        @(posedge clk) disable iff (!rst) 1'b1 |=> (out_data == ($past(in_data) + 16'h1234))
    );

// The first active cycle after reset release also loads the sum correctly.
    check_reset_release_updates_sum: assert property (
        @(posedge clk) disable iff (!rst) !$past(rst) |=> (out_data == ($past(in_data) + 16'h1234))
    );

// Zero input produces 16'h1234 on the next sampled clock.
    check_zero_input_case: assert property (
        @(posedge clk) disable iff (!rst) (in_data == 16'h0000) |=> (out_data == 16'h1234)
    );

// Max input wraps around to 16'h1233 on the next sampled clock.
    check_max_input_wraparound: assert property (
        @(posedge clk) disable iff (!rst) (in_data == 16'hFFFF) |=> (out_data == 16'h1233)
    );

endmodule

rtl:
module pg_49 ( g, p, g_prec, p_prec, p_out, g_out_BAR );
  input g, p, g_prec, p_prec;
  output p_out, g_out_BAR;

  // Implement logical AND between p and p_prec
  assign p_out = p & p_prec;

  // Implement logical NOR between g_prec and p
  assign g_out_BAR = ~(g_prec | p);

endmodule

sva:
module pg_49_sva (
    input logic clk,
    input logic g,
    input logic p,
    input logic g_prec,
    input logic p_prec,
    input logic p_out,
    input logic g_out_BAR
);

// p_out implements p AND p_prec.
    check_p_out_and_function: assert property (
        @(posedge clk) p_out == (p & p_prec)
    );

// g_out_BAR implements NOR of g_prec and p.
    check_g_out_bar_nor_function: assert property (
        @(posedge clk) g_out_BAR == ~(g_prec | p)
    );

// p_out can only be high when both inputs are high.
    check_p_out_high_requires_inputs_high: assert property (
        @(posedge clk) p_out |-> (p && p_prec)
    );

// p_out must be low if either input is low.
    check_p_out_low_when_any_input_low: assert property (
        @(posedge clk) (!p || !p_prec) |-> !p_out
    );

// g_out_BAR can only be high when both NOR inputs are low.
    check_g_out_bar_high_requires_inputs_low: assert property (
        @(posedge clk) g_out_BAR |-> (!g_prec && !p)
    );

// g_out_BAR must be low if either NOR input is high.
    check_g_out_bar_low_when_any_input_high: assert property (
        @(posedge clk) (g_prec || p) |-> !g_out_BAR
    );

// A high p_out forces g_out_BAR low because p must be high.
    check_p_out_implies_g_out_bar_low: assert property (
        @(posedge clk) p_out |-> !g_out_BAR
    );

endmodule

rtl:
module dff_rst_set_clr (
  input clk, rst, set, clr, d,
  output reg q
);

always @(posedge clk or negedge rst) begin
  if (~rst) begin
    q <= 1'b0;
  end else if (set) begin
    q <= 1'b1;
  end else if (clr) begin
    q <= 1'b0;
  end else begin
    q <= d;
  end
end

endmodule

sva:
module dff_rst_set_clr_sva (
    input logic clk,
    input logic rst,
    input logic set,
    input logic clr,
    input logic d,
    input logic q
);

// A low reset drives q low by the next clock sample.
    check_reset_clears_q: assert property (
        @(posedge clk)
        !rst |=> (q == 1'b0)
    );

// Set drives q high on the next cycle.
    check_set_loads_high: assert property (
        @(posedge clk) disable iff (!rst)
        set |=> (q == 1'b1)
    );

// Clear drives q low when set is not asserted.
    check_clear_loads_low: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && clr) |=> (q == 1'b0)
    );

// Data value 1 is loaded when set and clear are both low.
    check_data_one_loads_high: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && !clr && d) |=> (q == 1'b1)
    );

// Data value 0 is loaded when set and clear are both low.
    check_data_zero_loads_low: assert property (
        @(posedge clk) disable iff (!rst)
        (!set && !clr && !d) |=> (q == 1'b0)
    );

// Set has priority over clear when both are asserted.
    check_set_priority_over_clear: assert property (
        @(posedge clk) disable iff (!rst)
        (set && clr) |=> (q == 1'b1)
    );

endmodule

rtl:
module ctu_nor2 (z, a, b);

output z;
input  a;
input  b;

assign z = ~(a | b);

endmodule

sva:
module ctu_nor2_sva (
    input logic clk,
    input logic z,
    input logic a,
    input logic b
);

// Output must equal the NOR of the inputs.
    check_nor_function: assert property (
        @(posedge clk) z === ~(a | b)
    );

// z must be HIGH when both inputs are LOW.
    check_z_high_when_both_low: assert property (
        @(posedge clk) ((a === 1'b0) && (b === 1'b0)) |-> (z === 1'b1)
    );

// z must be LOW whenever a is HIGH.
    check_z_low_when_a_high: assert property (
        @(posedge clk) (a === 1'b1) |-> (z === 1'b0)
    );

// z must be LOW whenever b is HIGH.
    check_z_low_when_b_high: assert property (
        @(posedge clk) (b === 1'b1) |-> (z === 1'b0)
    );

// A HIGH output implies both inputs are LOW.
    check_z_high_implies_both_low: assert property (
        @(posedge clk) (z === 1'b1) |-> ((a === 1'b0) && (b === 1'b0))
    );

endmodule

rtl:
module digital_circuit (
    input input_1,
    input input_2,    
    input input_3,    
    input input_4,    
    output output_1,    
    output output_2    
);

    // Implement output_1 as the AND of input_1 and input_2
    assign output_1 = input_1 & input_2;

    // Implement output_2 as the OR of input_3 and input_4
    assign output_2 = input_3 | input_4;

endmodule

sva:
module digital_circuit_sva (
    input logic clk,
    input logic input_1,
    input logic input_2,
    input logic input_3,
    input logic input_4,
    input logic output_1,
    input logic output_2
);

// output_1 must equal the AND of input_1 and input_2.
    check_output_1_and: assert property (
        @(posedge clk) output_1 == (input_1 & input_2)
    );

// output_2 must equal the OR of input_3 and input_4.
    check_output_2_or: assert property (
        @(posedge clk) output_2 == (input_3 | input_4)
    );

endmodule

module a221o_2_sva (
    input logic clk,
    input logic X,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic Y
);

// Y must match the implemented sum-of-products equation.
    check_output_equation: assert property (
        @(posedge clk)
        Y == ((A1 & B1 & C1) | (A2 & B2 & C1))
    );

// C1 low forces Y low.
    check_c1_low_forces_y_low: assert property (
        @(posedge clk)
        !C1 |-> !Y
    );

// The A1/B1 path is sufficient to drive Y high.
    check_first_product_term_drives_y: assert property (
        @(posedge clk)
        (A1 & B1 & C1) |-> Y
    );

// The A2/B2 path is sufficient to drive Y high.
    check_second_product_term_drives_y: assert property (
        @(posedge clk)
        (A2 & B2 & C1) |-> Y
    );

// Y high requires C1 to be high.
    check_y_implies_c1_high: assert property (
        @(posedge clk)
        Y |-> C1
    );

// Y high requires at least one input pair product to be true.
    check_y_implies_product_term: assert property (
        @(posedge clk)
        Y |-> ((A1 & B1) | (A2 & B2))
    );

endmodule

module logic_function_sva (
    input logic clk,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic C1,
    input logic C2,
    input logic X
);

// X must match the implemented sum-of-products function.
    check_x_matches_logic_function: assert property (
        @(posedge clk)
        X == ((A1 & A2) | (B1 & B2) | (C1 & C2))
    );

// An asserted A input pair must drive X high.
    check_a_term_sets_x: assert property (
        @(posedge clk)
        (A1 && A2) |-> X
    );

// An asserted B input pair must drive X high.
    check_b_term_sets_x: assert property (
        @(posedge clk)
        (B1 && B2) |-> X
    );

// An asserted C input pair must drive X high.
    check_c_term_sets_x: assert property (
        @(posedge clk)
        (C1 && C2) |-> X
    );

// If no input pair is fully asserted, X must be low.
    check_no_terms_clear_x: assert property (
        @(posedge clk)
        !((A1 && A2) || (B1 && B2) || (C1 && C2)) |-> !X
    );

// If X is high with B and C terms inactive, the A term must be active.
    check_x_high_with_only_a_path: assert property (
        @(posedge clk)
        X && !(B1 && B2) && !(C1 && C2) |-> (A1 && A2)
    );

// If X is high with A and C terms inactive, the B term must be active.
    check_x_high_with_only_b_path: assert property (
        @(posedge clk)
        X && !(A1 && A2) && !(C1 && C2) |-> (B1 && B2)
    );

// If X is high with A and B terms inactive, the C term must be active.
    check_x_high_with_only_c_path: assert property (
        @(posedge clk)
        X && !(A1 && A2) && !(B1 && B2) |-> (C1 && C2)
    );

endmodule

rtl:
module and_gate (
    Y,
    A,
    B,
    C
);

    output Y;
    input A;
    input B;
    input C;

    assign Y = (A & B & ~C);

endmodule

sva:
module and_gate_sva (
    input logic clk,
    input logic Y,
    input logic A,
    input logic B,
    input logic C
);

// Y must implement A & B & ~C.
    check_y_function: assert property (
        @(posedge clk) Y === (A & B & ~C)
    );

// When A, B, and ~C are true, Y must be high.
    check_y_high_when_inputs_match: assert property (
        @(posedge clk) (A & B & ~C) |-> (Y === 1'b1)
    );

// A low forces Y low.
    check_a_low_forces_y_low: assert property (
        @(posedge clk) (A === 1'b0) |-> (Y === 1'b0)
    );

// B low forces Y low.
    check_b_low_forces_y_low: assert property (
        @(posedge clk) (B === 1'b0) |-> (Y === 1'b0)
    );

// C high forces Y low.
    check_c_high_forces_y_low: assert property (
        @(posedge clk) (C === 1'b1) |-> (Y === 1'b0)
    );

// Y high implies A and B are high and C is low.
    check_y_high_implies_inputs_match: assert property (
        @(posedge clk) (Y === 1'b1) |-> ((A === 1'b1) && (B === 1'b1) && (C === 1'b0))
    );

endmodule

rtl:
module mux_2to1(
