    check_mux_equation: assert property (
        @(posedge clk)
        Y == ((A & ~S0 & ~S1) | (B & S0 & ~S1) | (C & ~S0 & S1) | (D & S0 & S1))
    );

// Select 2'b00 routes A to Y.
    check_select_00_routes_a: assert property (
        @(posedge clk)
        (!S1 && !S0) |-> (Y == A)
    );

