        .data_1(data_in[3]),
        .sel(sel[0]),
        .data_out(data_out_temp1)
    );

    // Instantiate another 2:1 multiplexer to select the output of the two 2:1 multiplexers
    mux2to1 mux2 (
        .data_0(data_out_temp0),
        .data_1(data_out_temp1),
        .sel(sel[1]),
        .data_out(data_out)
    );

