module input_output(
    input        clk,
    input  [6:0] a,
    input        a_msb,              
    output [14:0] b,              
    output       b_msb            
);

    wire c;

    reg [15:0] b_reg = 0;      

    assign c = a_msb & b_reg[0];

    always @(posedge clk) begin
        b_reg <= b_reg + {a_msb ? {8'd255, a} : {8'd0, a}};
    end

    assign b_msb = b_reg[15];
    assign b = {b_reg[14:0], c};

endmodule

sva:
module input_output_sva (
    input logic        clk,
    input logic [6:0]  a,
    input logic        a_msb,
    input logic [14:0] b,
    input logic        b_msb
);

// b[0] is a_msb gated by the stored LSB carried on b[1].
    check_b_lsb_gate: assert property (
        @(posedge clk) b[0] == (a_msb & b[1])
    );

// With a_msb low, the observable accumulator slice adds zero-extended a.
    check_slice_update_no_extend: assert property (
        @(posedge clk) (!a_msb) |=> (b[14:1] == ($past(b[14:1]) + {7'h00, $past(a)}))
    );

// With a_msb high, the observable accumulator slice adds {7'h7F, a}.
    check_slice_update_with_extend: assert property (
        @(posedge clk) (a_msb) |=> (b[14:1] == ($past(b[14:1]) + {7'h7F, $past(a)}))
    );

// The stored bit0, exposed on b[1], updates with the previous a[0].
    check_state_bit0_update: assert property (
        @(posedge clk) 1'b1 |=> (b[1] == ($past(b[1]) ^ $past(a[0])))
    );

// A non-extended add without low-14 overflow leaves b_msb unchanged.
    check_b_msb_hold_without_low14_carry: assert property (
        @(posedge clk) ((!a_msb) && (({1'b0, b[14:1]} + {8'h00, a}) < 15'h4000)) |=> (b_msb == $past(b_msb))
    );

endmodule

rtl:
module shift_register (
    input CLK,
    input LOAD,
    input SHIFT,
    input [3:0] DATA_IN,
    output [3:0] DATA_OUT
);

reg [3:0] shift_reg;

always @(posedge CLK) begin
    if (LOAD) begin
        shift_reg <= DATA_IN;
    end else if (SHIFT) begin
        shift_reg <= {shift_reg[2:0], shift_reg[3]};
    end
end

assign DATA_OUT = shift_reg;

endmodule

sva:
module shift_register_sva (
    input logic       CLK,
    input logic       LOAD,
    input logic       SHIFT,
    input logic [3:0] DATA_IN,
    input logic [3:0] DATA_OUT
);

// LOAD captures DATA_IN into the register on the next cycle.
    check_load_captures_data: assert property (
        @(posedge CLK)
        LOAD |=> (DATA_OUT == $past(DATA_IN))
    );

// SHIFT rotates the stored value left when LOAD is low.
    check_shift_rotates_data: assert property (
        @(posedge CLK)
        (!LOAD && SHIFT) |=> (DATA_OUT == {$past(DATA_OUT[2:0]), $past(DATA_OUT[3])})
    );

// The register holds its value when neither control is asserted.
    check_hold_without_control: assert property (
        @(posedge CLK)
        (!LOAD && !SHIFT) |=> (DATA_OUT == $past(DATA_OUT))
    );

// LOAD takes priority over SHIFT when both are asserted.
    check_load_priority_over_shift: assert property (
        @(posedge CLK)
        (LOAD && SHIFT) |=> (DATA_OUT == $past(DATA_IN))
    );

endmodule

