module sky130_fd_sc_hdll__and3b (
    X  ,
    A_N,
    B  ,
    C
);

    output X  ;
    input  A_N;
    input  B  ;
    input  C  ;

    wire not0_out  ;
    wire and0_out_X;

    not not0 (not0_out  , A_N            );
    and and0 (and0_out_X, C, not0_out, B );
    buf buf0 (X         , and0_out_X     );

endmodule

sva:
module sky130_fd_sc_hdll__and3b_sva (
    input logic clk,
    input logic X,
    input logic A_N,
    input logic B,
    input logic C
);

// X matches the implemented function ~A_N & B & C.
    check_x_function: assert property (
        @(posedge clk) X == ((~A_N) & B & C)
    );

// A high X requires all effective AND terms to be high.
    check_x_high_implies_inputs: assert property (
        @(posedge clk) X |-> ((!A_N) && B && C)
    );

// When all effective AND terms are high, X must be high.
    check_inputs_imply_x_high: assert property (
        @(posedge clk) ((!A_N) && B && C) |-> X
    );

// A_N high forces X low because A_N is inverted internally.
    check_an_high_forces_x_low: assert property (
        @(posedge clk) A_N |-> !X
    );

// B low forces X low.
    check_b_low_forces_x_low: assert property (
        @(posedge clk) !B |-> !X
    );

// C low forces X low.
    check_c_low_forces_x_low: assert property (
        @(posedge clk) !C |-> !X
    );

endmodule

module twos_complement_sva (
    input logic clk,
    input logic rst_n,
    input logic en,
    input logic [3:0] in,
    input logic [3:0] out
);

// While reset is asserted, the output is cleared.
    check_reset_clears_out: assert property (
        @(posedge clk) !rst_n |-> (out == 4'b0000)
    );

// Two's complement of zero remains zero when enabled.
    check_zero_maps_to_zero: assert property (
        @(posedge clk) disable iff (!rst_n)
        ($past(rst_n) && $past(en) && ($past(in) == 4'b0000)) |-> (out == 4'b0000)
    );

endmodule

rtl:
module pipelined_JC_counter(
  input                clk,
  input                rst_n,
  output reg  [3:0]    Q
);

  reg [63:0] shift_reg;
  wire [3:0] feedback;

  assign feedback = {shift_reg[0], shift_reg[15], shift_reg[30], shift_reg[45]};

  always @(posedge clk) begin
    if (!rst_n) begin
      shift_reg <= 64'h0000000000000000;
      Q <= 4'b0000;
    end else begin
      shift_reg <= {shift_reg[62:0], feedback};
      Q <= shift_reg[63:60];
    end
  end

endmodule

sva:
module pipelined_JC_counter_sva (
    input logic        clk,
    input logic        rst_n,
    input logic [3:0]  Q,
    input logic [63:0] shift_reg,
    input logic [3:0]  feedback
);

// Active-low reset clears the state and derived feedback by the next cycle.
    check_reset_clears_state: assert property (
        @(posedge clk)
        !rst_n |=> (shift_reg == 64'h0000000000000000) &&
                   (Q == 4'h0) &&
                   (feedback == 4'h0)
    );

endmodule

