rtl:
module mux_adder (
    input [2:0] sel,
    input [3:0] data0,
    input [3:0] data1,
    input [3:0] data2,
    input [3:0] data3,
    input [3:0] data4,
    input [3:0] data5,
    input [1:0] add_in,
    input clk,
    input reset,
    input select,
    output reg [7:0] out
);

reg [3:0] mux_out;
reg [1:0] add_out;

always @ (sel or data0 or data1 or data2 or data3 or data4 or data5) begin
    case (sel)
        3'b000: mux_out = data0;
        3'b001: mux_out = data1;
        3'b010: mux_out = data2;
        3'b011: mux_out = data3;
        3'b100: mux_out = data4;
        3'b101: mux_out = data5;
        default: mux_out = 4'b0;
    endcase
end

always @ (add_in or select) begin
    if (select == 1'b0) begin
        add_out = 2'b0;
    end else begin
        add_out = add_in;
    end
end

always @ (posedge clk or posedge reset) begin
    if (reset) begin
        out <= 8'b0;
    end else begin
        if (select == 1'b0) begin
            out <= mux_out;
        end else begin
            out <= {2'b0, mux_out} + {2'b0, add_out};
        end
    end
end

endmodule

sva:
module mux_adder_sva (
    input logic [2:0] sel,
    input logic [3:0] data0,
    input logic [3:0] data1,
    input logic [3:0] data2,
    input logic [3:0] data3,
    input logic [3:0] data4,
    input logic [3:0] data5,
    input logic [1:0] add_in,
    input logic clk,
    input logic reset,
    input logic select,
    input logic [7:0] out
);

// Reset forces the registered output low.
    check_reset_clears_out: assert property (
        @(posedge clk) reset |-> (out == 8'b00000000)
    );

// In bypass mode, out captures the zero-extended muxed data.
    check_bypass_mode_output: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |=> (
            out == {
                4'b0000,
                selected_data(
                    $past(sel),
                    $past(data0),
                    $past(data1),
                    $past(data2),
                    $past(data3),
                    $past(data4),
                    $past(data5)
                )
            }
        )
    );

// In add mode, out captures the muxed data plus add_in.
    check_add_mode_output: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |=> (
            out == (
                {
                    4'b0000,
                    selected_data(
                        $past(sel),
                        $past(data0),
                        $past(data1),
                        $past(data2),
                        $past(data3),
                        $past(data4),
                        $past(data5)
                    )
                } + {6'b000000, $past(add_in)}
            )
        )
    );

// Bypass mode always zero-extends into the upper nibble.
    check_bypass_zero_extension: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b0) |=> (out[7:4] == 4'b0000)
    );

// Add mode always zero-extends into the upper two bits.
    check_add_mode_zero_extension: assert property (
        @(posedge clk) disable iff (reset)
        (select == 1'b1) |=> (out[7:6] == 2'b00)
    );

// Invalid mux select codes produce zero in bypass mode.
    check_invalid_sel_bypass_zero: assert property (
        @(posedge clk) disable iff (reset)
        ((select == 1'b0) && ((sel == 3'b110) || (sel == 3'b111))) |=> (out == 8'b00000000)
    );

// Invalid mux select codes add only add_in in add mode.
    check_invalid_sel_add_uses_add_in_only: assert property (
        @(posedge clk) disable iff (reset)
        ((select == 1'b1) && ((sel == 3'b110) || (sel == 3'b111))) |=> (out == {6'b000000, $past(add_in)})
    );

endmodule

module karnaugh_map_5_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic F
);

// AB=00 drives F with the parity of C, D, and E.
    check_ab00_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b0) && (B == 1'b0)) |-> (F === (C ^ D ^ E))
    );

// AB=01 drives F with the inverted parity of C, D, and E.
    check_ab01_inverted_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b0) && (B == 1'b1)) |-> (F === ~(C ^ D ^ E))
    );

// AB=10 drives F with the parity of C, D, and E.
    check_ab10_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b1) && (B == 1'b0)) |-> (F === (C ^ D ^ E))
    );

// AB=11 drives F with the inverted parity of C, D, and E.
    check_ab11_inverted_parity: assert property (
        @(posedge clk)
        (!$isunknown({A,B,C,D,E}) && (A == 1'b1) && (B == 1'b1)) |-> (F === ~(C ^ D ^ E))
    );

// Overall, F reduces to B xor C xor D xor E.
    check_overall_xor_function: assert property (
        @(posedge clk)
        !$isunknown({A,B,C,D,E}) |-> (F === (B ^ C ^ D ^ E))
    );

endmodule

