module light_ctrl(
    output X,
    input A1,
    input A2,
    input A3,
    input B1
);

    wire or0_out;
    wire or1_out;
    wire or2_out;
    wire and0_out;
    wire and1_out;
    wire and2_out;
    wire and3_out;

