    check_statusb_zone_encoding: assert property (
        @(posedge clk) disable iff (1'b0)
        (!ctrl1_zone && !ctrl2_zone && statusb_zone) |->
            (m68k_data == {system_mode, nwp, ncd2, ncd1, p2_in[9:8], p1_in[9:8]})
    );

