module full_adder(
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    wire s1, s2, s3;

    // XOR gates for sum
    xor (s1, a, b);
    xor (sum, s1, cin);

    // AND gates for carry-out
    and (s2, a, b);
    and (s3, s1, cin);
    or (cout, s2, s3);

endmodule

