        Y == ((A1 & A2 & ~A3) | (B1 & ~C1) | (~C1 & (A1 ~^ A2)))
    );

// When C1 is high, only the A1/A2/A3 term can drive Y.
    check_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        C1 |-> (Y == (A1 & A2 & ~A3))
    );

// When C1 is low, Y reduces to B1 OR equality of A1 and A2.
    check_y_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        !C1 |-> (Y == (B1 | (A1 ~^ A2)))
    );

// The explicit A1&A2&~A3 term always forces Y high.
    check_a_term_drives_y: assert property (
        @(posedge clk) disable iff (1'b0)
        (A1 & A2 & ~A3) |-> Y
    );

// When C1 is low and A1 equals A2, the S5 path forces Y high.
    check_equal_a_inputs_drive_y_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!C1 && (A1 ~^ A2)) |-> Y
    );

// When C1 is low, B1 is low, and A1 differs from A2, Y must be low.
    check_unequal_a_inputs_need_b1_when_c1_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!C1 && !B1 && (A1 ^ A2)) |-> !Y
    );

// With C1 high, A3 high blocks the A1&A2 term.
    check_a3_blocks_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C1 && A1 && A2 && A3) |-> !Y
    );

// With C1 high, A3 low enables the A1&A2 term.
    check_a3_enables_y_when_c1_high: assert property (
        @(posedge clk) disable iff (1'b0)
        (C1 && A1 && A2 && !A3) |-> Y
    );

endmodule

rtl:
module my_module (
    input A,
    input B,
    input C,
    input D,
    input E,
    output Z
);

    // Module ports
    wire Y;
    wire AB_AND;
    wire CD_AND;
    wire AB_OR_CD_AND_E;

    // Module supplies
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Instances
    and and0 (AB_AND, A, B);
    and and1 (CD_AND, C, D);
    or or0 (AB_OR_CD_AND_E, AB_AND, CD_AND, E);
    buf buf0 (Z, AB_OR_CD_AND_E);

endmodule

sva:
module my_module_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic C,
    input logic D,
    input logic E,
    input logic Z
);

// Z implements (A&B) | (C&D) | E.
    check_output_function: assert property (
        @(posedge clk) Z == ((A & B) | (C & D) | E)
    );

// E high must force Z high.
    check_e_term_drives_z: assert property (
        @(posedge clk) E |-> Z
    );

// A and B high must force Z high.
    check_ab_term_drives_z: assert property (
        @(posedge clk) (A & B) |-> Z
    );

// C and D high must force Z high.
    check_cd_term_drives_z: assert property (
        @(posedge clk) (C & D) |-> Z
    );

// If all three OR terms are low, Z must be low.
    check_no_active_term_means_z_low: assert property (
        @(posedge clk) (!(A & B) && !(C & D) && !E) |-> !Z
    );

// If Z is low, none of the three OR terms can be high.
    check_z_low_implies_no_active_term: assert property (
        @(posedge clk) !Z |-> (!(A & B) && !(C & D) && !E)
    );

endmodule

rtl:
module accumulator (
  input clk, // clock signal
  input [15:0] data, // input data signal
  output [15:0] acc // accumulated value
);

  // Define a register to store the accumulated value
  reg [15:0] acc_reg;

  // Reset the accumulator to zero on power up or when a reset signal is received
  initial begin
    acc_reg <= 16'd0;
  end

  // On the rising edge of the clock signal, add the input data value to the previous accumulated value
  always @(posedge clk) begin
    acc_reg <= acc_reg + data;
  end

  // Assign the accumulated value to the output
  assign acc = acc_reg;

endmodule

sva:
module accumulator_assertions (
    input logic        clk,
    input logic [15:0] data,
    input logic [15:0] acc
);

// Clock: clk
    // Reset: none
    // Sequential accumulator with registered output

    // The accumulator adds the previous cycle's data on each rising clock edge.
    check_accumulates_data: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> acc == ($past(acc) + $past(data))
    );

// The cycle-to-cycle change in acc matches the previous cycle's data.
    check_cycle_delta_matches_data: assert property (
        @(posedge clk) disable iff (1'b0)
        1'b1 |=> (acc - $past(acc)) == $past(data)
    );

// A zero input leaves the accumulator unchanged on the next cycle.
    check_hold_on_zero_data: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'd0 |=> acc == $past(acc)
    );

// An input of one increments the accumulator by one on the next cycle.
    check_increment_on_one: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'd1 |=> acc == ($past(acc) + 16'd1)
    );

// If the accumulator is zero, the next value equals the current input data.
    check_load_data_from_zero: assert property (
        @(posedge clk) disable iff (1'b0)
        acc == 16'd0 |=> acc == $past(data)
    );

// Adding one to 16'hFFFF wraps the accumulator to zero.
    check_wrap_on_full_plus_one: assert property (
        @(posedge clk) disable iff (1'b0)
        (acc == 16'hFFFF) && (data == 16'd1) |=> acc == 16'd0
    );

// An input of 16'hFFFF decrements the accumulator by one on the next cycle.
    check_decrement_on_all_ones_data: assert property (
        @(posedge clk) disable iff (1'b0)
        data == 16'hFFFF |=> acc == ($past(acc) - 16'd1)
    );

endmodule

rtl:
module binary_converter (
    input [3:0] D,
    output [2:0] Q
);

    wire [1:0] subtract;

    assign subtract = D[3:2] - 2'b11;

    assign Q = (D <= 4'b0111) ? D[2:0] : subtract;

endmodule

sva:
module binary_converter_sva (
    input logic        clk,
    input logic [3:0]  D,
    input logic [2:0]  Q
);

// Q must follow the RTL's full combinational mapping.
    check_full_mapping: assert property (
        @(posedge clk)
        Q == ((D[3] == 1'b0) ? D[2:0] : {1'b0, (D[3:2] - 2'b11)})
    );

// Inputs 0 through 7 pass D[2:0] directly to Q.
    check_low_range_passthrough: assert property (
        @(posedge clk)
        (D[3] == 1'b0) |-> (Q == D[2:0])
    );

// Inputs 8 through 15 use the subtract result, zero-extended to 3 bits.
    check_high_range_conversion: assert property (
        @(posedge clk)
        (D[3] == 1'b1) |-> (Q == {1'b0, (D[3:2] - 2'b11)})
    );

// For inputs 8 through 11, Q must be 3.
    check_range_8_to_11_value: assert property (
        @(posedge clk)
        (D[3:2] == 2'b10) |-> (Q == 3'b011)
    );

// For inputs 12 through 15, Q must be 0.
    check_range_12_to_15_value: assert property (
        @(posedge clk)
        (D[3:2] == 2'b11) |-> (Q == 3'b000)
    );

// The upper bit of Q is cleared whenever the subtract path is selected.
    check_high_range_msb_zero: assert property (
        @(posedge clk)
        (D[3] == 1'b1) |-> (Q[2] == 1'b0)
    );

endmodule

rtl:
module shift_register_combination (
    input CLK,
    input PL1,
    input CLR1,
    input PL2,
    input EN2,
    input [3:0] D1,
    input [3:0] D2,
    output [7:0] Q
);

reg [3:0] reg1;
reg [3:0] reg2;

always @(posedge CLK) begin
    if (CLR1) 
        reg1 <= 4'b0;
    else if (PL1) 
        reg1 <= D1;
    else 
        reg1 <= {reg1[2:0], reg1[3]};
end

always @(negedge CLK) begin
    if (EN2) 
        reg2 <= {reg2[2:0], D2};
end

assign Q = {reg1, reg2};

endmodule

sva:
module shift_register_combination_sva (
    input logic CLK,
    input logic PL1,
    input logic CLR1,
    input logic PL2,
    input logic EN2,
    input logic [3:0] D1,
    input logic [3:0] D2,
    input logic [7:0] Q
);

// CLR1 clears the upper nibble on the next posedge sample.
    check_reg1_clear: assert property (
        @(posedge CLK) disable iff (1'b0)
        CLR1 |=> (Q[7:4] == 4'b0000)
    );

// CLR1 has priority over PL1 when both are asserted.
    check_reg1_clear_priority: assert property (
        @(posedge CLK) disable iff (1'b0)
        (CLR1 && PL1) |=> (Q[7:4] == 4'b0000)
    );

// PL1 loads D1 into the upper nibble when CLR1 is low.
    check_reg1_parallel_load: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR1 && PL1) |=> (Q[7:4] == $past(D1))
    );

// Without CLR1 or PL1, the upper nibble rotates left by one bit.
    check_reg1_rotate: assert property (
        @(posedge CLK) disable iff (1'b0)
        (!CLR1 && !PL1) |=> (Q[7:4] == {$past(Q[6:4]), $past(Q[7])})
    );

// EN2 loads the lower nibble with D2 on the next negedge sample.
    check_reg2_load_d2: assert property (
        @(negedge CLK) disable iff (1'b0)
        EN2 |=> (Q[3:0] == $past(D2))
    );

// Without EN2, the lower nibble holds its value across negedges.
    check_reg2_hold: assert property (
        @(negedge CLK) disable iff (1'b0)
        (!EN2) |=> (Q[3:0] == $past(Q[3:0]))
    );

endmodule

module binary_adder_sva(
    input logic [3:0] A,
    input logic [3:0] B,
    input logic control,
    input logic [3:0] C,
    input logic clk
);

// In add mode, C equals the 4-bit sum of A and B.
    check_add_mode_result: assert property (
        @(posedge clk) (control == 1'b0) |-> (C == (A + B))
    );

// In subtract mode, C equals the 4-bit difference of A and B.
    check_sub_mode_result: assert property (
        @(posedge clk) (control == 1'b1) |-> (C == (A - B))
    );

endmodule

rtl:
module address_decoder(
    input [14:0] address,
    input clock,
    output reg [11:0] q
);

always @(posedge clock) begin
    if(address < 15'h0800) begin
        q <= 12'h000;
    end else if(address < 15'h1000) begin
        q <= address[11:0];
    end else begin
        q <= address[14:3];
    end
end

endmodule

sva:
module address_decoder_assertions(
    input logic [14:0] address,
    input logic        clock,
    input logic [11:0] q
);

// Addresses below 0x0800 decode to zero on the next clock.
    check_low_range_zero: assert property (
        @(posedge clock)
        (address < 15'h0800) |=> (q == 12'h000)
    );

// Addresses 0x0800 through 0x0FFF pass through the low 12 bits on the next clock.
    check_mid_range_passthrough: assert property (
        @(posedge clock)
        (address >= 15'h0800 && address < 15'h1000) |=> (q == $past(address[11:0]))
    );

// Addresses 0x1000 and above decode to address[14:3] on the next clock.
    check_high_range_slice: assert property (
        @(posedge clock)
        (address >= 15'h1000) |=> (q == $past(address[14:3]))
    );

// 0x07FF is still in the zero-decoded range.
    check_boundary_07ff: assert property (
        @(posedge clock)
        (address == 15'h07FF) |=> (q == 12'h000)
    );

// 0x0800 is the first address that passes through its low 12 bits.
    check_boundary_0800: assert property (
        @(posedge clock)
        (address == 15'h0800) |=> (q == 12'h800)
    );

// 0x0FFF is the last address in the pass-through range.
    check_boundary_0fff: assert property (
        @(posedge clock)
        (address == 15'h0FFF) |=> (q == 12'hFFF)
    );

// 0x1000 is the first address that uses address[14:3].
    check_boundary_1000: assert property (
        @(posedge clock)
        (address == 15'h1000) |=> (q == 12'h200)
    );

// 0x7FFF maps to the maximum sliced output value.
    check_boundary_7fff: assert property (
        @(posedge clock)
        (address == 15'h7FFF) |=> (q == 12'hFFF)
    );

endmodule

rtl:
module sync_dff_en_W32 (clk, en, te, d, q);

  input clk, en, te;
  input [31:0] d;
  output reg [31:0] q;

  always @(posedge clk) begin
    if (en) begin
      if (te) begin
        q <= d;
      end else begin
        q <= #1 d;
      end
    end
  end

endmodule

sva:
module sync_dff_en_W32_sva (
    input logic        clk,
    input logic        en,
    input logic        te,
    input logic [31:0] d,
    input logic [31:0] q
);

// When enabled in test mode, q captures d by the next clock.
    check_capture_te_branch: assert property (
        @(posedge clk) (en && te) |=> (q == $past(d))
    );

// When enabled in normal mode, q captures d by the next clock.
    check_capture_normal_branch: assert property (
        @(posedge clk) (en && !te) |=> (q == $past(d))
    );

// When disabled with te high, q holds its value.
    check_hold_disabled_te_high: assert property (
        @(posedge clk) (!en && te) |=> (q == $past(q))
    );

// When disabled with te low, q holds its value.
    check_hold_disabled_te_low: assert property (
        @(posedge clk) (!en && !te) |=> (q == $past(q))
    );

// If enabled and d differs from q, q updates to the new value on the next clock.
    check_update_when_enabled_and_data_differs: assert property (
        @(posedge clk) (en && (d != q)) |=> ((q == $past(d)) && (q != $past(q)))
    );

endmodule

rtl:
module PIO_TO_CTRL    (

                        clk,
                        rst_n,

                        req_compl_i,
                        compl_done_i,

                        cfg_to_turnoff,
                        cfg_turnoff_ok

                        );

    input               clk;
    input               rst_n;

    input               req_compl_i;
    input               compl_done_i;

    input               cfg_to_turnoff;
    output              cfg_turnoff_ok;

    reg                 trn_pending;
    reg                 cfg_turnoff_ok;


   //  *  Check if completion is pending

    always @ ( posedge clk or negedge rst_n ) begin

        if (!rst_n ) begin

          trn_pending <= 0;

        end else begin

          if (!trn_pending && req_compl_i)

            trn_pending <= 1'b1;

          else if (compl_done_i)

            trn_pending <= 1'b0;

        end

    end

    // *  Turn-off OK if requested and no transaction is pending

     always @ ( posedge clk or negedge rst_n ) begin

      if (!rst_n ) begin

        cfg_turnoff_ok <= 1'b0;

      end else begin

        if ( cfg_to_turnoff  && !trn_pending)
          cfg_turnoff_ok <= 1'b1;
        else
          cfg_turnoff_ok <= 1'b0;

      end

    end


endmodule

sva:
module PIO_TO_CTRL_sva (
    input logic clk,
    input logic rst_n,
    input logic req_compl_i,
    input logic compl_done_i,
    input logic cfg_to_turnoff,
    input logic cfg_turnoff_ok,
    input logic trn_pending
);

// trn_pending is cleared while reset is active.
    check_trn_pending_reset: assert property (
        @(posedge clk) !rst_n |-> (trn_pending == 1'b0)
    );

// cfg_turnoff_ok is cleared while reset is active.
    check_cfg_turnoff_ok_reset: assert property (
        @(posedge clk) !rst_n |-> (cfg_turnoff_ok == 1'b0)
    );

// Without a turnoff request, cfg_turnoff_ok is low on the next cycle.
    check_turnoff_ok_low_without_request: assert property (
        @(posedge clk) disable iff (!rst_n)
        (!cfg_to_turnoff) |=> (cfg_turnoff_ok == 1'b0)
    );

endmodule

rtl:
module consecutive_zeros_counter (
    input [15:0] in,
    output reg [3:0] out
);

reg [3:0] stage1_out;
reg [15:0] stage2_out;
reg [3:0] stage3_out;

// Stage 1: Fetch input
always @(*) begin
    stage1_out = in[15:12];
end

// Stage 2: Split input into nibbles
always @(*) begin
    stage2_out[15:12] = in[11:8];
    stage2_out[11:8] = in[7:4];
    stage2_out[7:4] = in[3:0];
    stage2_out[3:0] = 4'b0;
end

// Stage 3: Detect consecutive 0's in each nibble
always @(*) begin
    stage3_out = 4'b0;
    if (stage2_out[15:12] == 4'b0000) stage3_out = stage3_out + 1;
    if (stage2_out[11:8] == 4'b0000) stage3_out = stage3_out + 1;
    if (stage2_out[7:4] == 4'b0000) stage3_out = stage3_out + 1;
    if (stage2_out[3:0] == 4'b0000) stage3_out = stage3_out + 1;
end

// Stage 4: Output total number of consecutive 0's found in input
always @(*) begin
    out <= stage1_out + stage3_out;
end

endmodule

sva:
module consecutive_zeros_counter_sva (
    input logic clk,
    input logic [15:0] in,
    input logic [3:0] out,
    input logic [3:0] stage1_out,
    input logic [15:0] stage2_out,
    input logic [3:0] stage3_out
);

// The output matches the full input-derived expression.
    check_out_end_to_end: assert property (
        @(posedge clk) out == (in[15:12] + expected_stage3_from_in(in))
    );

endmodule

rtl:
module lfsr_3bit (
    input CLK,
    output reg Q0,
    output reg Q1,
    output reg Q2
);

reg [2:0] lfsr_reg;

always @(posedge CLK) begin
    lfsr_reg <= {lfsr_reg[1:0], lfsr_reg[2] ^ lfsr_reg[1]};
end

always @* begin
    Q0 = lfsr_reg[0];
    Q1 = lfsr_reg[1];
    Q2 = lfsr_reg[2];
end

endmodule

sva:
module lfsr_3bit_sva (
    input logic CLK,
    input logic Q0,
    input logic Q1,
    input logic Q2
);

// Q2 shifts in the previous Q1 value.
    check_q2_shift: assert property (
        @(posedge CLK) 1'b1 |=> (Q2 == $past(Q1))
    );

// Q1 shifts in the previous Q0 value.
    check_q1_shift: assert property (
        @(posedge CLK) 1'b1 |=> (Q1 == $past(Q0))
    );

// Q0 is the XOR of the previous Q2 and Q1 values.
    check_q0_feedback: assert property (
        @(posedge CLK) 1'b1 |=> (Q0 == ($past(Q2) ^ $past(Q1)))
    );

// The full 3-bit output state follows the RTL next-state function.
    check_state_update: assert property (
        @(posedge CLK) 1'b1 |=> ({Q2, Q1, Q0} == {$past(Q1), $past(Q0), ($past(Q2) ^ $past(Q1))})
    );

// Equal previous Q2 and Q1 drive Q0 low on the next cycle.
    check_feedback_zero_case: assert property (
        @(posedge CLK) (Q2 == Q1) |=> (Q0 == 1'b0)
    );

// Different previous Q2 and Q1 drive Q0 high on the next cycle.
    check_feedback_one_case: assert property (
        @(posedge CLK) (Q2 != Q1) |=> (Q0 == 1'b1)
    );

// The all-zero state remains all-zero on the next cycle.
    check_zero_lockup: assert property (
        @(posedge CLK) ({Q2, Q1, Q0} == 3'b000) |=> ({Q2, Q1, Q0} == 3'b000)
    );

endmodule

rtl:
module mux_2to1(
    input A,
    input B,
    input S,
    output Y
);

assign Y = (~S & A) | (S & B);

endmodule

sva:
module mux_2to1_sva (
    input logic clk,
    input logic A,
    input logic B,
    input logic S,
    input logic Y
);

// Y must implement the 2:1 mux equation.
    check_mux_equation: assert property (
        @(posedge clk) Y == ((~S & A) | (S & B))
    );

// When S is low, Y must select A.
    check_select_a: assert property (
        @(posedge clk) !S |-> (Y == A)
    );

// When S is high, Y must select B.
    check_select_b: assert property (
        @(posedge clk) S |-> (Y == B)
    );

// If both inputs are equal, Y must match that value.
    check_equal_inputs: assert property (
        @(posedge clk) (A == B) |-> (Y == A)
    );

// With A=0 and B=1, Y must follow S.
    check_follow_s: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b1) |-> (Y == S)
    );

// With A=1 and B=0, Y must follow inverted S.
    check_follow_not_s: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b0) |-> (Y == ~S)
    );

endmodule

rtl:
module reg_shifter(
	input [31:0] rt_out,
	input [1:0] mem_addr_in,
	input MemWrite,
	input [5:0] IR_out,
	output reg [31:0] rt_out_shift,
	output reg [3:0] mem_byte_write_out
);

	reg [3:0] mem_byte_write;

	always @ (*)
	begin
		case (IR_out)
			6'b101011: begin 
						rt_out_shift = rt_out;
						mem_byte_write = 4'b1111;
					  end
			default: begin
						case (mem_addr_in)
							2'b00: begin 
									rt_out_shift = {rt_out[7:0],  24'b0};
									mem_byte_write = 4'b1000;
								   end
							2'b01: begin 
									rt_out_shift = {rt_out[15:0], 16'b0};
									mem_byte_write = 4'b1100;
								   end
							2'b10: begin 
									rt_out_shift = {rt_out[23:0], 8'b0};
									mem_byte_write = 4'b1110;
								   end
							2'b11: begin 
									rt_out_shift = rt_out;
									mem_byte_write = 4'b1111;
								   end
						endcase
					  end
		endcase
		mem_byte_write_out = mem_byte_write & {4{MemWrite}};
	end

endmodule

sva:
module reg_shifter_sva(
    input logic        clk,
    input logic [31:0] rt_out,
    input logic [1:0]  mem_addr_in,
    input logic        MemWrite,
    input logic [5:0]  IR_out,
    input logic [31:0] rt_out_shift,
    input logic [3:0]  mem_byte_write_out
);

// MemWrite low suppresses all byte write enables.
    check_memwrite_masks_all_bytes: assert property (
        @(posedge clk) !MemWrite |-> (mem_byte_write_out == 4'b0000)
    );

// Store-word opcode passes rt_out through unchanged.
    check_sw_shift_passthrough: assert property (
        @(posedge clk) (IR_out == 6'b101011) |-> (rt_out_shift == rt_out)
    );

// Store-word opcode enables all byte lanes when writing.
    check_sw_full_byte_enable: assert property (
        @(posedge clk) (IR_out == 6'b101011 && MemWrite) |-> (mem_byte_write_out == 4'b1111)
    );

// Non-store-word at address 00 moves the low byte into the top byte lane.
    check_addr00_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b00) |-> (rt_out_shift == {rt_out[7:0], 24'b0})
    );

// Non-store-word at address 00 enables only the top byte lane when writing.
    check_addr00_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b00 && MemWrite) |-> (mem_byte_write_out == 4'b1000)
    );

// Non-store-word at address 01 moves the low halfword into the top halfword lanes.
    check_addr01_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b01) |-> (rt_out_shift == {rt_out[15:0], 16'b0})
    );

// Non-store-word at address 01 enables the upper two byte lanes when writing.
    check_addr01_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b01 && MemWrite) |-> (mem_byte_write_out == 4'b1100)
    );

// Non-store-word at address 10 moves the low 24 bits into the upper three byte lanes.
    check_addr10_shift: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b10) |-> (rt_out_shift == {rt_out[23:0], 8'b0})
    );

// Non-store-word at address 10 enables the upper three byte lanes when writing.
    check_addr10_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b10 && MemWrite) |-> (mem_byte_write_out == 4'b1110)
    );

// Non-store-word at address 11 passes rt_out through unchanged.
    check_addr11_shift_passthrough: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b11) |-> (rt_out_shift == rt_out)
    );

// Non-store-word at address 11 enables all byte lanes when writing.
    check_addr11_full_byte_enable: assert property (
        @(posedge clk) (IR_out != 6'b101011 && mem_addr_in == 2'b11 && MemWrite) |-> (mem_byte_write_out == 4'b1111)
    );

endmodule

