module signal_converter (
    Y,
    VOUT,
    VREF,
    A1,
    A2,
    B1,
    B2,
    VPWR,
    VGND,
    VPB,
    VNB
);

    output reg [1:0] Y;
    output reg VOUT;
    output reg VREF;
    input A1;
    input A2;
    input B1;
    input B2;
    input VPWR;
    input VGND;
    input VPB;
    input VNB;

    always @* begin
        case ({A1, A2, B1, B2})
            4'b0000: Y = 2'b00;
            4'b0001: Y = 2'b01;
            4'b0010: Y = 2'b10;
            4'b0011: Y = 2'b11;
            4'b0100: Y = 2'b00;
            4'b0101: Y = 2'b01;
            4'b0110: Y = 2'b10;
            4'b0111: Y = 2'b11;
            4'b1000: Y = 2'b00;
            4'b1001: Y = 2'b01;
            4'b1010: Y = 2'b10;
            4'b1011: Y = 2'b11;
            4'b1100: Y = 2'b00;
            4'b1101: Y = 2'b01;
            4'b1110: Y = 2'b10;
            4'b1111: Y = 2'b11;
        endcase
    end

    always @* begin
        if (Y % 2 == 0)
            VOUT = VPWR;
        else
            VOUT = VGND;
    end

    always @* begin
        if (Y < 2)
            VREF = VPB;
        else
            VREF = VNB;
    end

endmodule

sva:
module signal_converter_sva (
    input logic clk,
    input logic [1:0] Y,
    input logic VOUT,
    input logic VREF,
    input logic A1,
    input logic A2,
    input logic B1,
    input logic B2,
    input logic VPWR,
    input logic VGND,
    input logic VPB,
    input logic VNB
);

// Y ignores A1/A2 and matches the B inputs.
    check_y_matches_b_inputs: assert property (
        @(posedge clk) Y == {B1, B2}
    );

// VOUT selects VPWR for even Y and VGND for odd Y.
    check_vout_follows_y_lsb: assert property (
        @(posedge clk) VOUT == (Y[0] ? VGND : VPWR)
    );

// VREF selects VPB for Y below 2 and VNB otherwise.
    check_vref_follows_y_msb: assert property (
        @(posedge clk) VREF == (Y[1] ? VNB : VPB)
    );

// VOUT is ultimately controlled by B2 through Y.
    check_vout_matches_b2: assert property (
        @(posedge clk) VOUT == (B2 ? VGND : VPWR)
    );

// VREF is ultimately controlled by B1 through Y.
    check_vref_matches_b1: assert property (
        @(posedge clk) VREF == (B1 ? VNB : VPB)
    );

endmodule

