    input  S ;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    // Implementation of 2:1 multiplexer
    assign X = (S == 0) ? A0 : A1;

endmodule

sva:
module mux2_sva (
    input logic clk,
    input logic X,
    input logic A0,
    input logic A1,
