rtl:
module binary_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] S,
    output Cout
);

    wire [3:0] adder_output;
    wire [3:0] carry_out;

    // 4-bit binary adder with carry-in and carry-out functionality
    // This adder is implemented using four full adders
    full_adder FA0(.A(A[0]), .B(B[0]), .Cin(Cin), .S(adder_output[0]), .Cout(carry_out[0]));
    full_adder FA1(.A(A[1]), .B(B[1]), .Cin(carry_out[0]), .S(adder_output[1]), .Cout(carry_out[1]));
    full_adder FA2(.A(A[2]), .B(B[2]), .Cin(carry_out[1]), .S(adder_output[2]), .Cout(carry_out[2]));
    full_adder FA3(.A(A[3]), .B(B[3]), .Cin(carry_out[2]), .S(adder_output[3]), .Cout(Cout));

    assign S = adder_output;

endmodule

module full_adder(
    input A,
    input B,
    input Cin,
    output S,
    output Cout
);

    // XOR gate for sum output
    assign S = A ^ B ^ Cin;

    // AND gate for carry output
    assign Cout = (A & B) | (A & Cin) | (B & Cin);

endmodule

sva:
module binary_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic       Cin,
    input logic [3:0] S,
    input logic       Cout
);

// Full 5-bit result matches A + B + Cin.
    check_full_result: assert property (
        @(posedge clk) disable iff (1'b0)
        {Cout, S} == ({1'b0, A} + {1'b0, B} + Cin)
    );

// Sum bit 0 matches the full-adder XOR equation.
    check_sum_bit0: assert property (
        @(posedge clk) disable iff (1'b0)
        S[0] == (A[0] ^ B[0] ^ Cin)
    );

// Lower two sum bits match a 2-bit add with carry-in.
    check_lower_two_bits: assert property (
        @(posedge clk) disable iff (1'b0)
        S[1:0] == (A[1:0] + B[1:0] + Cin)
    );

// Lower three sum bits match a 3-bit add with carry-in.
    check_lower_three_bits: assert property (
        @(posedge clk) disable iff (1'b0)
        S[2:0] == (A[2:0] + B[2:0] + Cin)
    );

// Adding zero on B with Cin low passes A through.
    check_add_zero_on_b: assert property (
        @(posedge clk) disable iff (1'b0)
        (B == 4'b0000 && Cin == 1'b0) |-> (S == A && Cout == 1'b0)
    );

// Adding zero on A with Cin low passes B through.
    check_add_zero_on_a: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'b0000 && Cin == 1'b0) |-> (S == B && Cout == 1'b0)
    );

// All-zero inputs produce an all-zero result.
    check_all_zero_inputs: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'b0000 && B == 4'b0000 && Cin == 1'b0) |-> (S == 4'b0000 && Cout == 1'b0)
    );

// Carry-in alone produces a value of one.
    check_cin_only: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'b0000 && B == 4'b0000 && Cin == 1'b1) |-> (S == 4'b0001 && Cout == 1'b0)
    );

// Maximum inputs with carry-in produce 5'h1F.
    check_max_with_cin: assert property (
        @(posedge clk) disable iff (1'b0)
        (A == 4'hF && B == 4'hF && Cin == 1'b1) |-> (S == 4'hF && Cout == 1'b1)
    );

endmodule

rtl:
module Multiplexer_AC__parameterized33
   (ctrl,
    D0,
    D1,
    D2,
    S);
  input ctrl;
  input [0:0]D0;
  input [0:0]D1;
  input [0:0]D2;
  output [0:0]S;

  wire [0:0]S;
  wire [2:0]sel;

  assign sel = {ctrl, ctrl};

  assign S = (sel == 3'b000) ? D0 : 
             (sel == 3'b001) ? D1 : 
             (sel == 3'b010) ? D2 : 0;

endmodule

