sva:
module and_nor_sva (
    input logic clk,
    input logic Y,
    input logic A1,
    input logic A2,
    input logic B1_N
);

// Y matches the implemented gate equation.
    check_y_matches_gate_equation: assert property (
        @(posedge clk) Y == ~(~B1_N | (A1 & A2))
    );

