    check_y_high_requires_not_a1_a2_high: assert property (
        @(posedge clk) Y |-> !(A1 && A2)
    );

// Low Y with high B1_N requires both A inputs high.
    check_y_low_with_b1_n_high_requires_a1_a2_high: assert property (
