module counter(
    input clk,
    input rst,
    output reg [3:0] count
);

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            count <= 0;
        end else begin
            count <= count + 1;
        end
    end

endmodule

sva:
module counter_sva (
    input logic       clk,
    input logic       rst,
    input logic [3:0] count
);

// Reset drives count to zero.
    check_reset_clears_count: assert property (
        @(posedge clk) (!rst) |-> (count == 4'd0)
    );

// When count is below 15, it increments by one on the next clock.
    check_count_increments: assert property (
        @(posedge clk) disable iff (!rst)
        (count != 4'hF) |=> (count == ($past(count) + 4'd1))
    );

// When count reaches 15, it wraps to zero on the next clock.
    check_count_wraps: assert property (
        @(posedge clk) disable iff (!rst)
        (count == 4'hF) |=> (count == 4'h0)
    );

endmodule

rtl:
module data_modifier(
    input [31:0] reg_input,
    input [3:0] address,
    input reg_out_syn,
    input ack,
    input ack_syn,
    output reg [31:0] reg_out
);

reg [31:0] shifted_input;
reg [31:0] reversed_input;
reg [31:0] reg_out_nxt;

always @(*) begin
    if (ack && !ack_syn) begin
        shifted_input = {reg_input[30:0], 1'b0};
        reg_out_nxt     = shifted_input;
    end
    else if (!ack && ack_syn) begin
        shifted_input = {1'b0, reg_input[31:1]};
        reg_out_nxt     = shifted_input;
    end
    else if (ack && ack_syn) begin
        reversed_input = {reg_input[7:0], reg_input[15:8], reg_input[23:16], reg_input[31:24]};
        reg_out_nxt     = reversed_input;
    end
    else begin
        reg_out_nxt = reg_input;
    end
end

wire reg_out_syn_nxt;
assign reg_out_syn_nxt = ack || ack_syn;

reg reg_out_syn_nxt_r;
always @(*) begin
    reg_out_syn_nxt_r = reg_out_syn_nxt;
end

reg reg_out_syn_r;
always @(*) begin
    reg_out_syn_r <= reg_out_syn_nxt_r;
end

assign reg_out_syn = reg_out_syn_r;

always @(*) begin
    reg_out = reg_out_nxt;
end

endmodule

sva:
module data_modifier_sva (
    input logic        clk,
    input logic [31:0] reg_input,
    input logic [3:0]  address,
    input logic        reg_out_syn,
    input logic        ack,
    input logic        ack_syn,
    input logic [31:0] reg_out
);

// Sampled on external clk because the RTL has no clock or reset.

    // ack=1 and ack_syn=0 selects a left shift by one bit.
    check_left_shift: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && ack && !ack_syn
        |-> reg_out == {reg_input[30:0], 1'b0}
    );

// ack=0 and ack_syn=1 selects a right shift by one bit.
    check_right_shift: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && !ack && ack_syn
        |-> reg_out == {1'b0, reg_input[31:1]}
    );

// ack=1 and ack_syn=1 selects the byte-reversed value.
    check_byte_reverse: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && ack && ack_syn
        |-> reg_out == {reg_input[7:0], reg_input[15:8], reg_input[23:16], reg_input[31:24]}
    );

// ack=0 and ack_syn=0 passes reg_input through unchanged.
    check_passthrough: assert property (
        @(posedge clk)
        $stable({reg_input, ack, ack_syn}) && !ack && !ack_syn
        |-> reg_out == reg_input
    );

endmodule

module binary_latch_with_reset_sva(
    input logic CLK,
    input logic RST,
    input logic D,
    input logic Q
