rtl:
module adder_4bit (
  input [3:0] a,
  input [3:0] b,
  input cin,
  output [3:0] sum,
  output cout
);

wire [3:0] c;
assign c[0] = cin;

full_adder fa0(a[0],b[0],c[0],sum[0],c[1]);
full_adder fa1(a[1],b[1],c[1],sum[1],c[2]);
full_adder fa2(a[2],b[2],c[2],sum[2],c[3]);
full_adder fa3(a[3],b[3],c[3],sum[3],cout);

endmodule
module full_adder (
  input a,
  input b,
  input cin,
  output sum,
  output cout
);

wire s1, s2;
assign s1 = a ^ b;
assign s2 = s1 ^ cin;
assign sum = s2;
assign cout = (a & b) | (s1 & cin);

endmodule

sva:
module adder_4bit_sva (
    input logic clk,
    input logic [3:0] a,
    input logic [3:0] b,
    input logic cin,
    input logic [3:0] sum,
    input logic cout
);

// Full 5-bit output matches the arithmetic sum of the inputs.
    check_full_result: assert property (
        @(posedge clk) {cout, sum} == ({1'b0, a} + {1'b0, b} + {4'b0, cin})
    );

// Bit 0 sum is the XOR of a[0], b[0], and cin.
    check_sum_bit0: assert property (
        @(posedge clk) sum[0] == (a[0] ^ b[0] ^ cin)
    );

// Bit 1 sum uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk) sum[1] == (
            a[1] ^ b[1] ^
            ((a[0] & b[0]) | ((a[0] ^ b[0]) & cin))
        )
    );

// Bit 2 sum uses the ripple carry from bits 0 and 1.
    check_sum_bit2: assert property (
        @(posedge clk) sum[2] == (
            a[2] ^ b[2] ^
            (
                (a[1] & b[1]) |
                (
                    (a[1] ^ b[1]) &
                    (
                        (a[0] & b[0]) |
                        ((a[0] ^ b[0]) & cin)
                    )
                )
            )
        )
    );

// Bit 3 sum uses the ripple carry from bits 0 through 2.
    check_sum_bit3: assert property (
        @(posedge clk) sum[3] == (
            a[3] ^ b[3] ^
            (
                (a[2] & b[2]) |
                (
                    (a[2] ^ b[2]) &
                    (
                        (a[1] & b[1]) |
                        (
                            (a[1] ^ b[1]) &
                            (
                                (a[0] & b[0]) |
                                ((a[0] ^ b[0]) & cin)
                            )
                        )
                    )
                )
            )
        )
    );

// Carry out is the final ripple carry from the MSB stage.
    check_carry_out: assert property (
        @(posedge clk) cout == (
            (a[3] & b[3]) |
            (
                (a[3] ^ b[3]) &
                (
                    (a[2] & b[2]) |
                    (
                        (a[2] ^ b[2]) &
                        (
                            (a[1] & b[1]) |
                            (
                                (a[1] ^ b[1]) &
                                (
                                    (a[0] & b[0]) |
                                    ((a[0] ^ b[0]) & cin)
                                )
                            )
                        )
                    )
                )
            )
        )
    );

endmodule

