module soc_system_pio_aliveTest_cpu_s0 (
  // inputs:
  address,
  chipselect,
  clk,
  reset_n,
  write_n,
  writedata,

  // outputs:
  out_port,
  readdata
);

  output  [  1: 0] out_port;
  output  [ 31: 0] readdata;
  input   [  1: 0] address;
  input            chipselect;
  input            clk;
  input            reset_n;
  input            write_n;
  input   [ 31: 0] writedata;

  wire             clk_en;
  reg     [  1: 0] data_out;
  wire    [  1: 0] out_port;
  wire    [  1: 0] read_mux_out;
  wire    [ 31: 0] readdata;
  assign clk_en = 1;

  //s1, which is an e_avalon_slave
  assign read_mux_out = {2 {(address == 0)}} & data_out;

  always @(posedge clk or negedge reset_n) begin
    if (reset_n == 0) begin
      data_out <= 0;
    end else if (chipselect && ~write_n && (address == 0)) begin
      data_out <= writedata[1 : 0];
    end
  end

  assign readdata = {30'b0, read_mux_out};

  assign out_port = data_out;

endmodule

sva:
module soc_system_pio_aliveTest_cpu_s0_sva (
    input logic [1:0]  address,
    input logic        chipselect,
    input logic        clk,
    input logic        reset_n,
    input logic        write_n,
    input logic [31:0] writedata,
    input logic [1:0]  out_port,
    input logic [31:0] readdata
);

// Clock: clk; reset: reset_n active low; mixed sequential/combinational logic.

    // Reset forces the registered output low.
    reset_clears_out_port: assert property (
        @(posedge clk) !reset_n |-> (out_port == 2'b00)
    );

// Reset forces the readback value low.
    reset_clears_readdata: assert property (
        @(posedge clk) !reset_n |-> (readdata == 32'b0)
    );

// Read data is always zero-extended in the upper 30 bits.
    read_upper_bits_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (readdata[31:2] == 30'b0)
    );

// Address 0 returns the current output register value.
    read_addr_zero_returns_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address == 2'b00) |-> (readdata == {30'b0, out_port})
    );

// Nonzero addresses return zero.
    read_nonzero_addr_returns_zero: assert property (
        @(posedge clk) disable iff (!reset_n)
        (address != 2'b00) |-> (readdata == 32'b0)
    );

// A write to address 0 updates the output register with writedata[1:0].
    write_addr_zero_captures_low_bits: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address == 2'b00)) |=> (out_port == $past(writedata[1:0]))
    );

// When not selected, the output register holds its value.
    unselected_cycle_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (!chipselect) |=> (out_port == $past(out_port))
    );

// Read cycles do not modify the output register.
    read_cycle_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && write_n) |=> (out_port == $past(out_port))
    );

// Writes to nonzero addresses do not modify the output register.
    write_nonzero_addr_holds_out_port: assert property (
        @(posedge clk) disable iff (!reset_n)
        (chipselect && !write_n && (address != 2'b00)) |=> (out_port == $past(out_port))
    );

endmodule

rtl:
module bw_io_cmos_edgelogic(
   // Outputs
   to_core, por, pad_up, bsr_up, pad_dn_l, bsr_dn_l,

   // Inputs
   data, oe, bsr_mode, por_l,
   bsr_data_to_core, se, rcvr_data
   );

input		data;
input		oe;
input		bsr_mode;
input		por_l;
input		se;
input		bsr_data_to_core;
input		rcvr_data;
supply0		vss;
output		pad_up;
output		pad_dn_l;
output		bsr_up;
output		bsr_dn_l;
output		por;
output		to_core;


// WIRES
wire pad_up;
wire pad_dn_l;
wire bsr_up;
wire bsr_dn_l;
wire por;
wire to_core;

assign bsr_up   = pad_up;
assign bsr_dn_l = pad_dn_l;
assign por      = ~por_l;
assign pad_up   =  data && oe;
assign pad_dn_l = ~(~data && oe);
assign to_core  = (bsr_mode && !se) ? bsr_data_to_core : rcvr_data;

endmodule

sva:
module bw_io_cmos_edgelogic_sva (
    input logic clk,
    input logic data,
    input logic oe,
    input logic bsr_mode,
    input logic por_l,
    input logic bsr_data_to_core,
    input logic se,
    input logic rcvr_data,
    input logic pad_up,
    input logic pad_dn_l,
    input logic bsr_up,
    input logic bsr_dn_l,
    input logic por,
    input logic to_core
);

// por is the inverse of por_l.
    check_por_inversion: assert property (
        @(posedge clk) disable iff (1'b0) (por == ~por_l)
    );

// pad_up is asserted only when data and oe are both high.
    check_pad_up_function: assert property (
        @(posedge clk) disable iff (1'b0) (pad_up == (data && oe))
    );

// pad_dn_l follows the implemented active-low drive equation.
    check_pad_dn_l_function: assert property (
        @(posedge clk) disable iff (1'b0) (pad_dn_l == ~(~data && oe))
    );

// bsr_up mirrors pad_up.
    check_bsr_up_mirror: assert property (
        @(posedge clk) disable iff (1'b0) (bsr_up == pad_up)
    );

// bsr_dn_l mirrors pad_dn_l.
    check_bsr_dn_l_mirror: assert property (
        @(posedge clk) disable iff (1'b0) (bsr_dn_l == pad_dn_l)
    );

// to_core follows the mux implemented in the RTL.
    check_to_core_mux_function: assert property (
        @(posedge clk) disable iff (1'b0)
        (to_core == ((bsr_mode && !se) ? bsr_data_to_core : rcvr_data))
    );

// In boundary-scan mode with se low, to_core selects bsr_data_to_core.
    check_to_core_bsr_path: assert property (
        @(posedge clk) disable iff (1'b0)
        (bsr_mode && !se) |-> (to_core == bsr_data_to_core)
    );

// Otherwise, to_core selects rcvr_data.
    check_to_core_rcvr_path: assert property (
        @(posedge clk) disable iff (1'b0)
        (!bsr_mode || se) |-> (to_core == rcvr_data)
    );

// With output enable low, the pad outputs remain in their inactive state.
    check_outputs_when_oe_low: assert property (
        @(posedge clk) disable iff (1'b0)
        (!oe) |-> (!pad_up && pad_dn_l)
    );

// With output enable high, both pad outputs track data as implemented.
    check_outputs_when_oe_high: assert property (
        @(posedge clk) disable iff (1'b0)
        oe |-> ((pad_up == data) && (pad_dn_l == data))
    );

endmodule

rtl:
module round_sat (
  input clk,
  input rst,
  input signed [15:0] in_val,
  input signed [15:0] min_val,
  input signed [15:0] max_val,
  output reg signed [15:0] out_round,
  output reg signed [15:0] out_sat
);

  always @(posedge clk) begin
    if (rst) begin
      out_round <= 0;
      out_sat <= 0;
    end
    else begin
      // Round block
      if (in_val[0]) begin
        out_round <= in_val + 1;
      end
      else begin
        out_round <= in_val;
      end

      // Saturation block
      if (in_val < min_val) begin
        out_sat <= min_val;
      end
      else if (in_val > max_val) begin
        out_sat <= max_val;
      end
      else begin
        out_sat <= in_val;
      end
    end
  end

endmodule

sva:
module round_sat_sva (
    input logic clk,
    input logic rst,
    input logic signed [15:0] in_val,
    input logic signed [15:0] min_val,
    input logic signed [15:0] max_val,
    input logic signed [15:0] out_round,
    input logic signed [15:0] out_sat
);

// Synchronous reset clears both registered outputs.
    check_reset_clears_outputs: assert property (
        @(posedge clk)
        rst |=> (out_round == 16'sd0 && out_sat == 16'sd0)
    );

// Odd input values are rounded up by one.
    check_round_odd_adds_one: assert property (
        @(posedge clk) disable iff (rst)
        in_val[0] |=> (out_round == ($past(in_val) + 16'sd1))
    );

// Even input values pass through the round block unchanged.
    check_round_even_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        !in_val[0] |=> (out_round == $past(in_val))
    );

// Inputs below the minimum clamp to min_val.
    check_sat_low_clamps_to_min: assert property (
        @(posedge clk) disable iff (rst)
        (in_val < min_val) |=> (out_sat == $past(min_val))
    );

// Inputs above the maximum clamp to max_val when not already below min_val.
    check_sat_high_clamps_to_max: assert property (
        @(posedge clk) disable iff (rst)
        (!(in_val < min_val) && (in_val > max_val)) |=> (out_sat == $past(max_val))
    );

// Inputs within the range pass through the saturation block unchanged.
    check_sat_in_range_passthrough: assert property (
        @(posedge clk) disable iff (rst)
        (!(in_val < min_val) && !(in_val > max_val)) |=> (out_sat == $past(in_val))
    );

endmodule

