rtl:
module four_bit_adder (
    input [3:0] A,
    input [3:0] B,
    input CIN,
    output [3:0] S,
    output COUT
);

    wire [3:0] sum;
    wire carry_out_1;
    wire carry_out_2;

    // First stage of the adder
    full_adder fa1(.A(A[0]), .B(B[0]), .CIN(CIN), .S(sum[0]), .COUT(carry_out_1));
    full_adder fa2(.A(A[1]), .B(B[1]), .CIN(carry_out_1), .S(sum[1]), .COUT(carry_out_2));
    full_adder fa3(.A(A[2]), .B(B[2]), .CIN(carry_out_2), .S(sum[2]), .COUT(COUT));
    full_adder fa4(.A(A[3]), .B(B[3]), .CIN(COUT), .S(sum[3]), .COUT());

    assign S = sum;

endmodule

module full_adder (
    input A,
    input B,
    input CIN,
    output S,
    output COUT
);

    assign S = A ^ B ^ CIN;
    assign COUT = (A & B) | (A & CIN) | (B & CIN);

endmodule

sva:
module four_bit_adder_sva (
    input logic clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic CIN,
    input logic [3:0] S,
    input logic COUT
);

// Bit 0 sum matches the first full-adder XOR.
    check_sum_bit0: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0] ^ CIN)
    );

// Bit 1 sum uses the carry generated from bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^
                 ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))
    );

// The low three bits and COUT equal the 3-bit addition result.
    check_lower_three_bit_addition: assert property (
        @(posedge clk)
        {COUT, S[2:0]} == ({1'b0, A[2:0]} + {1'b0, B[2:0]} + CIN)
    );

// Bit 2 sum uses the carry generated from bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^
                 ((A[1] & B[1]) |
                  (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                  (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN)))))
    );

// COUT is the carry out produced by the bit 2 full adder.
    check_cout_from_bit2: assert property (
        @(posedge clk)
        COUT == ((A[2] & B[2]) |
                 (A[2] & ((A[1] & B[1]) |
                          (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                          (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))))) |
                 (B[2] & ((A[1] & B[1]) |
                          (A[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))) |
                          (B[1] & ((A[0] & B[0]) | (A[0] & CIN) | (B[0] & CIN))))))
    );

// Bit 3 sum XORs A[3] and B[3] with COUT.
    check_sum_bit3_uses_cout: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^ COUT)
    );

endmodule

