module greater_of_two(
    input [7:0] A,
    input [7:0] B,
    output wire [7:0] G
);

    wire tmp;
    assign tmp = (A > B);
    assign G = tmp ? A : B;

endmodule
module comparator(
    input [7:0] A,
    input [7:0] B,
    output wire [7:0] G
);

    assign G = A > B ? A : B;

