module sky130_fd_sc_lp__xnor3 (
    X,
    A,
    B,
    C
);

    output X;
    input  A;
    input  B;
    input  C;

    wire xnor0_out_X;

    xnor xnor0 (xnor0_out_X, A, B, C        );
    buf  buf0  (X          , xnor0_out_X    );

endmodule

sva:
module sky130_fd_sc_lp__xnor3_sva (
    input logic clk,
    input logic X,
    input logic A,
    input logic B,
    input logic C
);

// X matches the 3-input XNOR of A, B, and C.
    check_xnor3_function: assert property (
        @(posedge clk) X === ~(A ^ B ^ C)
    );

// With C low, X reduces to the XNOR of A and B.
    check_c_low_reduces_to_ab_xnor: assert property (
        @(posedge clk) (C == 1'b0) |-> (X === ~(A ^ B))
    );

// With C high, X reduces to the XOR of A and B.
    check_c_high_reduces_to_ab_xor: assert property (
        @(posedge clk) (C == 1'b1) |-> (X === (A ^ B))
    );

// When A and B are equal, X is the inversion of C.
    check_ab_equal_inverts_c: assert property (
        @(posedge clk) (A == B) |-> (X === ~C)
    );

// When A and B differ, X follows C.
    check_ab_different_follows_c: assert property (
        @(posedge clk) (A != B) |-> (X === C)
    );

// When B and C are equal, X is the inversion of A.
    check_bc_equal_inverts_a: assert property (
        @(posedge clk) (B == C) |-> (X === ~A)
    );

// When B and C differ, X follows A.
    check_bc_different_follows_a: assert property (
        @(posedge clk) (B != C) |-> (X === A)
    );

// When A and C are equal, X is the inversion of B.
    check_ac_equal_inverts_b: assert property (
        @(posedge clk) (A == C) |-> (X === ~B)
    );

// When A and C differ, X follows B.
    check_ac_different_follows_b: assert property (
        @(posedge clk) (A != C) |-> (X === B)
    );

// All-zero inputs must produce a high output.
    check_all_zero_case: assert property (
        @(posedge clk) (A == 1'b0 && B == 1'b0 && C == 1'b0) |-> (X === 1'b1)
    );

// All-one inputs must produce a low output.
    check_all_one_case: assert property (
        @(posedge clk) (A == 1'b1 && B == 1'b1 && C == 1'b1) |-> (X === 1'b0)
    );

endmodule

rtl:
module barrel_shifter (
    input [3:0] in,
    input [1:0] ctrl,
    output reg [3:0] out
);

always @(*) begin
    case(ctrl)
        2'b00: out = {in[2:0], 1'b0};
        2'b01: out = {in[1:0], 2'b00};
        2'b10: out = {1'b0, in[3:1]};
        2'b11: out = {2'b00, in[3:2]};
        default: out = 4'b0;
    endcase
end

endmodule

sva:
module barrel_shifter_sva (
    input logic clk,
    input logic [3:0] in,
    input logic [1:0] ctrl,
    input logic [3:0] out
);

// Output matches the selected shift operation for all control values.
    check_functional_mapping: assert property (
        @(posedge clk)
        out == ((ctrl == 2'b00) ? {in[2:0], 1'b0} :
                (ctrl == 2'b01) ? {in[1:0], 2'b00} :
                (ctrl == 2'b10) ? {1'b0, in[3:1]} :
                                  {2'b00, in[3:2]})
    );

// ctrl 00 shifts left by 1 with zero fill.
    check_ctrl_00_shift_left_1: assert property (
        @(posedge clk) (ctrl == 2'b00) |-> (out == {in[2:0], 1'b0})
    );

// ctrl 01 shifts left by 2 with zero fill.
    check_ctrl_01_shift_left_2: assert property (
        @(posedge clk) (ctrl == 2'b01) |-> (out == {in[1:0], 2'b00})
    );

// ctrl 10 shifts right by 1 with zero fill.
    check_ctrl_10_shift_right_1: assert property (
        @(posedge clk) (ctrl == 2'b10) |-> (out == {1'b0, in[3:1]})
    );

// ctrl 11 shifts right by 2 with zero fill.
    check_ctrl_11_shift_right_2: assert property (
        @(posedge clk) (ctrl == 2'b11) |-> (out == {2'b00, in[3:2]})
    );

endmodule

