    input [7:0] b,
    output reg [7:0] sum
);

    always @(*) begin
        sum = a + b;
    end

endmodule
module mux2to1_module (
    input [7:0] a,
    input [7:0] b,
    input select,
    output reg [7:0] out
);

    always @(select or a or b) begin
        out = (select == 1'b0) ? a : b;
