module adder (
    input [15:0] in0,
    input [15:0] in1,
    output [15:0] out
);

assign out = in0 + in1;

endmodule
module subtractor (
    input [15:0] in0,
    input [15:0] in1,
    output [15:0] out
);

assign out = in0 - in1;

endmodule
module absolute_diff (
    input [15:0] in0,
    input [15:0] in1,
    output [15:0] out
);

assign out = in0 > in1 ? in0 - in1 : in1 - in0;

