module padder(in, byte_num, out);
    input      [31:0] in;
    input      [1:0]  byte_num;
    output reg [31:0] out;

    always @ (*)
      case (byte_num)
        0: out = 32'h1000000;
        1: out = {in[31:8], 8'h01};
        2: out = {in[31:16], 16'h0100};
        3: out = {in[31:24], 24'h010000};
      endcase
endmodule

