module shift_reg(CK, D, S, Q);
input CK, S;
input [3:0] D;
output [3:0] Q;

wire [3:0] Q_temp;
reg [3:0] Q_reg;

always @ (posedge CK) begin
    if(S) begin
        Q_reg <= D;
    end else begin
        Q_reg <= {Q_reg[2:0], Q_temp[3]};
    end
end

assign Q_temp = Q_reg;
assign Q = Q_reg;

endmodule

sva:
module shift_reg_assertions (
    input logic        CK,
    input logic        S,
    input logic [3:0]  D,
    input logic [3:0]  Q
);

// Q updates each cycle from either D or the rotated previous Q.
    check_state_update: assert property (
        @(posedge CK)
        1'b1 |=> Q == ($past(S) ? $past(D) : {$past(Q[2:0]), $past(Q[3])})
    );

// When S is high, Q loads D.
    check_load_on_select: assert property (
        @(posedge CK)
        S |=> Q == $past(D)
    );

// When S is low, Q rotates left by one bit.
    check_rotate_on_shift: assert property (
        @(posedge CK)
        !S |=> Q == {$past(Q[2:0]), $past(Q[3])}
    );

// In shift mode, Q[3] comes from the previous Q[2].
    check_rotate_bit3: assert property (
        @(posedge CK)
        !S |=> Q[3] == $past(Q[2])
    );

// In shift mode, Q[2] comes from the previous Q[1].
    check_rotate_bit2: assert property (
        @(posedge CK)
        !S |=> Q[2] == $past(Q[1])
    );

// In shift mode, Q[1] comes from the previous Q[0].
    check_rotate_bit1: assert property (
        @(posedge CK)
        !S |=> Q[1] == $past(Q[0])
    );

// In shift mode, Q[0] comes from the previous Q[3].
    check_rotate_bit0: assert property (
        @(posedge CK)
        !S |=> Q[0] == $past(Q[3])
    );

// Four consecutive shifts restore the original value.
    check_four_shifts_restore_state: assert property (
        @(posedge CK)
        (!S)[*4] |=> Q == $past(Q, 4)
    );

endmodule

module d_ff_sync_reset_set_ce_assertions (
    input logic CLK,
    input logic D,
    input logic RESET,
    input logic SET,
    input logic CE,
    input logic Q
);

// Enabled updates follow RESET, then SET, then D priority.
    check_enabled_update_value: assert property (
        @(posedge CLK)
        CE |=> (Q == ($past(RESET) ? 1'b0 : ($past(SET) ? 1'b1 : $past(D))))
    );

// RESET clears Q on the next clock when CE is high.
    check_reset_clears_q: assert property (
        @(posedge CLK)
        CE && RESET |=> (Q == 1'b0)
    );

// RESET overrides SET when both are high and CE is high.
    check_reset_priority_over_set: assert property (
        @(posedge CLK)
        CE && RESET && SET |=> (Q == 1'b0)
    );

// SET drives Q high when enabled and not in reset.
    check_set_sets_q: assert property (
        @(posedge CLK) disable iff (RESET)
        CE && SET |=> (Q == 1'b1)
    );

// D is captured when enabled with neither RESET nor SET active.
    check_data_capture: assert property (
        @(posedge CLK) disable iff (RESET)
        CE && !SET |=> (Q == $past(D))
    );

// Q holds its value whenever CE is low.
    check_ce_low_holds_q: assert property (
        @(posedge CLK)
        !CE |=> (Q == $past(Q))
    );

endmodule

