    output Q  ;
    output Q_N;
    input  SCD;
    input  SCE;

    wire Q_reg;
    wire Q_N_reg;

    assign Q = Q_reg;
    assign Q_N = Q_N_reg;

    sdfxbp base (
        .CLK(CLK),
        .D(D),
        .Q(Q_reg),
        .Q_N(Q_N_reg),
