module adbg_crc32 (clk, data, enable, shift, clr, rst, crc_out, serial_out);

input         clk;
input         data;
input         enable;
input         shift;
input         clr;
input         rst;
output [31:0] crc_out;
output        serial_out;


reg    [31:0] crc;
wire   [31:0] new_crc;


assign new_crc[0] = crc[1];
assign new_crc[1] = crc[2];
assign new_crc[2] = crc[3];
assign new_crc[3] = crc[4];
assign new_crc[4] = crc[5];
assign new_crc[5] = crc[6] ^ data ^ crc[0];
assign new_crc[6] = crc[7];
assign new_crc[7] = crc[8];
assign new_crc[8] = crc[9] ^ data ^ crc[0];
assign new_crc[9] = crc[10] ^ data ^ crc[0];
assign new_crc[10] = crc[11];
assign new_crc[11] = crc[12];
assign new_crc[12] = crc[13];
assign new_crc[13] = crc[14];
assign new_crc[14] = crc[15];
assign new_crc[15] = crc[16] ^ data ^ crc[0];
assign new_crc[16] = crc[17];
assign new_crc[17] = crc[18];
assign new_crc[18] = crc[19];
assign new_crc[19] = crc[20] ^ data ^ crc[0];
assign new_crc[20] = crc[21] ^ data ^ crc[0];
assign new_crc[21] = crc[22] ^ data ^ crc[0];
assign new_crc[22] = crc[23];
assign new_crc[23] = crc[24] ^ data ^ crc[0];
assign new_crc[24] = crc[25] ^ data ^ crc[0];
assign new_crc[25] = crc[26];
assign new_crc[26] = crc[27] ^ data ^ crc[0];
assign new_crc[27] = crc[28] ^ data ^ crc[0];
assign new_crc[28] = crc[29];
assign new_crc[29] = crc[30] ^ data ^ crc[0];
assign new_crc[30] = crc[31] ^ data ^ crc[0];
assign new_crc[31] =           data ^ crc[0];

always @ (posedge clk or posedge rst)
begin
  if(rst)
    crc[31:0] <= 32'hffffffff;
  else if(clr)
    crc[31:0] <= 32'hffffffff;
  else if(enable)
    crc[31:0] <= new_crc;
  else if (shift)
    crc[31:0] <= {1'b0, crc[31:1]};
end


assign crc_out = crc; assign serial_out = crc[0];

endmodule

sva:
module adbg_crc32_sva (
    input logic        clk,
    input logic        data,
    input logic        enable,
    input logic        shift,
    input logic        clr,
    input logic        rst,
    input logic [31:0] crc_out,
    input logic        serial_out
);

// Reset drives the CRC state to all ones.
    check_reset_value: assert property (
        @(posedge clk) rst |=> (crc_out == 32'hffffffff && serial_out == 1'b1)
    );

// serial_out always mirrors the CRC LSB.
    check_serial_matches_lsb: assert property (
        @(posedge clk) disable iff (rst) (serial_out == crc_out[0])
    );

// clr loads all ones and has priority over enable and shift.
    check_clear_sets_all_ones: assert property (
        @(posedge clk) disable iff (rst)
        clr |=> (crc_out == 32'hffffffff && serial_out == 1'b1)
    );

// enable updates the CRC with the implemented feedback polynomial.
    check_enable_updates_crc: assert property (
        @(posedge clk) disable iff (rst)
        (enable && !clr) |=> (crc_out == next_crc($past(crc_out), $past(data)))
    );

// shift right occurs only when enable and clr are not active.
    check_shift_right: assert property (
        @(posedge clk) disable iff (rst)
        (shift && !enable && !clr) |=> (crc_out == {1'b0, $past(crc_out[31:1])})
    );

// With no control active, the CRC register holds its value.
    check_idle_holds_crc: assert property (
        @(posedge clk) disable iff (rst)
        (!clr && !enable && !shift) |=> (crc_out == $past(crc_out))
    );

endmodule

