      dbrk_goto1 <= 0;
      dbrk_traceme <= 0;
      dbrk_traceoff <= 0;
      dbrk_traceon <= 0;
      dbrk_trigout <= 0;
    end else begin
      dbrk_break <= debugack;
      dbrk_goto0 <= 0;
      dbrk_goto1 <= 0;
      dbrk_traceme <= 0;
      dbrk_traceoff <= 0;
      dbrk_traceon <= 0;
      dbrk_trigout <= 0;
    end
